(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-5-e", [{"sp": "HDR", "t": "Ἱστορίαι (ΙϚʹ–ΚΖʹ)"}, {"sp": "HDR", "t": "Βιβλίον ΙϚʹ", "st": "16"}, {"sp": "N", "t": "ὅτι Φίλιππος ὁ βασιλεὺς παραγενόμενος εἰς τὸ Πέργαμον καὶ νομίζων οἷον αὐτόχειρ Ἀττάλου γενέσθαι πᾶσαν αἰκίαν ἐναπεδείκνυτο. χαριζόμενος γὰρ οἷον εἰ λυττῶντι τῷ θυμῷ, τὸ πλεῖον τῆς ὀργῆς οὐκ εἰς τοὺς ἀνθρώπους, ἀλλ’ εἰς τοὺς θεοὺς διετίθετο. κατὰ μὲν γὰρ τοὺς ἀκροβολισμοὺς εὐχερῶς αὐτὸν ἀπήρυκον διὰ τὰς τῶν τόπων ὀχυρότητας οἱ τὸ Πέργαμον παραφυλάττοντες· ἀπὸ δὲ τῆς χώρας οὐδὲν ὠφελεῖτο τῷ προνενοῆσθαι τὸν Ἄτταλον ὑπὲρ τούτων ἐπιμελῶς. λοιπὸν εἰς τὰ τῶν θεῶν ἕδη καὶ τεμένη διετίθετο τὴν ὀργήν, ὑβρίζων οὐκ Ἄτταλον, ὥς γ’ ἐμοὶ δοκεῖ, πολὺ δὲ μᾶλλον ἑαυτόν. οὐ γὰρ μόνον ἐνεπίμπρα καὶ κατασπῶν ἐρρίπτει τοὺς νεὼς καὶ τοὺς βωμούς, ἀλλὰ καὶ τοὺς λίθους ἔθραυε πρὸς τὸ μηδὲ πάλιν ἀνασταθῆναι μηδὲν τῶν κατεφθαρμένων. ἐπεὶ δὲ τὸ Νικηφόριον ἐλυμήνατο, τὸ μὲν ἄλσος ἐκτεμών, τὸν δὲ περίβολον διαρρίψας, τούς τε ναοὺς ἐκ θεμελίων ἀνέσκαψε, πολλοὺς καὶ πολυτελεῖς ὑπάρχοντας, ὥρμησε τὰς μὲν ἀρχὰς ἐπὶ Θυατείρων· ἐκεῖθεν δὲ ποιησάμενος τὴν ἀναζυγὴν εἰς τὸ Θήβης πεδίον εἰσέβαλε, νομίζων εὐπορήσειν λείας μάλιστα περὶ τούτους τοὺς τόπους. ἀποπεσὼν δὲ καὶ ταύτης τῆς ἐλπίδος, καὶ παραγενόμενος εἰς Ἱερὰν κώμην, διεπέμπετο πρὸς Ζεῦξιν, παρακαλῶν αὐτὸν σῖτον χορηγῆσαι καὶ τὰ λοιπὰ συμπράττειν κατὰ τὰς συνθήκας. ὁ δὲ Ζεῦξις ὑπεκρίνετο μὲν ποιεῖν τὰ κατὰ τὰς συνθήκας, οὐκ ἐβούλετο δὲ σωματοποιεῖν ἀληθινῶς τὸν Φίλιππον. —", "st": "16.1"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος, τῶν μὲν κατὰ τὴν πολιορκίαν ἀντιπιπτόντων αὐτῷ, τῶν δὲ πολεμίων ἐφορμούντων πλείοσι καταφράκτοις ναυσίν, ἠπορεῖτο καὶ δυσχρήστως διέκειτο περὶ τοῦ μέλλοντος. οὐκ ἐπιδεχομένων δὲ τῶν παρόντων αἵρεσιν, ἀνήχθη παρὰ τὴν τῶν πολεμίων προσδοκίαν· ἔτι γὰρ αὐτὸν ἤλπιζον οἱ περὶ τὸν Ἄτταλον προσκαρτερήσειν τῇ τῶν μετάλλων κατασκευῇ. μάλιστα δ’ ἐσπούδαζε ποιήσασθαι τὸν ἀνάπλουν αἰφνίδιον, πεπεισμένος καταταχήσειν καὶ τὸ λοιπὸν ἀσφαλῶς ἤδη κομισθήσεσθαι παρὰ τὴν γῆν εἰς τὴν Σάμον. διεψεύσθη δὲ παρὰ πολὺ τοῖς λογισμοῖς· οἱ γὰρ περὶ τὸν Ἄτταλον καὶ Θεοφιλίσκον, ἅμα τῷ συνιδεῖν αὐτὸν ἀναγόμενον, εἴχοντο τῶν προκειμένων εὐθέως. συνέβη δὲ τὸν ἀνάπλουν αὐτῶν γενέσθαι διαλελυμένον, ἅτε πεπεισμένων τὸν Φίλιππον, καθάπερ εἶπον, ἔτι μένειν ἐπὶ τῶν ὑποκειμένων. οὐ μὴν ἀλλὰ χρησάμενοι ταῖς εἰρεσίαις ἐνεργῶς προσέβαλλον, Ἄτταλος μὲν τῷ δεξιῷ καὶ καθηγουμένῳ τῶν πολεμίων, Θεοφιλίσκος δὲ τοῖς εὐωνύμοις. Φίλιππος δὲ περικαταλαμβανόμενος τοῖς καιροῖς, δοὺς τὸ σύνθημα τοῖς ἐπὶ τοῦ δεξιοῦ καὶ παραγγείλας ἀντιπρώρρους ποιεῖν τὰς ναῦς καὶ συμπλέκεσθαι τοῖς πολεμίοις ἐρρωμένως, αὐτὸς ὑπὸ τὰς νησίδας ἀναχωρήσας μετά τινων λέμβων, τὰς μεταξὺ τοῦ πόρου κειμένας, ἀπεκαραδόκει τὸν κίνδυνον. ἦν δὲ τῶν μὲν τοῦ Φιλίππου νεῶν τὸ πλῆθος τὸ συγκαταστὰν εἰς τὸν ἀγῶνα κατάφρακτοι τρεῖς καὶ πεντήκοντα, σὺν δὲ τούτοις ἄφρακτα λέμβοι δὲ σὺν ταῖς πρίστεσιν ἑκατὸν καὶ πεντήκοντα· τὰς γὰρ ἐν τῇ Σάμῳ ναῦς οὐκ ἠδυνήθη καταρτίσαι πάσας. τὰ δὲ τῶν πολεμίων σκάφη κατάφρακτα μὲν ἦν ἑξήκοντα καὶ πέντε σὺν τοῖς τῶν Βυζαντίων, μετὰ δὲ τούτων ἐννέα τριημιολίαι καὶ τριήρεις τρεῖς ὑπῆρχον.", "st": "16.2"}, {"sp": "N", "t": "λαβούσης δὲ τὴν καταρχὴν τῆς ναυμαχίας ἐκ τῆς Ἀττάλου νεώς, εὐθέως πάντες οἱ σύνεγγυς ἀπαραγγέλτως συνέβαλον ἀλλήλοις. Ἄτταλος μὲν οὖν συμπεσὼν ὀκτήρει, καὶ προεμβαλὼν ταύτῃ καιρίαν καὶ ὕφαλον πληγήν, ἐπὶ πολὺ τῶν ἐπὶ τοῦ καταστρώματος ἀγωνισαμένων τέλος ἐβύθισε τὴν ναῦν. ἡ δὲ τοῦ Φιλίππου δεκήρης, ναυαρχὶς οὖσα, παραλόγως ἐγένετο τοῖς ἐχθροῖς ὑποχείριος. ὑποπεσούσης γὰρ αὐτῇ τριημιολίας, ταύτῃ δοῦσα πληγὴν βιαίαν κατὰ μέσον τὸ κύτος ὑπὸ τὸν θρανίτην σκαλμὸν ἐδέθη, τοῦ κυβερνήτου τὴν ὁρμὴν τῆς νεὼς οὐκέτι δυνηθέντος ἀναλαβεῖν· διὸ καὶ προσκρεμαμένου τοῦ πλοίου τοῖς ὅλοις ἐδυσχρηστεῖτο καὶ δυσκίνητος ἦν πρὸς πᾶν. ἐν ᾧ καιρῷ δύο πεντήρεις προσπεσοῦσαι, καὶ τρώσασαι τὴν ναῦν ἐξ ἀμφοῖν τοῖν μεροῖν, καὶ τὸ σκάφος καὶ τοὺς ἐπιβάτας τοὺς ἐν αὐτῷ διέφθειραν, ἐν οἷς ἦν καὶ Δημοκράτης ὁ τοῦ Φιλίππου ναύαρχος. κατὰ δὲ τὸν αὐτὸν καιρὸν Διονυσόδωρος καὶ Δεινοκράτης, ὄντες ἀδελφοὶ καὶ ναυαρχοῦντες παρ’ Ἀττάλῳ, συμπεσόντες ὁ μὲν ἑπτήρει τῶν πολεμίων, ὁ δ’ ὀκτήρει, παραβόλως ἐχρήσαντο τῇ ναυμαχίᾳ. Δεινοκράτης μὲν πρὸς ὀκτήρη συμπεσὼν αὐτὸς μὲν ἔξαλον ἔλαβε τὴν πληγήν, ἀναστείρου τῆς νεὼς οὔσης, τὴν δὲ τῶν πολεμίων τρώσας ναῦν ὑπὸ τὰ βίαχα τὸ μὲν πρῶτον οὐκ ἐδύνατο χωρισθῆναι, καίπερ πολλάκις ἐπιβαλόμενος πρύμναν κρούειν· διὸ καὶ τῶν Μακεδόνων εὐψύχως ἀγωνιζομένων εἰς τὸν ἔσχατον παρεγένετο κίνδυνον. Ἀττάλου δ’ ἐπιβοηθήσαντος αὐτῷ, καὶ διὰ τῆς εἰς τὴν πολεμίαν ναῦν ἐμβολῆς λύσαντος τὴν συμπλοκὴν τῶν σκαφῶν, ὁ μὲν Δεινοκράτης ἀπελύθη παραδόξως, οἱ δὲ τῆς πολεμίας νεὼς ἐπιβάται πάντες εὐψύχως διαγωνισάμενοι διεφθάρησαν, τὸ δὲ σκάφος ἔρημον ἀπολειφθὲν ὑποχείριον ἐγένετο τοῖς περὶ τὸν Ἄτταλον. ὁ δὲ Διονυσόδωρος μετὰ βίας ἐπιφερόμενος εἰς ἐμβολὴν αὐτὸς μὲν ἥμαρτε τοῦ τρῶσαι, παραπεσὼν δὲ τοῖς πολεμίοις ἀπέβαλε τὸν δεξιὸν ταρσὸν τῆς νεώς, ὁμοῦ συρραγέντων καὶ τῶν πυργούχων· οὗ γενομένου περιέστησαν αὐτὸν πανταχόθεν οἱ πολέμιοι. κραυγῆς δὲ καὶ θορύβου γενομένου τὸ μὲν λοιπὸν πλῆθος τῶν ἐπιβατῶν ἅμα τῷ σκάφει διεφθάρη, τρίτος δ’ αὐτὸς ὁ Διονυσόδωρος ἀπενήξατο πρὸς τὴν ἐπιβοηθοῦσαν αὐτῷ τριημιολίαν.", "st": "16.3"}, {"sp": "N", "t": "τῶν δὲ λοιπῶν νεῶν τοῦ πλήθους ὁ κίνδυνος ἐφάμιλλος ἦν· καθ’ ὅσον γὰρ ἐπλεόναζον οἱ παρὰ τοῦ Φιλίππου λέμβοι, κατὰ τοσοῦτον διέφερον οἱ περὶ τὸν Ἄτταλον τῷ τῶν καταφράκτων νεῶν πλήθει. καὶ τὰ μὲν περὶ τὸ δεξιὸν κέρας τοῦ Φιλίππου τοιαύτην εἶχε τὴν διάθεσιν ὥστ’ ἀκμὴν ἄκριτα μένειν τὰ ὅλα, πολὺ δὲ τοὺς περὶ τὸν Ἄτταλον ἐπικυδεστέρας ἔχειν τὰς ἐλπίδας. οἱ δὲ Ῥόδιοι κατὰ μὲν τὰς ἀρχὰς εὐθέως ἐκ τῆς ἀναγωγῆς ἀπεσπάσθησαν τῶν πολεμίων, καθάπερ ἀρτίως εἶπα, τῷ δὲ ταχυναυτεῖν παρὰ πολὺ διαφέροντες τῶν ἐναντίων συνῆψαν τοῖς ἐπὶ τῆς οὐραγίας Μακεδόσι. καὶ τὸ μὲν πρῶτον ὑποχωροῦσι τοῖς σκάφεσι κατὰ πρύμναν ἐπιφερόμενοι τοὺς ταρσοὺς παρέλυον· ὡς δ’ οἱ μὲν παρὰ τοῦ Φιλίππου συνεπιστρέφειν ἤρξαντο παραβοηθοῦντες τοῖς κινδυνεύουσι, τῶν δὲ Ῥοδίων οἱ καθυστεροῦντες ἐκ τῆς ἀναγωγῆς συνῆψαν τοῖς περὶ τὸν Θεοφιλίσκον, τότε κατὰ πρόσωπον ἀντιπρώρρους τάξαντες τὰς ναῦς ἀμφότεροι συνέβαλον εὐψύχως, ὁμοῦ ταῖς σάλπιγξι καὶ τῇ κραυγῇ παρακαλοῦντες ἀλλήλους. εἰ μὲν οὖν μὴ μεταξὺ τῶν καταφράκτων νεῶν ἔταξαν οἱ Μακεδόνες τοὺς λέμβους, ῥᾳδίαν ἂν καὶ σύντομον ἔλαβε κρίσιν ἡ ναυμαχία· νῦν δὲ ταῦτ’ ἐμπόδια πρὸς τὴν χρείαν τοῖς Ῥοδίοις ἐγίνετο κατὰ πολλοὺς τρόπους. μετὰ γὰρ τὸ κινηθῆναι τὴν ἐξ ἀρχῆς τάξιν ἐκ τῆς πρώτης συμβολῆς πάντες ἦσαν ἀναμὶξ ἀλλήλοις, ὅθεν οὔτε διεκπλεῖν εὐχερῶς οὔτε στρέφειν ἐδύναντο τὰς ναῦς οὔτε καθόλου χρῆσθαι τοῖς ἰδίοις προτερήμασιν, ἐμπιπτόντων αὐτοῖς τῶν λέμβων ποτὲ μὲν εἰς τοὺς ταρσούς, ὥστε δυσχρηστεῖν ταῖς εἰρεσίαις, ποτὲ δὲ πάλιν εἰς τὰς πρώρρας, ἔστι δ’ ὅτε κατὰ πρύμναν, ὥστε παραποδίζεσθαι καὶ τὴν τῶν κυβερνητῶν καὶ τὴν τῶν ἐρετῶν χρείαν. κατὰ δὲ τὰς ἀντιπρώρρους συμπτώσεις ἐποίουν τι τεχνικόν· αὐτοὶ μὲν γὰρ ἔμπρωρρα τὰ σκάφη ποιοῦντες ἐξάλους ἐλάμβανον τὰς πληγάς, τοῖς δὲ πολεμίοις ὕφαλα τὰ τραύματα διδόντες ἀβοηθήτους ἐσκεύαζον τὰς πληγάς. σπανίως δ’ εἰς τοῦτο συγκατέβαινον· καθόλου γὰρ ἐξέκλινον τὰς συμπλοκὰς διὰ τὸ γενναίως ἀμύνεσθαι τοὺς Μακεδόνας ἀπὸ τῶν καταστρωμάτων ἐν ταῖς συστάδην γινομέναις μάχαις. τὸ δὲ πολὺ κατὰ μὲν τοὺς διέκπλους παρασύροντες τῶν πολεμίων νεῶν τοὺς ταρσοὺς ἠχρείουν· μετὰ δὲ ταῦτα πάλιν ἐκπεριπλέοντες, καὶ τοῖς μὲν κατὰ πρύμναν ἐμβάλλοντες, τοῖς δὲ πλαγίοις καὶ στρεφομένοις ἀκμὴν προσπίπτοντες οὓς μὲν ἐτίτρωσκον, οἷς δὲ παρέλυον ἀεί τι τῶν πρὸς τὴν χρείαν ἀναγκαίων. καὶ δὴ τῷ τοιούτῳ τρόπῳ μαχόμενοι παμπληθεῖς τῶν πολεμίων ναῦς διέφθειραν.", "st": "16.4"}, {"sp": "N", "t": "ἐπιφανέστατα δ’ ἐκινδύνευσαν τρεῖς πεντήρεις τῶν Ῥοδίων, ἥ τε ναυαρχίς, ἐφ’ ἧς ἔπλει Θεοφιλίσκος, μετὰ δὲ ταύτην ἧς ἐτριηράρχει Φιλόστρατος, τρίτη δ’ ἣν ἐκυβέρνα μὲν Αὐτόλυκος, ἐπέπλει δὲ Νικόστρατος. ταύτης γὰρ ἐμβαλούσης εἰς πολεμίαν ναῦν καὶ καταλιπούσης ἐν τῷ σκάφει τὸν ἔμβολον, συνέβη δὴ τὴν μὲν πληγεῖσαν αὔτανδρον καταδῦναι, τοὺς δὲ περὶ τὸν Αὐτόλυκον, εἰσρεούσης εἰς τὴν ναῦν τῆς θαλάττης διὰ τῆς πρώρρας, κυκλωθέντας ὑπὸ τῶν πολεμίων τὰς μὲν ἀρχὰς ἀγωνίζεσθαι γενναίως, τέλος δὲ τὸν μὲν Αὐτόλυκον ἐκπεσεῖν τρωθέντα μετὰ τῶν ὅπλων εἰς τὴν θάλατταν, τοὺς δὲ λοιποὺς ἐπιβάτας ἀποθανεῖν μαχομένους γενναίως. ἐν ᾧ καιρῷ Θεοφιλίσκος, βοηθήσας μετὰ τριῶν πεντήρων, τὴν μὲν ναῦν οὐκ ἠδυνήθη σῶσαι διὰ τὸ πλήρη θαλάττης εἶναι, δύο δὲ ναῦς πολεμίας τρώσας τοὺς ἐπιβάτας ἐξέβαλε. ταχὺ δὲ περιχυθέντων αὐτῷ λέμβων πλειόνων καὶ καταφράκτων νεῶν, τοὺς μὲν πλείστους ἀπέβαλε τῶν ἐπιβατῶν ἐπιφανῶς ἀγωνισαμένους, αὐτὸς δὲ τρία τραύματα λαβὼν καὶ παραβόλως τῇ τόλμῃ κινδυνεύσας μόλις ἐξέσωσε τὴν ἰδίαν ναῦν ἐπιβοηθήσαντος αὐτῷ Φιλοστράτου καὶ συναναδεξαμένου τὸν ἐνεστῶτα κίνδυνον εὐψύχως. συνάψας δὲ τοῖς αὑτοῦ σκάφεσι πάλιν ἐξ ἄλλης ὁρμῆς συνεπλέκετο τοῖς πολεμίοις, τῇ μὲν σωματικῇ δυνάμει παραλυόμενος ὑπὸ τῶν τραυμάτων, τῇ δὲ τῆς ψυχῆς γενναιότητι λαμπρότερος ὢν καὶ παραστατικώτερος ἢ πρόσθεν. συνέβη δὲ δύο γενέσθαι ναυμαχίας πολὺ διεστώσας ἀλλήλων· τὸ μὲν γὰρ δεξιὸν κέρας τοῦ Φιλίππου κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν ἀεὶ τῆς γῆς ὀρεγόμενον οὐ μακρὰν ἀπεῖχε τῆς Ἀσίας, τὸ δ’ εὐώνυμον διὰ τὸ παραβοηθῆσαι τοῖς ἐπὶ τῆς οὐραγίας ἐξ ὑποστροφῆς οὐ πολὺ τῆς Χίας ἀπέχον ἐναυμάχει τοῖς Ῥοδίοις.", "st": "16.5"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ παρὰ πολὺ τοῦ δεξιοῦ κέρατος κατακρατούντων τῶν περὶ τὸν Ἄτταλον, καὶ συνεγγιζόντων ἤδη πρὸς τὰς νησίδας ὑφ’ αἷς ὁ Φίλιππος ὥρμει καραδοκῶν τὸ συμβησόμενον, συνιδὼν Ἄτταλος μίαν πεντήρη τῶν ἰδίων ἐκτὸς τοῦ κινδύνου τετρωμένην καὶ βαπτιζομένην ὑπὸ νεὼς πολεμίας, ὥρμησε παραβοηθήσων ταύτῃ μετὰ δύο τετρήρων. τοῦ δὲ πολεμίου σκάφους ἐγκλίναντος καὶ ποιουμένου τὴν ἀποχώρησιν ὡς πρὸς τὴν γῆν, ἐπέκειτο φιλοτιμότερον, ἐγκρατὴς γενέσθαι σπουδάζων τῆς νεώς. ὁ δὲ Φίλιππος, συνθεασάμενος ἀπεσπασμένον πολὺ τὸν Ἄτταλον ἀπὸ τῶν ἰδίων, παραλαβὼν τέτταρας πεντήρεις καὶ τρεῖς ἡμιολίας, ἔτι δὲ τῶν λέμβων τοὺς ἐγγὺς ὄντας, ὥρμησε, καὶ διακλείσας τὸν Ἄτταλον ἀπὸ τῶν οἰκείων νεῶν ἠνάγκασε μετὰ μεγάλης ἀγωνίας εἰς τὴν γῆν ἐκβαλεῖν τὰ σκάφη. τούτου δὲ συμβάντος αὐτὸς μὲν ὁ βασιλεὺς μετὰ τῶν πληρωμάτων εἰς τὰς Ἐρυθρὰς ἀπεχώρησε, τῶν δὲ πλοίων καὶ τῆς βασιλικῆς κατασκευῆς ἐγκρατὴς ὁ Φίλιππος ἐγένετο. καὶ γὰρ ἐποίησάν τι τεχνικὸν ἐν τούτοις τοῖς καιροῖς οἱ περὶ τὸν Ἄτταλον· τὰ γὰρ ἐπιφανέστατα τῆς βασιλικῆς κατασκευῆς ἐπὶ τὸ κατάστρωμα τῆς νεὼς ἐξέβαλον. ὅθεν οἱ πρῶτοι τῶν Μακεδόνων, συνάψαντες ἐν τοῖς λέμβοις, συνθεασάμενοι ποτηρίων πλῆθος καὶ πορφυρῶν ἱματίων καὶ τῶν τούτοις παρεπομένων σκευῶν, ἀφέμενοι τοῦ διώκειν ἀπένευσαν ἐπὶ τὴν τούτων ἁρπαγήν. διὸ συνέβη τὸν Ἄτταλον ἀσφαλῆ ποιήσασθαι τὴν ἀποχώρησιν εἰς τὰς Ἐρυθράς. Φίλιππος δὲ τοῖς μὲν ὅλοις ἠλαττωμένος παρὰ πολὺ τὴν ναυμαχίαν, τῇ δὲ περιπετείᾳ τῇ κατὰ τὸν Ἄτταλον ἐπαρθείς, ἐπανέπλει, καὶ πολὺς ἦν συναθροίζων τὰς σφετέρας ναῦς καὶ παρακαλῶν τοὺς ἄνδρας εὐθαρσεῖς εἶναι, διότι νικῶσι τῇ ναυμαχίᾳ· καὶ γὰρ ὑπέδραμέ τις ἔννοια καὶ πιθανότης τοῖς ἀνθρώποις ὡς ἀπολωλότος τοῦ βασιλέως Ἀττάλου διὰ τὸ κατάγειν τοὺς περὶ τὸν Φίλιππον ἀναδεδεμένους τὴν βασιλικὴν ναῦν. ὁ δὲ Διονυσόδωρος ὑπονοήσας τὸ περὶ τὸν αὑτοῦ βασιλέα γεγονός, ἥθροιζε τὰς οἰκείας ναῦς ἐξαίρων σύνθημα· ταχὺ δὲ συλλεχθεισῶν πρὸς αὐτὸν ἀπέπλει μετ’ ἀσφαλείας εἰς τοὺς κατὰ τὴν Ἀσίαν ὅρμους. κατὰ δὲ τὸν αὐτὸν καιρὸν οἱ πρὸς τοὺς Ῥοδίους ἀγωνιζόμενοι τῶν Μακεδόνων, πάλαι κακῶς πάσχοντες, ἐξέλυον αὑτοὺς ἐκ τοῦ κινδύνου μετὰ προφάσεως κατὰ μέρη ποιούμενοι τὴν ἀποχώρησιν, ὡς ταῖς οἰκείαις σπεύδοντες ἐπικουρῆσαι ναυσίν. οἱ δὲ Ῥόδιοι, τὰς μὲν ἀναδησάμενοι τῶν νεῶν, τὰς δὲ προδιαφθείραντες ταῖς ἐμβολαῖς, ἀπέπλευσαν εἰς τὴν Χίον.", "st": "16.6"}, {"sp": "N", "t": "ἐφθάρησαν δὲ τοῦ μὲν Φιλίππου ναῦς ἐν μὲν τῇ πρὸς Ἄτταλον ναυμαχίᾳ δεκήρης, ἐννήρης, ἑπτήρης, ἑξήρης, τῶν δὲ λοιπῶν κατάφρακτοι μὲν δέκα καὶ τριημιολίαι τρεῖς, λέμβοι δὲ πέντε καὶ εἴκοσι καὶ τὰ τούτων πληρώματα· ἐν δὲ τῇ πρὸς Ῥοδίους διεφθάρησαν κατάφρακτοι μὲν δέκα, λέμβοι δὲ περὶ τετταράκοντα τὸν ἀριθμόν· ἥλωσαν δὲ δύο τετρήρεις καὶ λέμβοι σὺν τοῖς πληρώμασιν ἑπτά. τῶν δὲ παρ’ Ἀττάλου κατέδυσαν μὲν τριημιολία μία καὶ δύο πεντήρεις, ἥλωσαν δὲ δύο τετρήρεις καὶ τὸ τοῦ βασιλέως σκάφος. τῶν δὲ Ῥοδίων διεφθάρησαν μὲν δύο πεντήρεις καὶ τριήρης, ἥλω δ’ οὐδέν. ἄνδρες δὲ τῶν μὲν Ῥοδίων ἀπέθανον εἰς ἑξήκοντα, τῶν δὲ παρ’ Ἀττάλου πρὸς ἑβδομήκοντα, τῶν δὲ τοῦ Φιλίππου Μακεδόνες μὲν εἰς τρισχιλίους, τῶν δὲ πληρωμάτων εἰς ἑξακισχιλίους. ἑάλωσαν δὲ ζωγρίᾳ τῶν μὲν συμμάχων καὶ Μακεδόνων εἰς δισχιλίους, τῶν δ’ ὑπεναντίων εἰς ἑπτακοσίους.", "st": "16.7"}, {"sp": "N", "t": "καὶ τὸ μὲν τέλος τῆς περὶ Χίον ναυμαχίας τοιοῦτον συνέβη γενέσθαι, τῆς δὲ νίκης ὁ Φίλιππος ἀντεποιεῖτο κατὰ δύο προφάσεις, κατὰ μίαν μέν, ᾗ τὸν Ἄτταλον εἰς τὴν γῆν ἐκβαλὼν ἐγκρατὴς τῆς νεὼς ἐγεγόνει, καθ’ ἑτέραν δ’, ᾗ καθορμισθεὶς ἐπὶ τὸ καλούμενον Ἄργεννον ἐδόκει πεποιῆσθαι τὸν ὅρμον ἐπὶ τῶν ναυαγίων. ἀκόλουθα δὲ τούτοις ἔπραττε καὶ κατὰ τὴν ἑξῆς ἡμέραν συνάγων τὰ ναυάγια καὶ τῶν νεκρῶν ποιούμενος ἀναίρεσιν τῶν ἐπιγινωσκομένων, χάριν τοῦ συναύξειν τὴν προειρημένην φαντασίαν. ὅτι γὰρ οὐδ’ αὐτὸς ἐπέπειστο νικᾶν, ἐξήλεγξαν αὐτὸν οἵ τε Ῥόδιοι καὶ Διονυσόδωρος μετ’ ὀλίγον· κατὰ γὰρ τὴν ἐπιοῦσαν ἡμέραν ἔτι περὶ ταῦτα γινομένου τοῦ βασιλέως διαπεμψάμενοι πρὸς ἀλλήλους ἐπέπλευσαν αὐτῷ, καὶ στήσαντες ἐν μετώπῳ τὰς ναῦς, οὐδενὸς ἐπ’ αὐτοὺς ἀνταναγομένου πάλιν ἀπέπλευσαν εἰς τὴν Χίον. ὁ δὲ Φίλιππος, οὐδέποτε τοσούτους ἄνδρας ἀπολωλεκὼς οὔτε κατὰ γῆν οὔτε κατὰ θάλατταν ἑνὶ καιρῷ, βαρέως μὲν ἔφερε τὸ γεγονὸς καὶ τὸ πολὺ τῆς ὁρμῆς αὐτοῦ παρῄρητο, πρὸς μέντοι γε τοὺς ἐκτὸς ἐπειρᾶτο κατὰ πάντα τρόπον ἐπικρύπτεσθαι τὴν αὑτοῦ διάληψιν, καίπερ οὐκ ἐώντων αὐτῶν τῶν πραγμάτων. χωρὶς γὰρ τῶν ἄλλων καὶ τὰ μετὰ τὴν μάχην συμβαίνοντα πάντας ἐξέπληττε τοὺς θεωμένους· γενομένης γὰρ τοσαύτης φθορᾶς ἀνθρώπων, παρ’ αὐτὸν μὲν τὸν καιρὸν πᾶς ὁ πόρος ἐπληρώθη νεκρῶν, αἵματος, ὅπλων, ναυαγίων, ταῖς δ’ ἑξῆς ἡμέραις τοὺς αἰγιαλοὺς ἦν ἰδεῖν φύρδην σεσωρευμένους ἀναμὶξ πάντων τῶν προειρημένων. ἐξ ὧν οὐ μόνον αὐτός, ἀλλὰ καὶ πάντες οἱ Μακεδόνες εἰς διατροπὴν ἐνέπιπτον οὐ τὴν τυχοῦσαν.", "st": "16.8"}, {"sp": "N", "t": "Θεοφιλίσκος δὲ μίαν ἡμέραν ἐπιβιώσας, καὶ τῇ πατρίδι γράψας ὑπὲρ τῶν κατὰ τὴν ναυμαχίαν, καὶ Κλεωναῖον ἡγεμόνα συστήσας ἀνθ’ ἑαυτοῦ ταῖς δυνάμεσι, μετήλλαξε τὸν βίον ἐκ τῶν τραυμάτων, ἀνὴρ καὶ κατὰ τὸν κίνδυνον ἀγαθὸς γενόμενος καὶ κατὰ τὴν προαίρεσιν μνήμης ἄξιος. μὴ γὰρ ἐκείνου τολμήσαντος προεπιβαλεῖν τῷ Φιλίππῳ τὰς χεῖρας πάντες ἂν καταπροεῖντο τοὺς καιρούς, δεδιότες τὴν τοῦ Φιλίππου τόλμαν. νῦν δ’ ἐκεῖνος ἀρχὴν πολέμου ποιήσας ἠνάγκασε μὲν τὴν αὑτοῦ πατρίδα συνεξαναστῆναι τοῖς καιροῖς, ἠνάγκασε δὲ τὸν Ἄτταλον μὴ μέλλειν καὶ παρασκευάζεσθαι τὰ πρὸς τὸν πόλεμον, ἀλλὰ πολεμεῖν ἐρρωμένως καὶ κινδυνεύειν. τοιγαροῦν εἰκότως αὐτὸν οἱ Ῥόδιοι καὶ μεταλλάξαντα τοιαύταις ἐτίμησαν τιμαῖς δι’ ὧν οὐ μόνον τοὺς ζῶντας, ἀλλὰ καὶ τοὺς ἐπιγενομένους ἐξεκαλέσαντο πρὸς τοὺς ὑπὲρ τῆς πατρίδος καιρούς. —", "st": "16.9"}, {"sp": "N", "t": "ὅτι μετὰ τὸ συντελεσθῆναι τὴν περὶ τὴν Λάδην ναυμαχίαν καὶ τοὺς μὲν Ῥοδίους ἐκποδὼν γενέσθαι, τὸν δ’ Ἄτταλον μηδέπω συμμεμιχέναι, δῆλον ὡς ἐξῆν γε τελεῖν τῷ Φιλίππῳ τὸν εἰς τὴν Ἀλεξάνδρειαν πλοῦν. ἐξ οὗ δὴ καὶ μάλιστ’ ἄν τις καταμάθοι τὸ μανιώδη γενόμενον Φίλιππον τοῦτο πρᾶξαι. — τί οὖν ἦν τὸ τῆς ὁρμῆς ἐπιλαβόμενον; οὐδὲν ἕτερον ἀλλ’ ἡ φύσις τῶν πραγμάτων. ἐκ πολλοῦ μὲν γὰρ ἐνίοτε πολλοὶ τῶν ἀδυνάτων ἐφίενται διὰ τὸ μέγεθος τῶν προφαινομένων ἐλπίδων, κρατούσης τῆς ἐπιθυμίας τῶν ἑκάστου λογισμῶν· ὅταν δ’ ἐγγίσωσι τοῖς ἔργοις, οὐδενὶ λόγῳ πάλιν ἀφίστανται τῶν προθέσεων, ἐπισκοτούμενοι καὶ παραλογιζόμενοι τοῖς λογισμοῖς διὰ τὴν ἀμηχανίαν καὶ τὴν δυσχρηστίαν τῶν ἀπαντωμένων. —", "st": "16.10"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ ποιησάμενος ὁ Φίλιππός τινας ἀπράκτους προσβολὰς διὰ τὴν ὀχυρότητα τοῦ πολίσματος αὖθις ἀπεχώρει, πορθῶν τὰ φρούρια καὶ τὰς κατὰ τὴν χώραν συνοικίας. ὅθεν ἀπαλλαττόμενος προσεστρατοπέδευσε τῇ Πρινασσῷ. ταχὺ δὲ γέρρα καὶ τὴν τοιαύτην ἑτοιμάσας παρασκευὴν ἤρξατο πολιορκεῖν διὰ τῶν μετάλλων. οὔσης δ’ ἀπράκτου τῆς ἐπιβολῆς αὐτῷ διὰ τὸ πετρώδη τὸν τόπον ὑπάρχειν ἐπινοεῖ τι τοιοῦτον. τὰς μὲν ἡμέρας ψόφον ἐποίει κατὰ γῆς, ὡς ἐνεργουμένων τῶν μετάλλων, τὰς δὲ νύκτας ἔξωθεν ἔφερε χοῦν καὶ παρέβαλλε παρὰ τὰ στόμια τῶν ὀρυγμάτων, ὥστε διὰ τοῦ πλήθους τῆς σωρευομένης γῆς στοχαζομένους καταπλαγεῖς γενέσθαι τοὺς ἐν τῇ πόλει. τὰς μὲν οὖν ἀρχὰς ὑπέμενον οἱ Πρινασσεῖς εὐγενῶς· ἐπεὶ δὲ προσπέμψας ὁ Φίλιππος ἐνεφάνιζε διότι πρὸς δύο πλέθρα τοῦ τείχους αὐτοῖς ἐξήρεισται, καὶ προσεπυνθάνετο πότερα βούλονται λαβόντες τὴν ἀσφάλειαν ἐκχωρεῖν ἢ μετὰ τῆς πόλεως συναπολέσθαι πανδημεί, τῶν ἐρεισμάτων ἐμπρησθέντων, τηνικάδε πιστεύσαντες τοῖς λεγομένοις παρέδοσαν τὴν πόλιν. —", "st": "16.11"}, {"sp": "N", "t": "ἡ δὲ τῶν Ἰασέων πόλις κεῖται μὲν ἐπὶ τῆς Ἀσίας ἐν τῷ κόλπῳ τῷ μεταξὺ κειμένῳ τοῦ τῆς Μιλησίας Ποσειδίου καὶ τῆς Μυνδίων πόλεως, προσαγορευομένῳ, παρὰ δὲ τοῖς πλείστοις Βαργυλιητικῷ συνωνύμως ταῖς περὶ τὸν μυχὸν αὐτοῦ πόλεσιν ἐκτισμέναις. εὔχονται δὲ τὸ μὲν ἀνέκαθεν Ἀργείων ἄποικοι γεγονέναι, μετὰ δὲ ταῦτα Μιλησίων, ἐπαγαγομένων τῶν προγόνων τὸν Νηλέως υἱὸν τοῦ κτίσαντος Μίλητον διὰ τὴν ἐν τῷ Καρικῷ πολέμῳ γενομένην φθορὰν αὐτῶν. τὸ δὲ μέγεθος τῆς πόλεώς ἐστι δέκα στάδια. καταπεφήμισται δὲ καὶ πεπίστευται παρὰ μὲν τοῖς Βαργυλιήταις διότι τὸ τῆς Κινδυάδος Ἀρτέμιδος ἄγαλμα, καίπερ ὂν ὑπαίθριον, οὔτε νίφεται τὸ παράπαν οὔτε βρέχεται, παρὰ δὲ τοῖς Ἰασεῦσι τὸ τῆς Ἀστιάδος· καὶ ταῦτά τινες εἰρήκασι καὶ τῶν συγγραφέων. ἐγὼ δὲ πρὸς τὰς τοιαύτας ἀποφάσεις τῶν ἱστοριογράφων οὐκ οἶδ’ ὅπως παρ’ ὅλην τὴν πραγματείαν ἐναντιούμενος καὶ δυσανασχετῶν διατελῶ. δοκεῖ γάρ μοι τὰ τοιαῦτα παντάπασι παιδικῆς εὐηθείας ὅσα μὴ μόνον τῆς τῶν εὐλόγων ἐκτὸς πίπτει θεωρίας, ἀλλὰ καὶ τῆς τοῦ δυνατοῦ. τὸ γὰρ φάσκειν ἔνια τῶν σωμάτων ἐν φωτὶ τιθέμενα μὴ ποιεῖν σκιὰν ἀπηλγηκυίας ἐστὶ ψυχῆς· ὃ πεποίηκε Θεόπομπος, φήσας τοὺς εἰς τὸ τοῦ Διὸς ἄβατον ἐμβάντας κατ’ Ἀρκαδίαν ἀσκίους γίνεσθαι. τούτῳ δὲ παραπλήσιόν ἐστι καὶ τὸ νυνὶ λεγόμενον. ὅσα μὲν οὖν συντείνει πρὸς τὸ διασῴζειν τὴν τοῦ πλήθους εὐσέβειαν πρὸς τὸ θεῖον, δοτέον ἐστὶ συγγνώμην ἐνίοις τῶν συγγραφέων τερατευομένοις καὶ λογοποιοῦσι περὶ τὰ τοιαῦτα· τὸ δ’ ὑπεραῖρον οὐ συγχωρητέον. τάχα μὲν οὖν ἐν παντὶ δυσπαράγραφός ἐστιν ἡ ποσότης, οὐ μὴν ἀπαράγραφός γε. διὸ καὶ παρὰ βραχὺ μὲν εἰ καὶ ἀγνοεῖται καὶ ψευδοδοξεῖται, δεδόσθω συγγνώμη, τὸ δ’ ὑπεραῖρον ἀθετείσθω κατά γε τὴν ἐμὴν δόξαν.", "st": "16.12"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Πελοπόννησον τίνα μὲν ἐξ ἀρχῆς προαίρεσιν ἐνεστήσατο Νάβις ὁ τῶν Λακεδαιμονίων τύραννος, καὶ πῶς ἐκβαλὼν τοὺς πολίτας ἠλευθέρωσε τοὺς δούλους καὶ συνῴκισε ταῖς τῶν δεσποτῶν γυναιξὶ καὶ θυγατράσιν, ὁμοίως δὲ καὶ τίνα τρόπον ἀναδείξας τὴν ἑαυτοῦ δύναμιν οἷον ἄσυλον ἱερὸν τοῖς ἢ δι’ ἀσέβειαν ἢ πονηρίαν φεύγουσι τὰς ἑαυτῶν πατρίδας ἥθροισε πλῆθος ἀνθρώπων ἀνοσίων εἰς τὴν Σπάρτην, ἐν τοῖς πρὸ τούτων δεδηλώκαμεν. πῶς δὲ καὶ τίνα τρόπον κατὰ τοὺς προειρημένους καιροὺς σύμμαχος ὑπάρχων Αἰτωλοῖς, Ἠλείοις, Μεσσηνίοις, καὶ πᾶσι τούτοις ὀφείλων καὶ κατὰ τοὺς ὅρκους καὶ κατὰ τὰς συνθήκας βοηθεῖν, εἴ τις ἐπ’ αὐτοὺς ἴοι, παρ’ οὐδὲν ποιησάμενος τὰς προειρημένας πίστεις ἐπεβάλετο παρασπονδῆσαι τὴν τῶν Μεσσηνίων πόλιν, νῦν ἐροῦμεν. —", "st": "16.13"}, {"sp": "N", "t": "ὅτι φησὶ Πολύβιος ἐπεὶ δέ τινες τῶν τὰς κατὰ μέρος γραφόντων πράξεις γεγράφασι καὶ περὶ τούτων τῶν καιρῶν, ἐν οἷς τά τε κατὰ Μεσσηνίους καὶ τὰ κατὰ τὰς προειρημένας ναυμαχίας συνετελέσθη, βούλομαι βραχέα περὶ αὐτῶν διαλεχθῆναι. ποιήσομαι δ’ οὐ πρὸς ἅπαντας, ἀλλ’ ὅσους ὑπολαμβάνω μνήμης ἀξίους εἶναι καὶ διαστολῆς· εἰσὶ δ’ οὗτοι Ζήνων καὶ Ἀντισθένης οἱ Ῥόδιοι. τούτους δ’ ἀξίους εἶναι κρίνω διὰ πλείους αἰτίας. καὶ γὰρ κατὰ τοὺς καιροὺς γεγόνασι καὶ προσέτι πεπολίτευνται καὶ καθόλου πεποίηνται τὴν πραγματείαν οὐκ ὠφελείας χάριν, ἀλλὰ δόξης καὶ τοῦ καθήκοντος ἀνδράσι πολιτικοῖς. τῷ δὲ τὰς αὐτὰς γράφειν ἡμῖν πράξεις ἀναγκαῖόν ἐστι μὴ παρασιωπᾶν, ἵνα μὴ τῷ τῆς πατρίδος ὀνόματι καὶ τῷ δοκεῖν οἰκειοτάτας εἶναι Ῥοδίοις τὰς κατὰ θάλατταν πράξεις, ἡμῶν ἀντιδοξούντων πρὸς αὐτοὺς ἐνίοτε, μᾶλλον ἐπακολουθήσωσιν ἐκείνοις ἤπερ ἡμῖν οἱ φιλομαθοῦντες. οὗτοι τοιγαροῦν ἀμφότεροι πρῶτον μὲν τὴν περὶ Λάδην ναυμαχίαν οὐχ ἥττω τῆς περὶ Χίον, ἀλλ’ ἐνεργεστέραν καὶ παραβολωτέραν ἀποφαίνουσι καὶ τῇ κατὰ μέρος τοῦ κινδύνου χρείᾳ καὶ συντελείᾳ καὶ καθόλου φασὶ τὸ νίκημα γεγονέναι κατὰ τοὺς Ῥοδίους. ἐγὼ δὲ διότι μὲν δεῖ ῥοπὰς διδόναι ταῖς αὑτῶν πατρίσι τοὺς συγγραφέας, συγχωρήσαιμ’ ἄν, οὐ μὴν τὰς ἐναντίας τοῖς συμβεβηκόσιν ἀποφάσεις ποιεῖσθαι περὶ αὐτῶν. ἱκανὰ γὰρ τὰ κατ’ ἄγνοιαν γινόμενα τοῖς γράφουσιν, ἃ διαφυγεῖν ἄνθρωπον δυσχερές· ἐὰν δὲ κατὰ προαίρεσιν ψευδογραφῶμεν ἢ πατρίδος ἕνεκεν ἢ φίλων [ἢ] χάριτος, τί διοίσομεν τῶν ἀπὸ τούτου τὸν βίον ποριζομένων; ὥσπερ γὰρ ἐκεῖνοι τῷ λυσιτελεῖ μετροῦντες ἀδοκίμους ποιοῦσι τὰς αὑτῶν συντάξεις, οὕτως οἱ πολιτικοὶ τῷ μισεῖν ἢ τῷ φιλεῖν ἑλκόμενοι πολλάκις εἰς ταὐτὸ τέλος ἐμπίπτουσι τοῖς προειρημένοις. διὸ δεῖ καὶ τοῦτο τὸ μέρος ἐπιμελῶς τοὺς μὲν ἀναγινώσκοντας παρατηρεῖν, τοὺς δὲ γράφοντας αὐτοὺς παραφυλάττεσθαι.", "st": "16.14"}, {"sp": "N", "t": "δῆλον δ’ ἔστι τὸ λεγόμενον ἐκ τῶν ἐνεστώτων. ὁμολογοῦντες γὰρ οἱ προειρημένοι διὰ τῶν κατὰ μέρος ἐν τῇ περὶ Λάδην ναυμαχίᾳ δύο μὲν αὐτάνδρους πεντήρεις τῶν Ῥοδίων ὑποχειρίους γενέσθαι τοῖς πολεμίοις, ἐκ δὲ τοῦ κινδύνου μιᾶς νηὸς ἐπαραμένης τὸν δόλωνα διὰ τὸ τετρωμένην αὐτὴν θαλαττοῦσθαι, πολλοὺς καὶ τῶν ἐγγὺς τὸ παραπλήσιον ποιοῦντας ἀποχωρεῖν πρὸς τὸ πέλαγος, τέλος δὲ μετ’ ὀλίγων καταλειφθέντα τὸν ναύαρχον ἀναγκασθῆναι ταὐτὸ τοῖς προειρημένοις πράττειν, καὶ τότε μὲν εἰς τὴν Μυνδίαν ἀπουρώσαντας καθορμισθῆναι, τῇ δ’ ἐπαύριον ἀναχθέντας εἰς Κῶ διᾶραι, τοὺς δὲ πολεμίους τὰς πεντήρεις ἐνάψασθαι καὶ καθορμισθέντας ἐπὶ τὴν Λάδην ἐπὶ τῇ ’κείνων στρατοπεδείᾳ ποιήσασθαι τὴν ἔπαυλιν, ἔτι δὲ τοὺς Μιλησίους, καταπλαγέντας τὸ γεγονός, οὐ μόνον τὸν Φίλιππον, ἀλλὰ καὶ τὸν Ἡρακλείδην στεφανῶσαι διὰ τὴν ἔφοδον, ταῦτα δ’ εἰρηκότες ἃ προφανῶς ἐστιν ἴδια τῶν ἡττημένων, ὅμως καὶ διὰ τῶν κατὰ μέρος καὶ διὰ τῆς καθολικῆς ἀποφάσεως νικῶντας ἀποφαίνουσι τοὺς Ῥοδίους, καὶ ταῦτα τῆς ἐπιστολῆς ἔτι μενούσης ἐν τῷ πρυτανείῳ τῆς ὑπ’ αὐτοὺς τοὺς καιροὺς ὑπὸ τοῦ ναυάρχου πεμφθείσης περὶ τούτων τῇ τε βουλῇ καὶ τοῖς πρυτάνεσιν, οὐ ταῖς Ἀντισθένους καὶ Ζήνωνος ἀποφάσεσι συμφωνούσης ἀλλὰ ταῖς ἡμετέραις.", "st": "16.15"}, {"sp": "N", "t": "ἑξῆς δὲ τοῖς προειρημένοις γράφουσι περὶ τοῦ κατὰ Μεσσηνίους παρασπονδήματος. ἐν ᾧ φησιν ὁ Ζήνων ὁρμήσαντα τὸν Νάβιν ἐκ τῆς. Λακεδαίμονος καὶ διαβάντα τὸν Εὐρώταν ποταμὸν παρὰ τὸν Ὁπλίτην προσαγορευόμενον πορεύεσθαι διὰ τῆς ὁδοῦ τῆς στενῆς παρὰ τὸ Πολιάσιον, ἕως ἐπὶ τοὺς κατὰ Σελλασίαν ἀφίκετο τόπους· ἐντεῦθεν δ’ ἐπὶ Θαλάμας ἐπιβαλόντα κατὰ Φαρὰς παραγενέσθαι πρὸς τὸν Πάμισον ποταμόν. ὑπὲρ ὧν οὐκ οἶδα πῶς χρὴ λέγειν· τοιαύτην γὰρ φύσιν ἔχει τὰ προειρημένα πάντα συλλήβδην ὥστε μηδὲν διαφέρειν τοῦ λέγειν ὅτι ποιησάμενός τις ἐκ Κορίνθου τὴν ὁρμὴν καὶ διαπορευθεὶς τὸν Ἰσθμὸν καὶ συνάψας ταῖς Σκειρωνίσιν εὐθέως ἐπὶ τὴν Κοντοπορίαν ἐπέβαλε καὶ παρὰ τὰς Μυκήνας ἐποιεῖτο τὴν πορείαν εἰς Ἄργος. ταῦτα γὰρ οὐχ οἷον παρὰ μικρόν ἐστιν, ἀλλὰ τὴν ἐναντίαν διάθεσιν ἔχει πρὸς ἄλληλα, καὶ τὰ μὲν κατὰ τὸν Ἰσθμόν ἐστι καὶ τὰς Σκιράδας πρὸς ἀνατολὰς τοῦ Κορίνθου, τὰ δὲ κατὰ τὴν Κοντοπορίαν καὶ Μυκήνας ἔγγιστα πρὸς δύσεις χειμερινάς, ὥστ’ εἶναι τελέως ἀδύνατον ἀπὸ τῶν προηγουμένων ἐπιβαλεῖν τοῖς προειρημένοις τόποις. τὸ δ’ αὐτὸ καὶ περὶ τοὺς κατὰ τὴν Λακεδαίμονα συμβέβηκεν· ὁ μὲν γὰρ Εὐρώτας καὶ τὰ περὶ τὴν Σελλασίαν κεῖται τῆς Σπάρτης ὡς πρὸς τὰς θερινὰς ἀνατολάς, τὰ δὲ κατὰ Θαλάμας καὶ Φαρὰς καὶ Πάμισον ὡς πρὸς τὰς χειμερινὰς δύσεις, ὅθεν οὐχ οἷον ἐπὶ τὴν Σελλασίαν, ἀλλ’ οὐδὲ τὸν Εὐρώταν δέον ἐστὶ διαβαίνειν τὸν προτιθέμενον παρὰ Θαλάμας ποιεῖσθαι τὴν πορείαν εἰς τὴν Μεσσηνίαν.", "st": "16.16"}, {"sp": "N", "t": "πρὸς δὲ τούτοις φησὶ τὴν ἐπάνοδον ἐκ τῆς Μεσσήνης πεποιῆσθαι τὸν Νάβιν κατὰ τὴν πύλην τὴν φέρουσαν ἐπὶ Τεγέαν. τοῦτο δ’ ἔστιν ἄλογον· πρόκειται γὰρ τῆς Τεγέας ἡ Μεγάλη πόλις ὡς πρὸς τὴν Μεσσήνην, ὥστ’ ἀδύνατον εἶναι καλεῖσθαί τινα πύλην παρὰ τοῖς Μεσσηνίοις ἐπὶ Τεγέαν. ἀλλ’ ἔστι παρ’ αὐτοῖς πύλη Τεγεᾶτις προσαγορευομένη, καθ’ ἣν ἐποιήσατο τὴν ἐπάνοδον Νάβις· ᾧ πλανηθεὶς ἔγγιον ὑπέλαβε τὴν Τεγέαν εἶναι Μεσσηνίων. τὸ δ’ ἔστιν οὐ τοιοῦτον, ἀλλ’ ἡ Λακωνικὴ καὶ [ἡ] Μεγαλοπολῖτις χώρα μεταξὺ κεῖται τῆς Μεσσηνίας καὶ Τεγεάτιδος. τὸ δὲ τελευταῖον· φησὶ γὰρ τὸν Ἀλφειὸν ἐκ τῆς πηγῆς εὐθέως κρυφθέντα καὶ πολὺν ἐνεχθέντα τόπον ὑπὸ γῆς ἐκβάλλειν περὶ Λυκόαν τῆς Ἀρκαδίας. ὁ δὲ ποταμὸς οὐ πολὺν τόπον ἀποσχὼν τῆς πηγῆς, καὶ κρυφθεὶς ἐπὶ δέκα στάδια, πάλιν ἐκπίπτει, καὶ τὸ λοιπὸν φερόμενος διὰ τῆς Μεγαλοπολίτιδος τὰς μὲν ἀρχὰς ἐλαφρός, εἶτα λαμβάνων αὔξησιν καὶ διανύσας ἐπιφανῶς πᾶσαν τὴν προειρημένην χώραν ἐπὶ διακοσίους σταδίους γίνεται πρὸς Λυκόαν, ἤδη προσειληφὼς καὶ τὸ τοῦ Λουσίου ῥεῦμα καὶ παντελῶς ἄβατος ὢν καὶ βαρύς. οὐ μὴν ἀλλὰ καὶ πάντα μοι δοκεῖ τὰ προειρημένα διαπτώματα μὲν εἶναι, πρόφασιν δ’ ἐπιδέχεσθαι καὶ παραίτησιν· τὰ μὲν γὰρ δι’ ἄγνοιαν γέγονε, τὸ δὲ περὶ τὴν ναυμαχίαν διὰ τὴν πρὸς τὴν πατρίδα φιλοστοργίαν. τί τις οὖν εἰκότως ἂν Ζήνωνι μέμψαιτο; διότι τὸ πλεῖον οὐ περὶ τὴν τῶν πραγμάτων ζήτησιν οὐδὲ περὶ τὸν χειρισμὸν τῆς ὑποθέσεως, ἀλλὰ περὶ τὴν τῆς λέξεως κατασκευὴν ἐσπούδακε, καὶ δῆλός ἐστι πολλάκις ἐπὶ τούτῳ σεμνυνόμενος, καθάπερ καὶ πλείους ἕτεροι τῶν ἐπιφανῶν συγγραφέων; ἐγὼ δὲ φημὶ μὲν δεῖν πρόνοιαν ποιεῖσθαι καὶ σπουδάζειν ὑπὲρ τοῦ δεόντως ἐξαγγέλλειν τὰς πράξεις — δῆλον γὰρ ὡς οὐ μικρά, μεγάλα δὲ συμβάλλεται τοῦτο πρὸς τὴν ἱστορίαν — οὐ μὴν ἡγεμονικώτατόν γε καὶ πρῶτον αὐτὸ παρὰ τοῖς μετρίοις ἀνδράσι τίθεσθαι· πολλοῦ γε δεῖν· ἄλλα γὰρ ἂν εἴη καλλίω μέρη τῆς ἱστορίας, ἐφ’ οἷς ἂν μᾶλλον σεμνυνθείη πολιτικὸς ἀνήρ.", "st": "16.17"}, {"sp": "N", "t": "ὃ δὲ λέγειν βούλομαι, γένοιτ’ ἂν οὕτω μάλιστα καταφανές. ἐξηγούμενος γὰρ ὁ προειρημένος συγγραφεὺς τήν τε Γάζης πολιορκίαν καὶ τὴν γενομένην παράταξιν Ἀντιόχου πρὸς Σκόπαν ἐν Κοίλῃ Συρίᾳ περὶ τὸ Πάνιον, περὶ μὲν τὴν τῆς λέξεως κατασκευὴν δῆλός ἐστιν ἐπὶ τοσοῦτον ἐσπουδακὼς ὡς ὑπερβολὴν τερατείας μὴ καταλιπεῖν τοῖς τὰς ἐπιδεικτικὰς καὶ πρὸς ἔκπληξιν τῶν πολλῶν συντάξεις ποιουμένοις, τῶν γε μὴν πραγμάτων ἐπὶ τοσοῦτον ὠλιγώρηκεν ὥστε πάλιν ἀνυπέρβλητον εἶναι τὴν εὐχέρειαν καὶ τὴν ἀπειρίαν τοῦ συγγραφέως. προθέμενος γὰρ πρώτην διασαφεῖν τὴν τῶν περὶ τὸν Σκόπαν ἔκταξιν, τῷ μὲν δεξιῷ κέρατί φησι τῆς ὑπωρείας ἔχεσθαι τὴν φάλαγγα μετ’ ὀλίγων ἱππέων, τὸ δ’ εὐώνυμον αὐτῆς καὶ τοὺς ἱππεῖς πάντας τοὺς ἐπὶ τούτου τεταγμένους ἐν τοῖς ἐπιπέδοις κεῖσθαι. τὸν δ’ Ἀντίοχον ἐπὶ μὲν τὴν ἑωθινὴν ἐκπέμψαι φησὶ τὸν πρεσβύτερον υἱὸν Ἀντίοχον ἔχοντα μέρος τι τῆς δυνάμεως, ἵνα προκαταλάβηται τῆς ὀρεινῆς τοὺς ὑπερκειμένους τῶν πολεμίων τόπους, τὴν δὲ λοιπὴν δύναμιν ἅμα τῷ φωτὶ διαβιβάσαντα τὸν ποταμὸν τὸν μεταξὺ τῶν στρατοπέδων ἐν τοῖς ἐπιπέδοις ἐκτάττειν, τιθέντα τοὺς μὲν φαλαγγίτας ἐπὶ μίαν εὐθεῖαν κατὰ μέσην τὴν τῶν πολεμίων τάξιν, τῶν δ’ ἱππέων τοὺς μὲν ἐπὶ τὸ λαιὸν κέρας τῆς φάλαγγος, τοὺς δ’ ἐπὶ τὸ δεξιόν, ἐν οἷς εἶναι καὶ τὴν κατάφρακτον ἵππον, ἧς ἡγεῖτο πάσης ὁ νεώτερος Ἀντίοχος τῶν υἱῶν. μετὰ δὲ ταῦτά φησι τὰ θηρία προτάξαι τῆς φάλαγγος ἐν διαστήματι καὶ τοὺς μετ’ Ἀντιπάτρου Ταραντίνους, τὰ δὲ μεταξὺ τῶν θηρίων πληρῶσαι τοῖς τοξόταις καὶ σφενδονήταις, αὐτὸν δὲ μετὰ τῆς ἑταιρικῆς ἵππου καὶ τῶν ὑπασπιστῶν κατόπιν ἐπιστῆναι τοῖς θηρίοις. ταῦτα δ’ ὑποθέμενος, τὸν μὲν νεώτερον Ἀντίοχόν φησιν, ὃν ἐν τοῖς ἐπιπέδοις ἔθηκε κατὰ τὸ λαιὸν τῶν πολεμίων ἔχοντα τὴν κατάφρακτον ἵππον, τοῦτον ἐκ τῆς ὀρεινῆς ἐπενεχθέντα τρέψασθαι τοὺς ἱππέας τοὺς περὶ τὸν Πτολεμαῖον τὸν Ἀερόπου καὶ καταδιώκειν, ὃς ἐτύγχανε τοῖς Αἰτωλοῖς ἐπιτεταγμένος ἐν τοῖς ἐπιπέδοις ἐπὶ τῶν εὐωνύμων, τὰς δὲ φάλαγγας, ἐπεὶ συνέβαλλον ἀλλήλαις, μάχην ποιεῖν ἰσχυράν. ὅτι δὲ συμβαλεῖν ἀδύνατον ἦν τῶν θηρίων καὶ τῶν ἱππέων καὶ τῶν εὐζώνων προτεταγμένων, τοῦτ’ οὐκέτι συνορᾷ.", "st": "16.18"}, {"sp": "N", "t": "μετὰ δὲ ταῦτά φησι καταπροτερουμένην τὴν φάλαγγα ταῖς εὐχειρίαις καὶ πιεζομένην ὑπὸ τῶν Αἰτωλῶν ἀναχωρεῖν ἐπὶ πόδα, τὰ δὲ θηρία τοὺς ἐγκλίνοντας ἐκδεχόμενα καὶ συμπίπτοντα τοῖς πολεμίοις μεγάλην παρέχεσθαι χρείαν. πῶς δὲ ταῦτα γέγονεν ὀπίσω τῆς φάλαγγος οὐ ῥᾴδιον καταμαθεῖν, ἢ πῶς γενόμενα παρείχετο χρείαν μεγάλην· ὅτε γὰρ ἅπαξ αἱ φάλαγγες συνέπεσον ἀλλήλαις, οὐκέτι δυνατὸν ἦν κρῖναι τὰ θηρία τίς τῶν ὑποπιπτόντων φίλιος ἢ πολέμιός ἐστι. πρὸς δὲ τούτοις φησὶ τοὺς Αἰτωλῶν ἱππέας δυσχρηστεῖσθαι κατὰ τὸν κίνδυνον διὰ τὴν ἀσυνήθειαν τῆς τῶν θηρίων φαντασίας. ἀλλ’ οἱ μὲν ἐπὶ τοῦ δεξιοῦ ταχθέντες ἐξ ἀρχῆς ἀκέραιοι διέμενον, ὡς αὐτός φησι· τὸ δὲ λοιπὸν πλῆθος τῶν ἱππέων τὸ μερισθὲν ἐπὶ τὸ λαιὸν ἐπεφεύγει πᾶν ὑπὸ τῶν περὶ τὸν Ἀντίοχον ἡττημένον. ποῖον οὖν μέρος τῶν ἱππέων ἦν κατὰ μέσην τὴν φάλαγγα τὸ τοὺς ἐλέφαντας ἐκπληττόμενον; ποῦ δ’ ὁ βασιλεὺς γέγονεν, ἢ τίνα παρέσχηται χρείαν ἐν τῇ μάχῃ, τὸ κάλλιστον σύστημα περὶ αὑτὸν ἐσχηκὼς καὶ τῶν πεζῶν καὶ τῶν ἱππέων; ἁπλῶς γὰρ οὐδὲν εἴρηται περὶ τούτων. ποῦ δ’ ὁ πρεσβύτερος τῶν υἱῶν Ἀντίοχος ὁ μετὰ μέρους τινὸς τῆς δυνάμεως προκαταλαβόμενος τοὺς ὑπερδεξίους τόπους; οὗτος μὲν γὰρ οὐδ’ εἰς τὴν στρατοπεδείαν ἀνακεχώρηκεν αὐτῷ μετὰ τὴν μάχην. εἰκότως· δύο γὰρ Ἀντιόχους ὑπέθετο τοῦ βασιλέως υἱούς, ὄντος ἑνὸς τοῦ τότε συνεστρατευμένου. πῶς δ’ ὁ Σκόπας ἅμα μὲν αὐτῷ πρῶτος, ἅμα δ’ ἔσχατος ἀναλέλυκεν ἐκ τοῦ κινδύνου; φησὶ γὰρ αὐτὸν ἰδόντα τοὺς περὶ τὸν νεώτερον Ἀντίοχον ἐκ τοῦ διώγματος ἐπιφαινομένους κατὰ νώτου τοῖς φαλαγγίταις, καὶ διὰ τοῦτο τὰς τοῦ νικᾶν ἐλπίδας ἀπογνόντα, ποιεῖσθαι τὴν ἀποχώρησιν· μετὰ δὲ ταῦτα συστῆναι τὸν μέγιστον κίνδυνον, κυκλωθείσης τῆς φάλαγγος ὑπό τε τῶν θηρίων καὶ τῶν ἱππέων, καὶ τελευταῖον ἀποχωρῆσαι τὸν Σκόπαν ἀπὸ τοῦ κινδύνου.", "st": "16.19"}, {"sp": "N", "t": "ταῦτα δέ μοι δοκεῖ, καὶ καθόλου τὰ τοιαῦτα τῶν ἀλογημάτων, πολλὴν ἐπιφέρειν αἰσχύνην τοῖς συγγραφεῦσι. διὸ δεῖ μάλιστα μὲν πειρᾶσθαι πάντων κρατεῖν τῶν τῆς ἱστορίας μερῶν· καλὸν γάρ· εἰ δὲ μὴ τοῦτο δυνατόν, τῶν ἀναγκαιοτάτων καὶ τῶν μεγίστων ἐν αὐτῇ πλείστην ποιεῖσθαι πρόνοιαν. ταῦτα μὲν οὖν προήχθην εἰπεῖν, θεωρῶν νῦν, καθάπερ καὶ ἐπὶ τῶν ἄλλων τεχνῶν καὶ ἐπιτηδευμάτων, τὸ μὲν ἀληθινὸν καὶ πρὸς τὴν χρείαν ἀνῆκον ἐν ἑκάστοις ἐπισεσυρμένον, τὸ δὲ πρὸς ἀλαζονείαν καὶ φαντασίαν ἐπαινούμενον καὶ ζηλούμενον, ὡς μέγα τι καὶ θαυμάσιον, ὃ καὶ τὴν κατασκευὴν ἔχει ῥᾳδιεστέραν καὶ τὴν εὐδόκησιν ὀλιγοδεεστέραν, καθάπερ αἱ λοιπαὶ τῶν γραφῶν. περὶ δὲ τῆς τῶν τόπων ἀγνοίας τῶν κατὰ τὴν Λακωνικὴν διὰ τὸ μεγάλην εἶναι τὴν παράπτωσιν οὐκ ὤκνησα γράψαι καὶ πρὸς αὐτὸν Ζήνωνα, κρίνων καλὸν εἶναι τὸ μὴ τὰς τῶν πέλας ἁμαρτίας ἴδια προτερήματα νομίζειν, καθάπερ ἔνιοι ποιεῖν εἰώθασιν, ἀλλὰ μὴ μόνον τῶν ἰδίων ὑπομνημάτων, ἀλλὰ καὶ τῶν ἀλλοτρίων, καθ’ ὅσον οἷοί τ’ ἐσμέν, ποιεῖσθαι πρόνοιαν καὶ διόρθωσιν χάριν τῆς κοινῆς ὠφελείας. ὁ δὲ λαβὼν τὴν ἐπιστολήν, καὶ γνοὺς ἀδύνατον οὖσαν τὴν μετάθεσιν διὰ τὸ προεκδεδωκέναι τὰς συντάξεις, ἐλυπήθη μὲν ὡς ἔνι μάλιστα, ποιεῖν δ’ οὐδὲν εἶχε, τήν γε μὴν ἡμετέραν αἵρεσιν ἀπεδέξατο φιλοφρόνως. ὃ δὴ κἂν ἐγὼ παρακαλέσαιμι περὶ αὑτοῦ τοὺς καθ’ ἡμᾶς καὶ τοὺς ἐπιγινομένους, ἐὰν μὲν κατὰ πρόθεσιν εὑρισκώμεθά που κατὰ τὴν πραγματείαν διαψευδόμενοι καὶ παρορῶντες τὴν ἀλήθειαν, ἀπαραιτήτως ἐπιτιμᾶν, ἐὰν δὲ κατ’ ἄγνοιαν, συγγνώμην ἔχειν, καὶ μάλιστα πάντων ἡμῖν διὰ τὸ μέγεθος τῆς συντάξεως καὶ διὰ τὴν καθόλου περιβολὴν τῶν πραγμάτων.", "st": "16.20"}, {"sp": "N", "t": "ὅτι ὁ Τληπόλεμος ὁ τὰ τῆς βασιλείας τῶν Αἰγυπτίων πράγματα μεταχειριζόμενος ἦν μὲν κατὰ τὴν ἡλικίαν νέος καὶ κατὰ τὸ συνεχὲς ἐν στρατιωτικῷ βίῳ διεγεγόνει μετὰ φαντασίας, ἦν δὲ καὶ τῇ φύσει μετέωρος καὶ φιλόδοξος, καὶ καθόλου πολλὰ μὲν εἰς πραγμάτων λόγον ἀγαθὰ προσεφέρετο, πολλὰ δὲ καὶ κακά. στρατηγεῖν μὲν γὰρ ἐν τοῖς ὑπαίθροις καὶ χειρίζειν πολεμικὰς πράξεις δυνατὸς ἦν, καὶ ἀνδρώδης ὑπῆρχε τῇ φύσει, καὶ πρὸς τὰς στρατιωτικὰς ὁμιλίας εὐφυῶς διέκειτο· πρὸς δὲ ποικίλων πραγμάτων χειρισμόν, δεόμενον ἐπιστάσεως καὶ νήψεως, καὶ πρὸς φυλακὴν χρημάτων καὶ καθόλου τὴν περὶ τὸ λυσιτελὲς οἰκονομίαν, ἀφυέστατος ὑπῆρχε πάντων. ᾗ καὶ ταχέως οὐ μόνον ἔσφηλεν, ἀλλὰ καὶ τὴν βασιλείαν ἠλάττωσε. παραλαβὼν γὰρ τὴν τῶν χρημάτων ἐξουσίαν, τὸ μὲν πλεῖστον μέρος τῆς ἡμέρας κατέτριβε σφαιρομαχῶν καὶ πρὸς τὰ μειράκια διαμιλλώμενος ἐν τοῖς ὅπλοις, ἀπὸ δὲ τούτων γινόμενος εὐθέως πότους συνῆγε καὶ τὸ πλεῖον μέρος τοῦ βίου περὶ ταῦτα καὶ σὺν τούτοις εἶχε τὴν διατριβήν. ὃν δέ ποτε χρόνον τῆς ἡμέρας ἀπεμέριζε πρὸς ἐντεύξεις, ἐν τούτῳ διεδίδου, μᾶλλον δ’, εἰ δεῖ τὸ φαινόμενον εἰπεῖν, διερρίπτει τὰ βασιλικὰ χρήματα τοῖς ἀπὸ τῆς Ἑλλάδος παραγεγονόσι πρεσβευταῖς καὶ τοῖς περὶ τὸν Διόνυσον τεχνίταις, μάλιστα δὲ τοῖς περὶ τὴν αὐλὴν ἡγεμόσι καὶ στρατιώταις. καθόλου γὰρ ἀνανεύειν οὐκ ᾔδει, τῷ δὲ πρὸς χάριν ὁμιλήσαντι πᾶν ἐξ ἑτοίμου τὸ φανὲν ἐδίδου. τὸ λοιπὸν ηὐξάνετο τὸ κακόν, ἐξ αὑτοῦ λαμβάνον τὴν ἐπίδοσιν. πᾶς γὰρ ὁ παθὼν εὖ παρὰ τὴν προσδοκίαν καὶ τοῦ γεγονότος χάριν καὶ τοῦ μέλλοντος ὑπερεβάλλετο ταῖς τῶν λόγων εὐχαριστίαις· ὁ δὲ πυνθανόμενος τὸν γινόμενον ἐκ πάντων ἔπαινον ὑπὲρ αὑτοῦ καὶ τὰς ἐν τοῖς πότοις ἐπιχύσεις, ἔτι δὲ τὰς ἐπιγραφὰς καὶ τὰ διὰ τῶν ἀκροαμάτων εἰς αὑτὸν ᾀδόμενα παίγνια καθ’ ὅλην τὴν πόλιν, εἰς τέλος ἐχαυνοῦτο καὶ μᾶλλον ἀεὶ καὶ μᾶλλον ἐξετυφοῦτο, καὶ προχειρότερος ἐγίνετο πρὸς τὰς ξενικὰς καὶ στρατιωτικὰς χάριτας.", "st": "16.21"}, {"sp": "N", "t": "ἐφ’ οἷς οἱ περὶ τὴν αὐλὴν ἀσχάλλοντες πάντα παρεσημαίνοντο καὶ βαρέως αὐτοῦ τὴν αὐθάδειαν ὑπέφερον, τὸν δὲ Σωσίβιον ἐκ παραθέσεως ἐθαύμαζον. ἐδόκει γὰρ οὗτος τοῦ τε βασιλέως προεστάναι φρονιμώτερον ἢ κατὰ τὴν ἡλικίαν, τήν τε πρὸς τοὺς ἐκτὸς ἀπάντησιν ἀξίαν ποιεῖσθαι τῆς ἐγκεχειρισμένης αὐτῷ πίστεως· αὕτη δ’ ἦν ἡ σφραγὶς καὶ τὸ τοῦ βασιλέως σῶμα. κατὰ δὲ τὸν καιρὸν τοῦτον ἀνακομιζόμενος ἥκει παρὰ τοῦ Φιλίππου Πτολεμαῖος ὁ Σωσιβίου. καὶ πρὶν μὲν οὖν ἐκ τῆς Ἀλεξανδρείας ἐκπλεῦσαι πλήρης ἦν τύφου διά τε τὴν ἰδίαν φύσιν καὶ διὰ τὴν προσγεγενημένην ἐκ τοῦ πατρὸς εὐκαιρίαν· ὡς δὲ καταπλεύσας εἰς τὴν Μακεδονίαν συνέμιξε τοῖς περὶ τὴν αὐλὴν νεανίσκοις, ὑπολαβὼν εἶναι τὴν Μακεδόνων ἀνδρείαν ἐν τῇ τῆς ὑποδέσεως καὶ τῇ τῆς ἐσθῆτος διαφορᾷ, παρῆν ταῦτα πάντ’ ἐζηλωκὼς καὶ πεπεισμένος αὑτὸν μὲν ἄνδρα γεγονέναι διὰ τὴν ἐκδημίαν καὶ διὰ τὸ Μακεδόσιν ὡμιληκέναι, τοὺς δὲ κατὰ τὴν Ἀλεξάνδρειαν ἀνδράποδα καὶ βλᾶκας διαμένειν. διόπερ εὐθέως ἐζηλοτύπει καὶ παρετρίβετο πρὸς τὸν Τληπόλεμον. πάντων δ’ αὐτῷ συγκατατιθεμένων τῶν περὶ τὴν αὐλὴν διὰ τὸ τὸν Τληπόλεμον καὶ τὰ πράγματα καὶ τὰ χρήματα μὴ ὡς ἐπίτροπον, ἀλλ’ ὡς κληρονόμον χειρίζειν, ταχέως ηὐξήθη τὰ τῆς διαφορᾶς. καθ’ ὃν καιρὸν ὁ Τληπόλεμος, προσπιπτόντων αὐτῷ λόγων δυσμενικῶν ἐκ τῆς τῶν αὐλικῶν παρατηρήσεως καὶ κακοπραγμοσύνης, τὰς μὲν ἀρχὰς παρήκουε καὶ κατεφρόνει τῶν λεγομένων. ὡς δέ ποτε καὶ κοινῇ συνεδρεύσαντες ἐτόλμησαν ἐν τῷ μέσῳ καταμέμφεσθαι τὸν Τληπόλεμον, ὡς κακῶς χειρίζοντα τὰ κατὰ τὴν βασιλείαν, οὐ παρόντος αὐτοῦ, τότε δὴ παροξυνθεὶς συνῆγε τὸ συνέδριον καὶ παρελθὼν ἐκείνους μὲν ἔφη λάθρᾳ καὶ κατ’ ἰδίαν ποιεῖσθαι κατ’ αὐτοῦ τὰς διαβολάς, αὐτὸς δ’ ἔκρινε κοινῇ καὶ κατὰ πρόσωπον αὐτῶν ποιήσασθαι τὴν κατηγορίαν. — ὅτι μετὰ τὴν δημηγορίαν ἔλαβε καὶ τὴν σφραγῖδα παρὰ Σωσιβίου, καὶ ταύτην παρειληφὼς ὁ Τληπόλεμος λοιπὸν ἤδη πάντα τὰ πράγματα κατὰ τὴν αὑτοῦ προαίρεσιν ἔπραττεν.", "st": "16.22"}, {"sp": "N", "t": "ὅτι Ἀντιόχου τοῦ βασιλέως τὴν τῶν Γαζαίων πόλιν πορθήσαντος φησὶν ὁ Πολύβιος· ἐμοὶ δὲ καὶ δίκαιον ἅμα καὶ πρέπον εἶναι δοκεῖ τὸ τοῖς Γαζαίοις ἀποδοῦναι τὴν καθήκουσαν μαρτυρίαν. οὐδὲν γὰρ διαφέροντες ἀνδρείᾳ τῶν κατὰ Κοίλην Συρίαν πρὸς τὰς πολεμικὰς πράξεις, ἐν κοινωνίᾳ πραγμάτων καὶ τῷ τηρεῖν τὴν πίστιν πολὺ διαφέρουσι καὶ συλλήβδην ἀνυπόστατον ἔχουσι τὴν τόλμαν. κατὰ γὰρ τὴν Περσῶν ἔφοδον ἐκπλαγέντων τῶν ἄλλων διὰ τὸ μέγεθος τῆς δυναστείας, καὶ πάντων ἐγχειρισάντων σφᾶς αὐτοὺς καὶ τὰς πατρίδας Μήδοις, μόνοι τὸ δεινὸν ὑπέμειναν πάντες, τὴν πολιορκίαν ἀναδεξάμενοι. κατὰ δὲ τὴν Ἀλεξάνδρου παρουσίαν οὐ μόνον τῶν ἄλλων παραδεδωκότων αὑτούς, ἀλλὰ καὶ Τυρίων ἐξηνδραποδισμένων μετὰ βίας, καὶ σχεδὸν ἀνελπίστου τῆς σωτηρίας ὑπαρχούσης τοῖς ἐναντιουμένοις πρὸς τὴν ὁρμὴν καὶ βίαν τὴν Ἀλεξάνδρου, μόνοι τῶν κατὰ Συρίαν ὑπέστησαν καὶ πάσας ἐξήλεγξαν τὰς ἐλπίδας. τὸ δὲ παραπλήσιον ἐποίησαν καὶ κατὰ τοὺς ἐνεστῶτας καιρούς· οὐδὲν γὰρ ἀπέλειπον τῶν ἐνδεχομένων, σπουδάζοντες διαφυλάξαι τὴν πρὸς τὸν Πτολεμαῖον πίστιν. διὸ καθάπερ καὶ κατ’ ἰδίαν ἐπισημαινόμεθα τοὺς ἀγαθοὺς ἄνδρας ἐν τοῖς ὑπομνήμασι, τὸν αὐτὸν τρόπον χρὴ καὶ κοινῇ τῶν πόλεων τὴν ἐπ’ ἀγαθῷ ποιήσασθαι μνήμην, ὅσαι τῶν καλῶν ἐκ παραδόσεώς τι καὶ προθέσεως πράττειν εἰώθασιν.", "st": "16.22a"}, {"sp": "N", "t": "Πόπλιος δὲ Σκιπίων ἧκεν ἐκ Λιβύης οὐ πολὺ κατόπιν τῶν προειρημένων καιρῶν. οὔσης δὲ τῆς προσδοκίας τῶν πολλῶν ἀκολούθου τῷ μεγέθει τῶν πράξεων, μεγάλην εἶναι συνέβαινε καὶ τὴν φαντασίαν περὶ τὸν ἄνδρα καὶ τὴν τοῦ πλήθους εὔνοιαν πρὸς αὐτόν. καὶ τοῦτ’ εἰκότως ἐκ τῶν κατὰ λόγον ἐγίνετο καὶ καθηκόντως· οὐδέποτε γὰρ ἂν ἐλπίσαντες Ἀννίβαν ἐκβαλεῖν ἐξ Ἰταλίας οὐδ’ ἀποτρίψασθαι τὸν ὑπὲρ αὑτῶν καὶ τῶν ἀναγκαίων κίνδυνον, τότε δοκοῦντες ἤδη βεβαίως οὐ μόνον ἐκτὸς γεγονέναι παντὸς φόβου καὶ πάσης περιστάσεως, ἀλλὰ καὶ κρατεῖν τῶν ἐχθρῶν, ὑπερβολὴν οὐ κατέλιπον χαρᾶς. ὡς δὲ καὶ τὸν θρίαμβον εἰσῆγε, τότε καὶ μᾶλλον ἔτι διὰ τῆς τῶν εἰσαγομένων ἐνεργείας μιμνησκόμενοι τῶν προγεγονότων κινδύνων ἐκπαθεῖς ἐγίνοντο κατά τε τὴν πρὸς θεοὺς εὐχαριστίαν καὶ κατὰ τὴν πρὸς τὸν αἴτιον τῆς τηλικαύτης μεταβολῆς εὔνοιαν. καὶ γὰρ ὁ Σόφαξ ὁ τῶν Μασαισυλίων βασιλεὺς ἤχθη τότε διὰ τῆς πόλεως ἐν τῷ θριάμβῳ μετὰ τῶν αἰχμαλώτων· ὃς καὶ μετά τινα χρόνον ἐν τῇ φυλακῇ τὸν βίον μετήλλαξε. τούτων δὲ συντελεσθέντων οἱ μὲν ἐν τῇ Ῥώμῃ κατὰ τὸ συνεχὲς ἐπὶ πολλὰς ἡμέρας ἀγῶνας ἦγον καὶ πανηγύρεις ἐπιφανῶς, χορηγὸν ἔχοντες εἰς ταῦτα τὴν Σκιπίωνος μεγαλοψυχίαν.", "st": "16.23"}, {"sp": "N", "t": "ὅτι Φίλιππος ὁ βασιλεὺς τοῦ χειμῶνος ἤδη καταρχομένου, καθ’ ὃν Πόπλιος Σολπίκιος ὕπατος κατεστάθη ἐν Ῥώμῃ, ποιούμενος τὴν διατριβὴν ἐν τοῖς Βαργυλίοις, θεωρῶν καὶ τοὺς Ῥοδίους καὶ τὸν Ἄτταλον οὐχ οἷον διαλύοντας τὸ ναυτικόν, ἀλλὰ καὶ προσπληροῦντας ναῦς καὶ φιλοτιμότερον προσκειμένους ταῖς φυλακαῖς, δυσχρήστως διέκειτο καὶ πολλὰς καὶ ποικίλας εἶχε περὶ τοῦ μέλλοντος ἐπινοίας. ἅμα μὲν γὰρ ἠγωνία τὸν ἐκ τῶν Βαργυλίων ἔκπλουν καὶ προεωρᾶτο τὸν κατὰ θάλατταν κίνδυνον, ἅμα δὲ τοῖς κατὰ τὴν Μακεδονίαν πράγμασι διαπιστῶν οὐδαμῶς ἐβούλετο παραχειμάζειν κατὰ τὴν Ἀσίαν, φοβούμενος [μὲν οὖν] καὶ τοὺς Αἰτωλοὺς καὶ τοὺς Ῥωμαίους· καὶ γὰρ οὐδ’ ἠγνόει τὰς ἐξαποστελλομένας κατ’ αὐτοῦ πρεσβείας εἰς Ῥώμην, διόπερ πέρας ἔχει τὰ κατὰ τὴν Λιβύην. ἐξ ὧν ἐδυσχρηστεῖτο μὲν ὑπερβαλλόντως, ἠναγκάζετο δὲ κατὰ τὸ παρὸν ἐπιμένων αὐτοῦ, τὸ δὴ λεγόμενον, λύκου βίον ζῆν. παρ’ ὧν μὲν γὰρ ἁρπάζων καὶ κλέπτων, τοὺς δ’ ἀποβιαζόμενος, ἐνίους δὲ παρὰ φύσιν αἰκάλλων διὰ τὸ λιμώττειν αὐτῷ τὸ στράτευμα, ποτὲ μὲν ἐσιτεῖτο κρέα, ποτὲ δὲ σῦκα, ποτὲ δὲ σιτάρια βραχέα παντελῶς· ὧν τινὰ μὲν αὐτῷ Ζεῦξις ἐχορήγει, τὰ δὲ Μυλασεῖς καὶ Ἀλαβανδεῖς καὶ Μάγνητες, οὕς, ὁπότε μέν τι δοῖεν, ἔσαινεν, ὅτε δὲ μὴ δοῖεν, ὑλάκτει καὶ ἐπεβούλευεν αὐτοῖς. τέλος ἐπὶ τὴν Μυλασέων πόλιν πράξεις συνεστήσατο διὰ Φιλοκλέους, ἐσφάλη δὲ διὰ τὴν ἀλογίαν τῆς ἐπιβολῆς. τὴν δ’ Ἀλαβανδέων χώραν ὡς πολεμίαν κατέφθειρε, φήσας ἀναγκαῖον εἶναι πορίζειν τῷ στρατεύματι τὰ πρὸς τὴν τροφήν. — Πολύβιος δ’ ὁ Μεγαλοπολίτης ἐν τῇ ιϛʹ τῶν ἱστοριῶν \"Φίλιππος\" φησὶν \"ὁ Περσέως πατήρ, ὅτε τὴν Ἀσίαν κατέτρεχεν, ἀπορῶν τροφῶν τοῖς στρατιώταις παρὰ Μαγνήτων, ἐπεὶ σῖτον οὐκ εἶχον, σῦκα ἔλαβε. διὸ καὶ Μυοῦντος κυριεύσας τοῖς Μάγνησιν ἐχαρίσατο τὸ χωρίον ἀντὶ τῶν σύκων\". —", "st": "16.24"}, {"sp": "N", "t": "ὅτι ὁ τῶν Ἀθηναίων δῆμος ἐξέπεμπε πρεσβευτὰς πρὸς Ἄτταλον τὸν βασιλέα τοὺς ἅμα μὲν εὐχαριστήσοντας ἐπὶ τοῖς γεγονόσιν, ἅμα δὲ παρακαλέσοντας αὐτὸν ἐλθεῖν Ἀθήναζε χάριν τοῦ συνδιαλαβεῖν περὶ τῶν ἐνεστώτων. ὁ δὲ βασιλεὺς μετά τινας ἡμέρας πυθόμενος καταπεπλευκέναι Ῥωμαίων πρεσβευτὰς εἰς τὸν Πειραιᾶ, καὶ νομίζων ἀναγκαῖον εἶναι τὸ συμμῖξαι τούτοις, ἀνήχθη κατὰ σπουδήν. ὁ δὲ τῶν Ἀθηναίων δῆμος γνοὺς τὴν παρουσίαν αὐτοῦ μεγαλομερῶς ἐψηφίσατο περὶ τῆς ἀπαντήσεως καὶ τῆς ὅλης ἀποδοχῆς τοῦ βασιλέως. Ἄτταλος δὲ καταπλεύσας εἰς τὸν Πειραιᾶ τὴν μὲν πρώτην ἡμέραν ἐχρημάτισε τοῖς ἐκ τῆς Ῥώμης πρεσβευταῖς, θεωρῶν δ’ αὐτοὺς καὶ τῆς προγεγενημένης κοινοπραγίας μνημονεύοντας καὶ πρὸς τὸν κατὰ τοῦ Φιλίππου πόλεμον ἑτοίμους ὄντας περιχαρὴς ἦν. τῇ δ’ ἐπαύριον ἅμα τοῖς Ῥωμαίοις καὶ τοῖς τῶν Ἀθηναίων ἄρχουσιν ἀνέβαινεν εἰς ἄστυ μετὰ μεγάλης προστασίας· οὐ γὰρ μόνον οἱ τὰς ἀρχὰς ἔχοντες μετὰ τῶν ἱππέων, ἀλλὰ καὶ πάντες οἱ πολῖται μετὰ τῶν τέκνων καὶ γυναικῶν ἀπήντων αὐτοῖς. ὡς δὲ συνέμιξαν, τοιαύτη παρὰ τῶν πολλῶν ἐγένετο κατὰ τὴν ἀπάντησιν φιλανθρωπία πρός τε Ῥωμαίους καὶ ἔτι μᾶλλον πρὸς τὸν Ἄτταλον ὥσθ’ ὑπερβολὴν μὴ καταλιπεῖν. ἐπεὶ δ’ εἰσῄει κατὰ τὸ Δίπυλον, ἐξ ἑκατέρου τοῦ μέρους παρέστησαν τὰς ἱερείας καὶ τοὺς ἱερεῖς. μετὰ δὲ ταῦτα πάντας μὲν τοὺς ναοὺς ἀνέῳξαν, ἐπὶ δὲ πᾶσι θύματα τοῖς βωμοῖς παραστήσαντες ἠξίωσαν αὐτὸν θῦσαι. τὸ δὲ τελευταῖον ἐψηφίσαντο τιμὰς τηλικαύτας ἡλίκας οὐδενὶ ταχέως τῶν πρότερον εἰς αὐτοὺς εὐεργετῶν γεγονότων· πρὸς γὰρ τοῖς ἄλλοις καὶ φυλὴν ἐπώνυμον ἐποίησαν Ἀττάλῳ, καὶ κατένειμαν αὐτὸν εἰς τοὺς ἐπωνύμους τῶν ἀρχηγετῶν.", "st": "16.25"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα συναγαγόντες ἐκκλησίαν ἐκάλουν τὸν προειρημένον. παραιτουμένου δὲ καὶ φάσκοντος εἶναι φορτικὸν τὸ κατὰ πρόσωπον εἰσελθόντα διαπορεύεσθαι τὰς εὐεργεσίας τὰς αὑτοῦ τοῖς εὖ πεπονθόσι, τῆς εἰσόδου παρῆκαν, γράψαντα δ’ αὐτὸν ἠξίουν ἐκδοῦναι περὶ ὧν ὑπολαμβάνει συμφέρειν πρὸς τοὺς ἐνεστῶτας καιρούς. τοῦ δὲ πεισθέντος καὶ γράψαντος εἰσήνεγκαν τὴν ἐπιστολὴν οἱ προεστῶτες. ἦν δὲ τὰ κεφάλαια τῶν γεγραμμένων ἀνάμνησις τῶν πρότερον ἐξ αὐτοῦ γεγονότων εὐεργετημάτων εἰς τὸν δῆμον, ἐξαρίθμησις τῶν πεπραγμένων αὐτῷ πρὸς Φίλιππον κατὰ τοὺς ἐνεστῶτας καιρούς, τελευταία δὲ παράκλησις εἰς τὸν κατὰ Φιλίππου πόλεμον, καὶ διορκισμός, ὡς ἐὰν μὴ νῦν ἕλωνται συνεμβαίνειν εὐγενῶς εἰς τὴν ἀπέχθειαν ἅμα Ῥοδίοις καὶ Ῥωμαίοις καὶ αὐτῷ, μετὰ δὲ ταῦτα παρέντες τοὺς καιροὺς κοινωνεῖν βούλωνται τῆς εἰρήνης, ἄλλων αὐτὴν κατεργασαμένων, ἀστοχήσειν αὐτοὺς τοῦ τῇ πατρίδι συμφέροντος. τῆς δ’ ἐπιστολῆς ταύτης ἀναγνωσθείσης ἕτοιμον ἦν τὸ πλῆθος ψηφίζεσθαι τὸν πόλεμον καὶ διὰ τὰ λεγόμενα καὶ διὰ τὴν εὔνοιαν τὴν πρὸς τὸν Ἄτταλον. οὐ μὴν ἀλλὰ καὶ τῶν Ῥοδίων ἐπεισελθόντων καὶ πολλοὺς πρὸς τὴν αὐτὴν ὑπόθεσιν διαθεμένων λόγους, ἔδοξε τοῖς Ἀθηναίοις ἐκφέρειν τῷ Φιλίππῳ τὸν πόλεμον. ἀπεδέξαντο δὲ καὶ τοὺς Ῥοδίους μεγαλομερῶς καὶ τόν τε δῆμον ἐστεφάνωσαν ἀριστείων στεφάνῳ καὶ πᾶσι Ῥοδίοις ἰσοπολιτείαν ἐψηφίσαντο διὰ τὸ κἀκείνους αὐτοῖς χωρὶς τῶν ἄλλων τάς τε ναῦς ἀποκαταστῆσαι τὰς αἰχμαλώτους γενομένας καὶ τοὺς ἄνδρας. οἱ μὲν οὖν πρέσβεις οἱ παρὰ τῶν Ῥοδίων ταῦτα διαπράξαντες ἀνήχθησαν εἰς τὴν Κέων ἐπὶ τὰς νήσους μετὰ τοῦ στόλου. —", "st": "16.26"}, {"sp": "N", "t": "ὅτι καθ’ ὃν χρόνον οἱ τῶν Ῥωμαίων πρέσβεις ἐν ταῖς Ἀθήναις ἐποιοῦντο τὴν διατριβήν, Νικάνορος τοῦ παρὰ Φιλίππου κατατρέχοντος τὴν Ἀττικὴν ἕως τῆς Ἀκαδημείας, προδιαπεμψάμενοι πρὸς αὐτὸν οἱ Ῥωμαῖοι κήρυκα συνέμιξαν αὐτῷ καὶ παρεκάλεσαν ἀναγγεῖλαι τῷ Φιλίππῳ διότι Ῥωμαῖοι παρακαλοῦσι τὸν βασιλέα τῶν μὲν Ἑλλήνων μηδενὶ πολεμεῖν, τῶν δὲ γεγονότων εἰς Ἄτταλον ἀδικημάτων δίκας ὑπέχειν ἐν ἴσῳ κριτηρίῳ, καὶ διότι πράξαντι μὲν ταῦτα τὴν εἰρήνην ἄγειν ἔξεστι πρὸς Ῥωμαίους, μὴ βουλομένῳ δὲ πείθεσθαι τἀναντία συνεξακολουθήσειν ἔφασαν. ὁ μὲν οὖν Νικάνωρ ταῦτ’ ἀκούσας ἀπηλλάγη· τὸν αὐτὸν δὲ λόγον τοῦτον οἱ Ῥωμαῖοι καὶ πρὸς Ἠπειρώτας εἶπαν περὶ Φιλίππου παραπλέοντες ἐν Φοινίκῃ καὶ πρὸς Ἀμύνανδρον ἀναβάντες εἰς Ἀθαμανίαν· παραπλησίως καὶ πρὸς Αἰτωλοὺς ἐν Ναυπάκτῳ καὶ πρὸς τοὺς Ἀχαιοὺς ἐν Αἰγίῳ. τότε δὲ διὰ τοῦ Νικάνορος τῷ Φιλίππῳ ταῦτα δηλώσαντες αὐτοὶ μὲν ἀπέπλευσαν ὡς Ἀντίοχον καὶ Πτολεμαῖον ἐπὶ τὰς διαλύσεις. —", "st": "16.27"}, {"sp": "N", "t": "ἀλλ’ ἐμοὶ δοκεῖ τὸ μὲν ἄρξασθαι καλῶς καὶ συνακμάσαι ταῖς ὁρμαῖς πρὸς τὴν τῶν πραγμάτων αὔξησιν ἐπὶ πολλῶν ἤδη γεγονέναι, τὸ δ’ ἐπὶ τέλος ἀγαγεῖν τὸ προτεθὲν καί που καὶ τῆς τύχης ἀντιπιπτούσης συνεκπληρῶσαι τῷ λογισμῷ τὸ τῆς προθυμίας ἐλλιπὲς ἐπ’ ὀλίγων γίνεσθαι. διὸ καὶ τότε δικαίως ἄν τις τὴν μὲν Ἀττάλου καὶ Ῥοδίων ὀλιγοπονίαν καταμέμψαιτο, τὸ δὲ Φιλίππου βασιλικὸν καὶ μεγαλόψυχον καὶ τὸ τῆς προθέσεως ἐπίμονον ἀποδέξαιτο, οὐχ ὡς καθόλου τὸν τρόπον ἐπαινῶν, ἀλλ’ ὡς τὴν πρὸς τὸ παρὸν ὁρμὴν ἐπισημαινόμενος. ποιοῦμαι δὲ τὴν τοιαύτην διαστολήν, ἵνα μή τις ἡμᾶς ὑπολάβῃ μαχόμενα λέγειν ἑαυτοῖς, ἄρτι μὲν ἐπαινοῦντας Ἄτταλον καὶ Ῥοδίους, Φίλιππον δὲ καταμεμφομένους, νῦν δὲ τοὐναντίον. τούτου γὰρ χάριν ἐν ἀρχαῖς τῆς πραγματείας διεστειλάμην, φήσας ἀναγκαῖον εἶναι ποτὲ μὲν εὐλογεῖν, ποτὲ δὲ ψέγειν τοὺς αὐτούς, ἐπειδὴ πολλάκις μὲν αἱ πρὸς τὸ χεῖρον τῶν πραγμάτων ῥοπαὶ καὶ περιστάσεις ἀλλοιοῦσι τὰς προαιρέσεις τῶν ἀνθρώπων, πολλάκις δ’ αἱ πρὸς τὸ βέλτιον, ἔστι δ’ ὅτε κατὰ τὴν ἰδίαν φύσιν ἄνθρωποι ποτὲ μὲν ἐπὶ τὸ δέον ὁρμῶσι, ποτὲ δ’ ἐπὶ τοὐναντίον. ὧν ἕν τί μοι δοκεῖ καὶ τότε γεγονέναι περὶ τὸν Φίλιππον· ἀσχάλλων γὰρ ἐπὶ τοῖς γεγονόσιν ἐλαττώμασι, καὶ τὸ πλεῖον ὀργῇ καὶ θυμῷ χρώμενος, παραστατικῶς καὶ δαιμονίως ἐνήρμοσεν εἰς τοὺς ἐνεστῶτας καιρούς, καὶ τούτῳ τῷ τρόπῳ κατανέστη τῶν Ῥοδίων καὶ τοῦ βασιλέως Ἀττάλου, καὶ καθίκετο τῶν ἑξῆς πράξεων. ταῦτα μὲν οὖν προήχθην εἰπεῖν διὰ τὸ τινὰς μὲν πρὸς τῷ τέρματι, καθάπερ οἱ κακοὶ τῶν σταδιέων, ἐγκαταλιπεῖν τὰς ἑαυτῶν προθέσεις, τινὰς δ’ ἐν τούτῳ μάλιστα νικᾶν τοὺς ἀντιπάλους. —", "st": "16.28"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος ἐβούλετο παρελέσθαι Ῥωμαίων τὰς ἐν τούτοις τοῖς τόποις ἀφορμὰς καὶ τὰς ἐπιβάθρας. — ἵνα, ἐὰν πρόθηται διαβαίνειν αὖθις εἰς τὴν Ἀσίαν, ἐπιβάθραν ἔχοι τὴν Ἄβυδον. — τὴν δὲ τῆς Ἀβύδου καὶ Σηστοῦ θέσιν καὶ τὴν εὐκαιρίαν τῶν πόλεων τὸ μὲν διὰ πλειόνων ἐξαριθμεῖσθαι μάταιον εἶναί μοι δοκεῖ διὰ τὸ πάντας, ὧν καὶ μικρὸν ὄφελος, ἱστορηκέναι διὰ τὴν ἰδιότητα τῶν τόπων· κεφαλαιωδῶς γε μὴν ὑπομνῆσαι τοὺς ἀναγινώσκοντας ἐπιστάσεως χάριν οὐκ ἄχρηστον εἶναι νομίζω πρὸς τὸ παρόν. γνοίη δ’ ἄν τις τὰ περὶ τὰς προειρημένας πόλεις οὐχ οὕτως ἐξ αὐτῶν τῶν ὑποκειμένων τόπων ὡς ἐκ τῆς παραθέσεως καὶ συγκρίσεως τῶν λέγεσθαι μελλόντων. καθάπερ γὰρ οὐδ’ ἐκ τοῦ παρὰ μέν τισιν Ὠκεανοῦ προσαγορευομένου, παρὰ δέ τισιν Ἀτλαντικοῦ πελάγους. δυνατὸν εἰς τὴν καθ’ ἡμᾶς θάλατταν εἰσπλεῦσαι μὴ οὐχὶ διὰ τοῦ καθ’ Ἡρακλέους στήλας περαιωθέντα στόματος, οὕτως οὐδ’ ἐκ τῆς καθ’ ἡμᾶς εἰς τὴν Προποντίδα καὶ τὸν Πόντον ἀφικέσθαι μὴ οὐχὶ διὰ τοῦ μεταξὺ Σηστοῦ καὶ Ἀβύδου διαστήματος ποιησάμενον τὸν εἴσπλουν. ὥσπερ δὲ πρός τινα λόγον τῆς τύχης ποιουμένης τὴν κατασκευὴν ἀμφοτέρων τῶν πορθμῶν, πολλαπλάσιον εἶναι συμβαίνει τὸν καθ’ Ἡρακλέους στήλας πόρον τοῦ κατὰ τὸν Ἑλλήσποντον· ὁ μὲν γάρ ἐστιν ἑξήκοντα σταδίων, ὁ δὲ κατὰ τὴν Ἄβυδον δυεῖν, ὡς ἂν εἴ τινος τεκμαιρομένου διὰ τὸ πολλαπλασίαν εἶναι τὴν ἔξω θάλατταν τῆς καθ’ ἡμᾶς. εὐκαιρότερον μέντοι γε τοῦ καθ’ Ἡρακλείους στήλας στόματός ἐστι τὸ κατὰ τὴν Ἄβυδον. τὸ μὲν γὰρ ἐξ ἀμφοῖν ὑπ’ ἀνθρώπων οἰκούμενον πύλης ἔχει διάθεσιν διὰ τὴν πρὸς ἀλλήλους ἐπιμιξίαν, ποτὲ μὲν γεφυρούμενον ὑπὸ τῶν πεζεύειν ἐπ’ ἀμφοτέρας τὰς ἠπείρους προαιρουμένων, ποτὲ δὲ πλωτευόμενον συνεχῶς· τὸ δὲ καθ’ Ἡρακλείους στήλας σπάνιον ἔχει τὴν χρῆσιν καὶ σπανίοις διὰ τὴν ἀνεπιμιξίαν τῶν ἐθνῶν τῶν πρὸς τοῖς πέρασι κατοικούντων τῆς Λιβύης καὶ τῆς Εὐρώπης καὶ διὰ τὴν ἀγνωσίαν τῆς ἐκτὸς θαλάττης. αὐτὴ δ’ ἡ τῶν Ἀβυδηνῶν πόλις περιέχεται μὲν ἐξ ἀμφοῖν τοῖν μεροῖν ὑπὸ τῶν τῆς Εὐρώπης ἀκρωτηρίων, ἔχει δὲ λιμένα δυνάμενον σκέπειν ἀπὸ παντὸς ἀνέμου τοὺς ἐνορμοῦντας. ἐκτὸς δὲ τῆς εἰς τὸν λιμένα καταγωγῆς οὐδαμῶς οὐδαμῇ δυνατόν ἐστιν ὁρμῆσαι πρὸς τὴν πόλιν διὰ τὴν ὀξύτητα καὶ βίαν τοῦ ῥοῦ τοῦ κατὰ τὸν πόρον.", "st": "16.29"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ὅ γε Φίλιππος τὰ μὲν ἀποσταυρώσας, τὰ δὲ περιχαρακώσας τοὺς Ἀβυδηνοὺς ἐπολιόρκει καὶ κατὰ γῆν ἅμα καὶ κατὰ θάλατταν. ἡ δὲ πρᾶξις αὕτη κατὰ μὲν τὸ μέγεθος τῆς παρασκευῆς καὶ τὴν ποικιλίαν τῶν ἐν τοῖς ἔργοις ἐπινοημάτων, δι’ ὧν οἵ τε πολιορκοῦντες καὶ πολιορκούμενοι πρὸς ἀλλήλους εἰώθασιν ἀντιμηχανᾶσθαι καὶ φιλοτεχνεῖν, οὐ γέγονε θαυμάσιος, κατὰ δὲ τὴν γενναιότητα τῶν πολιορκουμένων καὶ τὴν ὑπερβολὴν τῆς εὐψυχίας, εἰ καί τις ἄλλη, μνήμης ἀξία καὶ παραδόσεως. τὰς μὲν γὰρ ἀρχὰς πιστεύοντες αὑτοῖς οἱ τὴν Ἄβυδον κατοικοῦντες ὑπέμενον ἐρρωμένως τὰς τοῦ Φιλίππου παρασκευάς, καὶ τῶν τε κατὰ θάλατταν προσαχθέντων μηχανημάτων τὰ μὲν τοῖς πετροβόλοις τύπτοντες διεσάλευσαν, τὰ δὲ τῷ πυρὶ διέφθειραν, οὕτως ὥστε καὶ τὰς ναῦς μόλις ἀνασπάσαι τοὺς πολεμίους ἐκ τοῦ κινδύνου. τοῖς δὲ κατὰ γῆν ἔργοις ἕως μέν τινος προσαντεῖχον εὐψύχως, οὐκ ἀπελπίζοντες κατακρατήσειν τῶν πολεμίων. ἐπειδὴ δὲ τὸ μὲν ἐκτὸς τοῦ τείχους ἔπεσε διὰ τῶν ὀρυγμάτων, μετὰ δὲ ταῦτα διὰ τῶν μετάλλων ἤγγιζον οἱ Μακεδόνες τῷ κατὰ τὸ πεπτωκὸς ὑπὸ τῶν ἔνδοθεν ἀντῳκοδομημένῳ τείχει, τὸ τηνικάδε πέμψαντες πρεσβευτὰς Ἰφιάδην καὶ Παντάγνωτον ἐκέλευον παραλαμβάνειν τὸν Φίλιππον τὴν πόλιν, τοὺς μὲν στρατιώτας ὑποσπόνδους ἀφέντα τοὺς παρὰ Ῥοδίων καὶ παρ’ Ἀττάλου, τὰ δ’ ἐλεύθερα τῶν σωμάτων ἐάσαντα σῴζεσθαι κατὰ δύναμιν οὗ ποτ’ ἂν ἕκαστος προαιρῆται μετὰ τῆς ἐσθῆτος τῆς περὶ τὸ σῶμα. τοῦ δὲ Φιλίππου προστάττοντος περὶ πάντων ἐπιτρέπειν ἢ μάχεσθαι γενναίως, οὗτοι μὲν ἐπανῆλθον.", "st": "16.30"}, {"sp": "N", "t": "οἱ δ’ Ἀβυδηνοὶ πυθόμενοι τὰ λεγόμενα, συνελθόντες εἰς ἐκκλησίαν ἐβουλεύοντο περὶ τῶν ἐνεστώτων ἀπονοηθέντες ταῖς γνώμαις. ἔδοξεν οὖν αὐτοῖς πρῶτον μὲν τοὺς δούλους ἐλευθεροῦν, ἵνα συναγωνιστὰς ἔχοιεν ἀπροφασίστους, ἔπειτα συναθροῖσαι τὰς μὲν γυναῖκας εἰς τὸ τῆς Ἀρτέμιδος ἱερὸν ἁπάσας, τὰ δὲ τέκνα σὺν ταῖς τροφοῖς εἰς τὸ γυμνάσιον, ἑξῆς δὲ τούτοις τὸν ἄργυρον καὶ τὸν χρυσὸν εἰς τὴν ἀγορὰν συναγαγεῖν, ὁμοίως δὲ καὶ τὸν ἱματισμὸν τὸν ἀξιόλογον εἰς τὴν τετρήρη τὴν τῶν Ῥοδίων καὶ τὴν τριήρη τὴν τῶν Κυζικηνῶν. ταῦτα δὲ προθέμενοι καὶ πράξαντες ὁμοθυμαδὸν κατὰ τὸ δόγμα πάλιν συνηθροίσθησαν εἰς τὴν ἐκκλησίαν, καὶ πεντήκοντα προεχειρίσαντο τῶν πρεσβυτέρων ἀνδρῶν καὶ μάλιστα πιστευομένων, ἔτι δὲ τὴν σωματικὴν δύναμιν ἐχόντων πρὸς τὸ δύνασθαι τὸ κριθὲν ἐπιτελεῖν, καὶ τούτους ἐξώρκισαν ἐναντίον ἁπάντων τῶν πολιτῶν ἦ μήν, ἐὰν ἴδωσι τὸ διατείχισμα καταλαμβανόμενον ὑπὸ τῶν ἐχθρῶν, κατασφάξειν μὲν τὰ τέκνα καὶ τὰς γυναῖκας, ἐμπρήσειν δὲ τὰς προειρημένας ναῦς, ῥίψειν δὲ κατὰ τὰς ἀρὰς τὸν ἄργυρον καὶ τὸν χρυσὸν εἰς τὴν θάλατταν. μετὰ δὲ ταῦτα παραστησάμενοι τοὺς ἱερέας ὤμνυον πάντες ἢ κρατήσειν τῶν ἐχθρῶν ἢ τελευτήσειν μαχόμενοι περὶ τῆς πατρίδος. ἐπὶ δὲ πᾶσι σφαγιασάμενοι κατάρας ἠνάγκασαν ἐπὶ τῶν ἐμπύρων ποιεῖσθαι τοὺς ἱερέας καὶ τὰς ἱερείας περὶ τῶν προειρημένων. ταῦτα δ’ ἐπικυρώσαντες τοῦ μὲν ἀντιμεταλλεύειν τοῖς πολεμίοις ἀπέστησαν, ἐπὶ δὲ τοιαύτην γνώμην κατέστησαν ὥστ’ ἐπειδὰν πέσῃ τὸ διατείχισμα, τότ’ ἐπὶ τοῦ πτώματος διαμάχεσθαι καὶ διαποθνήσκειν πρὸς τοὺς βιαζομένους.", "st": "16.31"}, {"sp": "N", "t": "ἐξ ὧν εἴποι τις ἂν καὶ τὴν λεγομένην Φωκικὴν ἀπόνοιαν καὶ τὴν Ἀκαρνάνων εὐψυχίαν ὑπερηρκέναι τὴν τῶν Ἀβυδηνῶν τόλμαν. Φωκεῖς τε γὰρ δοκοῦσι τὰ παραπλήσια βουλεύσασθαι περὶ τῶν ἀναγκαίων, οὐκ εἰς τέλος ἀπηλπισμένας ἔχοντες τὰς τοῦ νικᾶν ἐλπίδας διὰ τὸ μέλλειν ποιεῖσθαι τὸν κίνδυνον πρὸς τοὺς Θετταλοὺς ἐν τοῖς ὑπαίθροις ἐκ παρατάξεως· ὁμοίως δὲ καὶ τὸ τῶν Ἀκαρνάνων ἔθνος, ὅτε προιδόμενοι τὴν Αἰτωλῶν ἔφοδον, ἐβουλεύσαντο παραπλήσια περὶ τῶν ἐνεστώτων· ὑπὲρ ὧν τὰ κατὰ μέρος ἡμεῖς ἐν τοῖς πρὸ τούτων ἱστορήκαμεν. Ἀβυδηνοὶ δέ, συγκεκλεισμένοι καὶ σχεδὸν ἀπηλπικότες τὴν σωτηρίαν, πανδημεὶ προείλοντο τῆς εἱμαρμένης τυχεῖν μετὰ τῶν τέκνων καὶ τῶν γυναικῶν μᾶλλον ἢ ζῶντες ἔτι πρόληψιν ἔχειν τοῦ πεσεῖσθαι τὰ σφέτερα τέκνα καὶ τὰς γυναῖκας ὑπὸ τὴν τῶν ἐχθρῶν ἐξουσίαν. διὸ καὶ μάλιστ’ ἄν τις ἐπὶ τῆς Ἀβυδηνῶν περιπετείας μέμψαιτο τῇ τύχῃ, διότι τὰς μὲν τῶν προειρημένων συμφορὰς οἷον ἐλεήσασα παραυτίκα διωρθώσατο, περιθεῖσα τὴν νίκην ἅμα καὶ τὴν σωτηρίαν τοῖς ἀπηλπισμένοις, περὶ δ’ Ἀβυδηνῶν τὴν ἐναντίαν εἶχε διάληψιν. οἱ μὲν γὰρ ἄνδρες ἀπέθανον, ἡ δὲ πόλις ἑάλω, τὰ δὲ τέκνα σὺν αὐταῖς μητράσιν ἐγένετο τοῖς ἐχθροῖς ὑποχείρια.", "st": "16.32"}, {"sp": "N", "t": "πεσόντος γὰρ τοῦ διατειχίσματος, ἐπιβάντες ἐπὶ τὸ πτῶμα κατὰ τοὺς ὅρκους διεμάχοντο τοῖς πολεμίοις οὕτω τετολμηκότως ὥστε τὸν Φίλιππον, καίπερ ἐκ διαδοχῆς προβαλόμενον τοὺς Μακεδόνας ἕως νυκτός, τέλος ἀποστῆναι τῆς μάχης, δυσελπιστήσαντα καὶ περὶ τῆς ὅλης ἐπιβολῆς. οὐ γὰρ μόνον ἐπὶ τοὺς θνήσκοντας τῶν πολεμίων ἐπιβαίνοντες ἠγωνίζοντο μετὰ παραστάσεως οἱ προκινδυνεύοντες τῶν Ἀβυδηνῶν, οὐδὲ τοῖς ξίφεσι καὶ τοῖς δόρασιν αὐτοῖς ἐμάχοντο παραβόλως, ἀλλ’ ὅτε τι τούτων ἀχρειωθὲν ἀδυνατήσειεν ἢ μετὰ βίας προοῖντ’ ἐκ τῶν χειρῶν, συμπλεκόμενοι τοῖς Μακεδόσιν οὓς μὲν ἀνέτρεπον ὁμοῦ τοῖς ὅπλοις, ὧν δὲ συντρίβοντες τὰς σαρίσας αὐτοῖς τοῖς ἐκείνων κλάσμασιν ἐκ διαλήψεως τύπτοντες αὐτῶν ταῖς ἐπιδορατίσι τὰ πρόσωπα καὶ τοὺς γυμνοὺς τόπους εἰς ὁλοσχερῆ διατροπὴν ἦγον. ἐπιγενομένης δὲ τῆς νυκτὸς καὶ διαλυθείσης τῆς μάχης, τῶν μὲν πλείστων τεθνεώτων ἐπὶ τοῦ πτώματος, τῶν δὲ λοιπῶν ὑπὸ τοῦ κόπου καὶ τῶν τραυμάτων ἀδυνατούντων, συναγαγόντες ὀλίγους τινὰς τῶν πρεσβυτέρων Γλαυκίδης καὶ Θεόγνητος κατέβαλον τὸ σεμνὸν καὶ θαυμάσιον τῆς τῶν πολιτῶν προαιρέσεως διὰ τὰς ἰδίας ἐλπίδας· ἐβουλεύσαντο γὰρ τὰ μὲν τέκνα καὶ τὰς γυναῖκας ζωγρεῖν, ἅμα δὲ τῷ φωτὶ τοὺς ἱερεῖς καὶ τὰς ἱερείας ἐκπέμπειν μετὰ στεμμάτων πρὸς τὸν Φίλιππον, δεησομένους καὶ παραδιδόντας αὐτῷ τὴν πόλιν.", "st": "16.33"}, {"sp": "N", "t": "κατὰ δὲ τοὺς καιροὺς τούτους Ἄτταλος ὁ βασιλεὺς ἀκούσας πολιορκεῖσθαι τοὺς Ἀβυδηνούς, δι’ Αἰγαίου ποιησάμενος τὸν πλοῦν εἰς Τένεδον, ὁμοίως δὲ καὶ τῶν Ῥωμαίων Μάρκος Αἰμίλιος ὁ νεώτατος ἧκε καταπλέων εἰς αὐτὴν τὴν Ἄβυδον. οἱ γὰρ Ῥωμαῖοι τὸ σαφὲς ἀκούσαντες ἐν τῇ Ῥόδῳ περὶ τῆς τῶν Ἀβυδηνῶν πολιορκίας καὶ βουλόμενοι πρὸς αὐτὸν τὸν Φίλιππον ποιήσασθαι τοὺς λόγους κατὰ τὰς ἐντολάς, ἐπιστήσαντες τὴν πρὸς τοὺς βασιλέας ὁρμὴν ἐξέπεμψαν τὸν προειρημένον, ὃς καὶ συμμίξας περὶ τὴν Ἄβυδον διεσάφει τῷ βασιλεῖ διότι δέδοκται τῇ συγκλήτῳ παρακαλεῖν αὐτὸν μήτε τῶν Ἑλλήνων μηδενὶ πολεμεῖν μήτε τοῖς Πτολεμαίου πράγμασιν ἐπιβάλλειν τὰς χεῖρας, περὶ δὲ τῶν εἰς Ἄτταλον καὶ Ῥοδίους ἀδικημάτων δίκας ὑποσχεῖν, καὶ διότι ταῦτα μὲν οὕτω πράττοντι τὴν εἰρήνην ἄγειν ἐξέσται, μὴ βουλομένῳ δὲ πειθαρχεῖν ἑτοίμως ὑπάρξειν τὸν πρὸς Ῥωμαίους πόλεμον. τοῦ δὲ Φιλίππου βουλομένου διδάσκειν ὅτι Ῥόδιοι τὰς χεῖρας ἐπιβάλοιεν αὐτῷ, μεσολαβήσας ὁ Μάρκος ἤρετο \"τί δαὶ Ἀθηναῖοι; τί δαὶ Κιανοί; τί δαὶ νῦν Ἀβυδηνοί; καὶ τούτων τίς\" ἔφη \"σοὶ πρότερος ἐπέβαλε τὰς χεῖρας;\" ὁ δὲ βασιλεὺς ἐξαπορήσας κατὰ τρεῖς τρόπους ἔφησεν αὐτῷ συγγνώμην ἔχειν ὑπερηφάνως ὁμιλοῦντι, πρῶτον μὲν ὅτι νέος ἐστὶ καὶ πραγμάτων ἄπειρος, δεύτερον ὅτι κάλλιστος ὑπάρχει τῶν καθ’ αὑτὸν — καὶ γὰρ ἦν τοῦτο κατ’ ἀλήθειαν — μάλιστα δ’ ὅτι Ῥωμαῖος. \"ἐγὼ δὲ μάλιστα μὲν ἀξιῶ Ῥωμαίους\" ἔφη \"μὴ παραβαίνειν τὰς συνθήκας μηδὲ πολεμεῖν ἡμῖν· ἐὰν δὲ καὶ τοῦτο ποιῶσιν, ἀμυνούμεθα γενναίως, παρακαλέσαντες τοὺς θεούς\". οὗτοι μὲν οὖν ταῦτ’ εἰπόντες διεχωρίσθησαν ἀπ’ ἀλλήλων· ὁ δὲ Φίλιππος κυριεύσας τῆς πόλεως, τὴν ὕπαρξιν ἅπασαν καταλαβὼν συνηθροισμένην ὑπὸ τῶν Ἀβυδηνῶν ἐξ ἑτοίμου παρέλαβε. θεωρῶν δὲ τὸ πλῆθος καὶ τὴν ὁρμὴν τῶν σφᾶς αὐτοὺς καὶ τὰ τέκνα καὶ τὰς γυναῖκας ἀποσφαττόντων, κατακαόντων, ἀπαγχόντων, εἰς τὰ φρέατα ῥιπτούντων, κατακρημνιζόντων ἀπὸ τῶν τεγῶν, ἐκπλαγὴς ἦν, καὶ διαλγῶν ἐπὶ τοῖς γινομένοις παρήγγειλε διότι τρεῖς ἡμέρας ἀναστροφὴν δίδωσι τοῖς βουλομένοις ἀπάγχεσθαι καὶ σφάττειν αὑτούς. οἱ δ’ Ἀβυδηνοί, προδιειληφότες ὑπὲρ αὑτῶν κατὰ τὴν ἐξ ἀρχῆς στάσιν, καὶ νομίζοντες οἷον εἰ προδόται γίνεσθαι τῶν ὑπὲρ τῆς πατρίδος ἠγωνισμένων καὶ τεθνεώτων, οὐδαμῶς ὑπέμενον τὸ ζῆν, ὅσοι μὴ δεσμοῖς ἢ τοιαύταις ἀνάγκαις προκατελήφθησαν· οἱ δὲ λοιποὶ πάντες ὥρμων ἀμελλήτως κατὰ συγγενείας ἐπὶ τὸν θάνατον. —", "st": "16.34"}, {"sp": "N", "t": "ὅτι παρῆσαν μετὰ τὴν ἅλωσιν Ἀβύδου παρὰ τοῦ τῶν Ἀχαιῶν ἔθνους εἰς τὴν Ῥόδον πρεσβευταί, παρακαλοῦντες τὸν δῆμον εἰς τὰς πρὸς τὸν Φίλιππον διαλύσεις. οἷς ἐπελθόντων τῶν ἐκ τῆς Ῥώμης πρεσβευτῶν καὶ διαλεγομένων ὑπὲρ τοῦ μὴ ποιεῖσθαι διαλύσεις πρὸς Φίλιππον ἄνευ Ῥωμαίων, ἔδοξε προσέχειν τῷ δήμῳ τοῖς Ῥωμαίοις καὶ στοχάζεσθαι τῆς τούτων φιλίας. —", "st": "16.35"}, {"sp": "N", "t": "ὁ δὲ Φιλοποίμην ἐξελογίσατο τὰ διαστήματα τῶν Ἀχαϊκῶν πόλεων ἁπασῶν καὶ ποῖαι δύνανται κατὰ τὰς αὐτὰς ὁδοὺς εἰς τὴν Τεγέαν παραγίνεσθαι. λοιπὸν ἐπιστολὰς ἔγραψε πρὸς πάσας τὰς πόλεις, καὶ ταύτας διέδωκε ταῖς πορρωτάτω πόλεσι, μερίσας οὕτως ὥστε καθ’ ἑκάστην ἔχειν μὴ μόνον τὰς ἑαυτῆς, ἀλλὰ καὶ τὰς τῶν ἄλλων πόλεων, ὅσαι κατὰ τὴν αὐτὴν ὁδὸν ἔπιπτον. ἐγέγραπτο δ’ ἐν ταῖς πρώταις τοῖς ἀποτελείοις τοιαῦτα. \"ὅταν κομίσησθε τὴν ἐπιστολήν, παραχρῆμα ποιήσασθε τοὺς ἐν ταῖς ἡλικίαις ἔχοντας τὰ ὅπλα καὶ πένθ’ ἡμερῶν ἐφόδια καὶ πέντ’ ἀργύριον, ἁθροίζεσθαι παραυτίκα πάντας εἰς τὴν ἀγοράν. ἐπειδὰν δὲ συλλεχθῶσιν οἱ παρόντες, ἀναλαβόντες αὐτοὺς ἄγετ’ εἰς τὴν ἑξῆς πόλιν· ὅταν δ’ ἐκεῖ παραγένησθε, τὴν ἐπιστολὴν ἀπόδοτε τὴν ἐπιγεγραμμένην τῷ παρ’ ἐκείνων ἀποτελείῳ καὶ πειθαρχεῖτε τοῖς ἐγγεγραμμένοις\". ἐγγέγραπτο δ’ ἐν ταύτῃ ταὐτὰ τοῖς πρόσθεν, πλὴν διότι τὸ τῆς ἑξῆς κειμένης ὄνομα πόλεως οὐ ταὐτὸν εἶχεν, εἰς ἣν ἔδει προάγειν. τοιούτου δὲ τοῦ χειρισμοῦ γενομένου κατὰ τὸ συνεχές, πρῶτον μὲν οὐδεὶς ἐγίνωσκε πρὸς τίνα πρᾶξιν ἢ πρὸς ποίαν ἐπιβολήν ἐστιν ἡ παρασκευή, εἶτα ποῦ πορεύεται, πλὴν τῆς ἑξῆς πόλεως, οὐδεὶς ἁπλῶς ᾔδει, πάντες δὲ διαποροῦντες καὶ παραλαμβάνοντες ἀλλήλους προῆγον εἰς τοὔμπροσθεν. τῷ δὲ μὴ τὸ ἴσον ἀπέχειν τῆς Τεγέας τὰς πορρωτάτω κειμένας πόλεις οὐχ ἅμα πάσαις ἀπεδόθη τὰ γράμματα ταύταις, ἀλλὰ κατὰ λόγον ἑκάσταις. ἐξ ὧν συνέβη, μήτε τῶν Τεγεατῶν εἰδότων τὸ μέλλον μήτε τῶν παραγινομένων, ἅμα πάντας τοὺς Ἀχαιοὺς καὶ κατὰ πάσας τὰς πύλας εἰς τὴν Τεγέαν εἰσπορεύεσθαι σὺν τοῖς ὅπλοις.", "st": "16.36"}, {"sp": "N", "t": "ταῦτα δὲ διεστρατήγει καὶ περιεβάλλετο τῇ διανοίᾳ διὰ τὸ πλῆθος τῶν ὠτακουστῶν καὶ κατασκόπων τοῦ τυράννου. κατὰ δὲ τὴν ἡμέραν, ἐν ᾗ συναθροίζεσθαι τὸ πλῆθος ἔμελλε τῶν Ἀχαιῶν εἰς Τεγέαν, ἐξαπέστειλε τοὺς ἐπιλέκτους, ὥστε νυκτερεύσαντας περὶ Σελλασίαν ἅμα τῷ φωτὶ κατὰ τὴν ἐπιοῦσαν ἡμέραν ἐπιτρέχειν τὴν Λακωνικήν. ἐὰν δ’ οἱ μισθοφόροι βοηθήσαντες παρενοχλῶσιν αὐτούς, συνέταξε ποιεῖσθαι τὴν ἀποχώρησιν ἐπὶ τὸν Σκοτίταν καὶ τὰ λοιπὰ πειθαρχεῖν Διδασκαλώνδᾳ τῷ Κρητί· τούτῳ γὰρ ἐπεπιστεύκει καὶ διετέτακτο περὶ τῆς ὅλης ἐπιβολῆς. οὗτοι μὲν οὖν προῆγον εὐθαρσῶς ἐπὶ τὸ συντεταγμένον· ὁ δὲ Φιλοποίμην ἐν ὥρᾳ παραγγείλας δειπνοποιεῖσθαι τοῖς Ἀχαιοῖς ἐξῆγε τὴν δύναμιν ἐκ τῆς Τεγέας, καὶ νυκτοπορήσας ἐνεργῶς περὶ τὴν ἑωθινὴν ἐνεκάθισε τὴν στρατιὰν ἐν τοῖς περὶ τὸν Σκοτίταν προσαγορευομένοις τόποις, ὅς ἐστι μεταξὺ τῆς Τεγέας καὶ τῆς Λακεδαίμονος. οἱ δ’ ἐν τῇ Πελλήνῃ μισθοφόροι κατὰ τὴν ἐπιοῦσαν ἡμέραν ἅμα τῷ σημῆναι τοὺς σκοποὺς τὴν καταδρομὴν τῶν πολεμίων ἐκ χειρὸς ἐβοήθουν, καθάπερ ἔθος ἦν αὐτοῖς, καὶ προσέκειντο τοῖς ὑπεναντίοις. τῶν δ’ Ἀχαιῶν κατὰ τὸ συνταχθὲν ὑποχωρούντων εἵποντο κατόπιν ἐπικείμενοι θρασέως καὶ τετολμηκότως. ἅμα δὲ τῷ παραβάλλειν εἰς τοὺς κατὰ τὴν ἐνέδραν τόπους, διαναστάντων τῶν Ἀχαιῶν οἱ μὲν κατεκόπησαν, οἱ δ’ ἑάλωσαν αὐτῶν. —", "st": "16.37"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος ὁρῶν τοὺς Ἀχαιοὺς εὐλαβῶς διακειμένους πρὸς τὸν κατὰ Ῥωμαίων πόλεμον, ἐσπούδαζε κατὰ πάντα τρόπον ἐμβιβάσαι αὐτοὺς εἰς ἀπέχθειαν.", "st": "16.38"}, {"sp": "N", "t": "μαρτυρεῖ τούτοις ἡμῶν τοῖς λόγοις Πολύβιος ὁ Μεγαλοπολίτης· ἐν γὰρ τῇ ἑξκαιδεκάτῃ τῶν ἱστοριῶν αὐτοῦ φησιν οὕτως· \"ὁ δὲ τοῦ Πτολεμαίου στρατηγὸς Σκόπας ὁρμήσας εἰς τοὺς ἄνω τόπους κατεστρέψατο ἐν τῷ χειμῶνι τὸ Ἰουδαίων ἔθνος.\" — τῆς δὲ πολιορκίας ῥεμβώδους γενομένης ὁ μὲν Σκόπας ἠδόξει καὶ διεβέβλητο νεανικῶς. — λέγει δὲ ἐν τῇ αὐτῇ βίβλῳ ὡς \" τοῦ Σκόπα νικηθέντος ὑπ’ Ἀντιόχου τὴν μὲν Βατανέαν καὶ Σαμάρειαν καὶ Ἄβιλα καὶ Γάδαρα παρέλαβεν Ἀντίοχος· μετ’ ὀλίγον δὲ προσεχώρησαν αὐτῷ καὶ τῶν Ἰουδαίων οἱ περὶ τὸ ἱερὸν τὸ προσαγορευόμενον Ἱεροσόλυμα κατοικοῦντες. ὑπὲρ οὗ καὶ πλείω λέγειν ἔχοντες, καὶ μάλιστα περὶ τῆς γενομένης περὶ τὸ ἱερὸν ἐπιφανείας, εἰς ἕτερον καιρὸν ὑπερθησόμεθα τὴν διήγησιν.\"", "st": "16.39"}, {"sp": "N", "t": "Βαβράντιον, τόπος περὶ Χίον. Πολύβιος ἑκκαιδεκάτῳ. Γίττα, πόλις Παλαιστίνης. Πολύβιος ἑκκαιδεκάτῳ. Ἕλλα, χωρίον Ἀσίας, Ἀττάλου βασιλέως ἐμπόριον. Πολύβιος ιϛʹ. Ἴνσοβροι, ἔθνος Ἰταλικόν. Πολύβιος ιϛʹ. Κάνδασα. … φρούριον Καρίας. Πολύβιος ἑκκαιδεκάτῳ. Κάρθαια, μία τῆς ἐν Κέῳ τετραπόλεως. … οἱ οἰκοῦντες Καρθαεῖς. Πολύβιος ιϛʹ. Μάντυα, πόλις Ῥωμαίων. τὸ ἐθνικὸν Μαντυανός. Πολύβιος ἑκκαιδεκάτῳ.", "st": "16.40"}, {"sp": "HDR", "t": "Βιβλίον ΙΖʹ", "st": "17"}, {"sp": "HDR", "t": "Βιβλίον ΙΗʹ", "st": "18"}, {"sp": "N", "t": "ἐπελθόντος δὲ τοῦ τεταγμένου καιροῦ παρῆν ὁ μὲν Φίλιππος ἐκ Δημητριάδος ἀναχθεὶς εἰς τὸν Μηλιέα κόλπον, πέντε λέμβους ἔχων καὶ μίαν πρίστιν, ἐφ’ ἧς αὐτὸς ἐπέπλει. συνῆσαν δ’ αὐτῷ Μακεδόνες μὲν Ἀπολλόδωρος καὶ Δημοσθένης οἱ γραμματεῖς, ἐκ Βοιωτίας Βραχύλλης, Ἀχαιὸς δὲ Κυκλιάδας, ἐκπεπτωκὼς ἐκ Πελοποννήσου διὰ τὰς πρότερον ὑφ’ ἡμῶν εἰρημένας αἰτίας. μετὰ δὲ τοῦ Τίτου παρῆν ὅ τε βασιλεὺς Ἀμύνανδρος καὶ παρ’ Ἀττάλου Διονυσόδωρος, ἀπὸ δὲ τῶν ἐθνῶν καὶ πόλεων τῶν μὲν Ἀχαιῶν Ἀρίσταινος καὶ Ξενοφῶν, παρὰ δὲ Ῥοδίων Ἀκεσίμβροτος ὁ ναύαρχος, παρὰ δὲ τῶν Αἰτωλῶν Φαινέας ὁ στρατηγός, καὶ πλείους δ’ ἕτεροι τῶν πολιτευομένων. συνεγγίσαντες δὲ κατὰ Νίκαιαν πρὸς τὴν θάλατταν, οἱ μὲν περὶ τὸν Τίτον ἐπέστησαν παρ’ αὐτὸν τὸν αἰγιαλόν, ὁ δὲ Φίλιππος ἐγγίσας τῇ γῇ μετέωρος ἔμενε. τοῦ δὲ Τίτου κελεύοντος αὐτὸν ἀποβαίνειν, διαναστὰς ἐκ τῆς νεὼς οὐκ ἔφησεν ἀποβήσεσθαι. τοῦ δὲ πάλιν ἐρομένου τίνα φοβεῖται, φοβεῖσθαι μὲν ἔφησεν ὁ Φίλιππος οὐδένα πλὴν τοὺς θεούς, ἀπιστεῖν δὲ τοῖς πλείστοις τῶν παρόντων, μάλιστα δ’ Αἰτωλοῖς. τοῦ δὲ τῶν Ῥωμαίων στρατηγοῦ θαυμάσαντος καὶ φήσαντος ἴσον εἶναι πᾶσι τὸν κίνδυνον καὶ κοινὸν τὸν καιρόν, μεταλαβὼν ὁ Φίλιππος οὐκ ἔφησεν αὐτὸν ὀρθῶς λέγειν· Φαινέου μὲν γὰρ παθόντος τι πολλοὺς εἶναι τοὺς στρατηγήσοντας Αἰτωλῶν, Φιλίππου δ’ ἀπολομένου κατὰ τὸ παρὸν οὐκ εἶναι τὸν βασιλεύσοντα Μακεδόνων. ἐδόκει μὲν οὖν πᾶσι φορτικῶς κατάρχεσθαι τῆς ὁμιλίας. ὅμως δὲ λέγειν αὐτὸν ἐκέλευεν ὁ Τίτος ὑπὲρ ὧν πάρεστιν. ὁ δὲ Φίλιππος οὐκ ἔφη τὸν λόγον αὑτῷ καθήκειν, ἀλλ’ ἐκείνῳ· διόπερ ἠξίου διασαφεῖν τὸν Τίτον τί δεῖ ποιήσαντα τὴν εἰρήνην ἄγειν. ὁ δὲ τῶν Ῥωμαίων στρατηγὸς αὑτῷ μὲν ἁπλοῦν τινα λόγον ἔφη καθήκειν καὶ φαινόμενον. κελεύειν γὰρ αὐτὸν ἐκ μὲν τῆς Ἑλλάδος ἁπάσης ἐκχωρεῖν, ἀποδόντα τοὺς αἰχμαλώτους καὶ τοὺς αὐτομόλους ἑκάστοις οὓς ἔχει, τοὺς δὲ κατὰ τὴν Ἰλλυρίδα τόπους παραδοῦναι Ῥωμαίοις, ὧν γέγονε κύριος μετὰ τὰς ἐν Ἠπείρῳ διαλύσεις· ὁμοίως δὲ καὶ Πτολεμαίῳ τὰς πόλεις ἀποκαταστῆσαι πάσας, ἃς παρῄρηται μετὰ τὸν Πτολεμαίου τοῦ Φιλοπάτορος θάνατον.", "st": "18.1"}, {"sp": "N", "t": "ταῦτα δ’ εἰπὼν ὁ Τίτος αὐτὸς μὲν ἐπέσχε, πρὸς δὲ τοὺς ἄλλους ἐπιστραφεὶς ἐκέλευε λέγειν ἅπερ ἑκάστοις αὐτῶν οἱ πέμψαντες εἴησαν ἐντεταλμένοι. πρῶτος δὲ Διονυσόδωρος ὁ παρ’ Ἀττάλου μεταλαβὼν τὸν λόγον τάς τε ναῦς ἔφη δεῖν αὐτὸν ἀποδοῦναι τὰς τοῦ βασιλέως τὰς γενομένας αἰχμαλώτους ἐν τῇ περὶ Χίον ναυμαχίᾳ καὶ τοὺς ἅμα ταύταις ἄνδρας, ἀποκαταστῆσαι δὲ καὶ τὸ τῆς Ἀφροδίτης ἱερὸν ἀκέραιον καὶ τὸ Νικηφόριον, ἃ κατέφθειρε. μετὰ δὲ τοῦτον ὁ τῶν Ῥοδίων ναύαρχος Ἀκεσίμβροτος τῆς μὲν Περαίας ἐκέλευεν ἐκχωρεῖν τὸν Φίλιππον, ἧς αὐτῶν παρῄρηται, τὰς δὲ φρουρὰς ἐξάγειν ἐξ Ἰασοῦ καὶ Βαργυλίων καὶ τῆς Εὐρωμέων πόλεως, ἀποκαταστῆσαι δὲ καὶ Περινθίους εἰς τὴν Βυζαντίων συμπολιτείαν, παραχωρεῖν δὲ καὶ Σηστοῦ καὶ Ἀβύδου καὶ τῶν ἐμπορίων καὶ λιμένων τῶν κατὰ τὴν Ἀσίαν ἁπάντων. ἐπὶ δὲ τοῖς Ῥοδίοις Ἀχαιοὶ Κόρινθον ἀπῄτουν καὶ τὴν τῶν Ἀργείων πόλιν ἀβλαβῆ. μετὰ δὲ τούτους Αἰτωλοὶ πρῶτον μὲν τῆς Ἑλλάδος ἁπάσης ἐκέλευον ἐξίστασθαι, καθάπερ καὶ Ῥωμαῖοι, δεύτερον αὑτοῖς ἀποκαθιστάναι τὰς πόλεις ἀβλαβεῖς τὰς πρότερον μετασχούσας τῆς τῶν Αἰτωλῶν συμπολιτείας.", "st": "18.2"}, {"sp": "N", "t": "ταῦτα δ’ εἰπόντος τοῦ Φαινέου τοῦ τῶν Αἰτωλῶν στρατηγοῦ, μεταλαβὼν Ἀλέξανδρος ὁ προσαγορευόμενος Ἴσιος, ἀνὴρ δοκῶν πραγματικὸς εἶναι καὶ λέγειν ἱκανός, οὔτε διαλύεσθαι νῦν ἔφησε τὸν Φίλιππον ἀληθινῶς οὔτε πολεμεῖν γενναίως, ὅταν δέῃ τοῦτο πράττειν, ἀλλ’ ἐν μὲν τοῖς συλλόγοις καὶ ταῖς ὁμιλίαις ἐνεδρεύειν καὶ παρατηρεῖν καὶ ποιεῖν τὰ τοῦ πολεμοῦντος ἔργα, κατ’ αὐτὸν δὲ τὸν πόλεμον ἀδίκως ἵστασθαι καὶ λίαν ἀγεννῶς· ἀφέντα γὰρ τοῦ κατὰ πρόσωπον ἀπαντᾶν τοῖς πολεμίοις, φεύγοντα τὰς πόλεις ἐμπιπράναι καὶ διαρπάζειν καὶ διὰ ταύτης τῆς προαιρέσεως ἡττώμενον τὰ τῶν νικώντων ἆθλα λυμαίνεσθαι. καίτοι γε τοὺς πρότερον Μακεδόνων βεβασιλευκότας οὐ ταύτην ἐσχηκέναι τὴν πρόθεσιν, ἀλλὰ τὴν ἐναντίαν· μάχεσθαι μὲν γὰρ πρὸς ἀλλήλους συνεχῶς ἐν τοῖς ὑπαίθροις, τὰς δὲ πόλεις σπανίως ἀναιρεῖν καὶ καταφθείρειν. τοῦτο δ’ εἶναι πᾶσι φανερὸν ἔκ τε τοῦ πολέμου τοῦ περὶ τὴν Ἀσίαν, ὃν Ἀλέξανδρος ἐπολέμησε πρὸς Δαρεῖον, ἔκ τε τῆς τῶν διαδεξαμένων ἀμφισβητήσεως, καθ’ ἣν ἐπολέμησαν πάντες πρὸς Ἀντίγονον ὑπὲρ τῆς Ἀσίας. παραπλησίως δὲ καὶ τοὺς τούτους διαδεξαμένους μέχρι Πύρρου κεχρῆσθαι τῇ προαιρέσει ταύτῃ· διακινδυνεύειν μὲν γὰρ πρὸς αὑτοὺς ἐν τοῖς ὑπαίθροις προχείρως καὶ πάντα ποιεῖν εἰς τὸ καταγωνίσασθαι διὰ τῶν ὅπλων ἀλλήλους, τῶν δὲ πόλεων φείδεσθαι χάριν τοῦ τοὺς νικήσαντας ἡγεῖσθαι τούτων καὶ τιμᾶσθαι παρὰ τοῖς ὑποταττομένοις. τὸ δ’ ἀναιροῦντα περὶ ὧν ὁ πόλεμός ἐστι τὸν πόλεμον αὐτὸν καταλιπεῖν μανίας ἔργον εἶναι, καὶ ταύτης ἐρρωμένης, ὃ νῦν ποιεῖν τὸν Φίλιππον· τοσαύτας γὰρ διεφθαρκέναι πόλεις ἐν Θετταλίᾳ, φίλον ὄντα καὶ σύμμαχον, καθ’ ὃν καιρὸν ἐκ τῶν ἐν Ἠπείρῳ στενῶν ἐποιεῖτο τὴν σπουδήν, ὅσας οὐδείς ποτε τῶν Θετταλοῖς πεπολεμηκότων διέφθειρε. πολλὰ δὲ καὶ ἕτερα πρὸς ταύτην τὴν ὑπόθεσιν διαλεχθεὶς τελευταίοις ἐχρήσατο τούτοις. ἤρετο γὰρ τὸν Φίλιππον διὰ τί Λυσιμάχειαν μετ’ Αἰτωλῶν ταττομένην καὶ στρατηγὸν ἔχουσαν παρ’ αὐτῶν ἐκβαλὼν τοῦτον κατάσχοι φρουρᾷ τὴν πόλιν· διὰ τί δὲ Κιανούς, παραπλησίως μετ’ Αἰτωλῶν συμπολιτευομένους ἐξανδραποδίσαιτο, φίλος ὑπάρχων Αἰτωλοῖς· τί δὲ λέγων κατέχει νῦν Ἐχῖνον καὶ Θήβας τὰς Φθίας καὶ Φάρσαλον καὶ Λάρισαν.", "st": "18.3"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἀλέξανδρος ταῦτ’ εἰπὼν ἀπεσιώπησεν. ὁ δὲ Φίλιππος ἐγγίσας τῇ γῇ μᾶλλον ἢ πρόσθεν καὶ διαναστὰς ἐπὶ τῆς νεὼς Αἰτωλικὸν ἔφη καὶ θεατρικὸν διατεθεῖσθαι τὸν Ἀλέξανδρον λόγον. σαφῶς γὰρ πάντας γινώσκειν ὅτι τοὺς ἰδίους συμμάχους ἑκὼν μὲν οὐδεὶς διαφθείρει, κατὰ δὲ τὰς τῶν καιρῶν περιστάσεις πολλὰ ποιεῖν ἀναγκάζεσθαι τοὺς ἡγουμένους παρὰ τὰς ἑαυτῶν προαιρέσεις. ἔτι δὲ ταῦτα λέγοντος τοῦ βασιλέως ὁ Φαινέας, ἠλαττωμένος τοῖς ὄμμασιν ἐπὶ πλεῖον, ὑπέκρουε τὸν Φίλιππον, φάσκων αὐτὸν ληρεῖν· δεῖν γὰρ ἢ μαχόμενον νικᾶν ἢ ποιεῖν τοῖς κρείττοσι τὸ προσταττόμενον. ὁ δὲ Φίλιππος, καίπερ ἐν κακοῖς ὤν, ὅμως οὐκ ἀπέσχετο τοῦ καθ’ αὑτὸν ἰδιώματος, ἀλλ’ ἐπιστραφείς \"τοῦτο μὲν\" ἔφησεν \"ὦ Φαινέα, καὶ τυφλῷ δῆλον\". ἦν γὰρ εὔθικτος καὶ πρὸς τοῦτο τὸ μέρος εὖ πεφυκὼς πρὸς τὸ διαχλευάζειν ἀνθρώπους. αὖθις δὲ πρὸς τὸν Ἀλέξανδρον ἐπιστρέψας \"ἐρωτᾷς με\" φησὶν \"Ἀλέξανδρε, διὰ τί Λυσιμάχειαν προσέλαβον; ἵνα μὴ διὰ τὴν ὑμετέραν ὀλιγωρίαν ἀνάστατος ὑπὸ Θρᾳκῶν γένηται, καθάπερ νῦν γέγονεν ἡμῶν ἀπαγαγόντων τοὺς στρατιώτας διὰ τοῦτον τὸν πόλεμον, οὐ τοὺς φρουροῦντας αὐτήν, ὡς σὺ φής, ἀλλὰ τοὺς παραφυλάττοντας. Κιανοῖς δ’ ἐγὼ μὲν οὐκ ἐπολέμησα, Προυσίου δὲ πολεμοῦντος βοηθῶν ἐκείνῳ συνεξεῖλον αὐτούς, ὑμῶν αἰτίων γενομένων· πολλάκις γὰρ κἀμοῦ καὶ τῶν ἄλλων Ἑλλήνων διαπρεσβευομένων πρὸς ὑμᾶς, ἵνα τὸν νόμον ἄρητε τὸν διδόντα τὴν ἐξουσίαν ὑμῖν ἄγειν λάφυρον ἀπὸ λαφύρου, πρότερον ἔφατε τὴν Αἰτωλίαν ἐκ τῆς Αἰτωλίας ἀρεῖν ἢ τοῦτον τὸν νόμον.\"", "st": "18.4"}, {"sp": "N", "t": "τοῦ δὲ Τίτου θαυμάσαντος τί τοῦτ’ ἐστίν, ὁ βασιλεὺς ἐπειρᾶτο διασαφεῖν αὐτῷ, λέγων ὅτι τοῖς Αἰτωλοῖς ἔθος ὑπάρχει μὴ μόνον πρὸς οὓς ἂν αὐτοὶ πολεμῶσι, τούτους αὐτοὺς ἄγειν καὶ τὴν τούτων χώραν, ἀλλὰ κἂν ἕτεροί τινες πολεμῶσι πρὸς ἀλλήλους, ὄντες Αἰτωλῶν φίλοι καὶ σύμμαχοι, μηδὲν ἧττον ἐξεῖναι τοῖς Αἰτωλοῖς ἄνευ κοινοῦ δόγματος καὶ παραβοηθεῖν ἀμφοτέροις τοῖς πολεμοῦσι καὶ τὴν χώραν ἄγειν τὴν ἀμφοτέρων, ὥστε παρὰ μὲν τοῖς Αἰτωλοῖς μήτε φιλίας ὅρους ὑπάρχειν μήτ’ ἔχθρας, ἀλλὰ πᾶσι τοῖς ἀμφισβητοῦσι περί τινος ἑτοίμους ἐχθροὺς εἶναι τούτους καὶ πολεμίους. \" πόθεν οὖν ἔξεστι τούτοις ἐγκαλεῖν νῦν, εἰ φίλος ὑπάρχων Αἰτωλοῖς ἐγώ, Προυσίου δὲ σύμμαχος, ἔπραξά τι κατὰ Κιανῶν, βοηθῶν τοῖς αὑτοῦ συμμάχοις; τὸ δὲ δὴ πάντων δεινότατον, οἱ ποιοῦντες ἑαυτοὺς ἐφαμίλλους Ῥωμαίοις καὶ κελεύοντες ἐκχωρεῖν Μακεδόνας ἁπάσης τῆς Ἑλλάδος· τοῦτο γὰρ ἀναφθέγξασθαι καὶ καθόλου μέν ἐστιν ὑπερήφανον, οὐ μὴν ἀλλὰ Ῥωμαίων μὲν λεγόντων ἀνεκτόν, Αἰτωλῶν δ’ οὐκ ἀνεκτόν· ποίας δὲ κελεύετέ με\" φησὶν \" ἐκχωρεῖν Ἑλλάδος καὶ πῶς ἀφορίζετε ταύτην; αὐτῶν γὰρ Αἰτωλῶν οὐκ εἰσὶν Ἕλληνες οἱ πλείους· τὸ γὰρ τῶν Ἀγραῶν ἔθνος καὶ τὸ τῶν Ἀποδωτῶν, ἔτι δὲ τῶν Ἀμφιλόχων, οὐκ ἔστιν Ἑλλάς. ἢ τούτων μὲν παραχωρεῖτέ μοι;\"", "st": "18.5"}, {"sp": "N", "t": "τοῦ δὲ Τίτου γελάσαντος \"ἀλλὰ δὴ πρὸς μὲν Αἰτωλοὺς ἀρκείτω μοι ταῦτ’\" ἔφη· \"πρὸς δὲ Ῥοδίους καὶ πρὸς Ἄτταλον ἐν μὲν ἴσῳ κριτῇ δικαιότερον ἂν νομισθείη τούτους ἡμῖν ἀποδιδόναι τὰς αἰχμαλώτους ναῦς καὶ τοὺς ἄνδρας ἤπερ ἡμᾶς τούτοις· οὐ γὰρ ἡμεῖς Ἀττάλῳ πρότεροι καὶ Ῥοδίοις τὰς χεῖρας ἐπεβάλομεν, οὗτοι δ’ ἡμῖν ὁμολογουμένως. οὐ μὴν ἀλλὰ σοῦ κελεύοντος Ῥοδίοις μὲν ἀποδίδωμι τὴν Περαίαν, Ἀττάλῳ δὲ τὰς ναῦς καὶ τοὺς ἄνδρας τοὺς διασῳζομένους. τὴν δὲ τοῦ Νικηφορίου καταφθορὰν καὶ τοῦ τῆς Ἀφροδίτης τεμένους ἄλλως μὲν οὐκ εἰμὶ δυνατὸς ἀποκαταστῆσαι, φυτὰ δὲ καὶ κηπουροὺς πέμψω τοὺς φροντιοῦντας θεραπείας τοῦ τόπου καὶ τῆς αὐξήσεως τῶν ἐκκοπέντων δένδρων\". πάλιν δὲ τοῦ Τίτου γελάσαντος ἐπὶ τῷ χλευασμῷ, μεταβὰς ὁ Φίλιππος ἐπὶ τοὺς Ἀχαιοὺς πρῶτον μὲν τὰς εὐεργεσίας ἐξηριθμήσατο τὰς ἐξ Ἀντιγόνου γεγενημένας εἰς αὐτούς, εἶτα τὰς ἰδίας· ἑξῆς δὲ τούτοις προηνέγκατο τὸ μέγεθος τῶν τιμῶν τῶν ἀπηντημένων αὐτοῖς παρὰ τῶν Ἀχαιῶν. τελευταῖον δ’ ἀνέγνω τὸ περὶ τῆς ἀποστάσεως ψήφισμα καὶ τῆς πρὸς Ῥωμαίους μεταθέσεως, ᾗ χρησάμενος ἀφορμῇ πολλὰ κατὰ τῶν Ἀχαιῶν εἰς ἀθεσίαν εἶπε καὶ ἀχαριστίαν. ὅμως δ’ ἔφη τὸ μὲν Ἄργος ἀποδώσειν, περὶ δὲ τοῦ Κορίνθου βουλεύσεσθαι μετὰ τοῦ Τίτου.", "st": "18.6"}, {"sp": "N", "t": "ταῦτα δὲ διαλεχθεὶς πρὸς τοὺς ἄλλους ἤρετο τὸν Τίτον, φήσας πρὸς ἐκεῖνον αὑτῷ τὸν λόγον εἶναι καὶ πρὸς Ῥωμαίους, πότερον οἴεται δεῖν ἐκχωρεῖν ὧν ἐπέκτηται πόλεων καὶ τόπων ἐν τοῖς Ἕλλησιν, ἢ καὶ τούτων ὅσα παρὰ τῶν γονέων παρείληφε. τοῦ δ’ ἀποσιωπήσαντος ἐκ χειρὸς ἀπαντᾶν οἷοί τ’ ἦσαν ὁ μὲν Ἀρίσταινος ὑπὲρ τῶν Ἀχαιῶν, ὁ δὲ Φαινέας ὑπὲρ τῶν Αἰτωλῶν. ἤδη δὲ τῆς ὥρας συγκλειούσης ὁ μὲν τούτων λόγος ἐκωλύθη διὰ τὸν καιρόν, ὁ δὲ Φίλιππος ἠξίου γράψαντας αὑτῷ δοῦναι πάντας ἐφ’ οἷς δεήσει γίνεσθαι τὴν εἰρήνην· μόνος γὰρ ὢν οὐκ ἔχειν μεθ’ ὧν βουλεύηται· διὸ θέλειν αὑτῷ λόγον δοῦναι περὶ τῶν ἐπιταττομένων. ὁ δὲ Τίτος οὐκ ἀηδῶς μὲν ἤκουε τοῦ Φιλίππου χλευάζοντος· μὴ βουλόμενος δὲ τοῖς ἄλλοις [μὴ] δοκεῖν ἀντεπέσκωψε τὸν Φίλιππον εἰπὼν οὕτως· \" εἰκότως\" ἔφη \"Φίλιππε, μόνος εἶ νῦν· τοὺς γὰρ φίλους τοὺς τὰ κράτιστά σοι συμβουλεύσοντας ἀπώλεσας ἅπαντας\". ὁ δὲ Μακεδὼν ὑπομειδιάσας σαρδάνιον ἀπεσιώπησε. καὶ τότε μὲν ἅπαντες, ἐγγράπτους δόντες τῷ Φιλίππῳ τὰς ἑαυτῶν προαιρέσεις ἀκολούθως τοῖς προειρημένοις, ἐχωρίσθησαν, ταξάμενοι κατὰ τὴν ἐπιοῦσαν εἰς Νίκαιαν πάλιν ἀπαντήσειν· τῇ δ’ αὔριον οἱ μὲν περὶ τὸν Τίτον ἧκον ἐπὶ τὸν ταχθέντα τόπον ἐν ὥρᾳ πάντες [ἦσαν], ὁ δὲ Φίλιππος οὐ παρεγίνετο.", "st": "18.7"}, {"sp": "N", "t": "τῆς δ’ ἡμέρας ἤδη προαγούσης ἐπὶ πολὺ καὶ σχεδὸν ἀπεγνωκότων τῶν περὶ τὸν Τίτον, παρῆν ὁ Φίλιππος δείλης ὀψίας ἐπιφαινόμενος μεθ’ ὧν καὶ πρότερον, κατατετριφὼς τὴν ἡμέραν, ὡς μὲν αὐτὸς ἔφη, διὰ τὴν ἀπορίαν καὶ δυσχρηστίαν τῶν ἐπιταττομένων, ὡς δὲ τοῖς ἄλλοις ἐδόκει, βουλόμενος ἐκκλεῖσαι τῷ καιρῷ τήν τε τῶν Ἀχαιῶν καὶ τὴν τῶν Αἰτωλῶν κατηγορίαν· ἑώρα γὰρ τῇ πρόσθεν ἀπαλλαττόμενος ἀμφοτέρους τούτους ἑτοίμους ὄντας πρὸς τὸ συμπλέκεσθαι καὶ μεμψιμοιρεῖν αὐτῷ. διὸ καὶ τότε συνεγγίσας ἠξίου τὸν τῶν Ῥωμαίων στρατηγὸν ἰδίᾳ πρὸς αὐτὸν διαλεχθῆναι περὶ τῶν ἐνεστώτων, ἵνα μὴ λόγοι γένωνται μόνον ἐξ ἀμφοτέρων ἁψιμαχούντων, ἀλλὰ καὶ τέλος τι τοῖς ἀμφισβητουμένοις ἐπιτεθῇ. πλεονάκις δ’ αὐτοῦ παρακαλοῦντος καὶ προσαξιοῦντος, ἤρετο τοὺς συμπαρόντας ὁ Τίτος τί δέον εἴη ποιεῖν. τῶν δὲ κελευόντων συνελθεῖν καὶ διακοῦσαι τῶν λεγομένων, παραλαβὼν ὁ Τίτος Ἄππιον Κλαύδιον χιλίαρχον ὄντα τότε, τοῖς μὲν ἄλλοις μικρὸν ἀπὸ τῆς θαλάττης ἀναχωρήσασιν εἶπεν αὐτόθι μένειν, αὐτὸς δὲ τὸν Φίλιππον ἐκέλευσεν ἐκβαίνειν. ὁ δὲ βασιλεὺς παραλαβὼν Ἀπολλόδωρον καὶ Δημοσθένην ἀπέβη, συμμίξας δὲ τῷ Τίτῳ διελέγετο καὶ πλείω χρόνον. τίνα μὲν οὖν ἦν τὰ τότε ῥηθέντα παρ’ ἑκατέρου, δυσχερὲς εἰπεῖν· ἔφη δ’ οὖν ὁ Τίτος μετὰ τὸ χωρισθῆναι τὸν Φίλιππον, διασαφῶν τοῖς ἄλλοις τὰ παρὰ τοῦ βασιλέως, Αἰτωλοῖς μὲν ἀποδοῦναι Φάρσαλον καὶ Λάρισαν, Θήβας δ’ οὐκ ἀποδιδόναι, Ῥοδίοις δὲ τῆς μὲν Περαίας παραχωρεῖν, Ἰασοῦ δὲ καὶ Βαργυλίων οὐκ ἐκχωρεῖν· Ἀχαιοῖς δὲ παραδιδόναι τὸν Κόρινθον καὶ τὴν τῶν Ἀργείων πόλιν. Ῥωμαίοις δὲ τὰ κατὰ τὴν Ἰλλυρίδα φάναι παραδώσειν καὶ τοὺς αἰχμαλώτους πάντας, Ἀττάλῳ δὲ τάς τε ναῦς ἀποκαταστήσειν καὶ τῶν ἀνδρῶν τῶν ἐν ταῖς ναυμαχίαις ἁλόντων ὅσοι περίεισι.", "st": "18.8"}, {"sp": "N", "t": "πάντων δὲ τῶν παρόντων δυσαρεστουμένων τῇ διαλύσει καὶ φασκόντων δεῖν τὸ κοινὸν ἐπίταγμα πρῶτον ποιεῖν — τοῦτο δ’ ἦν ἁπάσης ἐκχωρεῖν τῆς Ἑλλάδος — εἰ δὲ μή, διότι τὰ κατὰ μέρος μάταια γίνεται καὶ πρὸς οὐδέν, θεωρῶν ὁ Φίλιππος τὴν ἐν αὐτοῖς ἀμφισβήτησιν καὶ δεδιὼς ἅμα τὰς κατηγορίας, ἠξίου τὸν Τίτον ὑπερθέσθαι τὴν σύνοδον εἰς τὴν αὔριον διὰ τὸ καὶ τὴν ὥραν εἰς ὀψὲ συγκλείειν· ἢ γὰρ πείσειν ἢ πεισθήσεσθαι τοῖς παρακαλουμένοις. τοῦ δὲ συγχωρήσαντος, ταξάμενοι συμπορεύεσθαι πρὸς τὸν κατὰ Θρόνιον αἰγιαλόν, τότε μὲν ἐχωρίσθησαν, τῇ δ’ ὑστεραίᾳ πάντες ἧκον ἐπὶ τὸν ταχθέντα τόπον ἐν ὥρᾳ. καὶ βραχέα διαλεχθεὶς ὁ Φίλιππος ἠξίου πάντας, μάλιστα δὲ τὸν Τίτον, μὴ διακόψαι τὴν διάλυσιν, τῶν γε δὴ πλείστων εἰς συμβατικὴν διάθεσιν ἠγμένων, ἀλλ’ εἰ μὲν ἐνδέχεται δι’ αὑτῶν συμφώνους γενέσθαι περὶ τῶν ἀντιλεγομένων· εἰ δὲ μή, πρεσβεύσειν ἔφη πρὸς τὴν σύγκλητον, κἀκείνην πείσειν περὶ τῶν ἀμφισβητουμένων, ἢ ποιήσειν ὅ, τι ποτ’ ἂν ἐπιτάττῃ. ταῦτα δ’ αὐτοῦ προτείνοντος, οἱ μὲν ἄλλοι πάντες ἔφασαν δεῖν πράττειν τὰ τοῦ πολέμου καὶ μὴ προσέχειν τοῖς ἀξιουμένοις. ὁ δὲ τῶν Ῥωμαίων στρατηγὸς οὐκ ἀγνοεῖν μὲν οὐδ’ αὐτὸς ἔφη διότι τὸν Φίλιππον οὐκ εἰκός ἐστι ποιῆσαι τῶν παρακαλουμένων οὐδέν· τῷ δ’ ἁπλῶς μηδὲν ἐμποδίζειν τὰς σφετέρας πράξεις τὴν αἰτουμένην χάριν ὑπὸ τοῦ βασιλέως ἐκποιεῖν ἔφη χαρίζεσθαι. κυρωθῆναι μὲν γὰρ οὐδ’ ὣς εἶναι δυνατὸν οὐδὲν τῶν νῦν λεγομένων ἄνευ τῆς συγκλήτου, πρὸς δὲ τὸ λαβεῖν πεῖραν τῆς ἐκείνων γνώμης εὐφυῶς ἔχειν τὸν ἐπιφερόμενον καιρόν· τῶν γὰρ στρατοπέδων οὐδ’ ὣς δυναμένων οὐδὲν πράττειν διὰ τὸν χειμῶνα, τοῦτον ἀποθέσθαι τὸν χρόνον εἰς τὸ προσανενεγκεῖν τῇ συγκλήτῳ περὶ τῶν προσπιπτόντων, οὐκ ἄθετον, ἀλλ’ οἰκεῖον εἶναι πᾶσι.", "st": "18.9"}, {"sp": "N", "t": "ταχὺ δὲ συγκαταθεμένων ἁπάντων διὰ τὸ θεωρεῖν τὸν Τίτον οὐκ ἀλλότριον ὄντα τῆς ἐπὶ τὴν σύγκλητον ἀναφορᾶς, ἔδοξε συγχωρεῖν τῷ Φιλίππῳ πρεσβεύειν εἰς τὴν Ῥώμην, ὁμοίως δὲ καὶ παρ’ αὑτῶν πέμπειν ἑκάστους πρεσβευτὰς τοὺς διαλεχθησομένους τῇ συγκλήτῳ καὶ κατηγορήσοντας τοῦ Φιλίππου. τοῦ δὲ πράγματος τῷ Τίτῳ τοῦ κατὰ τὸν σύλλογον κατὰ νοῦν καὶ κατὰ τοὺς ἐξ ἀρχῆς διαλογισμοὺς προκεχωρηκότος, παραυτίκα τὸ συνεχὲς τῆς ἐπιβολῆς ἐξύφαινε, τά τε καθ’ αὑτὸν ἀσφαλιζόμενος ἐπιμελῶς καὶ πρόλημμα τῷ Φιλίππῳ ποιῶν οὐδέν. δοὺς γὰρ ἀνοχὰς διμήνους αὐτῷ τὴν μὲν πρεσβείαν τὴν εἰς τὴν Ῥώμην ἐν τούτῳ τῷ χρόνῳ συντελεῖν ἐπέταξε, τὰς δὲ φρουρὰς ἐξάγειν παραχρῆμα τὰς ἐκ τῆς Φωκίδος καὶ Λοκρίδος ἐκέλευσε. διετάξατο δὲ καὶ περὶ τῶν ἰδίων συμμάχων φιλοτίμως, ἵνα κατὰ μηδένα τρόπον μηδὲν εἰς αὐτοὺς ἀδίκημα γίνηται κατὰ τοῦτον τὸν χρόνον ὑπὸ Μακεδόνων. ταῦτα δὲ ποιήσας πρὸς τὸν Φίλιππον ἔγγραπτα, λοιπὸν αὐτὸς ἤδη δι’ αὑτοῦ τὸ προκείμενον ἐπετέλει. καὶ τὸν μὲν Ἀμύνανδρον εἰς τὴν Ῥώμην ἐξέπεμπε παραχρῆμα, γινώσκων αὐτὸν εὐάγωγον μὲν ὄντα καὶ ῥᾳδίως ἐξακολουθήσοντα τοῖς ἐκεῖ φίλοις, ἐφ’ ὁπότερ’ ἂν ἄγωσιν αὐτόν, φαντασίαν δὲ ποιήσοντα καὶ προσδοκίαν διὰ τὸ τῆς βασιλείας ὄνομα. μετὰ δὲ τοῦτον ἐξέπεμπε τοὺς παρ’ αὑτοῦ πρέσβεις, Κόιντόν τε τὸν Φάβιον, ὃς ἦν αὐτῷ τῆς γυναικὸς ἀδελφιδοῦς, καὶ Κόιντον Φολούιον, σὺν δὲ τούτοις Ἄππιον Κλαύδιον ἐπικαλούμενον Νέρωνα. παρὰ δὲ τῶν Αἰτωλῶν ἐπρέσβευον Ἀλέξανδρος Ἴσιος, Δαμόκριτος Καλυδώνιος, Δικαίαρχος Τριχωνιεύς, Πολέμαρχος Ἀρσινοεύς, Λάμιος Ἀμβρακιώτης, Νικόμαχος Ἀκαρνὰν τῶν ἐκ Θουρίου πεφευγότων κατοικούντων δ’ ἐν Ἀμβρακίᾳ, Θεόδοτος Φεραῖος, φυγὰς ἐκ Θετταλίας, κατοικῶν δ’ ἐν Στράτῳ, παρὰ δὲ τῶν Ἀχαιῶν Ξενοφῶν Αἰγιεύς, παρὰ δὲ τοῦ βασιλέως Ἀττάλου μόνος Ἀλέξανδρος, παρὰ δὲ τοῦ δήμου τῶν Ἀθηναίων οἱ περὶ Κηφισόδωρον.", "st": "18.10"}, {"sp": "N", "t": "οὗτοι δὲ παρεγενήθησαν εἰς τὴν Ῥώμην πρὸ τοῦ τὴν σύγκλητον διαλαβεῖν ὑπὲρ τῶν εἰς τοῦτον τὸν ἐνιαυτὸν καθεσταμένων ὑπάτων, πότερον ἀμφοτέρους εἰς τὴν Γαλατίαν ἢ τὸν ἕτερον αὐτῶν δεήσει πέμπειν ἐπὶ Φίλιππον. πεπεισμένων δὲ τῶν τοῦ Τίτου φίλων μένειν τοὺς ὑπάτους ἀμφοτέρους κατὰ τὴν Ἰταλίαν διὰ τὸν ἀπὸ τῶν Κελτῶν φόβον, εἰσελθόντες εἰς τὴν σύγκλητον πάντες κατηγόρουν ἀποτόμως τοῦ Φιλίππου. τὰ μὲν οὖν ἄλλα παραπλήσια τοῖς καὶ πρὸς αὐτὸν τὸν βασιλέα πρότερον εἰρημένοις ἦν· τοῦτο δ’ ἐπιμελῶς ἐντίκτειν ἐπειρῶντο τῇ συγκλήτῳ πάντες, διότι τῆς Χαλκίδος καὶ τοῦ Κορίνθου καὶ τῆς Δημητριάδος ὑπὸ τῷ Μακεδόνι ταττομένων οὐχ οἷόν τε τοὺς Ἕλληνας ἔννοιαν λαβεῖν ἐλευθερίας. ὃ γὰρ αὐτὸς Φίλιππος εἶπε, τοῦτο καὶ λίαν ἀληθὲς ἔφασαν ὑπάρχειν· ὃς ἔφη τοὺς προειρημένους τόπους εἶναι πέδας Ἑλληνικάς, ὀρθῶς ἀποφαινόμενος. οὔτε γὰρ Πελοποννησίους ἀναπνεῦσαι δυνατὸν ἐν Κορίνθῳ βασιλικῆς φρουρᾶς ἐγκαθημένης, οὔτε Λοκροὺς καὶ Βοιωτοὺς καὶ Φωκέας θαρρῆσαι Φιλίππου Χαλκίδα κατέχοντος καὶ τὴν ἄλλην Εὔβοιαν, οὐδὲ μὴν Θετταλοὺς οὐδὲ Μάγνητας δυνατὸν ἐπαύρασθαι τῆς ἐλευθερίας οὐδέποτε, Δημητριάδα Φιλίππου κατέχοντος καὶ Μακεδόνων. διὸ καὶ τὸ παραχωρεῖν τῶν ἄλλων τόπων τὸν Φίλιππον φαντασίαν εἶναι χάριν τοῦ τὸν παρόντα καιρὸν ἐκφυγεῖν· ᾗ δ’ ἂν ἡμέρᾳ βουληθῇ, ῥᾳδίως πάλιν ὑφ’ αὑτὸν ποιήσεσθαι τοὺς Ἕλληνας, ἐὰν κρατῇ τῶν προειρημένων τόπων. διόπερ ἠξίουν τὴν σύγκλητον ἢ τούτων τῶν πόλεων ἀναγκάσαι τὸν Φίλιππον ἐκχωρεῖν ἢ μένειν ἐπὶ τῶν ὑποκειμένων καὶ πολεμεῖν ἐρρωμένως πρὸς αὐτόν. καὶ γὰρ ἠνύσθαι τὰ μέγιστα τοῦ πολέμου, τῶν τε Μακεδόνων προηττημένων δὶς ἤδη καὶ κατὰ γῆν πλείστων αὐτοῖς χορηγιῶν ἐκδεδαπανημένων. ταῦτα δ’ εἰπόντες παρεκάλουν μήτε τοὺς Ἕλληνας ψεῦσαι τῶν περὶ τῆς ἐλευθερίας ἐλπίδων μήθ’ ἑαυτοὺς ἀποστερῆσαι τῆς καλλίστης ἐπιγραφῆς. οἱ μὲν οὖν παρὰ τῶν Ἑλλήνων πρέσβεις ταῦτα καὶ τούτοις παραπλήσια διελέχθησαν, οἱ δὲ παρὰ τοῦ Φιλίππου παρεσκευάσαντο μὲν ὡς ἐπὶ πλεῖον ποιησόμενοι τοὺς λόγους, ἐν ἀρχαῖς δ’ εὐθέως ἐκωλύθησαν· ἐρωτηθέντες γὰρ εἰ παραχωροῦσι Χαλκίδος καὶ Κορίνθου καὶ Δημητριάδος, ἀπεῖπαν μηδεμίαν ἔχειν περὶ τούτων ἐντολήν. οὗτοι μὲν οὖν ἐπιτμηθέντες οὕτως κατέπαυσαν τὸν λόγον.", "st": "18.11"}, {"sp": "N", "t": "ἡ δὲ σύγκλητος τοὺς μὲν ὑπάτους ἀμφοτέρους εἰς Γαλατίαν ἐξαπέστειλε, καθάπερ ἐπάνω προεῖπα, τὸν δὲ πρὸς τὸν Φίλιππον πόλεμον ἐψηφίσατο κατάμονον εἶναι, δοῦσα τῷ Τίτῳ τὴν ἐπιτροπὴν ὑπὲρ τῶν Ἑλληνικῶν. ταχὺ δὲ τούτων εἰς τὴν Ἑλλάδα διασαφηθέντων ἐγεγόνει τῷ Τίτῳ πάντα κατὰ νοῦν, ἐπὶ βραχὺ μὲν καὶ ταὐτομάτου συνεργήσαντος, τὸ δὲ πολὺ διὰ τῆς αὐτοῦ προνοίας ἁπάντων κεχειρισμένων. πάνυ γὰρ ἀγχίνους, εἰ καί τις ἕτερος Ῥωμαίων, [καὶ] ὁ προειρημένος ἀνὴρ γέγονεν· οὕτως γὰρ εὐστόχως ἐχείριζε καὶ νουνεχῶς οὐ μόνον τὰς κοινὰς ἐπιβολάς, ἀλλὰ καὶ τὰς κατ’ ἰδίαν ἐντεύξεις, ὥσθ’ ὑπερβολὴν μὴ καταλιπεῖν. καίτοι γε [καὶ] νέος ἦν κομιδῇ· πλείω γὰρ τῶν τριάκοντ’ ἐτῶν οὐκ εἶχε· καὶ πρῶτος εἰς τὴν Ἑλλάδα διαβεβήκει μετὰ στρατοπέδων. —", "st": "18.12"}, {"sp": "N", "t": "ἔμοιγε πολλάκις μὲν καὶ ἐπὶ πολλοῖς θαυμάζειν ἐπέρχεται τῶν ἀνθρωπείων ἁμαρτημάτων, μάλιστα δ’ ἐπὶ τῷ κατὰ τοὺς προδότας. διὸ καὶ βούλομαι τὰ πρέποντα τοῖς καιροῖς διαλεχθῆναι περὶ αὐτῶν. καίτοι γ’ οὐκ ἀγνοῶ διότι δυσθεώρητον ὁ τόπος ἔχει τι καὶ δυσπαράγραφον· τίνα γὰρ ὡς ἀληθῶς προδότην δεῖ νομίζειν, οὐ ῥᾴδιον ἀποφήνασθαι. δῆλον γὰρ ὡς οὔτε τοὺς ἐξ ἀκεραίου συντιθεμένους τῶν ἀνδρῶν πρός τινας βασιλεῖς ἢ δυνάστας κοινωνίαν πραγμάτων εὐθέως προδότας νομιστέον, οὔτε τοὺς κατὰ τὰς περιστάσεις μετατιθέντας τὰς αὑτῶν πατρίδας ἀπό τινων ὑποκειμένων πρὸς ἑτέρας φιλίας καὶ συμμαχίας, οὐδὲ τούτους. πολλοῦ γε δεῖν· ἐπείτοι γε πολλάκις οἱ τοιοῦτοι τῶν μεγίστων ἀγαθῶν γεγόνασιν αἴτιοι ταῖς ἰδίαις πατρίσιν. ἵνα δὲ μὴ πόρρωθεν τὰ παραδείγματα φέρωμεν, ἐξ αὐτῶν τῶν ἐνεστώτων ῥᾳδίως ἔσται τὸ λεγόμενον κατανοεῖν. εἰ γὰρ μὴ σὺν καιρῷ τότε μετέρριψε τοὺς Ἀχαιοὺς Ἀρίσταινος ἀπὸ τῆς Φιλίππου συμμαχίας πρὸς τὴν Ῥωμαίων, φανερῶς ἄρδην ἀπολώλει τὸ ἔθνος. νῦν δὲ χωρὶς τῆς παρ’ αὐτὸν τὸν καιρὸν ἀσφαλείας ἑκάστοις περιγενομένης, αὐξήσεως τῶν Ἀχαιῶν ὁμολογουμένως ὁ προειρημένος ἀνὴρ κἀκεῖνο τὸ διαβούλιον αἴτιος ἐδόκει γεγονέναι· διὸ καὶ πάντες αὐτὸν οὐχ ὡς προδότην, ἀλλ’ ὡς εὐεργέτην καὶ σωτῆρα τῆς χώρας ἐτίμων. ὁ δ’ αὐτὸς ἂν εἴη λόγος καὶ περὶ τῶν ἄλλων, ὅσοι κατὰ τὰς τῶν καιρῶν περιστάσεις τὰ παραπλήσια τούτοις πολιτεύονται καὶ πράττουσιν.", "st": "18.13"}, {"sp": "N", "t": "ἧι καὶ Δημοσθένην κατὰ πολλά τις ἂν ἐπαινέσας ἐν τούτῳ μέμψαιτο, διότι πικρότατον ὄνειδος τοῖς ἐπιφανεστάτοις τῶν Ἑλλήνων εἰκῇ καὶ ἀκρίτως προσέρριψε, φήσας ἐν μὲν Ἀρκαδίᾳ τοὺς περὶ Κερκιδᾶν καὶ Ἱερώνυμον καὶ Εὐκαμπίδαν προδότας γενέσθαι τῆς Ἑλλάδος, ὅτι Φιλίππῳ συνεμάχουν, ἐν δὲ Μεσσήνῃ τοὺς Φιλιάδου παῖδας Νέωνα καὶ Θρασύλοχον, ἐν Ἄργει δὲ τοὺς περὶ Μύρτιν καὶ Τελέδαμον καὶ Μνασέαν, παραπλησίως ἐν Θετταλίᾳ μὲν τοὺς περὶ Δάοχον καὶ Κινέαν, παρὰ δὲ Βοιωτοῖς τοὺς περὶ Θεογείτονα καὶ Τιμόλαν· σὺν δὲ τούτοις καὶ πλείους ἑτέρους ἐξηρίθμηται, κατὰ πόλιν ὀνομάζων, καίτοι γε πάντων μὲν τῶν προειρημένων ἀνδρῶν πολὺν ἐχόντων λόγον καὶ φαινόμενον ὑπὲρ τῶν καθ’ αὑτοὺς δικαίων, πλεῖστον δὲ τῶν ἐξ Ἀρκαδίας καὶ Μεσσήνης. οὗτοι γὰρ ἐπισπασάμενοι Φίλιππον εἰς Πελοπόννησον καὶ ταπεινώσαντες Λακεδαιμονίους πρῶτον μὲν ἐποίησαν ἀναπνεῦσαι καὶ λαβεῖν ἐλευθερίας ἔννοιαν πάντας τοὺς τὴν Πελοπόννησον κατοικοῦντας, ἔπειτα δὲ τὴν χώραν ἀνακομισάμενοι καὶ τὰς πόλεις, ἃς παρῄρηντο Λακεδαιμόνιοι κατὰ τὴν εὐκαιρίαν Μεσσηνίων, Μεγαλοπολιτῶν, Τεγεατῶν, Ἀργείων, ηὔξησαν τὰς ἑαυτῶν πατρίδας ὁμολογουμένως· ἀνθ’ ὧν οὐ πολεμεῖν ὤφειλον Φιλίππῳ καὶ Μακεδόσιν, ἀλλὰ πάντα κατὰ δύναμιν ἐνεργεῖν ὅσα πρὸς δόξαν καὶ τιμὴν ἀνῆκεν. εἰ μὲν οὖν ταῦτ’ ἔπραττον ἢ φρουρὰν παρὰ Φιλίππου δεχόμενοι ταῖς πατρίσιν ἢ καταλύοντες τοὺς νόμους ἀφῃροῦντο τὴν ἐλευθερίαν καὶ παρρησίαν τῶν πολιτῶν χάριν τῆς ἰδίας πλεονεξίας ἢ δυναστείας, ἄξιοι τῆς προσηγορίας ἦσαν ταύτης· εἰ δὲ τηροῦντες τὰ πρὸς τὰς πατρίδας δίκαια κρίσει πραγμάτων διεφέροντο, νομίζοντες οὐ ταὐτὸ συμφέρον Ἀθηναίοις εἶναι καὶ ταῖς ἑαυτῶν πόλεσιν, οὐ δήπου διὰ τοῦτο καλεῖσθαι προδότας ἐχρῆν αὐτοὺς ὑπὸ Δημοσθένους. ὁ δὲ πάντα μετρῶν πρὸς τὸ τῆς ἰδίας πατρίδος συμφέρον, καὶ πάντας ἡγούμενος δεῖν τοὺς Ἕλληνας ἀποβλέπειν πρὸς Ἀθηναίους, εἰ δὲ μή, προδότας ἀποκαλῶν, ἀγνοεῖν μοι δοκεῖ καὶ πολὺ παραπαίειν τῆς ἀληθείας [ὃ πεποίηκε Δημοσθένης], ἄλλως τε δὴ καὶ τῶν συμβάντων τότε τοῖς Ἕλλησιν οὐ Δημοσθένει μεμαρτυρηκότων ὅτι καλῶς προυνοήθη τοῦ μέλλοντος, ἀλλ’ Εὐκαμπίδᾳ καὶ Ἱερωνύμῳ καὶ Κερκιδᾷ καὶ τοῖς Φιλιάδου παισίν. Ἀθηναίοις μὲν γὰρ τῆς πρὸς Φίλιππον ἀντιπαραγωγῆς τὸ τέλος ἀπέβη τὸ πεῖραν λαβεῖν τῶν μεγίστων συμπτωμάτων πταίσασι τῇ μάχῃ τῇ περὶ Χαιρώνειαν· εἰ δὲ μὴ διὰ τὴν τοῦ βασιλέως μεγαλοψυχίαν καὶ φιλοδοξίαν, καὶ πορρωτέρω τὰ τῆς ἀτυχίας ἂν αὐτοῖς προύβη διὰ τὴν Δημοσθένους πολιτείαν. διὰ δὲ τοὺς προειρημένους ἄνδρας κοινῇ μὲν Ἀρκάσι καὶ Μεσσηνίοις ἀπὸ Λακεδαιμονίων ἀσφάλεια καὶ ῥᾳστώνη παρεσκευάσθη, κατ’ ἰδίαν δὲ ταῖς αὐτῶν πατρίσι πολλὰ καὶ λυσιτελῆ συνεξηκολούθησε.", "st": "18.14"}, {"sp": "N", "t": "τίσιν οὖν εἰκότως ἂν ἐπιφέροι τις τὴν ὀνομασίαν ταύτην, ἔστι μὲν δυσπαράγραφον· μάλιστα δ’ ἂν προστρέχοι πρὸς τὴν ἀλήθειαν ἐπὶ τοὺς τοιούτους φέρων, ὅσοι τῶν ἀνδρῶν κατὰ τὰς ὁλοσχερεῖς περιστάσεις ἢ τῆς ἰδίας ἀσφαλείας καὶ λυσιτελείας χάριν ἢ τῆς πρὸς τοὺς ἀντιπολιτευομένους διαφορᾶς ἐγχειρίζουσι τοῖς ἐχθροῖς τὰς πόλεις, ἢ καὶ νὴ Δία πάλιν ὅσοι φρουρὰν εἰσδεχόμενοι καὶ συγχρώμενοι ταῖς ἔξωθεν ἐπικουρίαις πρὸς τὰς ἰδίας ὁρμὰς καὶ προθέσεις ὑποβάλλουσι τὰς πατρίδας ὑπὸ τὴν τῶν πλεῖον δυναμένων ἐξουσίαν. τοὺς τοιούτους ὑπὸ τὸ τῆς προδοσίας ὄνομα μετρίως ἄν τις ὑποτάττοι πάντας. οἷς λυσιτελὲς μὲν ἀληθῶς ἢ καλὸν οὐδὲν οὐδέποτε συνεξηκολούθησε, τὰ δ’ ἐναντία πᾶσιν ὁμολογουμένως. ᾗ καὶ θαυμάζειν ἔστι πρὸς τὸν ἐξ ἀρχῆς λόγον, πρὸς τί ποτε βλέποντες ἢ τίσι χρώμενοι διαλογισμοῖς ὁρμῶσι πρὸς τὴν τοιαύτην ἀτυχίαν. οὔτε γὰρ ἔλαθε πώποτε προδοὺς οὐδεὶς πόλιν ἢ στρατόπεδον ἢ φρούριον, ἀλλὰ κἂν παρ’ αὐτὸν τὸν τῆς πράξεως καιρὸν ἀγνοηθῇ τις, ὅ γ’ ἐπιγινόμενος χρόνος ἐποίησε φανεροὺς ἅπαντας· οὐδὲ μὴν γνωσθεὶς οὐδεὶς οὐδέποτε μακάριον ἔσχε βίον, ἀλλ’ ὡς μὲν ἐπίπαν ὑπ’ αὐτῶν τούτων οἷς χαρίζονται τυγχάνουσι τῆς ἁρμοζούσης τιμωρίας. χρῶνται μὲν γὰρ τοῖς προδόταις οἱ στρατηγοὶ καὶ δυνάσται πολλάκις διὰ τὸ συμφέρον· ὅταν γε μὴν ἀποχρήσωνται, χρῶνται λοιπὸν ὡς προδόταις, κατὰ τὸν Δημοσθένην, μάλ’ εἰκότως ἡγούμενοι τὸν ἐγχειρίσαντα τοῖς ἐχθροῖς τὴν πατρίδα καὶ τοὺς ἐξ ἀρχῆς φίλους μηδέποτ’ ἂν εὔνουν σφίσι γενέσθαι μηδὲ διαφυλάξαι τὴν πρὸς αὐτοὺς πίστιν. οὐ μὴν ἀλλ’ ἐὰν καὶ τὰς τούτων διαφύγωσι χεῖρας, τάς γε δὴ τῶν παρασπονδηθέντων οὐ ῥᾳδίως ἐκφυγγάνουσιν. ἐὰν δέ ποτε καὶ τὰς ἀμφοτέρων τούτων ἐπιβουλὰς διολίσθωσιν, ἥ γε παρὰ τοῖς ἄλλοις ἀνθρώποις φήμη τιμωρὸς αὐτοῖς ἕπεται παρ’ ὅλον τὸν βίον, πολλοὺς μὲν φόβους ψευδεῖς, πολλοὺς δ’ ἀληθεῖς παριστάνουσα καὶ νύκτωρ καὶ μεθ’ ἡμέραν, πᾶσι δὲ συνεργοῦσα καὶ συνυποδεικνύουσα τοῖς κακόν τι κατ’ ἐκείνων βουλευομένοις, τὸ δὲ τελευταῖον οὐδὲ κατὰ τοὺς ὕπνους ἐῶσα λήθην αὐτοὺς ἔχειν τῶν ἡμαρτημένων, ἀλλ’ ὀνειρώττειν ἀναγκάζουσα πᾶν γένος ἐπιβουλῆς καὶ περιπετείας, ἅτε συνειδότας ἑαυτοῖς τὴν ὑπάρχουσαν ἐκ πάντων ἀλλοτριότητα πρὸς σφᾶς καὶ τὸ κοινὸν μῖσος. ἀλλ’ ὅμως τούτων οὕτως ἐχόντων οὐδεὶς οὐδέποτε δεηθεὶς ἠπόρησε προδότου πλὴν τελέως ὀλίγων τινῶν. ἐξ ὧν εἰκότως εἴποι τις ἂν ὅτι τὸ τῶν ἀνθρώπων γένος, δοκοῦν πανουργότατον εἶναι τῶν ζῴων, πολὺν ἔχει λόγον τοῦ φαυλότατον ὑπάρχειν. τὰ μὲν γὰρ ἄλλα ζῷα, ταῖς τοῦ σώματος ἐπιθυμίαις αὐταῖς δουλεύοντα, διὰ μόνας ταύτας σφάλλεται· τὸ δὲ τῶν ἀνθρώπων γένος, καίπερ δεδοξοποιημένον, οὐχ ἧττον διὰ τὴν ἀλογιστίαν ἢ διὰ τὴν φύσιν ἁμαρτάνει. καὶ ταῦτα μὲν ἡμῖν ἐπὶ τοσοῦτον εἰρήσθω. —", "st": "18.15"}, {"sp": "N", "t": "ὅτι ὁ βασιλεὺς Ἄτταλος ἐτιμᾶτο μὲν καὶ πρότερον ὑπὸ τῆς τῶν Σικυωνίων πόλεως διαφερόντως, ἐξ οὗ τὴν ἱερὰν χώραν τοῦ Ἀπόλλωνος ἐλυτρώσατο χρημάτων αὐτοῖς οὐκ ὀλίγων, ἀνθ’ ὧν καὶ τὸν κολοσσὸν αὐτοῦ τὸν δεκάπηχυν ἔστησαν παρὰ τὸν Ἀπόλλωνα τὸν κατὰ τὴν ἀγοράν. τότε δὲ πάλιν αὐτοῦ δέκα τάλαντα δόντος καὶ μυρίους μεδίμνους πυρῶν, πολλαπλασίως ἐπιταθέντες ταῖς εὐνοίαις εἰκόνα τε χρυσῆν ἐψηφίσαντο καὶ θυσίαν αὐτῷ συντελεῖν κατ’ ἔτος ἐνομοθέτησαν. Ἄτταλος μὲν οὖν τυχὼν τῶν τιμῶν τούτων ἀπῆρεν εἰς Κεγχρεάς. —", "st": "18.16"}, {"sp": "N", "t": "ὅτι Νάβις ὁ τύραννος ἀπολιπὼν ἐπὶ τῆς τῶν Ἀργείων πόλεως Τιμοκράτην τὸν Πελληνέα διὰ τὸ μάλιστα τούτῳ πιστεύειν καὶ χρῆσθαι πρὸς τὰς ἐπιφανεστάτας πράξεις, ἐπανῆλθεν εἰς τὴν Σπάρτην, καὶ μετά τινας ἡμέρας ἐξέπεμψε τὴν γυναῖκα, δοὺς ἐντολὰς παραγενομένην εἰς Ἄργος περὶ πόρον γίνεσθαι χρημάτων. ἡ δ’ ἀφικομένη πολὺ κατὰ τὴν ὠμότητα Νάβιν ὑπερέθετο· ἀνακαλεσαμένη γὰρ τῶν γυναικῶν τινὰς μὲν κατ’ ἰδίαν, τινὰς δὲ κατὰ συγγένειαν, πᾶν γένος αἰκίας καὶ βίας προσέφερε, μέχρι σχεδὸν ἁπασῶν οὐ μόνον τὸν χρυσοῦν ἀφείλετο κόσμον, ἀλλὰ καὶ τὸν ἱματισμὸν τὸν πολυτελέστατον. — ὁ δὲ Ἄτταλος περιβαλλόμενος πλείω λόγον, ὑπεμίμνησκεν αὐτοὺς τῆς ἀνέκαθεν τῶν προγόνων ἀρετῆς. —", "st": "18.17"}, {"sp": "N", "t": "ὁ δὲ Τίτος οὐ δυνάμενος ἐπιγνῶναι τοὺς πολεμίους ᾗ στρατοπεδεύουσι, τοῦτο δὲ σαφῶς εἰδὼς ὅτι πάρεισιν εἰς Θετταλίαν, προσέταξε κόπτειν χάρακα πᾶσιν ἕνεκα τοῦ παρακομίζειν μεθ’ αὑτῶν πρὸς τὰς ἐκ τοῦ καιροῦ χρείας. τοῦτο δὲ κατὰ μὲν τὴν Ἑλληνικὴν ἀγωγὴν ἀδύνατον εἶναι δοκεῖ, κατὰ δὲ τὴν τῶν Ῥωμαίων εὔκοπον. οἱ μὲν γὰρ Ἕλληνες μόλις αὐτῶν κρατοῦσι τῶν σαρισῶν ἐν ταῖς πορείαις καὶ μόλις ὑπομένουσι τὸν ἀπὸ τούτων κόπον, Ῥωμαῖοι δὲ τοὺς μὲν θυρεοὺς τοῖς ὀχεῦσι τοῖς σκυτίνοις ἐκ τῶν ὤμων ἐξηρτηκότες, ταῖς δὲ χερσὶν αὐτοὺς τοὺς γαίσους φέροντες, ἐπιδέχονται τὴν παρακομιδὴν τοῦ χάρακος. ἅμα δὲ καὶ μεγάλην εἶναι συμβαίνει τὴν διαφορὰν τούτων· οἱ μὲν γὰρ Ἕλληνες τοῦτον ἡγοῦνται χάρακα βέλτιστον, ὃς ἂν ἔχῃ πλείστας ἐκφύσεις καὶ μεγίστας πέριξ τοῦ πρέμνου, παρὰ δὲ Ῥωμαίοις δύο κεραίας ἢ τρεῖς ἔχουσιν οἱ χάρακες, ὁ δὲ πλείστας τέτταρας· καὶ ταύτας ἔχοντες λαμβάνονται οὐκ ἐναλλάξ. ἐκ δὲ τούτου συμβαίνει τήν τε κομιδὴν εὐχερῆ γίνεσθαι τελέως — ὁ γὰρ εἷς ἀνὴρ φέρει τρεῖς καὶ τέτταρας συνθεὶς ἐπ’ ἀλλήλους — τήν τε χρείαν ἀσφαλῆ διαφερόντως. ὁ μὲν γὰρ τῶν Ἑλλήνων ὅταν τεθῇ πρὸ τῆς παρεμβολῆς, πρῶτον μέν ἐστιν εὐδιάσπαστος· ὅταν γὰρ τὸ μὲν κρατοῦν καὶ πιεζούμενον ὑπὸ τῆς γῆς ἓν ὑπάρχῃ μόνον, αἱ δ’ ἀποφύσεις ἐκ τούτου πολλαὶ καὶ μεγάλαι, κἄπειτα δύο παραστάντες ἢ τρεῖς ἐκ τῶν ἀποφύσεων ἐπισπάσωνται τὸν αὐτὸν χάρακα, ῥᾳδίως ἐκσπᾶται. τούτου δὲ συμβάντος εὐθέως πύλη γίνεται διὰ τὸ μέγεθος καὶ τὰ παρακείμενα λέλυται, τῷ βραχείας τὰς εἰς ἀλλήλους ἐμπλοκὰς καὶ τὰς ἐπαλλάξεις γίνεσθαι τοῦ τοιούτου χάρακος. παρὰ δὲ Ῥωμαίοις συμβαίνει τοὐναντίον. τιθέασι γὰρ εὐθέως ἐμπλέκοντες εἰς ἀλλήλους οὕτως ὥστε μήτε τὰς κεραίας εὐχερῶς ἐπιγνῶναι, ποίας εἰσὶν ἐκφύσεως τῶν ἐν τῇ γῇ κατωρυγμένων, μήτε τὰς ἐκφύσεις, ποίων κεραιῶν. λοιπὸν οὔτ’ ἐπιλαβέσθαι παρείραντα τὴν χεῖρα δυνατόν, ἅτε πυκνῶν οὐσῶν καὶ προσπιπτουσῶν αὑταῖς, ἔτι δὲ φιλοπόνως ἀπωξυμμένων τῶν κεραιῶν, οὔτ’ ἐπιλαβόμενον ἐκσπάσαι ῥᾴδιον διὰ τὸ πρῶτον μὲν πάσας τὰς προσβολὰς σχεδὸν αὐτοκράτορα τὴν ἐκ τῆς γῆς δύναμιν ἔχειν, δεύτερον δὲ τῷ τὸν μίαν ἐπισπώμενον κεραίαν πολλοὺς ἀναγκάζεσθαι πειθομένους ἅμα βαστάζειν διὰ τὴν εἰς ἀλλήλους ἐμπλοκήν· δύο δὲ καὶ τρεῖς ἐπιλαβέσθαι ταὐτοῦ χάρακος οὐδ’ ὅλως εἰκός. ἐὰν δέ ποτε καὶ κατακρατήσας ἐκσπάσῃ τις ἕνα καὶ δεύτερον, ἀνεπιγνώστως γίνεται τὸ διάστημα. διὸ καὶ μεγάλης οὔσης διαφορᾶς τῷ καὶ τὴν εὕρεσιν ἑτοίμην εἶναι τοῦ τοιούτου χάρακος καὶ τὴν κομιδὴν εὐχερῆ καὶ τὴν χρείαν ἀσφαλῆ καὶ μόνιμον, φανερὸν ὡς εἰ καί τι τῶν ἄλλων πολεμικῶν ἔργων ἄξιον ζήλου καὶ μιμήσεως ὑπάρχει παρὰ Ῥωμαίοις, καὶ τοῦτο, κατά γε τὴν ἐμὴν γνώμην.", "st": "18.18"}, {"sp": "N", "t": "πλὴν ὅ γε Τίτος ἑτοιμασάμενος ταῦτα πρὸς τὰς ἐκ τοῦ καιροῦ χρείας, προῆγε παντὶ τῷ στρατεύματι βάδην, ἀποσχὼν δὲ περὶ πεντήκοντα στάδια τῆς τῶν Φεραίων πόλεως αὐτοῦ παρενέβαλε. κατὰ δὲ τὴν ἐπιοῦσαν ὑπὸ τὴν ἑωθινὴν ἐξέπεμπε τοὺς κατοπτεύσοντας καὶ διερευνησομένους, εἴ τινα δυνηθεῖεν λαβεῖν ἀφορμὴν εἰς τὸ γνῶναι ποῦ ποτ’ εἰσὶ καὶ τί πράττουσιν οἱ πολέμιοι. Φίλιππος δὲ [καὶ] κατὰ τὸν αὐτὸν καιρὸν πυνθανόμενος τοὺς Ῥωμαίους στρατοπεδεύειν περὶ τὰς Θήβας, ἐξάρας ἀπὸ τῆς Λαρίσης παντὶ τῷ στρατεύματι προῆγε, ποιούμενος τὴν πορείαν ὡς ἐπὶ τὰς Φεράς. ἀποσχὼν δὲ περὶ τριάκοντα στάδια, τότε μὲν αὐτοῦ καταστρατοπεδεύσας ἐν ὥρᾳ παρήγγειλε πᾶσι γίνεσθαι περὶ τὴν τοῦ σώματος θεραπείαν, ὑπὸ δὲ τὴν ἑωθινὴν ἐξεγείρας τὴν δύναμιν τοὺς μὲν εἰθισμένους προπορεύεσθαι τῆς δυνάμεως προεξαπέστειλε, συντάξας ὑπερβάλλειν τὰς ὑπὲρ τὰς Φερὰς ἀκρολοφίας, αὐτὸς δὲ τῆς ἡμέρας διαφαινούσης ἐκίνει τὴν δύναμιν ἐκ τοῦ χάρακος. παρ’ ὀλίγον μὲν οὖν ἦλθον ἀμφοτέρων οἱ προεξαπεσταλμένοι τοῦ συμπεσεῖν ἀλλήλοις περὶ τὰς ὑπερβολάς· προϊδόμενοι γὰρ σφᾶς αὐτοὺς ὑπὸ τὴν ὄρφνην ἐκ πάνυ βραχέος διαστήματος ἐπέστησαν, καὶ ταχέως ἔπεμπον, ἀποδηλοῦντες ἀμφότεροι τοῖς ἡγεμόσι τὸ γεγονὸς καὶ πυνθανόμενοι τί δέον εἴη ποιεῖν. ἐπὶ τῶν ὑποκειμένων στρατοπεδειῶν κἀκείνους ἀνακαλεῖσθαι. τῇ δ’ ἐπαύριον ἐξέπεμψαν ἀμφότεροι κατασκοπῆς ἕνεκα τῶν ἱππέων καὶ τῶν εὐζώνων περὶ τριακοσίους ἑκατέρων, ἐν οἷς ὁ Τίτος καὶ τῶν Αἰτωλῶν δύ’ οὐλαμοὺς ἐξαπέστειλε διὰ τὴν ἐμπειρίαν τῶν τόπων· οἳ καὶ συμμίξαντες ἀλλήλοις ἐπὶ τάδε τῶν Φερῶν ὡς πρὸς Λάρισαν συνέβαλλον ἐκθύμως. τῶν δὲ περὶ τὸν Εὐπόλεμον τὸν Αἰτωλὸν εὐρώστως κινδυνευόντων καὶ συνεκκαλουμένων τοὺς Ἰταλικοὺς πρὸς τὴν χρείαν, θλίβεσθαι συνέβαινε τοὺς Μακεδόνας. καὶ τότε μὲν ἐπὶ πολὺν χρόνον ἀκροβολισάμενοι διεχωρίσθησαν εἰς τὰς αὑτῶν παρεμβολάς·", "st": "18.19"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐπιοῦσαν ἀμφότεροι δυσαρεστούμενοι τοῖς περὶ τὰς Φερὰς τόποις διὰ τὸ καταφύτους εἶναι καὶ πλήρεις αἱμασιῶν καὶ κηπίων ἀνέζυξαν. ὁ μὲν οὖν Φίλιππος ἐποιεῖτο τὴν πορείαν ὡς ἐπὶ τὴν Σκοτοῦσσαν, σπεύδων ἐκ ταύτης τῆς πόλεως ἐφοδιάσασθαι, μετὰ δὲ ταῦτα γενόμενος εὐτρεπὴς λαβεῖν τόπους ἁρμόζοντας ταῖς αὑτοῦ δυνάμεσιν· ὁ δὲ Τίτος ὑποπτεύσας τὸ μέλλον ἐκίνει τὴν δύναμιν ἅμα τῷ Φιλίππῳ, σπεύδων προκαταφθεῖραι τὸν ἐν τῇ Σκοτουσσαίᾳ σῖτον. τῆς δ’ ἑκατέρων πορείας μεταξὺ κειμένων ὄχθων ὑψηλῶν, οὔθ’ οἱ Ῥωμαῖοι συνεώρων τοὺς Μακεδόνας, ποῖ ποιοῦνται τὴν πορείαν, οὔθ’ οἱ Μακεδόνες τοὺς Ῥωμαίους. ταύτην μὲν οὖν τὴν ἡμέραν ἑκάτεροι διανύσαντες, ὁ μὲν Τίτος ἐπὶ τὴν προσαγορευομένην Ἐρέτριαν τῆς Φθιώτιδος χώρας, ὁ δὲ Φίλιππος ἐπὶ τὸν Ὀγχηστὸν ποταμόν, αὐτοῦ κατέζευξαν, ἀγνοοῦντες ἀμφότεροι τὰς ἀλλήλων παρεμβολάς· τῇ δ’ ὑστεραίᾳ προελθόντες ἐστρατοπέδευσαν, Φίλιππος μὲν ἐπὶ τὸ Μελάμβιον προσαγορευόμενον τῆς Σκοτουσσαίας, Τίτος δὲ περὶ τὸ Θετίδειον τῆς Φαρσαλίας, ἀκμὴν ἀγνοοῦντες ἀλλήλους. ἐπιγενομένου δ’ ὄμβρου καὶ βροντῶν ἐξαισίων, πάντα συνέβη τὸν ἀέρα τὸν ἐκ τῶν νεφῶν κατὰ τὴν ἐπιοῦσαν ἡμέραν ὑπὸ τὴν ἑωθινὴν πεσεῖν ἐπὶ τὴν γῆν, ὥστε διὰ τὸν ἐφεστῶτα ζόφον μηδὲ τοὺς ἐν ποσὶ δύνασθαι βλέπειν. οὐ μὴν ἀλλ’ ὅ γε Φίλιππος κατανύσαι σπεύδων ἐπὶ τὸ προκείμενον, ἀναζεύξας προῄει μετὰ πάσης τῆς στρατιᾶς. δυσχρηστούμενος δὲ κατὰ τὴν πορείαν διὰ τὴν ὀμίχλην, βραχὺν τόπον διανύσας τὴν μὲν δύναμιν εἰς χάρακα παρενέβαλε, τὴν δ’ ἐφεδρείαν ἀπέστειλε, συντάξας ἐπὶ τοὺς ἄκρους ἐπιβαλεῖν τῶν μεταξὺ κειμένων βουνῶν.", "st": "18.20"}, {"sp": "N", "t": "ὁ δὲ Τίτος στρατοπεδεύων περὶ τὸ Θετίδειον, καὶ διαπορούμενος ὑπὲρ τῶν πολεμίων ποῦ ποτ’ εἰσί, δέκα προθέμενος οὐλαμοὺς καὶ τῶν εὐζώνων εἰς χιλίους ἐξαπέστειλε, παρακαλέσας εὐλαβῶς ἐξερευνωμένους ἐπιπορεύεσθαι τὴν χώραν· οἳ καὶ προάγοντες ὡς ἐπὶ τὰς ὑπερβολὰς ἔλαθον ἐμπεσόντες εἰς τὴν τῶν Μακεδόνων ἐφεδρείαν διὰ τὸ δύσοπτον τῆς ἡμέρας. οὗτοι μὲν οὖν ἐν ταῖς ἀρχαῖς ἐπὶ βραχὺ διαταραχθέντες ἀμφότεροι μετ’ ὀλίγον ἤρξαντο καταπειράζειν ἀλλήλων, διεπέμψαντο δὲ καὶ πρὸς τοὺς ἑαυτῶν ἡγεμόνας ἑκάτεροι τοὺς διασαφήσοντας τὸ γεγονός· ἐπειδὴ δὲ κατὰ τὴν συμπλοκὴν οἱ Ῥωμαῖοι κατεβαροῦντο καὶ κακῶς ἔπασχον ὑπὸ τῆς τῶν Μακεδόνων ἐφεδρείας, πέμποντες εἰς τὴν ἑαυτῶν παρεμβολὴν ἐδέοντο σφίσι βοηθεῖν. ὁ δὲ Τίτος, παρακαλέσας τοὺς περὶ τὸν Ἀρχέδαμον καὶ τὸν Εὐπόλεμον Αἰτωλοὺς καὶ δύο τῶν παρ’ αὑτοῦ χιλιάρχων, ἐξέπεμψε μετὰ πεντακοσίων ἱππέων καὶ δισχιλίων πεζῶν. ὧν προσγενομένων τοῖς ἐξ ἀρχῆς ἀκροβολιζομένοις, παραυτίκα τὴν ἐναντίαν ἔσχε διάθεσιν ὁ κίνδυνος· οἱ μὲν γὰρ Ῥωμαῖοι, προσλαβόντες τὴν ἐκ τῆς βοηθείας ἐλπίδα διπλασίως ἐπερρώσθησαν πρὸς τὴν χρείαν, οἱ δὲ Μακεδόνες ἠμύνοντο μὲν γενναίως, πιεζούμενοι δὲ πάλιν οὗτοι καὶ καταβαρούμενοι τοῖς ὅλοις προσέφυγον πρὸς τοὺς ἄκρους καὶ διεπέμποντο πρὸς τὸν βασιλέα περὶ βοηθείας.", "st": "18.21"}, {"sp": "N", "t": "ὁ δὲ Φίλιππος οὐδέποτ’ ἂν ἐλπίσας κατ’ ἐκείνην τὴν ἡμέραν ὁλοσχερῆ γενέσθαι κίνδυνον διὰ τὰς προειρημένας αἰτίας, ἀφεικὼς ἔτυχε καὶ πλείους ἐκ τῆς παρεμβολῆς ἐπὶ χορτολογίαν. τότε δὲ πυνθανόμενος τὰ συμβαίνοντα παρὰ τῶν διαποστελλομένων, καὶ τῆς ὀμίχλης ἤδη διαφαινούσης, παρακαλέσας Ἡρακλείδην τε τὸν Γυρτώνιον, ὃς ἡγεῖτο τῆς Θετταλικῆς ἵππου, καὶ Λέοντα τὸν τῶν Μακεδόνων ἱππάρχην ἐξέπεμπε, σὺν δὲ τούτοις Ἀθηναγόραν ἔχοντα πάντας τοὺς μισθοφόρους πλὴν τῶν Θρᾳκῶν. συναψάντων δὲ τούτων τοῖς ἐν ταῖς ἐφεδρείαις, καὶ προσγενομένης τοῖς Μακεδόσι βαρείας χειρός, ἐνέκειντο τοῖς πολεμίοις· καὶ πάλιν οὗτοι τοὺς Ῥωμαίους ἤλαυνον ἐκ μεταβολῆς ἀπὸ τῶν ἄκρων. μέγιστον δ’ αὐτοῖς ἐμπόδιον ἦν τοῦ μὴ τρέψασθαι τοὺς πολεμίους ὁλοσχερῶς ἡ τῶν Αἰτωλικῶν ἱππέων φιλοτιμία· πάνυ γὰρ ἐκθύμως οὗτοι καὶ παραβόλως ἐκινδύνευον. Αἰτωλοὶ γάρ, καθ’ ὅσον ἐν τοῖς πεζικοῖς ἐλλιπεῖς εἰσι καὶ τῷ καθοπλισμῷ καὶ τῇ συντάξει πρὸς τοὺς ὁλοσχερεῖς ἀγῶνας, κατὰ τοσοῦτον τοῖς ἱππικοῖς διαφέρουσι πρὸς τὸ βέλτιον τῶν ἄλλων Ἑλλήνων ἐν τοῖς κατὰ μέρος καὶ κατ’ ἰδίαν κινδύνοις. διὸ καὶ τότε τούτων παρακατασχόντων τὴν ἐπιφορὰν τῶν πολεμίων, οὐκέτι συνηλάσθησαν ἕως εἰς τοὺς ἐπιπέδους τόπους, βραχὺ δ’ ἀποσχόντες ἐκ μεταβολῆς ἔστησαν. ὁ δὲ Τίτος, θεωρῶν οὐ μόνον τοὺς εὐζώνους καὶ τοὺς ἱππέας ἐγκεκλικότας, ἀλλὰ διὰ τούτους καὶ τὴν ὅλην δύναμιν ἐπτοημένην, ἐξῆγε τὸ στράτευμα πᾶν καὶ παρενέβαλε πρὸς τοῖς βουνοῖς. κατὰ δὲ τὸν αὐτὸν καιρὸν ἕτερος ἐφ’ ἑτέρῳ τῶν ἐκ τῆς ἐφεδρείας Μακεδόνων ἔθει πρὸς τὸν Φίλιππον, ἀναβοῶν \"βασιλεῦ, φεύγουσιν οἱ πολέμιοι· μὴ παρῇς τὸν καιρόν· οὐ μένουσιν ἡμᾶς οἱ βάρβαροι· σὴ νῦν ἐστιν ἡμέρα, σὸς ὁ καιρός.\" ὥστε τὸν Φίλιππον, καίπερ οὐκ εὐδοκούμενον τοῖς τόποις, ὅμως ἐκκληθῆναι πρὸς τὸν κίνδυνον. οἱ γὰρ προειρημένοι λόφοι καλοῦνται μὲν Κυνὸς Κεφαλαί, τραχεῖς δ’ εἰσὶ καὶ περικεκλασμένοι καὶ πρὸς ὕψος ἱκανὸν ἀνατείνοντες. διὸ καὶ προορώμενος ὁ Φίλιππος τὴν δυσχρηστίαν τῶν τόπων, ἐξ ἀρχῆς μὲν οὐδαμῶς ἡρμόζετο πρὸς ἀγῶνα· τότε δὲ παρορμηθεὶς διὰ τὴν ὑπερβολὴν τῆς εὐελπιστίας τῶν ἀγγελλόντων ἕλκειν παρήγγελλε τὴν δύναμιν ἐκ τοῦ χάρακος.", "st": "18.22"}, {"sp": "N", "t": "ὁ δὲ Τίτος παρεμβαλὼν τὴν αὑτοῦ στρατιὰν ἑξῆς ἅπασαν, ἅμα μὲν ἐφήδρευε τοῖς προκινδυνεύουσιν, ἅμα δὲ παρεκάλει τὰς τάξεις ἐπιπορευόμενος. ἡ δὲ παράκλησις ἦν αὐτοῦ βραχεῖα μέν, ἐμφαντικὴ δὲ καὶ γνώριμος τοῖς ἀκούουσιν. ἐναργῶς γὰρ ὑπὸ τὴν ὄψιν ἐνδεικνύμενος ἔλεγε τοῖς αὑτοῦ στρατιώταις \" οὐχ οὗτοι Μακεδόνες εἰσίν, ὦ ἄνδρες, οὓς ὑμεῖς προκατέχοντας ἐν Μακεδονίᾳ τὰς εἰς τὴν Ἐορδαίαν ὑπερβολὰς ἐκ τοῦ προφανοῦς μετὰ Σολπικίου βιασάμενοι πρὸς τόπους ὑπερδεξίους ἐξεβάλετε, πολλοὺς αὐτῶν ἀποκτείναντες; οὐχ οὗτοι Μακεδόνες εἰσίν, οὓς ὑμεῖς προκατέχοντας τὰς ἀπηλπισμένας ἐν Ἠπείρῳ δυσχωρίας ἐκβιασάμενοι ταῖς ἑαυτῶν ἀρεταῖς φεύγειν ἠναγκάσατε ῥίψαντας τὰ ὅπλα, τέως εἰς Μακεδονίαν ἀνεκομίσθησαν; πῶς οὖν ὑμᾶς εὐλαβεῖσθαι καθήκει, μέλλοντας ἐξ ἴσου ποιεῖσθαι τὸν κίνδυνον πρὸς τοὺς αὐτούς; τί δὲ προορᾶσθαι τῶν προγεγονότων, ἀλλ’ οὐ τἀναντία δι’ ἐκεῖνα καὶ νῦν θαρρεῖν; διόπερ, ὦ ἄνδρες, παρακαλέσαντες σφᾶς αὐτοὺς ὁρμᾶσθε πρὸς τὸν κίνδυνον ἐρρωμένως· θεῶν γὰρ βουλομένων ταχέως πέπεισμαι ταὐτὸ τέλος ἀποβήσεσθαι τῆς παρούσης μάχης τοῖς προγεγονόσι κινδύνοις\". οὗτος μὲν οὖν ταῦτ’ εἰπὼν τὸ μὲν δεξιὸν μέρος ἐκέλευε μένειν κατὰ χώραν καὶ τὰ θηρία πρὸ τούτων, τῷ δ’ εὐωνύμῳ μετὰ τῶν εὐζώνων ἐπῄει σοβαρῶς τοῖς πολεμίοις· οἱ δὲ προκινδυνεύοντες τῶν Ῥωμαίων, προσλαβόντες τὴν τῶν πεζῶν στρατοπέδων ἐφεδρείαν, ἐκ μεταβολῆς ἐνέκειντο τοῖς ὑπεναντίοις.", "st": "18.23"}, {"sp": "N", "t": "Φίλιππος δὲ κατὰ τὸν αὐτὸν καιρόν, ἐπειδὴ τὸ πλέον μέρος ἤδη τῆς ἑαυτοῦ δυνάμεως ἑώρα παρεμβεβληκὸς πρὸ τοῦ χάρακος, αὐτὸς μὲν ἀναλαβὼν τοὺς πελταστὰς καὶ τὸ δεξιὸν τῆς φάλαγγος προῆγε, σύντονον ποιούμενος τὴν πρὸς τοὺς λόφους ἀνάβασιν, τοῖς δὲ περὶ τὸν Νικάνορα τὸν ἐπικαλούμενον ἐλέφαντα συνέταξε φροντίζειν ἵνα τὸ λοιπὸν μέρος τῆς δυνάμεως ἐκ ποδὸς ἕπηται. ἅμα δὲ τῷ τοὺς πρώτους ἅψασθαι τῆς ὑπερβολῆς εὐθέως ἐξ ἀσπίδος παρενέβαλε καὶ προκατελάμβανε τοὺς ὑπερδεξίους· τῶν γὰρ προκινδυνευόντων Μακεδόνων ἐπὶ πολὺ τεθλιφότων τοὺς Ῥωμαίους ἐπὶ θάτερα μέρη τῶν λόφων, ἐρήμους κατέλαβε τοὺς ἄκρους. ἔτι δὲ παρεμβάλλοντος αὐτοῦ τὰ δεξιὰ μέρη τῆς στρατιᾶς, παρῆσαν οἱ μισθοφόροι, πιεζούμενοι κατὰ κράτος ὑπὸ τῶν πολεμίων· προσγενομένων γὰρ τοῖς τῶν Ῥωμαίων εὐζώνοις τῶν ἐν τοῖς βαρέσιν ὅπλοις ἀνδρῶν, καθάπερ ἀρτίως εἶπα, καὶ συνεργούντων κατὰ τὴν μάχην, προσλαβόντες οἷον εἰ σήκωμα τὴν τούτων χρείαν, βαρέως ἐπέκειντο τοῖς πολεμίοις καὶ πολλοὺς αὐτῶν ἔκτεινον. ὁ δὲ βασιλεὺς ἐν μὲν ταῖς ἀρχαῖς, ὅτε παρεγίνετο, θεωρῶν οὐ μακρὰν τῆς τῶν πολεμίων παρεμβολῆς συνεστῶτα τὸν τῶν εὐζώνων κίνδυνον περιχαρὴς ἦν· ὡς δὲ πάλιν ἐκ μεταβολῆς ἑώρα κλίνοντας τοὺς ἰδίους καὶ προσδεομένους ἐπικουρίας, ἠναγκάζετο βοηθεῖν καὶ κρίνειν ἐκ τοῦ καιροῦ τὰ ὅλα, καίπερ ἔτι τῶν πλείστων μερῶν τῆς φάλαγγος κατὰ πορείαν ὄντων καὶ προσβαινόντων πρὸς τοὺς βουνούς. προσδεξάμενος δὲ τοὺς ἀγωνιζομένους, τούτους μὲν ἥθροιζε πάντας ἐπὶ τὸ δεξιὸν κέρας, καὶ τοὺς πεζοὺς καὶ τοὺς ἱππέας, τοῖς δὲ πελτασταῖς καὶ τοῖς φαλαγγίταις παρήγγελλε διπλασιάζειν τὸ βάθος καὶ πυκνοῦν ἐπὶ τὸ δεξιόν. γενομένου δὲ τούτου, καὶ τῶν πολεμίων ἐν χερσὶν ὄντων, τοῖς μὲν φαλαγγίταις ἐδόθη παράγγελμα καταβαλοῦσι τὰς σαρίσας ἐπάγειν, τοῖς δ’ εὐζώνοις κερᾶν. κατὰ δὲ τὸν αὐτὸν καιρὸν καὶ Τίτος, δεξάμενος εἰς τὰ διαστήματα τῶν σημαιῶν τοὺς προκινδυνεύοντας, προσέβαλε τοῖς πολεμίοις.", "st": "18.24"}, {"sp": "N", "t": "γενομένης δὲ τῆς ἐξ ἀμφοῖν συμπτώσεως μετὰ βίας καὶ κραυγῆς ὑπερβαλλούσης, ὡς ἂν ἀμφοτέρων ὁμοῦ συναλαλαζόντων, ἅμα δὲ καὶ τῶν ἐκτὸς τῆς μάχης ἐπιβοώντων τοῖς ἀγωνιζομένοις, ἦν τὸ γινόμενον ἐκπληκτικὸν καὶ παραστατικὸν ἀγωνίας. τὸ μὲν οὖν δεξιὸν τοῦ Φιλίππου λαμπρῶς ἀπήλλαττε κατὰ τὸν κίνδυνον, ἅτε καὶ τὴν ἔφοδον ἐξ ὑπερδεξίου ποιούμενον καὶ τῷ βάρει τῆς συντάξεως ὑπερέχον καὶ τῇ διαφορᾷ τοῦ καθοπλισμοῦ πρὸς τὴν ἐνεστῶσαν χρείαν πολὺ παραλλάττον· τὰ δὲ λοιπὰ μέρη τῆς δυνάμεως αὐτῷ τὰ μὲν ἐχόμενα τῶν κινδυνευόντων ἐν ἀποστάσει τῶν πολεμίων ἦν, τὰ δ’ ἐπὶ τῶν εὐωνύμων ἄρτι διηνυκότα τὰς ὑπερβολὰς ἐπεφαίνετο τοῖς ἄκροις. ὁ δὲ Τίτος, θεωρῶν οὐ δυναμένους τοὺς παρ’ αὑτοῦ στέγειν τὴν τῆς φάλαγγος ἔφοδον, ἀλλ’ ἐκπιεζουμένους τοὺς ἐπὶ τῶν εὐωνύμων, καὶ τοὺς μὲν ἀπολωλότας ἤδη, τοὺς δ’ ἐπὶ πόδα ποιουμένους τὴν ἀναχώρησιν, ἐν δὲ τοῖς δεξιοῖς μέρεσι καταλειπομένας τῆς σωτηρίας τὰς ἐλπίδας, ταχέως ἀφορμήσας πρὸς τούτους, καὶ συνθεασάμενος [τῆς] τῶν πολεμίων τὰ μὲν συνεχῆ τοῖς διαγωνιζομένοις, τὰ δ’ ἐκ τῶν ἄκρων ἀκμὴν ἐπικαταβαίνοντα, τὰ δ’ ἔτι τοῖς ἄκροις ἐφεστῶτα, προθέμενος τὰ θηρία προσῆγε τὰς σημαίας τοῖς πολεμίοις. οἱ δὲ Μακεδόνες, οὔτε τὸν παραγγελοῦντ’ ἔχοντες οὔτε συστῆναι δυνάμενοι καὶ λαβεῖν τὸ τῆς φάλαγγος ἴδιον σχῆμα διά τε τὰς τῶν τόπων δυσχερείας καὶ διὰ τὸ τοῖς ἀγωνιζομένοις ἑπόμενοι πορείας ἔχειν διάθεσιν καὶ μὴ παρατάξεως, οὐδὲ προσεδέξαντο τοὺς Ῥωμαίους εἰς τὰς χεῖρας ἔτι, δι’ αὐτῶν δὲ τῶν θηρίων πτοηθέντες καὶ διασπασθέντες ἐνέκλιναν.", "st": "18.25"}, {"sp": "N", "t": "οἱ μὲν οὖν πλείους τῶν Ῥωμαίων ἑπόμενοι τούτους ἔκτεινον· εἷς δὲ τῶν χιλιάρχων τῶν ἅμα τούτοις, σημαίας ἔχων οὐ πλείους εἴκοσι, καὶ παρ’ αὐτὸν τὸν τῆς χρείας καιρὸν συμφρονήσας ὃ δέον εἴη ποιεῖν, μεγάλα συνεβάλετο πρὸς τὴν τῶν ὅλων κατόρθωσιν. θεωρῶν γὰρ τοὺς περὶ τὸν Φίλιππον ἐπὶ πολὺ προπεπτωκότας τῶν ἄλλων καὶ πιεζοῦντας τῷ βάρει τὸ σφέτερον εὐώνυμον, ἀπολιπὼν τοὺς ἐπὶ τοῦ δεξιοῦ νικῶντας ἤδη καταφανῶς, ἐπιστρέψας ἐπὶ τοὺς ἀγωνιζομένους καὶ κατόπιν ἐπιγενόμενος προσέβαλλε κατὰ νώτου τοῖς Μακεδόσι. τῆς δὲ τῶν φαλαγγιτῶν χρείας ἀδυνάτου καθεστώσης ἐκ μεταβολῆς καὶ κατ’ ἄνδρα κινδυνεύειν, οὗτος μὲν ἐπέκειτο κτείνων τοὺς ἐν ποσίν, οὐ δυναμένους αὑτοῖς βοηθεῖν, ἕως οὗ ῥίψαντες τὰ ὅπλα φεύγειν ἠναγκάσθησαν οἱ Μακεδόνες, συνεπιθεμένων αὐτοῖς ἐκ μεταβολῆς καὶ τῶν κατὰ πρόσωπον ἐγκεκλικότων. ὁ δὲ Φίλιππος ἐν μὲν ταῖς ἀρχαῖς, καθάπερ εἶπα, τεκμαιρόμενος ἐκ τοῦ καθ’ αὑτὸν μέρους ἐπέπειστο τελέως νικᾶν· τότε δὲ συνθεασάμενος ἄφνω ῥιπτοῦντας τὰ ὅπλα τοὺς Μακεδόνας καὶ τοὺς πολεμίους κατὰ νώτου προσβεβληκότας, βραχὺ γενόμενος ἐκ τοῦ κινδύνου μετ’ ὀλίγων ἱππέων καὶ πεζῶν συνεθεώρει τὰ ὅλα. κατανοήσας δὲ τοὺς Ῥωμαίους κατὰ τὸ δίωγμα τοῦ λαιοῦ κέρως τοῖς ἄκροις ἤδη προσπελάζοντας, ἐγίνετο πρὸς τὸ φεύγειν, ὅσους ἐδύνατο πλείστους ἐκ τοῦ καιροῦ συναθροίσας τῶν Θρᾳκῶν καὶ Μακεδόνων. Τίτος δὲ τοῖς φεύγουσιν ἑπόμενος, καὶ καταλαβὼν ἐν ταῖς ὑπερβολαῖς ἄρτι τοῖς ἄκροις ἐπιβαλλούσας τὰς εὐωνύμους τάξεις τῶν Μακεδόνων τὰς μὲν ἀρχὰς ἐπέστη, τῶν πολεμίων ὀρθὰς ἀνασχόντων τὰς σαρίσας, ὅπερ ἔθος ἐστὶ ποιεῖν τοῖς Μακεδόσιν, ὅταν ἢ παραδιδῶσιν αὑτοὺς ἢ μεταβάλλωνται πρὸς τοὺς ὑπεναντίους· μετὰ δὲ ταῦτα πυθόμενος τὴν αἰτίαν τοῦ συμβαίνοντος παρακατεῖχε τοὺς μεθ’ αὑτοῦ φείσασθαι κρίνων τῶν ἀποδεδειλιακότων. ἀκμὴν δὲ τοῦ Τίτου ταῦτα διανοουμένου τῶν προηγουμένων τινὲς ἐπιπεσόντες αὐτοῖς ἐξ ὑπερδεξίου προσέφερον τὰς χεῖρας, καὶ τοὺς μὲν πλείους διέφθειρον, ὀλίγοι δέ τινες διέφυγον ῥίψαντες τὰ ὅπλα.", "st": "18.26"}, {"sp": "N", "t": "πανταχόθεν δὲ τοῦ κινδύνου συντέλειαν εἰληφότος καὶ κρατούντων τῶν Ῥωμαίων, ὁ μὲν Φίλιππος ἐποιεῖτο τὴν ἀποχώρησιν ὡς ἐπὶ τὰ Τέμπη. καὶ τῇ μὲν πρώτῃ περὶ τὸν Ἀλεξάνδρου καλούμενον πύργον ηὐλίσθη, τῇ δ’ ὑστεραίᾳ προελθὼν εἰς Γόννους ἐπὶ τὴν εἰσβολὴν τῶν Τεμπῶν ἐπέμεινε, βουλόμενος ἀναδέξασθαι τοὺς ἐκ τῆς φυγῆς ἀνασῳζομένους. οἱ δὲ Ῥωμαῖοι, μέχρι μέν τινος ἐπακολουθήσαντες τοῖς φεύγουσιν, οἱ μὲν ἐσκύλευον τοὺς τεθνεῶτας, οἱ δὲ τοὺς αἰχμαλώτους ἥθροιζον, οἱ δὲ πλείους ὥρμησαν ἐπὶ τὴν διαρπαγὴν τοῦ τῶν πολεμίων χάρακος· ἔνθα δὴ καταλαβόντες τοὺς Αἰτωλοὺς προεμπεπτωκότας καὶ δόξαντες στέρεσθαι τῆς σφίσι καθηκούσης ὠφελείας, ἤρξαντο καταμέμφεσθαι τοὺς Αἰτωλοὺς καὶ λέγειν πρὸς τὸν στρατηγὸν ὅτι τοὺς μὲν κινδύνους αὐτοῖς ἐπιτάττει, τῆς δ’ ὠφελείας ἄλλοις παρακεχώρηκε. καὶ τότε μὲν ἐπανελθόντες εἰς τὴν ἑαυτῶν στρατοπεδείαν ηὐλίσθησαν, εἰς δὲ τὴν ἐπαύριον ἅμα μὲν ἥθροιζον τοὺς αἰχμαλώτους καὶ τὰ λειπόμενα τῶν σκύλων, ἅμα δὲ προῆγον ποιούμενοι τὴν πορείαν ὡς ἐπὶ Λαρίσης. ἔπεσον δὲ τῶν Ῥωμαίων πρὸς τοὺς ἑπτακοσίους· τῶν δὲ Μακεδόνων ἀπέθανον μὲν οἱ πάντες εἰς ὀκτακισχιλίους, ζωγρίᾳ δ’ ἑάλωσαν οὐκ ἐλάττους πεντακισχιλίων. καὶ τῆς μὲν ἐν Θετταλίᾳ γενομένης περὶ Κυνὸς Κεφαλὰς Ῥωμαίων καὶ Φιλίππου μάχης τοιοῦτον ἀπέβη τὸ τέλος·", "st": "18.27"}, {"sp": "N", "t": "ἐγὼ δὲ κατὰ μὲν τὴν ἕκτην βύβλον ἐν ἐπαγγελίᾳ καταλιπὼν ὅτι λαβὼν τὸν ἁρμόζοντα καιρὸν σύγκρισιν ποιήσομαι τοῦ καθοπλισμοῦ Ῥωμαίων καὶ Μακεδόνων, ὁμοίως δὲ καὶ τῆς συντάξεως τῆς ἑκατέρων, τί διαφέρουσιν ἀλλήλων πρὸς τὸ χεῖρον καὶ τί πρὸς τὸ βέλτιον, νῦν ἐπ’ αὐτῶν τῶν πράξεων πειράσομαι τὴν ἐπαγγελίαν ἐπὶ τέλος ἀγαγεῖν. ἐπεὶ γὰρ ἡ μὲν Μακεδόνων σύνταξις ἐν τοῖς πρὸ τοῦ χρόνοις, δι’ αὐτῶν τῶν ἔργων διδοῦσα τὴν πεῖραν, ἐκράτει τῶν τε κατὰ τὴν Ἀσίαν καὶ τῶν Ἑλληνικῶν συντάξεων, ἡ δὲ Ῥωμαίων τῶν τε κατὰ τὴν Λιβύην καὶ τῶν κατὰ τὴν Εὐρώπην προσεσπερίων ἐθνῶν ἁπάντων, ἐν δὲ τοῖς καθ’ ἡμᾶς καιροῖς οὐχ ἅπαξ, ἀλλὰ πλεονάκις γέγονε τούτων τῶν τάξεων καὶ τῶν ἀνδρῶν πρὸς ἀλλήλους διάκρισις, χρήσιμον καὶ καλὸν ἂν εἴη τὸ τὴν διαφορὰν ἐρευνῆσαι, καὶ παρὰ τί συμβαίνει Ῥωμαίους ἐπικρατεῖν καὶ τὸ πρωτεῖον ἐκφέρεσθαι τῶν κατὰ πόλεμον ἀγώνων, ἵνα μὴ τύχην λέγοντες μόνον μακαρίζωμεν τοὺς κρατοῦντας ἀλόγως, καθάπερ οἱ μάταιοι τῶν ἀνθρώπων, ἀλλ’ εἰδότες τὰς ἀληθεῖς αἰτίας ἐπαινῶμεν καὶ θαυμάζωμεν κατὰ λόγον τοὺς ἡγουμένους. περὶ μὲν οὖν τῶν πρὸς Ἀννίβαν ἀγώνων γεγονότων Ῥωμαίοις καὶ τῶν ἐν τούτοις ἐλαττωμάτων οὐδὲν ἂν δέοι πλείω λέγειν· οὐ γὰρ παρὰ τὸν καθοπλισμὸν οὐδὲ παρὰ τὴν σύνταξιν, ἀλλὰ παρὰ τὴν ἐπιδεξιότητα τὴν Ἀννίβου καὶ τὴν ἀγχίνοιαν περιέπιπτον τοῖς ἐλαττώμασι. δῆλον δὲ τοῦτο πεποιήκαμεν ἡμεῖς ἐπ’ αὐτῶν ὑποδεικνύοντες τῶν ἀγώνων. μαρτυρεῖ δὲ τοῖς ἡμετέροις λόγοις πρῶτον μὲν τὸ τέλος τοῦ πολέμου· προσγενομένου γὰρ στρατηγοῦ τοῖς Ῥωμαίοις παραπλησίαν δύναμιν ἔχοντος Ἀννίβᾳ, ταχέως καὶ τὸ νικᾶν συνεξηκολούθησε τοῖς προειρημένοις· εἶτα καὶ αὐτὸς Ἀννίβας ἀποδοκιμάσας τὸν ἐξ ἀρχῆς αὐτοῖς ὑπάρχοντα καθοπλισμόν, ἅμα τῷ νικῆσαι τῇ πρώτῃ μάχῃ παραχρῆμα τοῖς Ῥωμαίων ὅπλοις καθοπλίσας τὰς οἰκείας δυνάμεις, τούτοις διετέλεσε χρώμενος τὸν ἑξῆς χρόνον. Πύρρος γε μὴν οὐ μόνον ὅπλοις, ἀλλὰ καὶ δυνάμεσιν Ἰταλικαῖς συγκέχρηται, τιθεὶς ἐναλλὰξ σημαίαν καὶ σπεῖραν φαλαγγιτικὴν ἐν τοῖς πρὸς Ῥωμαίους ἀγῶσιν. ἀλλ’ ὅμως οὐδ’ οὕτως ἐδύνατο νικᾶν, ἀλλ’ ἀεί πως ἀμφίδοξα τὰ τέλη τῶν κινδύνων αὐτοῖς ἀπέβαινε. περὶ μὲν οὖν τούτων ἀναγκαῖον ἦν προειπεῖν χάριν τοῦ μηδὲν ἀντεμφαίνειν ταῖς ἡμετέραις ἀποφάσεσιν· ἐπάνειμι δ’ ἐπὶ τὴν προκειμένην σύγκρισιν.", "st": "18.28"}, {"sp": "N", "t": "ὅτι μὲν ἐχούσης τῆς φάλαγγος τὴν αὑτῆς ἰδιότητα καὶ δύναμιν οὐδὲν ἂν ὑποσταίη κατὰ πρόσωπον οὐδὲ μείναι τὴν ἔφοδον αὐτῆς, εὐχερὲς καταμαθεῖν ἐκ πολλῶν. ἐπεὶ γὰρ ὁ μὲν ἀνὴρ ἵσταται σὺν τοῖς ὅπλοις ἐν τρισὶ ποσὶ κατὰ τὰς ἐναγωνίους πυκνώσεις, τὸ δὲ τῶν σαρισῶν μέγεθός ἐστι κατὰ μὲν τὴν ἐξ ἀρχῆς ὑπόθεσιν ἑκκαίδεκα πηχῶν, κατὰ δὲ τὴν ἁρμογὴν τὴν πρὸς τὴν ἀλήθειαν δεκατεττάρων, τούτων δὲ τοὺς τέτταρας ἀφαιρεῖ τὸ μεταξὺ τοῖν χεροῖν διάστημα καὶ τὸ κατόπιν σήκωμα τῆς προβολῆς, φανερὸν ὅτι τοὺς δέκα πήχεις προπίπτειν ἀνάγκη τὴν σάρισαν πρὸ τῶν σωμάτων ἑκάστου τῶν ὁπλιτῶν, ὅταν ἴῃ δι’ ἀμφοῖν τοῖν χεροῖν προβαλόμενος ἐπὶ τοὺς πολεμίους. ἐκ δὲ τούτου συμβαίνει τὰς μὲν τοῦ δευτέρου καὶ τρίτου καὶ τετάρτου πλεῖον, τὰς δὲ τοῦ πέμπτου ζυγοῦ σαρίσας δύο προπίπτειν πήχεις πρὸ τῶν πρωτοστατῶν, ἐχούσης τῆς φάλαγγος τὴν αὑτῆς ἰδιότητα καὶ πύκνωσιν κατ’ ἐπιστάτην καὶ κατὰ παραστάτην, ὡς Ὅμηρος ὑποδείκνυσιν ἐν τούτοις· ἀσπὶς ἄρ’ ἀσπίδ’ ἔρειδε, κόρυς κόρυν, ἀνέρα δ’ ἀνήρ· ψαῦον δ’ ἱππόκομοι κόρυθες λαμπροῖσι φάλοισι νευόντων· ὣς πυκνοὶ ἐφέστασαν ἀλλήλοισι. τούτων δ’ ἀληθινῶς καὶ καλῶς λεγομένων, δῆλον ὡς ἀνάγκη καθ’ ἕκαστον τῶν πρωτοστατῶν σαρίσας προπίπτειν πέντε, δυσὶ πήχεσι διαφερούσας ἀλλήλων κατὰ μῆκος.", "st": "18.29"}, {"sp": "N", "t": "ἐκ δὲ τούτου ῥᾴδιον ὑπὸ τὴν ὄψιν λαβεῖν τὴν τῆς ὅλης φάλαγγος ἔφοδον καὶ προβολήν, ποίαν τιν’ εἰκὸς εἶναι καὶ τίνα δύναμιν ἔχειν, ἐφ’ ἑκκαίδεκα τὸ βάθος οὖσαν. ὧν ὅσοι τὸ πέμπτον ζυγὸν ὑπεραίρουσι, ταῖς μὲν σαρίσαις οὐδὲν οἷοί τ’ εἰσὶ συμβαλέσθαι πρὸς τὸν κίνδυνον· διόπερ οὐδὲ ποιοῦνται κατ’ ἄνδρα τὴν προβολήν, παρὰ δὲ τοὺς ὤμους τῶν προηγουμένων ἀνανενευκυίας φέρουσι χάριν τοῦ τὸν κατὰ κορυφὴν τόπον ἀσφαλίζειν τῆς ἐκτάξεως, εἰργουσῶν τῇ πυκνώσει τῶν σαρισῶν ὅσα τῶν βελῶν ὑπερπετῆ τῶν πρωτοστατῶν φερόμενα δύναται προσπίπτειν πρὸς τοὺς ἐφεστῶτας. αὐτῷ γε μὴν τῷ τοῦ σώματος βάρει κατὰ τὴν ἐπαγωγὴν πιεζοῦντες οὗτοι τοὺς προηγουμένους βιαίαν μὲν ποιοῦσι τὴν ἔφοδον, ἀδύνατον δὲ τοῖς πρωτοστάταις τὴν εἰς τοὔπισθεν μεταβολήν. τοιαύτης περὶ τὴν φάλαγγα διαθέσεως καὶ καθόλου καὶ κατὰ μέρος οὔσης, ῥητέον ἂν εἴη καὶ τοῦ Ῥωμαίων καθοπλισμοῦ καὶ τῆς ὅλης συντάξεως τὰς ἰδιότητας καὶ διαφορὰς ἐκ παραθέσεως. ἵστανται μὲν οὖν ἐν τρισὶ ποσὶ μετὰ τῶν ὅπλων καὶ Ῥωμαῖοι· τῆς μάχης δ’ αὐτοῖς κατ’ ἄνδρα τὴν κίνησιν λαμβανούσης διὰ τὸ τῷ μὲν θυρεῷ σκέπειν τὸ σῶμα, συμμετατιθεμένους αἰεὶ πρὸς τὸν τῆς πληγῆς καιρόν, τῇ μαχαίρᾳ δ’ ἐκ καταφορᾶς καὶ διαιρέσεως ποιεῖσθαι τὴν μάχην, προφανὲς ὅτι χάλασμα καὶ διάστασιν ἀλλήλων ἔχειν δεήσει τοὺς ἄνδρας ἐλάχιστον τρεῖς πόδας κατ’ ἐπιστάτην καὶ κατὰ παραστάτην, εἰ μέλλουσιν εὐχρηστεῖν πρὸς τὸ δέον. ἐκ δὲ τούτου συμβήσεται τὸν ἕνα Ῥωμαῖον ἵστασθαι κατὰ δύο πρωτοστάτας τῶν φαλαγγιτῶν, ὥστε πρὸς δέκα σαρίσας αὐτῷ γίνεσθαι τὴν ἀπάντησιν καὶ τὴν μάχην, ἃς οὔτε κόπτοντα τὸν ἕνα καταταχῆσαι δυνατόν, ὅταν ἅπαξ συνάψωσιν εἰς τὰς χεῖρας, οὔτε βιάσασθαι ῥᾴδιον, μηδέν γε τῶν ἐφεστώτων δυναμένων συμβάλλεσθαι τοῖς πρωτοστάταις μήτε πρὸς τὴν βίαν μήτε πρὸς τὴν τῶν μαχαιρῶν ἐνέργειαν. ἐξ ὧν εὐκατανόητον ὡς οὐχ οἷόν τε μεῖναι κατὰ πρόσωπον τὴν τῆς φάλαγγος ἔφοδον οὐδέν, διατηρούσης τὴν αὑτῆς ἰδιότητα καὶ δύναμιν, ὡς ἐν ἀρχαῖς εἶπα.", "st": "18.30"}, {"sp": "N", "t": "τίς οὖν αἰτία τοῦ νικᾶν Ῥωμαίους καὶ τί τὸ σφάλλον ἐστὶ τοὺς ταῖς φάλαγξι χρωμένους; ὅτι συμβαίνει τὸν μὲν πόλεμον ἀορίστους ἔχειν καὶ τοὺς καιροὺς καὶ τοὺς τόπους τοὺς πρὸς τὴν χρείαν, τῆς δὲ φάλαγγος ἕνα καιρὸν εἶναι καὶ τόπων ἓν γένος, ἐν οἷς δύναται τὴν αὑτῆς χρείαν ἐπιτελεῖν. εἰ μὲν οὖν τις ἦν ἀνάγκη τοῖς ἀντιπάλοις εἰς τοὺς τῆς φάλαγγος καιροὺς καὶ τόπους συγκαταβαίνειν, ὅτε μέλλοιεν κρίνεσθαι περὶ τῶν ὅλων, εἰκὸς ἦν κατὰ τὸν ἄρτι λόγον ἀεὶ φέρεσθαι τὸ πρωτεῖον τοὺς ταῖς φάλαγξι χρωμένους· εἰ δὲ δυνατὸν ἐκκλίνειν καὶ τοῦτο ποιεῖν ῥᾳδίως, πῶς ἂν ἔτι φοβερὸν εἴη τὸ προειρημένον σύνταγμα; καὶ μὴν ὅτι χρείαν ἔχει τόπων ἐπιπέδων καὶ ψιλῶν ἡ φάλαγξ, πρὸς δὲ τούτοις μηδὲν ἐμπόδιον ἐχόντων, λέγω δ’ οἷον τάφρους, ἐκρήγματα, συναγκείας, ὀφρῦς, ῥεῖθρα ποταμῶν, ὁμολογούμενόν ἐστι. πάντα γὰρ τὰ προειρημένα παραποδίζειν καὶ λύειν τὴν τοιαύτην τάξιν ἱκανὰ γίνεται. διότι δ’ εὑρεῖν τόπους ποτὲ μὲν ἐπὶ σταδίους εἴκοσι, ποτὲ δὲ καὶ πλείους, ἐν οἷς μηδέν τι τοιοῦτον ὑπάρχει, σχεδόν, ὡς εἰπεῖν, ἀδύνατόν ἐστιν, εἰ δὲ μή γε, τελέως σπάνιον, καὶ τοῦτο πᾶς ἄν τις ὁμολογήσειεν. οὐ μὴν ἀλλ’ ἔστω τόπους εὑρῆσθαι τοιούτους. ἐὰν οὖν οἱ [μὲν] πολεμοῦντες εἰς μὲν τούτους μὴ συγκαταβαίνωσι, περιπορευόμενοι δὲ πορθῶσι τὰς πόλεις καὶ τὴν χώραν τὴν τῶν συμμάχων, τί τῆς τοιαύτης ὄφελος ἔσται συντάξεως; μένουσα μὲν γὰρ ἐν τοῖς ἐπιτηδείοις αὑτῇ τόποις οὐχ οἷον ὠφελεῖν δύναιτ’ ἂν τοὺς φίλους, ἀλλ’ οὐδ’ ἑαυτὴν σῴζειν. αἱ γὰρ τῶν ἐπιτηδείων παρακομιδαὶ κωλυθήσονται ῥᾳδίως ὑπὸ τῶν πολεμίων, ὅταν ἀκονιτὶ κρατῶσι τῶν ὑπαίθρων· ἐὰν δ’ ἀπολιποῦσα τοὺς οἰκείους τόπους βούληταί τι πράττειν, εὐχείρωτος ἔσται τοῖς πολεμίοις. οὐ μὴν ἀλλὰ κἂν εἰς τοὺς ἐπιπέδους συγκαταβάς τις τόπους μὴ πᾶν ἅμα τὸ σφέτερον στρατόπεδον ὑπὸ τὴν ἐπαγωγὴν τῆς φάλαγγος καὶ τὸν ἕνα καιρὸν ὑποβάλῃ, βραχέα δὲ φυγομαχήσῃ κατ’ αὐτὸν τὸν τοῦ κινδύνου καιρόν, εὐθεώρητον γίνεται τὸ συμβησόμενον ἐξ ὧν ποιοῦσι Ῥωμαῖοι νῦν.", "st": "18.31"}, {"sp": "N", "t": "οὐκέτι γὰρ ἐκ τοῦ λόγου δεῖ τεκμαίρεσθαι τὸ νυνὶ λεγόμενον ὑφ’ ἡμῶν, ἀλλ’ ἐκ τῶν ἤδη γεγονότων. οὐ γὰρ ἐξισώσαντες τὴν παράταξιν πᾶσιν ἅμα συμβάλλουσι τοῖς στρατοπέδοις μετωπηδὸν πρὸς τὰς φάλαγγας, ἀλλὰ τὰ μὲν ἐφεδρεύει τῶν μερῶν αὐτοῖς, τὰ δὲ συμμίσγει τοῖς πολεμίοις. λοιπόν, ἄν τ’ ἐκπιέσωσιν οἱ φαλαγγῖται τοὺς καθ’ αὑτοὺς προσβάλλοντες ἄν τ’ ἐκπιεσθῶσιν ὑπὸ τούτων, λέλυται τὸ τῆς φάλαγγος ἴδιον· ἢ γὰρ ἑπόμενοι τοῖς ὑποχωροῦσιν ἢ φεύγοντες τοὺς προσκειμένους ἀπολείπουσι τὰ λοιπὰ μέρη τῆς οἰκείας δυνάμεως, οὗ γενομένου δέδοται τοῖς ἐφεδρεύουσι τῶν πολεμίων διάστημα καὶ τόπος, ὃν οὗτοι κατεῖχον, πρὸς τὸ μηκέτι κατὰ πρόσωπον ὁρμᾶν, ἀλλὰ παρεισπεσόντας πλαγίους παρίστασθαι καὶ κατὰ νώτου τοῖς φαλαγγίταις. ὅταν δὲ τοὺς μὲν τῆς φάλαγγος καιροὺς καὶ τὰ προτερήματα ῥᾴδιον ᾖ φυλάξασθαι, τοὺς δὲ κατὰ τῆς φάλαγγος ἀδύνατον, πῶς οὐ μεγάλην εἰκὸς εἶναι τὴν διαφορὰν ἐπὶ τῆς ἀληθείας τῶν προειρημένων; καὶ μὴν πορευθῆναι διὰ τόπων παντοδαπῶν ἀναγκαῖον τοὺς χρωμένους φάλαγγι καὶ καταστρατοπεδεῦσαι, ἔτι δὲ τόπους εὐκαίρους προκαταλαβέσθαι καὶ πολιορκῆσαί τινας καὶ πολιορκηθῆναι καὶ παραδόξοις ἐπιφανείαις περιπεσεῖν· ἅπαντα γὰρ ταῦτ’ ἐστὶ πολέμου μέρη καὶ ῥοπὰς ποιεῖ πρὸς τὸ νικᾶν, ποτὲ μὲν ὁλοσχερεῖς, ποτὲ δὲ μεγάλας. ἐν οἷς πᾶσιν ἡ μὲν Μακεδόνων ἐστὶ σύνταξις δύσχρηστος, ποτὲ δ’ ἄχρηστος, διὰ τὸ μὴ δύνασθαι τὸν φαλαγγίτην μήτε κατὰ τάγμα μήτε κατ’ ἄνδρα παρέχεσθαι χρείαν, ἡ δὲ Ῥωμαίων εὔχρηστος· πᾶς γὰρ Ῥωμαῖος, ὅταν ἅπαξ καθοπλισθεὶς ὁρμήσῃ πρὸς τὴν χρείαν, ὁμοίως ἥρμοσται πρὸς πάντα τόπον καὶ καιρὸν καὶ πρὸς πᾶσαν ἐπιφάνειαν. καὶ μὴν ἕτοιμός ἐστι καὶ τὴν αὐτὴν ἔχει διάθεσιν, ἄν τε μετὰ πάντων δέῃ κινδυνεύειν ἄν τε μετὰ μέρους ἄν τε κατὰ σημαίαν ἄν τε καὶ κατ’ ἄνδρα. διὸ καὶ παρὰ πολὺ τῆς κατὰ μέρος εὐχρηστίας διαφερούσης, παρὰ πολὺ καὶ τὰ τέλη συνεξακολουθεῖ ταῖς Ῥωμαίων προθέσεσι μᾶλλον ἢ ταῖς τῶν ἄλλων. περὶ μὲν οὖν τούτων ἀναγκαῖον ἡγησάμην εἶναι τὸ διὰ πλειόνων ποιήσασθαι μνήμην διὰ τὸ καὶ παρ’ αὐτὸν τὸν καιρὸν πολλοὺς τῶν Ἑλλήνων διαλαμβάνειν, ὅτε Μακεδόνες ἡττήθησαν, ἀπίστῳ τὸ γεγονὸς ἐοικέναι, καὶ μετὰ ταῦτα πολλοὺς διαπορήσειν διὰ τί καὶ πῶς λείπεται τὸ σύνταγμα τῆς φάλαγγος ὑπὸ τοῦ Ῥωμαίων καθοπλισμοῦ.", "st": "18.32"}, {"sp": "N", "t": "Φίλιππος δέ, τὰ δυνατὰ πεποιηκὼς πρὸς τὸν ἀγῶνα, τοῖς δ’ ὅλοις πράγμασιν ἐσφαλμένος, ἀναδεξάμενος ὅσους ἐδύνατο πλείστους τῶν ἐκ τῆς μάχης ἀνασῳζομένων, αὐτὸς μὲν ὥρμησε διὰ τῶν Τεμπῶν εἰς Μακεδονίαν. εἰς δὲ τὴν Λάρισαν ἔτι τῇ προτεραίᾳ νυκτὶ διεπέμψατό τινα τῶν ὑπασπιστῶν, ἐντειλάμενος ἀφανίσαι καὶ κατακαῦσαι τὰ βασιλικὰ γράμματα, ποιῶν πρᾶγμα βασιλικὸν τὸ μηδ’ ἐν τοῖς δεινοῖς λήθην ποιεῖσθαι τοῦ καθήκοντος· σαφῶς γὰρ ᾔδει διότι πολλὰς ἀφορμὰς δώσει τοῖς ἐχθροῖς καὶ καθ’ ἑαυτοῦ καὶ κατὰ τῶν φίλων, ἐὰν κρατήσωσι Ῥωμαῖοι τῶν ὑπομνημάτων. ἴσως μὲν οὖν καὶ ἑτέροις ἤδη τοῦτο συμβέβηκε, τὸ τὰς μὲν ἐν ταῖς ἐπιτυχίαις ἐξουσίας μὴ δύνασθαι φέρειν ἀνθρωπίνως, ἐν δὲ ταῖς περιπετείαις εὐλαβῶς ἵστασθαι καὶ νουνεχῶς· ἐν τοῖς δὲ μάλιστα καὶ περὶ Φίλιππον τοῦτο γέγονε. δῆλον δ’ ἔσται τοῦτο διὰ τῶν μετὰ ταῦτα ῥηθησομένων· καθάπερ γὰρ καὶ τὰς ἐξ ἀρχῆς ὁρμὰς ἐπὶ τὸ δέον αὐτοῦ σαφῶς ἐδηλώσαμεν, καὶ πάλιν τὴν ἐπὶ τὸ χεῖρον μεταβολήν, καὶ πότε καὶ διὰ τί καὶ πῶς ἐγένετο, καὶ τὰς ἐν ταύτῃ πράξεις μετ’ ἀποδείξεως ἐξηγησάμεθα, τὸν αὐτὸν τρόπον χρὴ καὶ τὴν μετάνοιαν αὐτοῦ δηλῶσαι καὶ τὴν εὐστοχίαν, καθ’ ἣν μεταθέμενος τοῖς ἐκ τῆς τύχης ἐλαττώμασιν εὐλογιστότατα δοκεῖ κεχρῆσθαι τοῖς καθ’ αὑτὸν καιροῖς. Τίτος δὲ μετὰ τὴν μάχην ποιησάμενος τὴν καθήκουσαν πρόνοιαν περί τε τῶν αἰχμαλώτων καὶ τῶν ἄλλων λαφύρων, ᾔει πρὸς Λάρισαν. —", "st": "18.33"}, {"sp": "N", "t": "καθόλου τῇ περὶ τὰ λάφυρα πλεονεξίᾳ τῶν Αἰτωλῶν εἴτ’ οὐκ ἐβούλετο Φίλιππον ἐκβαλὼν ἐκ τῆς ἀρχῆς Αἰτωλοὺς καταλιπεῖν δεσπότας τῶν Ἑλλήνων. δυσχερῶς δ’ ἔφερε καὶ τὴν ἀλαζονείαν αὐτῶν, θεωρῶν ἀντεπιγραφομένους ἐπὶ τὸ νίκημα καὶ πληροῦντας τὴν Ἑλλάδα τῆς αὑτῶν ἀνδραγαθίας. διὸ καὶ κατά τε τὰς ἐντεύξεις ἀγερωχότερον αὐτοῖς ἀπήντα καὶ περὶ τῶν κοινῶν ἀπεσιώπα, τὰ δὲ προκείμενα συνετέλει καὶ δι’ αὑτοῦ καὶ διὰ τῶν ἰδίων φίλων. τοιαύτης δ’ οὔσης δυσχρηστίας ἐν ἀμφοτέροις, ἧκον πρεσβευταὶ μετά τινας ἡμέρας παρὰ τοῦ Φιλίππου Δημοσθένης καὶ Κυκλιάδας καὶ Λιμναῖος. πρὸς οὓς κοινολογηθεὶς ὁ Τίτος ἐπὶ πλεῖον μετὰ τῶν χιλιάρχων πεντεκαιδεχημέρους ἀνοχὰς ἐποιήσατο παραχρῆμα, συνετάξατο δὲ καὶ συμπορεύεσθαι τῷ Φιλίππῳ κοινολογησόμενος ὑπὲρ τῶν καθεστώτων ἐν ταύταις. γενομένης δὲ ταύτης τῆς ἐντεύξεως φιλανθρώπου, διπλασίως ἐξεκάετο τὰ τῆς ὑποψίας κατὰ τοῦ Τίτου· ἤδη γὰρ κατὰ τὴν Ἑλλάδα τῆς δωροδοκίας ἐπιπολαζούσης καὶ τοῦ μηδένα μηδὲν δωρεὰν πράττειν, καὶ τοῦ χαρακτῆρος τούτου νομιστευομένου παρὰ τοῖς Αἰτωλοῖς, οὐκ ἐδύναντο πιστεύειν διότι χωρὶς δώρων ἡ τηλικαύτη μεταβολὴ γέγονε τοῦ Τίτου πρὸς τὸν Φίλιππον, οὐκ εἰδότες τὰ Ῥωμαίων ἔθη καὶ νόμιμα περὶ τοῦτο τὸ μέρος, ἀλλ’ ἐξ αὑτῶν τεκμαιρόμενοι καὶ συλλογιζόμενοι διότι τὸν μὲν Φίλιππον εἰκὸς ἦν προτείνειν πλῆθος χρημάτων διὰ τὸν καιρόν, τὸν δὲ Τίτον μὴ δύνασθαι τούτοις ἀντοφθαλμεῖν.", "st": "18.34"}, {"sp": "N", "t": "ἐγὼ δὲ κατὰ μὲν τοὺς ἀνωτέρω χρόνους καὶ κοινὴν ἂν ποιούμενος ἀπόφασιν ἐθάρρησα περὶ πάντων Ῥωμαίων εἰπεῖν ὡς οὐδὲν ἂν πράξαιεν τοιοῦτον, λέγω δὲ πρότερον ἢ τοῖς διαποντίοις αὐτοὺς ἐγχειρῆσαι πολέμοις, ἕως ἐπὶ τῶν ἰδίων ἐθῶν καὶ νομίμων ἔμενον. ἐν δὲ τοῖς νῦν καιροῖς περὶ πάντων μὲν οὐκ ἂν τολμήσαιμι τοῦτ’ εἰπεῖν· κατ’ ἰδίαν μέντοι γε περὶ πλειόνων ἀνδρῶν ἐν Ῥώμῃ θαρρήσαιμ’ ἂν ἀποφήνασθαι διότι δύνανται τὴν πίστιν ἐν τούτῳ τῷ μέρει διαφυλάττειν. μαρτυρίας δὲ χάριν ὁμολογούμενα δύ’ ὀνόματα τοῦ μὴ δοκεῖν ἀδύνατα λέγειν. Λεύκιος μὲν γὰρ Αἰμίλιος ὁ Περσέα νικήσας, κύριος γενόμενος τῆς Μακεδόνων βασιλείας, ἐν ᾗ τῆς ἄλλης χωρὶς κατασκευῆς καὶ χορηγίας ἐν αὐτοῖς εὑρέθη τοῖς θησαυροῖς ἀργυρίου καὶ χρυσίου πλείω τῶν ἑξακισχιλίων ταλάντων, οὐχ οἷον ἐπεθύμησε τούτων τινός, ἀλλ’ οὐδ’ αὐτόπτης ἠβουλήθη γενέσθαι, δι’ ἑτέρων δὲ τὸν χειρισμὸν ἐποιήσατο τῶν προειρημένων, καίτοι κατὰ τὸν ἴδιον βίον οὐ περιττεύων τῇ χορηγίᾳ, τὸ δ’ ἐναντίον ἐλλείπων μᾶλλον. μεταλλάξαντος γοῦν αὐτοῦ τὸν βίον οὐ πολὺ κατόπιν τοῦ πολέμου, βουληθέντες οἱ κατὰ φύσιν υἱοὶ Πόπλιος Σκιπίων καὶ Κόιντος Μάξιμος ἀποδοῦναι τῇ γυναικὶ τὴν φερνήν, εἴκοσι τάλαντα καὶ πέντε, ἐπὶ τοσοῦτον ἐδυσχρηστήθησαν ὡς οὐδ’ εἰς τέλος ἐδυνήθησαν, εἰ μὴ τὴν ἐνδουχίαν ἀπέδοντο καὶ τὰ σώματα καὶ σὺν τούτοις ἔτι τινὰς τῶν κτήσεων. εἰ δέ τισιν ἀπίστῳ τὸ λεγόμενον ἐοικέναι δόξει, ῥᾴδιον ὑπὲρ τούτου λαβεῖν πίστιν· πολλῶν γὰρ ἀμφισβητουμένων παρὰ Ῥωμαίοις καὶ μάλιστα περὶ τοῦτο τὸ μέρος διὰ τὰς πρὸς ἀλλήλους ἀντιπαραγωγάς, ὅμως τὸ νῦν εἰρημένον ὑφ’ ἡμῶν ὁμολογούμενον εὑρήσει παρὰ πᾶσιν ὁ ζητῶν. καὶ μὴν Πόπλιος Σκιπίων, ὁ τούτου μὲν κατὰ φύσιν υἱός, Ποπλίου δὲ τοῦ μεγάλου κληθέντος κατὰ θέσιν υἱωνός, κύριος γενόμενος τῆς Καρχηδόνος, ἥτις ἐδόκει πολυχρημονεστάτη τῶν κατὰ τὴν οἰκουμένην εἶναι πόλεων, ἁπλῶς τῶν ἐξ ἐκείνης οὐδὲν εἰς τὸν ἴδιον βίον μετήγαγεν, οὔτ’ ὠνησάμενος οὔτ’ ἄλλῳ τρόπῳ κτησάμενος οὐδέν, καίπερ οὐχ ὅλως εὐπορούμενος κατὰ τὸν βίον, ἀλλὰ μέτριος ὢν κατὰ τὴν ὕπαρξιν, ὡς Ῥωμαῖος. οὐχ οἷον δὲ τῶν ἐξ αὐτῆς τῆς Καρχηδόνος ἀπέσχετο μόνον, ἀλλὰ καὶ καθόλου τῶν ἐκ τῆς Λιβύης οὐδὲν ἐπιμιχθῆναι πρὸς τὸν ἴδιον εἴασε βίον. περὶ δὲ τούτου πάλιν τἀνδρὸς ὁ ζητῶν ἀληθινῶς ἀναμφισβήτητον εὑρήσει παρὰ Ῥωμαίοις τὴν περὶ τοῦτο τὸ μέρος δόξαν.", "st": "18.35"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὑπὲρ μὲν τούτων οἰκειότερον λαβόντες καιρὸν ποιησόμεθα τὴν ἐπὶ πλεῖον διαστολήν. ὁ δὲ Τίτος ταξάμενος ἡμέραν πρὸς τὸν Φίλιππον τοῖς μὲν συμμάχοις ἔγραψε παραχρῆμα, διασαφῶν πότε δεήσει παρεῖναι πρὸς τὸν σύλλογον, αὐτὸς δὲ μετά τινας ἡμέρας ἧκε πρὸς τὴν εἰσβολὴν τῶν Τεμπῶν εἰς τὸν ταχθέντα χρόνον. ἁθροισθέντων δὲ τῶν συμμάχων καὶ τοῦ συνεδρίου συναχθέντος ἐξ αὐτῶν τούτων, ἀναστὰς ὁ τῶν Ῥωμαίων στρατηγὸς ἐκέλευε λέγειν ἕκαστον ἐφ’ οἷς δεῖ ποιεῖσθαι τὰς πρὸς τὸν Φίλιππον διαλύσεις. Ἀμύνανδρος μὲν οὖν ὁ βασιλεὺς βραχέα διαλεχθεὶς καὶ μέτρια κατέπαυσε τὸν λόγον· ἠξίου γὰρ πρόνοιαν αὑτοῦ ποιήσασθαι πάντας, ἵνα μὴ χωρισθέντων Ῥωμαίων ἐκ τῆς Ἑλλάδος εἰς ἐκεῖνον ἀπερείδηται τὴν ὀργὴν ὁ Φίλιππος· εἶναι γὰρ εὐχειρώτους Ἀθαμᾶνας αἰεὶ Μακεδόσι διά τε τὴν ἀσθένειαν καὶ γειτνίασιν τῆς χώρας. μετὰ δὲ τοῦτον Ἀλέξανδρος ὁ Αἰτωλὸς ἀναστάς, καθότι μὲν ἥθροικε τοὺς συμμάχους ἐπὶ τὸ περὶ τῶν διαλύσεων διαβούλιον καὶ καθόλου νῦν ἑκάστους ἀξιοῖ λέγειν τὸ φαινόμενον, ἐπῄνεσε τὸν Τίτον, τοῖς δ’ ὅλοις πράγμασιν ἀγνοεῖν ἔφη καὶ παραπίπτειν αὐτόν, εἰ πέπεισται διαλύσεις ποιησάμενος πρὸς Φίλιππον ἢ Ῥωμαίοις τὴν εἰρήνην ἢ τοῖς Ἕλλησι τὴν ἐλευθερίαν βέβαιον ἀπολείψειν· οὐδέτερον γὰρ εἶναι τούτων δυνατόν, ἀλλ’ εἰ βούλεται καὶ τὴν τῆς πατρίδος πρόθεσιν ἐπιτελῆ ποιεῖν καὶ τὰς ἰδίας ὑποσχέσεις, ἃς ὑπέσχηται πᾶσι τοῖς Ἕλλησι, μίαν ὑπάρχειν ἔφη διάλυσιν πρὸς Μακεδόνας τὸ Φίλιππον ἐκβάλλειν ἐκ τῆς ἀρχῆς. τοῦτο δ’ εἶναι καὶ λίαν εὐχερές, ἐὰν μὴ παρῇ τὸν ἐνεστῶτα καιρόν. πλείω δὲ πρὸς ταύτην τὴν ὑπόθεσιν διαλεχθεὶς κατέπαυσε τὸν λόγον.", "st": "18.36"}, {"sp": "N", "t": "ὁ δὲ Τίτος ἀναδεξάμενος ἀστοχεῖν αὐτὸν ἔφησεν οὐ μόνον τῆς Ῥωμαίων προαιρέσεως, ἀλλὰ καὶ τῆς αὑτοῦ προθέσεως καὶ μάλιστα τοῦ τῶν Ἑλλήνων συμφέροντος. οὔτε γὰρ Ῥωμαίους οὐδενὶ τὸ πρῶτον πολεμήσαντας εὐθέως ἀναστάτους ποιεῖν τούτους· πίστιν δ’ ἔχειν τὸ λεγόμενον ἔκ [τε] τῶν κατ’ Ἀννίβαν καὶ Καρχηδονίους, ὑφ’ ὧν τὰ δεινότατα παθόντας Ῥωμαίους, καὶ μετὰ ταῦτα γενομένους κυρίους ὃ βουληθεῖεν πρᾶξαι κατ’ αὐτῶν ἁπλῶς, οὐδὲν ἀνήκεστον βουλεύσασθαι περὶ Καρχηδονίων· καὶ μὴν οὐδ’ αὐτὸς οὐδέποτε ταύτην ἐσχηκέναι τὴν αἵρεσιν, ὅτι δεῖ πολεμεῖν πρὸς τὸν Φίλιππον ἀδιαλύτως· ἀλλ’ εἴπερ ἐβουλήθη ποιεῖν τὰ παρακαλούμενα πρὸ τῆς μάχης, ἑτοίμως ἂν διαλελύσθαι πρὸς αὐτόν. διὸ καὶ θαυμάζειν ἔφη πῶς μετέχοντες τότε τῶν περὶ τῆς διαλύσεως συλλόγων ἅπαντες νῦν ἀκαταλλάκτως ἔχουσιν. \"ἢ δῆλον ὅτι νενικήκαμεν; ἀλλὰ τοῦτό γ’ ἐστὶ πάντων ἀγνωμονέστατον· πολεμοῦντας γὰρ δεῖ τοὺς ἀγαθοὺς ἄνδρας βαρεῖς εἶναι καὶ θυμικούς, ἡττωμένους δὲ γενναίους καὶ μεγαλόφρονας, νικῶντάς γε μὴν μετρίους καὶ πραεῖς καὶ φιλανθρώπους. ὑμεῖς δὲ τἀναντία παρακαλεῖτε νῦν. ἀλλὰ μὴν καὶ τοῖς Ἕλλησι ταπεινωθῆναι μὲν ἐπὶ πολὺ συμφέρει τὴν Μακεδόνων ἀρχήν, ἀρθῆναί γε μὴν οὐδαμῶς\". τάχα γὰρ αὐτοὺς πεῖραν λήψεσθαι τῆς Θρᾳκῶν καὶ Γαλατῶν παρανομίας· τοῦτο γὰρ ἤδη καὶ πλεονάκις γεγονέναι. καθόλου δ’ αὐτὸς μὲν ἔφη καὶ τοὺς παρόντας Ῥωμαίων κρίνειν, ἐὰν Φίλιππος ὑπομένῃ πάντα ποιεῖν τὰ πρότερον ὑπὸ τῶν συμμάχων ἐπιταττόμενα, διδόναι τὴν εἰρήνην αὐτῷ, προσλαβόντας καὶ τὴν τῆς συγκλήτου γνώμην· Αἰτωλοὺς δὲ κυρίους εἶναι βουλευομένους ὑπὲρ σφῶν αὐτῶν. τοῦ δὲ Φαινέου μετὰ ταῦτα βουλομένου λέγειν ὅτι μάταια πάντα τὰ πρὸ τοῦ γέγονε· τὸν γὰρ Φίλιππον, ἐὰν διολίσθῃ τὸν παρόντα καιρόν, ἤδη πάλιν ἀρχὴν ἄλλην ποιήσεσθαι πραγμάτων· ὁ Τίτος αὐτόθεν ἐξ ἕδρας καὶ θυμικῶς \"παῦσαι\" φησὶ \"Φαινέα, ληρῶν· ἐγὼ γὰρ οὕτως χειριῶ τὰς διαλύσεις ὥστε μηδὲ βουληθέντα τὸν Φίλιππον ἀδικεῖν δύνασθαι τοὺς Ἕλληνας.\"", "st": "18.37"}, {"sp": "N", "t": "καὶ τότε μὲν ἐπὶ τούτοις ἐχωρίσθησαν. τῇ δ’ ὑστεραίᾳ παραγενομένου τοῦ βασιλέως, καὶ τῇ τρίτῃ πάντων εἰς τὸν σύλλογον ἁθροισθέντων, εἰσελθὼν ὁ Φίλιππος εὐστόχως καὶ συνετῶς ὑπετέμετο τὰς πάντων ὁρμάς· ἔφη γὰρ τὰ μὲν πρότερον ὑπὸ Ῥωμαίων καὶ τῶν συμμάχων ἐπιταττόμενα πάντα συγχωρεῖν καὶ ποιήσειν, περὶ δὲ τῶν λοιπῶν διδόναι τῇ συγκλήτῳ τὴν ἐπιτροπήν. τούτων δὲ ῥηθέντων οἱ μὲν ἄλλοι πάντες ἀπεσιώπησαν, ὁ δὲ τῶν Αἰτωλῶν Φαινέας \"τί οὖν ἡμῖν οὐκ ἀποδίδως, Φίλιππε\" ἔφη \"Λάρισαν τὴν Κρεμαστήν, Φάρσαλον, Θήβας τὰς Φθίας, Ἐχῖνον\"; ὁ μὲν οὖν Φίλιππος ἐκέλευε παραλαμβάνειν αὐτούς, ὁ δὲ Τίτος τῶν μὲν ἄλλων οὐκ ἔφη δεῖν οὐδεμίαν, Θήβας δὲ μόνον τὰς Φθίας· Θηβαίους γὰρ ἐγγίσαντος αὐτοῦ μετὰ τῆς δυνάμεως καὶ παρακαλοῦντος σφᾶς εἰς τὴν Ῥωμαίων πίστιν οὐ βουληθῆναι· διὸ νῦν, κατὰ πόλεμον ὑποχειρίων ὄντων, ἔχειν ἐξουσίαν ἔφη βουλεύεσθαι περὶ αὐτῶν ὡς ἂν προαιρῆται. τῶν δὲ περὶ τὸν Φαινέαν ἀγανακτούντων, καὶ λεγόντων ὅτι δέον αὐτοὺς εἴη, πρῶτον μέν, καθότι συνεπολέμησαν νῦν, κομίζεσθαι τὰς πόλεις τὰς πρότερον μεθ’ αὑτῶν συμπολιτευομένας, ἔπειτα κατὰ τὴν ἐξ ἀρχῆς συμμαχίαν, καθ’ ἣν ἔδει τῶν κατὰ πόλεμον ἑλόντων τὰ μὲν ἔπιπλα Ῥωμαίων εἶναι, τὰς δὲ πόλεις Αἰτωλῶν, ὁ Τίτος ἀγνοεῖν αὐτοὺς ἔφη κατ’ ἀμφότερα. τήν τε γὰρ συμμαχίαν λελύσθαι, καθ’ ὃν καιρὸν τὰς διαλύσεις ἐποιήσαντο πρὸς Φίλιππον ἐγκαταλείποντες Ῥωμαίους, εἴ τε καὶ μένειν ἔτι τὴν συμμαχίαν, δεῖν αὐτοὺς κομίζεσθαι καὶ παραλαμβάνειν, οὐκ εἴ τινες ἐθελοντὴν σφᾶς εἰς τὴν Ῥωμαίων πίστιν ἐνεχείρισαν, ὅπερ αἱ κατὰ Θετταλίαν πόλεις ἅπασαι πεποιήκασι νῦν, ἀλλ’ εἴ τινες κατὰ κράτος ἑάλωσαν.", "st": "18.38"}, {"sp": "N", "t": "τοῖς μὲν οὖν ἄλλοις ὁ Τίτος ἤρεσκε ταῦτα λέγων, οἱ δ’ Αἰτωλοὶ βαρέως ἤκουον καί τις οἷον ἀρχὴ κακῶν ἐγεννᾶτο μεγάλων· ἐκ γὰρ ταύτης τῆς διαφορᾶς καὶ τούτου τοῦ σπινθῆρος μετ’ ὀλίγον ὅ τε πρὸς Αἰτωλοὺς ὅ τε πρὸς Ἀντίοχον ἐξεκαύθη πόλεμος. τὸ δὲ συνέχον ἦν τῆς ὁρμῆς τῆς τοῦ Τίτου πρὸς τὰς διαλύσεις, ἐπυνθάνετο τὸν Ἀντίοχον ἀπὸ Συρίας ἀνῆχθαι μετὰ δυνάμεως, ποιούμενον τὴν ὁρμὴν ἐπὶ τὴν Εὐρώπην. διόπερ ἠγωνία μὴ ταύτης ὁ Φίλιππος τῆς ἐλπίδος ἀντιλαμβανόμενος ἐπὶ τὸ πολιοφυλακεῖν ὁρμήσῃ καὶ τρίβειν τὸν πόλεμον, εἶθ’ ἑτέρου παραγενηθέντος ὑπάτου τὸ κεφάλαιον τῶν πράξεων εἰς ἐκεῖνον ἀνακλασθῇ. διὸ συνεχωρήθη τῷ βασιλεῖ, καθάπερ ἠξίου, λαβόντα τετραμήνους ἀνοχὰς παραχρῆμα μὲν δοῦναι τῷ Τίτῳ τὰ διακόσια τάλαντα καὶ Δημήτριον τὸν υἱὸν εἰς ὁμηρείαν καί τινας ἑτέρους τῶν φίλων, περὶ δὲ τῶν ὅλων πέμπειν εἰς τὴν Ῥώμην καὶ διδόναι τῇ συγκλήτῳ τὴν ἐπιτροπήν. καὶ τότε μὲν ἐχωρίσθησαν πιστωσάμενοι περὶ τῶν ὅλων πρὸς ἀλλήλους, ἐφ’ ᾧ Τίτον, ἐὰν μὴ συντελῆται τὰ κατὰ τὰς διαλύσεις, ἀποδοῦναι Φιλίππῳ τὰ διακόσια τάλαντα καὶ τοὺς ὁμήρους· μετὰ δὲ ταῦτα πάντες ἔπεμπον εἰς τὴν Ῥώμην, οἱ μὲν συνεργοῦντες, οἱ δ’ ἀντιπράττοντες τῇ διαλύσει. —", "st": "18.39"}, {"sp": "N", "t": "τί δήποτ’ ἐστὶν ὅτι τοῖς αὐτοῖς καὶ διὰ τῶν αὐτῶν ἀπατώμενοι πάντες οὐ δυνάμεθα λῆξαι τῆς ἀνοίας; τοῦτο γὰρ τὸ γένος τῆς ῥᾳδιουργίας πολλάκις ὑπὸ πολλῶν ἤδη γέγονε· καὶ τὸ μὲν παρὰ τοῖς ἄλλοις διαχωρεῖν ἴσως οὐ θαυμαστόν, τὸ δέ, παρ’ οἷς ἡ πηγὴ τῆς τοιαύτης ὑπάρχει κακοπραγμοσύνης. ἀλλ’ ἔστιν αἴτιον τὸ μὴ πρόχειρον ὑπάρχειν τὸ παρ’ Ἐπιχάρμῳ καλῶς εἰρημένον νᾶφε καὶ μέμνασ’ ἀπιστεῖν· ἄρθρα ταῦτα τᾶν φρενῶν. — Μεδίων, πόλις πρὸς τῇ Αἰτωλίᾳ. Πολύβιος ὀκτωκαιδεκάτῳ.", "st": "18.40"}, {"sp": "N", "t": "… κωλύειν δὲ τὸν Ἀντίοχον παραπλεῖν, οὐκ ἀπεχθείας χάριν, ἀλλ’ ὑφορώμενοι μὴ Φιλίππῳ συνεπισχύσας ἐμπόδιον γένηται τῇ τῶν Ἑλλήνων ἐλευθερίᾳ. — ὅτι Ἀντίοχος ὁ βασιλεὺς πάνυ ὠρέγετο τῆς Ἐφέσου διὰ τὴν εὐκαιρίαν, τῷ δοκεῖν μὲν κατὰ τῆς Ἰωνίας καὶ τῶν ἐφ’ Ἑλλησπόντου πόλεων καὶ κατὰ γῆν καὶ κατὰ θάλατταν ἀκροπόλεως ἔχειν θέσιν, κατὰ δὲ τῆς Εὐρώπης ἀμυντήριον ὑπάρχειν ἀεὶ τοῖς Ἀσίας βασιλεῦσιν εὐκαιρότατον. —", "st": "18.41"}, {"sp": "N", "t": "ὅτι φησὶν ὁ Πολύβιος ἐν τῷ ιηʹ λόγῳ. ὅτι Ἄτταλος ἐτελεύτησε τὸν βίον· ὑπὲρ οὗ δίκαιόν ἐστι, καθάπερ περὶ τῶν ἄλλων εἰθίσμεθα ποιεῖν, καὶ περὶ τούτου νῦν ἐπιφθέγξασθαι τὸν ἁρμόζοντα λόγον. ἐκείνῳ γὰρ ἐξ ἀρχῆς ἄλλο μὲν οὐδὲν ἐφόδιον ὑπῆρξε πρὸς βασιλείαν τῶν ἐκτός, πλοῦτος δὲ μόνον, ὃς μετὰ νοῦ μὲν καὶ τόλμης χειριζόμενος ὡς ἀληθῶς μεγάλην παρέχεται χρείαν πρὸς πᾶσαν ἐπιβολήν, ἄνευ δὲ τῶν προειρημένων τοῖς πλείστοις κακῶν παραίτιος πέφυκε γίνεσθαι καὶ συλλήβδην ἀπωλείας. καὶ γὰρ φθόνους γεννᾷ καὶ ἐπιβουλὰς καὶ πρὸς διαφθορὰν σώματος καὶ ψυχῆς μεγίστας ἔχει ῥοπάς. ὀλίγαι δέ τινές εἰσι ψυχαὶ παντάπασιν αἱ ταῦτα δυνάμεναι διωθεῖσθαι τῇ τοῦ πλούτου δυνάμει. διὸ καὶ τοῦ προειρημένου ἄξιον ἀγασθῆναι τὴν μεγαλοψυχίαν, ὅτι πρὸς οὐδὲν τῶν ἄλλων ἐπεβάλετο χρήσασθαι τοῖς χορηγίοις ἀλλὰ πρὸς βασιλείας κατάκτησιν, οὗ μεῖζον ἢ κάλλιον οὐδὲν οἷόν τ’ ἐστὶν οὐδ’ εἰπεῖν· ὃς τὴν ἀρχὴν ἐνεστήσατο τῆς προειρημένης ἐπιβολῆς οὐ μόνον διὰ τῆς εἰς τοὺς φίλους εὐεργεσίας καὶ χάριτος, ἀλλὰ καὶ διὰ τῶν κατὰ πόλεμον ἔργων. νικήσας γὰρ μάχῃ Γαλάτας, ὃ βαρύτατον καὶ μαχιμώτατον ἔθνος ἦν τότε κατὰ τὴν Ἀσίαν, ταύτην ἀρχὴν ἐποιήσατο καὶ τότε πρῶτον αὑτὸν ἔδειξε βασιλέα. τυχὼν δὲ τῆς τιμῆς ταύτης καὶ βιώσας ἔτη δύο πρὸς τοῖς ἑβδομήκοντα, τούτων δὲ βασιλεύσας τετταράκοντα καὶ τέτταρα, σωφρονέστατα μὲν ἐβίωσε καὶ σεμνότατα πρὸς γυναῖκα καὶ τέκνα, διεφύλαξε δὲ τὴν πρὸς πάντας τοὺς συμμάχους καὶ φίλους πίστιν, ἐναπέθανε δ’ ἐν αὐτοῖς τοῖς καλλίστοις ἔργοις, ἀγωνιζόμενος ὑπὲρ τῆς τῶν Ἑλλήνων ἐλευθερίας. τὸ δὲ μέγιστον, τέτταρας υἱοὺς ἐν ἡλικίᾳ καταλιπὼν οὕτως ἡρμόσατο τὰ κατὰ τὴν ἀρχὴν ὥστε παισὶ παίδων ἀστασίαστον παραδοθῆναι τὴν βασιλείαν.", "st": "18.41"}, {"sp": "N", "t": "ὅτι ἐπὶ Μαρκέλλου Κλαυδίου ὑπάτου παρειληφότος τὴν ὕπατον ἀρχὴν ἧκον εἰς τὴν Ῥώμην οἵ τε παρὰ τοῦ Φιλίππου πρέσβεις οἵ τε παρὰ τοῦ Τίτου καὶ τῶν συμμάχων ὑπὲρ τῶν πρὸς Φίλιππον συνθηκῶν. λόγων δὲ πλειόνων γενομένων ἐν τῇ συγκλήτῳ, ταύτῃ μὲν ἐδόκει βεβαιοῦν τὰς ὁμολογίας· εἰς δὲ τὸν δῆμον εἰσενεχθέντος τοῦ διαβουλίου Μάρκος, αὐτὸς ἐπιθυμῶν τῆς εἰς τὴν Ἑλλάδα διαβάσεως, ἀντέλεγε καὶ πολλὴν ἐποιεῖτο σπουδὴν εἰς τὸ διακόψαι τὰς συνθήκας. οὐ μὴν ἀλλ’ ὅ γε δῆμος κατὰ τὴν τοῦ Τίτου προαίρεσιν ἐπεκύρωσε τὰς διαλύσεις. ὧν ἐπιτελεσθεισῶν εὐθέως ἡ σύγκλητος ἄνδρας δέκα καταστήσασα τῶν ἐπιφανῶν ἐξέπεμπε τοὺς χειριοῦντας τὰ κατὰ τὴν Ἑλλάδα μετὰ τοῦ Τίτου καὶ βεβαιώσοντας τοῖς Ἕλλησι τὴν ἐλευθερίαν. ἐποιήσαντο δὲ λόγους ἐν τῇ συγκλήτῳ καὶ περὶ τῆς συμμαχίας οἱ παρὰ τῶν Ἀχαιῶν πρέσβεις, οἱ περὶ Δαμόξενον τὸν Αἰγιέα· γενομένης δ’ ἀντιρρήσεως κατὰ τὸ παρὸν διὰ τὸ κατὰ πρόσωπον Ἠλείους μὲν ἀμφισβητεῖν τοῖς Ἀχαιοῖς ὑπὲρ τῆς Τριφυλίας, Μεσσηνίους δ’ ὑπὲρ Ἀσίνης καὶ Πύλου, συμμάχους τότε Ῥωμαίων ὑπάρχοντας, Αἰτωλοὺς δὲ περὶ τῆς Ἡραιῶν πόλεως, ὑπέρθεσιν ἔλαβε τὸ διαβούλιον ἐπὶ τοὺς δέκα. καὶ τὰ μὲν κατὰ τὴν σύγκλητον ἐπὶ τούτοις ἦν.", "st": "18.42"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Ἑλλάδα μετὰ τὴν μάχην Τίτου παραχειμάζοντος ἐν Ἐλατείᾳ Βοιωτοί, σπουδάζοντες ἀνακομίσασθαι τοὺς ἄνδρας τοὺς παρ’ αὐτῶν στρατευσαμένους παρὰ τῷ Φιλίππῳ, διεπρεσβεύοντο περὶ τῆς ἀσφαλείας αὐτῶν πρὸς Τίτον. ὁ δὲ βουλόμενος ἐκκαλεῖσθαι τοὺς Βοιωτοὺς πρὸς τὴν σφετέραν εὔνοιαν διὰ τὸ προορᾶσθαι τὸν Ἀντίοχον, ἑτοίμως συνεχώρησεν. ταχὺ δὲ πάντων ἀνακομισθέντων ἐκ τῆς Μακεδονίας, ἐν οἷς ἦν καὶ Βραχύλλης, τοῦτον μὲν εὐθέως βοιωτάρχην κατέστησαν, παραπλησίως δὲ καὶ τοὺς ἄλλους τοὺς δοκοῦντας εἶναι φίλους τῆς Μακεδόνων οἰκίας ἐτίμων καὶ προῆγον οὐχ ἧττον ἢ πρότερον. ἔπεμψαν δὲ καὶ πρεσβείαν πρὸς τὸν Φίλιππον τὴν εὐχαριστήσουσαν ἐπὶ τῇ τῶν νεανίσκων ἐπανόδῳ, λυμαινόμενοι τὴν τοῦ Τίτου χάριν. ἃ συνορῶντες οἱ περὶ τὸν Ζεύξιππον καὶ Πεισίστρατον, καὶ πάντες οἱ δοκοῦντες εἶναι Ῥωμαίοις φίλοι δυσχερῶς ἔφερον, προορώμενοι τὸ μέλλον καὶ δεδιότες περὶ σφῶν αὐτῶν καὶ τῶν ἀναγκαίων· σαφῶς γὰρ ᾔδεισαν ὡς, ἐὰν μὲν οἱ Ῥωμαῖοι χωρισθῶσιν ἐκ τῆς Ἑλλάδος, ὁ δὲ Φίλιππος μένῃ παρὰ πλευράν, συνεπισχύων αἰεὶ τοῖς πρὸς σφᾶς ἀντιπολιτευομένοις, οὐδαμῶς ἀσφαλῆ σφίσιν ἐσομένην τὴν ἐν τῇ Βοιωτίᾳ πολιτείαν. διὸ καὶ συμφρονήσαντες ἐπρέσβευον πρὸς Τίτον εἰς τὴν Ἐλάτειαν. συμμίξαντες δὲ τῷ προειρημένῳ πολλοὺς καὶ ποικίλους εἰς τοῦτο τὸ μέρος διετίθεντο λόγους, ὑποδεικνύντες τὴν ὁρμὴν τοῦ πλήθους τὴν οὖσαν ἤδη νῦν καθ’ αὑτῶν καὶ τὴν ἀχαριστίαν τῶν ὄχλων. καὶ τέλος ἐθάρρησαν εἰπεῖν ὡς, ἐὰν μὴ τὸν Βραχύλλην ἐπανελόμενοι καταπλήξωνται τοὺς πολλούς, οὐκ ἔστιν ἀσφάλεια τοῖς Ῥωμαίων φίλοις χωρισθέντων τῶν στρατοπέδων. ὁ δὲ Τίτος ταῦτα διακούσας αὐτὸς μὲν οὐκ ἔφη κοινωνεῖν τῆς πράξεως ταύτης, τοὺς δὲ βουλομένους πράττειν οὐ κωλύειν· καθόλου δὲ λαλεῖν αὐτοὺς ἐκέλευε περὶ τούτων Ἀλεξαμενῷ τῷ τῶν Αἰτωλῶν στρατηγῷ. τῶν δὲ περὶ τὸν Ζεύξιππον πειθαρχησάντων καὶ διαλεγομένων, ταχέως ὁ προειρημένος πεισθεὶς καὶ συγκαταθέμενος τοῖς λεγομένοις τρεῖς μὲν τῶν Αἰτωλικῶν συνέστησε, τρεῖς δὲ τῶν Ἰταλικῶν νεανίσκων τοὺς προσοίσοντας τὰς χεῖρας τῷ Βραχύλλῃ. — οὐδεὶς γὰρ οὕτως οὔτε μάρτυς ἐστι φοβερὸς οὔτε κατήγορος δεινὸς ὡς ἡ σύνεσις ἡ κατοικοῦσ’ ἐν ταῖς ἑκάστων ψυχαῖς. —", "st": "18.43"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἧκον ἐκ τῆς Ῥώμης οἱ δέκα, δι’ ὧν ἔμελλε χειρίζεσθαι τὰ κατὰ τοὺς Ἕλληνας, κομίζοντες τὸ τῆς συγκλήτου δόγμα τὸ περὶ τῆς πρὸς Φίλιππον εἰρήνης. ἦν δὲ τὰ συνέχοντα τοῦ δόγματος ταῦτα, τοὺς μὲν ἄλλους Ἕλληνας πάντας, τούς τε κατὰ τὴν Ἀσίαν καὶ κατὰ τὴν Εὐρώπην, ἐλευθέρους ὑπάρχειν καὶ νόμοις χρῆσθαι τοῖς ἰδίοις· τοὺς δὲ ταττομένους ὑπὸ Φίλιππον καὶ τὰς πόλεις τὰς ἐμφρούρους παραδοῦναι Φίλιππον Ῥωμαίοις πρὸ τῆς τῶν Ἰσθμίων πανηγύρεως, Εὔρωμον δὲ καὶ Πήδασα καὶ Βαργύλια καὶ τὴν Ἰασέων πόλιν, ὁμοίως Ἄβυδον, Θάσον, Μύριναν, Πέρινθον, ἐλευθέρας ἀφεῖναι τὰς φρουρὰς ἐξ αὐτῶν μεταστησάμενον· περὶ δὲ τῆς τῶν Κιανῶν ἐλευθερώσεως Τίτον γράψαι πρὸς Προυσίαν κατὰ τὸ δόγμα τῆς συγκλήτου· τὰ δ’ αἰχμάλωτα καὶ τοὺς αὐτομόλους ἅπαντας ἀποκαταστῆσαι Φίλιππον Ῥωμαίοις ἐν τοῖς αὐτοῖς χρόνοις, ὁμοίως δὲ καὶ τὰς καταφράκτους ναῦς πλὴν πέντε σκαφῶν καὶ τῆς ἑκκαιδεκήρους· δοῦναι δὲ καὶ χίλια τάλαντα, τούτων τὰ μὲν ἡμίση παραυτίκα, τὰ δ’ ἡμίση κατὰ φόρους ἐν ἔτεσι δέκα.", "st": "18.44"}, {"sp": "N", "t": "τούτου δὲ τοῦ δόγματος διαδοθέντος εἰς τοὺς Ἕλληνας οἱ μὲν ἄλλοι πάντες εὐθαρσεῖς ἦσαν καὶ περιχαρεῖς, μόνοι δ’ Αἰτωλοί, δυσχεραίνοντες ἐπὶ τῷ μὴ τυγχάνειν ὧν ἤλπιζον, κατελάλουν τὸ δόγμα, φάσκοντες οὐ πραγμάτων, ἀλλὰ γραμμάτων μόνον ἔχειν αὐτὸ διάθεσιν. καί τινας ἐλάμβανον πιθανότητας ἐξ αὐτῶν τῶν ἐγγράπτων πρὸς τὸ διασείειν τοὺς ἀκούοντας τοιαύτας. ἔφασκον γὰρ εἶναι δύο γνώμας ἐν τῷ δόγματι περὶ τῶν ὑπὸ Φιλίππου φρουρουμένων πόλεων, τὴν μὲν μίαν ἐπιτάττουσαν ἐξάγειν τὰς φρουρὰς τὸν Φίλιππον, τὰς δὲ πόλεις παραδιδόναι Ῥωμαίοις, τὴν δ’ ἑτέραν ἐξάγοντα τὰς φρουρὰς ἐλευθεροῦν τὰς πόλεις. τὰς μὲν οὖν ἐλευθερουμένας ἐπ’ ὀνόματος δηλοῦσθαι, ταύτας δ’ εἶναι τὰς κατὰ τὴν Ἀσίαν, τὰς δὲ παραδιδομένας Ῥωμαίοις φανερὸν ὅτι τὰς κατὰ τὴν Εὐρώπην. εἶναι δὲ ταύτας Ὠρεόν, Ἐρέτριαν, Χαλκίδα, Δημητριάδα, Κόρινθον. ἐκ δὲ τούτων εὐθεώρητον ὑπάρχειν πᾶσιν ὅτι μεταλαμβάνουσι τὰς Ἑλληνικὰς πέδας παρὰ Φιλίππου Ῥωμαῖοι, καὶ γίνεται μεθάρμοσις δεσποτῶν, οὐκ ἐλευθέρωσις τῶν Ἑλλήνων. ταῦτα μὲν οὖν ὑπ’ Αἰτωλῶν ἐλέγετο κατακόρως. ὁ δὲ Τίτος ὁρμήσας ἐκ τῆς Ἐλατείας μετὰ τῶν δέκα καὶ κατάρας εἰς τὴν Ἀντίκυραν, παραυτίκα διέπλευσεν εἰς τὸν Κόρινθον, κἀκεῖ παραγενόμενος συνήδρευε μετὰ τούτων καὶ διελάμβανε περὶ τῶν ὅλων. πλεοναζούσης δὲ τῆς τῶν Αἰτωλῶν διαβολῆς καὶ πιστευομένης παρ’ ἐνίοις, πολλοὺς καὶ ποικίλους ἠναγκάζετο ποιεῖσθαι λόγους ὁ Τίτος ἐν τῷ συνεδρίῳ, διδάσκων ὡς εἴπερ βούλονται καὶ τὴν τῶν Ἑλλήνων εὔκλειαν ὁλόκληρον περιποιήσασθαι, καὶ καθόλου πιστευθῆναι παρὰ πᾶσι διότι καὶ τὴν ἐξ ἀρχῆς ἐποιήσαντο διάβασιν οὐ τοῦ συμφέροντος ἕνεκεν, ἀλλὰ τῆς τῶν Ἑλλήνων ἐλευθερίας, ἐκχωρητέον εἴη πάντων τῶν τόπων καὶ πάσας ἐλευθερωτέον τὰς πόλεις τὰς νῦν ὑπὸ Φιλίππου φρουρουμένας. ταύτην δὲ συνέβαινε γίνεσθαι τὴν ἀπορίαν ἐν τῷ συνεδρίῳ διὰ τὸ περὶ μὲν τῶν ἄλλων ἐν τῇ Ῥώμῃ προδιειλῆφθαι καὶ ῥητὰς ἔχειν τοὺς δέκα παρὰ τῆς συγκλήτου τὰς ἐντολάς, περὶ δὲ Χαλκίδος καὶ Κορίνθου καὶ Δημητριάδος ἐπιτροπὴν αὐτοῖς δεδόσθαι διὰ τὸν Ἀντίοχον, ἵνα βλέποντες πρὸς τοὺς καιροὺς βουλεύωνται περὶ τῶν προειρημένων πόλεων κατὰ τὰς αὑτῶν προαιρέσεις· ὁ γὰρ προειρημένος βασιλεὺς δῆλος ἦν ἐπέχων πάλαι τοῖς κατὰ τὴν Εὐρώπην πράγμασιν. οὐ μὴν ἀλλὰ τὸν μὲν Κόρινθον ὁ Τίτος ἔπεισε τὸ συνέδριον ἐλευθεροῦν παραχρῆμα καὶ τοῖς Ἀχαιοῖς ἐγχειρίζειν διὰ τὰς ἐξ ἀρχῆς ὁμολογίας, τὸν δ’ Ἀκροκόρινθον καὶ Δημητριάδα καὶ Χαλκίδα παρακατέσχεν.", "st": "18.45"}, {"sp": "N", "t": "δοξάντων δὲ τούτων, καὶ τῆς Ἰσθμίων πανηγύρεως ἐπελθούσης, καὶ σχεδὸν ἀπὸ πάσης τῆς οἰκουμένης τῶν ἐπιφανεστάτων ἀνδρῶν συνεληλυθότων διὰ τὴν προσδοκίαν τῶν ἀποβησομένων, πολλοὶ καὶ ποικίλοι καθ’ ὅλην τὴν πανήγυριν ἐνέπιπτον λόγοι, τῶν μὲν ἀδύνατον εἶναι φασκόντων Ῥωμαίους ἐνίων ἀποστῆναι τόπων καὶ πόλεων, τῶν δὲ διοριζομένων ὅτι τῶν μὲν ἐπιφανῶν εἶναι δοκούντων τόπων ἀποστήσονται, τοὺς δὲ φαντασίαν μὲν ἔχοντας ἐλάττω, χρείαν δὲ τὴν αὐτὴν παρέχεσθαι δυναμένους καθέξουσι. καὶ τούτους εὐθέως ἐπεδείκνυσαν αὐτοὶ καθ’ αὑτῶν διὰ τῆς πρὸς ἀλλήλους εὑρεσιλογίας. τοιαύτης δ’ οὔσης ἐν τοῖς ἀνθρώποις τῆς ἀπορίας, ἁθροισθέντος τοῦ πλήθους εἰς τὸ στάδιον ἐπὶ τὸν ἀγῶνα, προελθὼν ὁ κῆρυξ καὶ κατασιωπησάμενος τὰ πλήθη διὰ τοῦ σαλπικτοῦ τόδε τὸ κήρυγμ’ ἀνηγόρευσεν· \" ἡ σύγκλητος ἡ Ῥωμαίων καὶ Τίτος Κοΐντιος στρατηγὸς ὕπατος, καταπολεμήσαντες βασιλέα Φίλιππον καὶ Μακεδόνας, ἀφιᾶσιν ἐλευθέρους, ἀφρουρήτους, ἀφορολογήτους, νόμοις χρωμένους τοῖς πατρίοις, Κορινθίους, Φωκέας, Λοκρούς, Εὐβοεῖς, Ἀχαιοὺς τοὺς Φθιώτας, Μάγνητας, Θετταλούς, Περραιβούς\". κρότου δ’ ἐν ἀρχαῖς εὐθέως ἐξαισίου γενομένου τινὲς μὲν οὐδ’ ἤκουσαν τοῦ κηρύγματος, τινὲς δὲ πάλιν ἀκούειν ἐβούλοντο. τὸ δὲ πολὺ μέρος τῶν ἀνθρώπων διαπιστούμενον καὶ δοκοῦν ὡς ἂν εἰ καθ’ ὕπνον ἀκούειν τῶν λεγομένων διὰ τὸ παράδοξον τοῦ συμβαίνοντος, πᾶς τις ἐξ ἄλλης ὁρμῆς ἐβόα προάγειν τὸν κήρυκα καὶ τὸν σαλπικτὴν εἰς μέσον τὸ στάδιον καὶ λέγειν πάλιν ὑπὲρ τῶν αὐτῶν, ὡς μὲν ἐμοὶ δοκεῖ, βουλομένων τῶν ἀνθρώπων μὴ μόνον ἀκούειν, ἀλλὰ καὶ βλέπειν τὸν λέγοντα διὰ τὴν ἀπιστίαν τῶν ἀναγορευομένων. ὡς δὲ πάλιν ὁ κῆρυξ, προελθὼν εἰς τὸ μέσον καὶ κατασιωπησάμενος διὰ τοῦ σαλπικτοῦ τὸν θόρυβον, ἀνηγόρευσε ταὐτὰ καὶ ὡσαύτως τοῖς πρόσθεν, τηλικοῦτον συνέβη καταρραγῆναι τὸν κρότον ὥστε καὶ μὴ ῥᾳδίως ἂν ὑπὸ τὴν ἔννοιαν ἀγαγεῖν τοῖς νῦν ἀκούουσι τὸ γεγονός. ὡς δέ ποτε κατέληξεν ὁ κρότος, τῶν μὲν ἀθλητῶν ἁπλῶς οὐδεὶς οὐδένα λόγον εἶχεν ἔτι, πάντες δὲ διαλαλοῦντες, οἱ μὲν ἀλλήλοις, οἱ δὲ πρὸς σφᾶς αὐτούς, οἷον εἰ παραστατικοὶ τὰς διανοίας ἦσαν. ᾗ καὶ μετὰ τὸν ἀγῶνα διὰ τὴν ὑπερβολὴν τῆς χαρᾶς μικροῦ διέφθειραν τὸν Τίτον εὐχαριστοῦντες· οἱ μὲν γὰρ ἀντοφθαλμῆσαι κατὰ πρόσωπον καὶ σωτῆρα προσφωνῆσαι βουλόμενοι, τινὲς δὲ τῆς δεξιᾶς ἅψασθαι σπουδάζοντες, οἱ δὲ πολλοὶ στεφάνους ἐπιρριπτοῦντες καὶ λημνίσκους, παρ’ ὀλίγον διέλυσαν τὸν ἄνθρωπον. δοκούσης δὲ τῆς εὐχαριστίας ὑπερβολικῆς γενέσθαι, θαρρῶν ἄν τις εἶπε διότι πολὺ καταδεεστέραν εἶναι συνέβαινε τοῦ τῆς πράξεως μεγέθους. θαυμαστὸν γὰρ ἦν καὶ τὸ Ῥωμαίους ἐπὶ ταύτης γενέσθαι τῆς προαιρέσεως καὶ τὸν ἡγούμενον αὐτῶν Τίτον, ὥστε πᾶσαν ὑπομεῖναι δαπάνην καὶ πάντα κίνδυνον χάριν τῆς τῶν Ἑλλήνων ἐλευθερίας· μέγα δὲ καὶ τὸ δύναμιν ἀκόλουθον τῇ προαιρέσει προσενέγκασθαι· τούτων δὲ μέγιστον ἔτι τὸ μηδὲν ἐκ τῆς τύχης ἀντιπαῖσαι πρὸς τὴν ἐπιβολήν, ἀλλ’ ἁπλῶς ἅπαντα πρὸς ἕνα καιρὸν ἐκδραμεῖν, ὥστε διὰ κηρύγματος ἑνὸς ἅπαντας καὶ τοὺς τὴν Ἀσίαν κατοικοῦντας Ἕλληνας καὶ τοὺς τὴν Εὐρώπην ἐλευθέρους, ἀφρουρήτους, ἀφορολογήτους γενέσθαι, νόμοις χρωμένους τοῖς ἰδίοις.", "st": "18.46"}, {"sp": "N", "t": "διελθούσης δὲ τῆς πανηγύρεως πρώτοις μὲν ἐχρημάτισαν τοῖς παρ’ Ἀντιόχου πρεσβευταῖς, διακελευόμενοι τῶν ἐπὶ τῆς Ἀσίας πόλεων τῶν μὲν αὐτονόμων ἀπέχεσθαι καὶ μηδεμιᾷ πολεμεῖν, ὅσας δὲ νῦν παρείληφε τῶν ὑπὸ Πτολεμαῖον καὶ Φίλιππον ταττομένων, ἐκχωρεῖν. σὺν δὲ τούτοις προηγόρευον μὴ διαβαίνειν εἰς τὴν Εὐρώπην μετὰ δυνάμεως· οὐδένα γὰρ ἔτι τῶν Ἑλλήνων οὔτε πολεμεῖσθαι νῦν ὑπ’ οὐδενὸς οὔτε δουλεύειν οὐδενί. καθόλου δὲ καὶ ἐξ αὑτῶν τινας ἔφασαν ἥξειν πρὸς τὸν Ἀντίοχον. ταύτας μὲν οὖν οἱ περὶ τὸν Ἡγησιάνακτα καὶ Λυσίαν λαβόντες τὰς ἀποκρίσεις ἐπανῆλθον· μετὰ δὲ τούτους εἰσεκαλοῦντο πάντας τοὺς ἀπὸ τῶν ἐθνῶν καὶ πόλεων παραγεγονότας, καὶ τὰ δόξαντα τῷ συνεδρίῳ διεσάφουν. Μακεδόνων μὲν οὖν τοὺς Ὀρέστας καλουμένους διὰ τὸ προσχωρῆσαι σφίσι κατὰ τὸν πόλεμον αὐτονόμους ἀφεῖσαν, ἠλευθέρωσαν δὲ Περραιβοὺς καὶ Δόλοπας καὶ Μάγνητας. Θετταλοῖς δὲ μετὰ τῆς ἐλευθερίας καὶ τοὺς Ἀχαιοὺς τοὺς Φθιώτας προσένειμαν, ἀφελόμενοι Θήβας τὰς Φθίας καὶ Φάρσαλον· οἱ γὰρ Αἰτωλοὶ περί τε τῆς Φαρσάλου μεγάλην ἐποιοῦντο φιλοτιμίαν, φάσκοντες αὑτῶν δεῖν ὑπάρχειν κατὰ τὰς ἐξ ἀρχῆς συνθήκας, ὁμοίως δὲ καὶ περὶ Λευκάδος. οἱ δ’ ἐν τῷ συνεδρίῳ περὶ μὲν τούτων τῶν πόλεων ὑπερέθεντο τοῖς Αἰτωλοῖς τὸ διαβούλιον πάλιν ἐπὶ τὴν σύγκλητον, τοὺς δὲ Φωκέας καὶ τοὺς Λοκροὺς συνεχώρησαν αὐτοῖς ἔχειν, καθάπερ εἶχον καὶ πρότερον, ἐν τῇ συμπολιτείᾳ. Κόρινθον δὲ καὶ τὴν Τριφυλίαν καὶ τὴν Ἡραιῶν πόλιν Ἀχαιοῖς ἀπέδωκαν. Ὠρεὸν δ’, ἔτι δὲ τὴν Ἐρετριέων πόλιν ἐδόκει μὲν τοῖς πλείοσιν Εὐμένει δοῦναι· Τίτου δὲ πρὸς τὸ συνέδριον διαστείλαντος οὐκ ἐκυρώθη τὸ διαβούλιον· διὸ καὶ μετά τινα χρόνον ἠλευθερώθησαν αἱ πόλεις αὗται διὰ τῆς συγκλήτου καὶ σὺν ταύταις Κάρυστος. ἔδωκαν δὲ καὶ Πλευράτῳ Λυχνίδα καὶ Πάρθον, οὔσας μὲν Ἰλλυρίδας, ὑπὸ Φίλιππον δὲ ταττομένας. Ἀμυνάνδρῳ δὲ συνεχώρησαν, ὅσα παρεσπάσατο κατὰ πόλεμον ἐρύματα τοῦ Φιλίππου, κρατεῖν τούτων.", "st": "18.47"}, {"sp": "N", "t": "ταῦτα δὲ διοικήσαντες ἐμέρισαν σφᾶς αὐτούς, καὶ Πόπλιος μὲν Λέντλος εἰς Βαργύλια πλεύσας ἠλευθέρωσε τούτους, Λεύκιος δὲ Στερτίνιος εἰς Ἡφαιστίαν καὶ Θάσον ἀφικόμενος καὶ τὰς ἐπὶ Θρᾴκης πόλεις ἐποίησε τὸ παραπλήσιον. πρὸς δὲ τὸν Ἀντίοχον ὥρμησαν Πόπλιος Οὐίλλιος καὶ Λεύκιος Τερέντιος, οἱ δὲ περὶ Γνάιον τὸν Κορνήλιον πρὸς τὸν βασιλέα Φίλιππον. ᾧ καὶ συμμίξαντες πρὸς τοῖς Τέμπεσι περί τε τῶν ἄλλων διελέχθησαν ὑπὲρ ὧν εἶχον τὰς ἐντολάς, καὶ συνεβούλευον αὐτῷ πρεσβευτὰς πέμπειν εἰς τὴν Ῥώμην ὑπὲρ συμμαχίας, ἵνα μὴ δοκῇ τοῖς καιροῖς ἐφεδρεύων ἀποκαραδοκεῖν τὴν Ἀντιόχου παρουσίαν. τοῦ δὲ βασιλέως συγκαταθεμένου τοῖς ὑποδεικνυμένοις, εὐθέως ἀπ’ ἐκείνου χωρισθέντες ἧκον ἐπὶ τὴν τῶν Θερμικῶν σύνοδον, καὶ παρελθόντες εἰς τὰ πλήθη παρεκάλουν τοὺς Αἰτωλοὺς διὰ πλειόνων μένειν ἐπὶ τῆς ἐξ ἀρχῆς αἱρέσεως καὶ διαφυλάττειν τὴν πρὸς Ῥωμαίους εὔνοιαν. πολλῶν δὲ παρισταμένων, καὶ τῶν μὲν πρᾴως καὶ πολιτικῶς μεμψιμοιρούντων αὐτοῖς ἐπὶ τῷ μὴ κοινωνικῶς χρῆσθαι τοῖς εὐτυχήμασι μηδὲ τηρεῖν τὰς ἐξ ἀρχῆς συνθήκας, τῶν δὲ λοιδορούντων καὶ φασκόντων οὔτ’ ἂν ἐπιβῆναι τῆς Ἑλλάδος οὐδέποτε Ῥωμαίους οὔτ’ ἂν νικῆσαι Φίλιππον, εἰ μὴ δι’ ἑαυτούς, τὸ μὲν ἀπολογεῖσθαι πρὸς ἕκαστα τούτων οἱ περὶ τὸν Γνάιον ἀπεδοκίμασαν, παρεκάλουν δ’ αὐτοὺς πρεσβεύειν εἰς τὴν Ῥώμην, διότι πάντων παρὰ τῆς συγκλήτου τεύξονται τῶν δικαίων· ὃ καὶ πεισθέντες ἐποίησαν. καὶ τὸ μὲν τέλος τοῦ πρὸς Φίλιππον πολέμου τοιαύτην ἔσχε διάθεσιν.", "st": "18.48"}, {"sp": "N", "t": "ἐάν, τὸ δὴ λεγόμενον, τρέχωσι τὴν ἐσχάτην, ἐπὶ τοὺς Ῥωμαίους καταφεύξονται καὶ τούτοις ἐγχειριοῦσι σφᾶς αὐτοὺς καὶ τὴν πόλιν.", "st": "18.49"}, {"sp": "N", "t": "ὅτι προχωρούσης τῷ Ἀντιόχῳ κατὰ νοῦν τῆς ἐπιβολῆς παρόντι ἐν Θρᾴκῃ τῷ Ἀντιόχῳ κατέπλευσαν εἰς Σηλυβρίαν οἱ περὶ Λεύκιον Κορνήλιον. οὗτοι δ’ ἦσαν παρὰ τῆς συγκλήτου πρέσβεις ἐπὶ τὰς διαλύσεις ἐξαπεσταλμένοι τὰς Ἀντιόχου καὶ Πτολεμαίου.", "st": "18.50"}, {"sp": "N", "t": "κατὰ δὲ τὸν αὐτὸν καιρὸν ἧκον καὶ τῶν δέκα Πόπλιος μὲν Λέντλος ἐκ Βαργυλίων, Λεύκιος δὲ Τερέντιος καὶ Πόπλιος Οὐίλλιος ἐκ Θάσου. ταχὺ δὲ τῷ βασιλεῖ διασαφηθείσης τῆς τούτων παρουσίας, πάντες ἐν ὀλίγαις ἡμέραις ἡθροίσθησαν εἰς τὴν Λυσιμάχειαν. συνεκύρησαν δὲ καὶ οἱ περὶ τὸν Ἡγησιάνακτα καὶ Λυσίαν οἱ πρὸς τὸν Τίτον ἀποσταλέντες εἰς τὸν καιρὸν τοῦτον. αἱ μὲν οὖν κατ’ ἰδίαν ἐντεύξεις τοῦ τε βασιλέως καὶ τῶν Ῥωμαίων τελέως ἦσαν ἀφελεῖς καὶ φιλάνθρωποι· μετὰ δὲ ταῦτα γενομένης συνεδρείας κοινῆς ὑπὲρ τῶν ὅλων ἀλλοιοτέραν ἔλαβε τὰ πράγματα διάθεσιν. ὁ γὰρ Λεύκιος ὁ Κορνήλιος ἠξίου μὲν καὶ τῶν ὑπὸ Πτολεμαῖον ταττομένων πόλεων, ὅσας νῦν εἴληφε κατὰ τὴν Ἀσίαν, παραχωρεῖν τὸν Ἀντίοχον, τῶν δ’ ὑπὸ Φίλιππον διεμαρτύρετο φιλοτίμως ἐξίστασθαι· γελοῖον γὰρ εἶναι τὰ Ῥωμαίων ἆθλα τοῦ γεγονότος αὐτοῖς πολέμου πρὸς Φίλιππον Ἀντίοχον ἐπελθόντα παραλαμβάνειν. παρῄνει δὲ καὶ τῶν αὐτονόμων ἀπέχεσθαι πόλεων. καθόλου δ’ ἔφη θαυμάζειν τίνι λόγῳ τοσαύταις μὲν πεζικαῖς, τοσαύταις δὲ ναυτικαῖς δυνάμεσι πεποίηται τὴν εἰς τὴν Εὐρώπην διάβασιν· πλὴν γὰρ τοῦ προτίθεσθαι Ῥωμαίοις ἐγχειρεῖν αὐτόν, οὐδ’ ἔννοιαν ἑτέραν καταλείπεσθαι παρὰ τοῖς ὀρθῶς λογιζομένοις. οἱ μὲν οὖν Ῥωμαῖοι ταῦτ’ εἰπόντες ἀπεσιώπησαν·", "st": "18.50"}, {"sp": "N", "t": "ὁ δὲ βασιλεὺς πρῶτον μὲν διαπορεῖν ἔφη κατὰ τίνα λόγον ἀμφισβητοῦσι πρὸς αὐτὸν ὑπὲρ τῶν ἐπὶ τῆς Ἀσίας πόλεων· πᾶσι γὰρ μᾶλλον ἐπιβάλλειν τοῦτο ποιεῖν ἢ Ῥωμαίοις. δεύτερον δ’ ἠξίου μηδὲν αὐτοὺς πολυπραγμονεῖν καθόλου τῶν κατὰ τὴν Ἀσίαν· οὐδὲ γὰρ αὐτὸς περιεργάζεσθαι τῶν κατὰ τὴν Ἰταλίαν ἁπλῶς οὐδέν. εἰς δὲ τὴν Εὐρώπην ἔφη διαβεβηκέναι μετὰ τῶν δυνάμεων ἀνακτησόμενος τὰ κατὰ τὴν Χερρόνησον καὶ τὰς ἐπὶ Θρᾴκης πόλεις· τὴν γὰρ τῶν τόπων τούτων ἀρχὴν μάλιστα πάντων αὑτῷ καθήκειν. εἶναι μὲν γὰρ ἐξ ἀρχῆς τὴν δυναστείαν ταύτην Λυσιμάχου, Σελεύκου δὲ πολεμήσαντος πρὸς αὐτὸν καὶ κρατήσαντος τῷ πολέμῳ πᾶσαν τὴν Λυσιμάχου βασιλείαν δορίκτητον γενέσθαι Σελεύκου. κατὰ δὲ τοὺς τῶν αὑτοῦ προγόνων περισπασμοὺς ἐν τοῖς ἑξῆς χρόνοις πρῶτον μὲν Πτολεμαῖον παρασπασάμενον σφετερίσασθαι τοὺς τόπους τούτους, δεύτερον δὲ Φίλιππον. αὐτὸς δὲ νῦν οὐ κτᾶσθαι τοῖς Φιλίππου καιροῖς συνεπιτιθέμενος, ἀλλ’ ἀνακτᾶσθαι τοῖς ἰδίοις δικαίοις συγχρώμενος. Λυσιμαχεῖς δέ, παραλόγως ἀναστάτους γεγονότας ὑπὸ Θρᾳκῶν, οὐκ ἀδικεῖν Ῥωμαίους κατάγων καὶ συνοικίζων· ποιεῖν γὰρ τοῦτ’ ἔφη βουλόμενος οὐ Ῥωμαίοις τὰς χεῖρας ἐπιβαλεῖν, Σελεύκῳ δ’ οἰκητήριον ἑτοιμάζειν. τὰς δ’ αὐτονόμους τῶν κατὰ τὴν Ἀσίαν πόλεων οὐ διὰ τῆς Ῥωμαίων ἐπιταγῆς δέον εἶναι τυγχάνειν τῆς ἐλευθερίας, ἀλλὰ διὰ τῆς αὑτοῦ χάριτος. τὰ δὲ πρὸς Πτολεμαῖον αὐτὸς ἔφη διεξάξειν εὐδοκουμένως ἐκείνῳ· κρίνειν γὰρ οὐ φιλίαν μόνον, ἀλλὰ καὶ μετὰ τῆς φιλίας ἀναγκαιότητα συντίθεσθαι πρὸς αὐτόν.", "st": "18.51"}, {"sp": "N", "t": "τῶν δὲ περὶ τὸν Λεύκιον οἰομένων δεῖν καλεῖσθαι τοὺς Λαμψακηνοὺς καὶ τοὺς Σμυρναίους καὶ δοῦναι λόγον αὐτοῖς, ἐγένετο τοῦτο. παρῆσαν δὲ παρὰ μὲν Λαμψακηνῶν οἱ περὶ Παρμενίωνα καὶ Πυθόδωρον, παρὰ δὲ Σμυρναίων οἱ περὶ Κοίρανον. ὧν μετὰ παρρησίας διαλεγομένων, δυσχεράνας ὁ βασιλεὺς ἐπὶ τῷ δοκεῖν λόγον ὑπέχειν ἐπὶ Ῥωμαίων τοῖς πρὸς αὐτὸν ἀμφισβητοῦσι, μεσολαβήσας τὸν Παρμενίωνα \" παῦσαι\" φησὶ \"τῶν πολλῶν· οὐ γὰρ ἐπὶ Ῥωμαίων, ἀλλ’ ἐπὶ Ῥοδίων ὑμῖν εὐδοκῶ διακριθῆναι περὶ τῶν ἀντιλεγομένων. \" καὶ τότε μὲν ἐπὶ τούτοις διέλυσαν τὸν σύλλογον, οὐδαμῶς εὐδοκήσαντες ἀλλήλοις.", "st": "18.52"}, {"sp": "N", "t": "τῶν γὰρ παραβόλων καὶ καλῶν ἔργων ἐφίενται μὲν πολλοί, τολμῶσι δ’ ὀλίγοι ψαύειν. καίτοι πολὺ καλλίους ἀφορμὰς εἶχε Σκόπας Κλεομένους πρὸς τὸ παραβάλλεσθαι καὶ τολμᾶν. ἐκεῖνος μὲν γὰρ προκαταληφθεὶς εἰς αὐτὰς συνεκλείσθη τὰς ἐν τοῖς ἰδίοις οἰκέταις καὶ φίλοις ἐλπίδας· ἀλλ’ ὅμως οὐδὲ ταύτας ἐγκατέλιπεν, ἀλλ’ ἐφ’ ὅσον ἦν δυνατὸς ἐξήλεγξε, τὸ καλῶς ἀποθανεῖν τοῦ ζῆν αἰσχρῶς περὶ πλείονος ποιησάμενος. Σκόπας δέ, καὶ χεῖρα βαρεῖαν ἔχων συνεργὸν καὶ καιρόν, ἅτε τοῦ βασιλέως ἔτι παιδὸς ὄντος, μέλλων καὶ βουλευόμενος προκατελήφθη. γνόντες γὰρ αὐτὸν οἱ περὶ τὸν Ἀριστομένην συναθροίζοντα τοὺς φίλους εἰς τὴν ἰδίαν οἰκίαν καὶ συνεδρεύοντα μετὰ τούτων, πέμψαντές τινας τῶν ὑπασπιστῶν ἐκάλουν εἰς τὸ συνέδριον. ὁ δ’ οὕτως παρειστήκει τῶν φρενῶν ὡς οὔτε πράττειν ἐτόλμα τῶν ἑξῆς οὐδὲν οὔτε καλούμενος ὑπὸ τοῦ βασιλέως οἷός τ’ ἦν πειθαρχεῖν, ὃ πάντων ἐστὶν ἔσχατον, ἕως οἱ περὶ τὸν Ἀριστομένην γνόντες αὐτοῦ τὴν ἀλογίαν τοὺς μὲν στρατιώτας καὶ τὰ θηρία περιέστησαν περὶ τὴν οἰκίαν, Πτολεμαῖον δὲ τὸν Εὐμένους πέμψαντες μετὰ νεανίσκων ἄγειν αὐτὸν ἐκέλευον, ἐὰν μὲν ἑκὼν βούληται πειθαρχεῖν, εἰ δὲ μή, μετὰ βίας. τοῦ δὲ Πτολεμαίου παρεισελθόντος εἰς τὴν οἰκίαν καὶ δηλοῦντος ὅτι καλεῖ Σκόπαν ὁ βασιλεύς, τὰς μὲν ἀρχὰς οὐ προσεῖχε τοῖς λεγομένοις, ἀλλὰ καὶ βλέπων εἰς τὸν Πτολεμαῖον ἀτενὲς ἔμενε καὶ πλείω χρόνον ὡς ἂν εἰ προσανατεινόμενος αὐτῷ καὶ θαυμάζων τὴν τόλμαν. ὡς δ’ ἐπελθὼν ὁ Πτολεμαῖος θρασέως ἐπελάβετο τῆς χλαμύδος αὐτοῦ, τότε βοηθεῖν ἠξίου τοὺς παρόντας. ὄντων δὲ καὶ τῶν εἰσελθόντων νεανίσκων πλειόνων καὶ τὴν ἔξω περίστασιν διασαφήσαντός τινος, συνείξας τοῖς παροῦσιν ἠκολούθει μετὰ τῶν φίλων.", "st": "18.53"}, {"sp": "N", "t": "ἅμα δὲ τῷ παρελθεῖν εἰς τὸ συνέδριον βραχέα μὲν ὁ βασιλεὺς κατηγόρησε, μετὰ δὲ τοῦτον Πολυκράτης, ἄρτι παραγεγονὼς ἀπὸ Κύπρου, τελευταῖος δ’ Ἀριστομένης. ἦν δὲ τὰ μὲν ἄλλα παραπλήσιος ἡ κατηγορία πάντων τοῖς ἄρτι ῥηθεῖσι, προσετέθη δὲ τοῖς προειρημένοις ἡ μετὰ τῶν φίλων συνεδρεία καὶ τὸ μὴ πειθαρχῆσαι καλούμενον ὑπὸ τοῦ βασιλέως. ἐφ’ οἷς οὐ μόνον οἱ τοῦ συνεδρίου κατεγίνωσκον αὐτοῦ πάντες, ἀλλὰ καὶ τῶν ἔξωθεν τῶν πρεσβευτῶν οἱ συμπαρόντες. ὁ δ’ Ἀριστομένης, ὅτε κατηγορεῖν ἔμελλε, πολλοὺς μὲν καὶ ἑτέρους παρέλαβε τῶν ἐπιφανῶν ἀνδρῶν ἀπὸ τῆς Ἑλλάδος, καὶ τοὺς παρὰ τῶν Αἰτωλῶν δὲ πρεσβεύοντας ἐπὶ τὰς διαλύσεις, ἐν οἷς ἦν καὶ Δωρίμαχος ὁ Νικοστράτου. ῥηθέντων δὲ τούτων μεταλαβὼν ὁ Σκόπας ἐπειρᾶτο μὲν φέρειν τινὰς ἀπολογισμούς, οὐδενὸς δὲ προσέχοντος αὐτῷ διὰ τὴν τῶν πραγμάτων ἀλογίαν, εὐθέως οὗτος μὲν εἰς φυλακὴν ἀπήγετο μετὰ τῶν φίλων· ὁ δ’ Ἀριστομένης ἐπιγενομένης τῆς νυκτὸς τὸν μὲν Σκόπαν καὶ τοὺς συγγενεῖς αὐτοῦ καὶ φίλους πάντας διέφθειρε φαρμάκῳ, Δικαιάρχῳ δὲ καὶ στρέβλας καὶ μάστιγας προσαγαγὼν οὕτως αὐτὸν ἐπανείλετο, λαβὼν παρ’ αὐτοῦ δίκην καθήκουσαν καὶ κοινὴν ὑπὲρ πάντων τῶν Ἑλλήνων. ὁ γὰρ Δικαίαρχος οὗτος ἦν, ὃν Φίλιππος, ὅτε προέθετο παρασπονδεῖν τὰς Κυκλάδας νήσους καὶ τὰς ἐφ’ Ἑλλησπόντου πόλεις, ἀπέδειξε τοῦ στόλου παντὸς ἡγεμόνα καὶ τῆς ὅλης πράξεως προστάτην. ὃς ἐπὶ πρόδηλον ἀσέβειαν ἐκπεμπόμενος οὐχ οἷον ἄτοπόν τι πράττειν ἐνόμιζεν, ἀλλὰ τῇ τῆς ἀπονοίας ὑπερβολῇ καὶ τοὺς θεοὺς ὑπέλαβε καταπλήξεσθαι καὶ τοὺς ἀνθρώπους· οὗ γὰρ ὁρμίσειε τὰς ναῦς, δύο κατεσκεύαζε βωμούς, τὸν μὲν Ἀσεβείας, τὸν δὲ Παρανομίας, καὶ ἐπὶ τούτοις ἔθυε καὶ τούτους προσεκύνει καθάπερ ἂν εἰ δαίμονας. διὸ καὶ δοκεῖ μοι τυχεῖν τῆς ἁρμοζούσης δίκης καὶ παρὰ θεῶν καὶ παρ’ ἀνθρώπων· παρὰ φύσιν γὰρ ἐνστησάμενος τὸν αὑτοῦ βίον εἰκότως παρὰ φύσιν καὶ τῆς εἱμαρμένης ἔτυχε. τῶν δὲ λοιπῶν Αἰτωλῶν τοὺς βουλομένους εἰς τὴν οἰκείαν ἀπαλλάττεσθαι πάντας ἀπέλυσεν ὁ βασιλεὺς μετὰ τῶν ὑπαρχόντων.", "st": "18.54"}, {"sp": "N", "t": "Σκόπα δὲ καὶ ζῶντος μὲν ἐπίσημος ἦν ἡ φιλαργυρία — πολὺ γὰρ δή τι τοὺς ἄλλους ἀνθρώπους ὑπερέθετο κατὰ τὴν πλεονεξίαν — ἀποθανόντος δὲ καὶ μᾶλλον ἐγενήθη διὰ τοῦ πλήθους τοῦ χρυσίου καὶ τῆς κατασκευῆς τῆς εὑρημένης παρ’ αὐτῷ. λαβὼν γὰρ συνεργὸν τὴν ἀγριότητα τὴν Χαριμόρτου καὶ τὴν μέθην, ἄρδην ἐξετοιχωρύχησε τὴν βασιλείαν. ἐπειδὴ δὲ τὰ κατὰ τοὺς Αἰτωλοὺς ἔθεντο καλῶς οἱ περὶ τὴν αὐλήν, εὐθέως ἐγίνοντο περὶ τὸ ποιεῖν Ἀνακλητήρια τοῦ βασιλέως, οὐδέπω μὲν τῆς ἡλικίας κατεπειγούσης, νομίζοντες δὲ λήψεσθαί τινα τὰ πράγματα κατάστασιν καὶ πάλιν ἀρχὴν τῆς ἐπὶ τὸ βέλτιον προκοπῆς, δόξαντος αὐτοκράτορος ἤδη γεγονέναι τοῦ βασιλέως. χρησάμενοι δὲ ταῖς παρασκευαῖς μεγαλομερῶς, ἐπετέλουν τὴν πρᾶξιν ἀξίως τοῦ τῆς βασιλείας προσχήματος, πλεῖστα Πολυκράτους δοκοῦντος εἰς τὴν ἐπιβολὴν ταύτην αὐτοῖς συνηργηκέναι. ὁ γὰρ προειρημένος ἀνὴρ καὶ κατὰ τὸν πατέρα μὲν ἔτι νέος ὢν οὐδενὸς ἐδόκει τῶν περὶ τὴν αὐλὴν δευτερεύειν οὔτε κατὰ τὴν πίστιν οὔτε κατὰ τὰς πράξεις, ὁμοίως δὲ κατὰ τὸν ἐνεστῶτα βασιλέα. πιστευθεὶς γὰρ τῆς Κύπρου καὶ τῶν ἐν ταύτῃ προσόδων ἐν καιροῖς ἐπισφαλέσι καὶ ποικίλοις, οὐ μόνον διεφύλαξε τῷ παιδὶ τὴν νῆσον, ἀλλὰ καὶ πλῆθος ἱκανὸν ἥθροισε χρημάτων, ἃ τότε παραγεγόνει κομίζων τῷ βασιλεῖ, παραδεδωκὼς τὴν ἀρχὴν τῆς Κύπρου Πτολεμαίῳ τῷ Μεγαλοπολίτῃ. τυχὼν δὲ διὰ ταῦτα μεγάλης ἀποδοχῆς καὶ περιουσίας ἐν τοῖς ἑξῆς χρόνοις, μετὰ ταῦτα προβαινούσης τῆς ἡλικίας ὁλοσχερῶς εἰς ἀσέλγειαν ἐξώκειλε καὶ βίον ἀσυρῆ. παραπλησίαν δέ τινα τούτῳ φήμην ἐκληρονόμησεν ἐπὶ γήρως καὶ Πτολεμαῖος ὁ Ἀγησάρχου. περὶ ὧν, ὅταν ἐπὶ τοὺς καιροὺς ἔλθωμεν, οὐκ ὀκνήσομεν διασαφεῖν τὰ παρακολουθήσαντα ταῖς ἐξουσίαις αὐτῶν ἀπρεπῆ.", "st": "18.55"}, {"sp": "HDR", "t": "Βιβλίον ΙΘʹ", "st": "19"}, {"sp": "N", "t": "Πολύβιος μέν γέ φησι τῶν ἐντὸς Βαίτιος ποταμοῦ πόλεων ἡμέρᾳ μιᾷ τὰ τείχη κελεύσαντος αὐτοῦ περιαιρεθῆναι· πάμπολλαι δ’ ἦσαν αὗται καὶ γέμουσαι μαχίμων ἀνδρῶν.", "st": "19.1"}, {"sp": "HDR", "t": "Βιβλίον Κʹ", "st": "20"}, {"sp": "N", "t": "καὶ αὖθις Πολύβιος· τριάκοντα τῶν ἀποκλήτων προεχειρίσαντο τοὺς συνεδρεύσοντας μετὰ τοῦ βασιλέως. καὶ αὖθις· ὁ δὲ συνῆγε τοὺς ἀποκλήτους καὶ διαβούλιον ἀνεδίδου περὶ τῶν ἐνεστώτων. —", "st": "20.1"}, {"sp": "N", "t": "ὅτι φιλίππου πρεσβεύσαντος πρὸς Βοιωτοὺς οἱ Βοιωτοὶ ἀπεκρίθησαν τοῖς πρεσβευταῖς διότι παραγενομένου τοῦ βασιλέως πρὸς αὐτούς, τότε βουλεύσονται περὶ τῶν παρακαλουμένων. —", "st": "20.2"}, {"sp": "N", "t": "ὅτι Ἀντιόχου διατρίβοντος ἐν τῇ Χαλκίδι καὶ τοῦ χειμῶνος καταρχομένου παρεγένοντο πρὸς αὐτὸν πρεσβευταὶ παρὰ μὲν τοῦ τῶν Ἠπειρωτῶν ἔθνους οἱ περὶ Χάροπα, παρὰ δὲ τῆς τῶν Ἠλείων πόλεως οἱ περὶ Καλλίστρατον. οἱ μὲν οὖν Ἠπειρῶται παρεκάλουν αὐτὸν μὴ προεμβιβάζειν σφᾶς εἰς τὸν πρὸς Ῥωμαίους πόλεμον, θεωροῦντα διότι πρόκεινται πάσης τῆς Ἑλλάδος πρὸς τὴν Ἰταλίαν· ἀλλ’ εἰ μὲν αὐτὸς δύναται προκαθίσας τῆς Ἠπείρου παρασκευάζειν σφίσι τὴν ἀσφάλειαν, ἔφασαν αὐτὸν δέξασθαι καὶ ταῖς πόλεσι καὶ τοῖς λιμέσιν· εἰ δὲ μὴ κρίνει τοῦτο πράττειν κατὰ τὸ παρόν, συγγνώμην ἔχειν ἠξίουν αὐτοῖς δεδιόσι τὸν ἀπὸ Ῥωμαίων πόλεμον. οἱ δ’ Ἠλεῖοι παρεκάλουν πέμπειν τῇ πόλει βοήθειαν· ἐψηφισμένων γὰρ τῶν Ἀχαιῶν τὸν πόλεμον εὐλαβεῖσθαι τὴν τούτων ἔφοδον. ὁ δὲ βασιλεὺς τοῖς μὲν Ἠπειρώταις ἀπεκρίθη διότι πέμψει πρεσβευτὰς τοὺς διαλεχθησομένους αὐτοῖς ὑπὲρ τῶν κοινῇ συμφερόντων, τοῖς δ’ Ἠλείοις ἐξαπέστειλε χιλίους πεζούς, ἡγεμόνα συστήσας Εὐφάνη τὸν Κρῆτα. —", "st": "20.3"}, {"sp": "N", "t": "ὅτι Βοιωτοὶ ἐκ πολλῶν ἤδη χρόνων καχεκτοῦντες ἦσαν καὶ μεγάλην εἶχον διαφορὰν πρὸς τὴν γεγενημένην εὐεξίαν καὶ δόξαν αὐτῶν τῆς πολιτείας. οὗτοι γὰρ μεγάλην περιποιησάμενοι καὶ δόξαν καὶ δύναμιν ἐν τοῖς Λευκτρικοῖς καιροῖς, οὐκ οἶδ’ ὅπως κατὰ τὸ συνεχὲς ἐν τοῖς ἑξῆς χρόνοις ἀφῄρουν ἀμφοτέρων αἰεὶ τῶν προειρημένων, ἔχοντες στρατηγὸν Ἀβαιόκριτον. ἀπὸ δὲ τούτων τῶν καιρῶν οὐ μόνον ἀφῄρουν, ἀλλ’ ἁπλῶς εἰς τἀναντία τραπέντες καὶ τὴν πρὸ τοῦ δόξαν ἐφ’ ὅσον οἷοί τ’ ἦσαν ἠμαύρωσαν. Ἀχαιῶν γὰρ αὐτοὺς πρὸς Αἰτωλοὺς ἐκπολεμωσάντων, μετασχόντες τούτοις τῆς αὐτῆς αἱρέσεως καὶ ποιησάμενοι συμμαχίαν, μετὰ ταῦτα κατὰ τὸ συνεχὲς ἐπολέμουν πρὸς Αἰτωλούς. ἐμβαλόντων δὲ μετὰ δυνάμεως εἰς τὴν Βοιωτίαν τῶν Αἰτωλῶν ἐκστρατεύσαντες πανδημεί, καὶ τῶν Ἀχαιῶν ἡθροισμένων καὶ μελλόντων παραβοηθεῖν οὐκ ἐκδεξάμενοι τὴν τούτων παρουσίαν συνέβαλον τοῖς Αἰτωλοῖς, ἡττηθέντες δὲ κατὰ τὸν κίνδυνον οὕτως ἀνέπεσον ταῖς ψυχαῖς ὥστ’ ἀπ’ ἐκείνης τῆς χρείας ἁπλῶς οὐδενὸς ἔτι τῶν καλῶν ἀμφισβητεῖν ἐτόλμησαν οὐδ’ ἐκοινώνησαν οὔτε πράξεως οὔτ’ ἀγῶνος οὐδενὸς ἔτι τοῖς Ἕλλησι μετὰ κοινοῦ δόγματος, ἀλλ’ ὁρμήσαντες πρὸς εὐωχίαν καὶ μέθας οὐ μόνον τοῖς σώμασιν ἐξελύθησαν, ἀλλὰ καὶ ταῖς ψυχαῖς.", "st": "20.4"}, {"sp": "N", "t": "τὰ δὲ κεφάλαια τῆς κατὰ μέρος ἀγνοίας ἐχειρίσθη παρ’ αὐτοῖς τὸν τρόπον τοῦτον. μετὰ γὰρ τὴν προειρημένην ἧτταν εὐθέως ἐγκαταλιπόντες τοὺς Ἀχαιοὺς προσένειμαν Αἰτωλοῖς τὸ ἔθνος. ἀνελομένων δὲ καὶ τούτων πόλεμον μετά τινα χρόνον πρὸς Δημήτριον τὸν Φιλίππου πατέρα, πάλιν ἐγκαταλιπόντες τούτους, καὶ παραγενομένου Δημητρίου μετὰ δυνάμεως εἰς τὴν Βοιωτίαν οὐδενὸς πεῖραν λαβόντες τῶν δεινῶν, ὑπέταξαν σφᾶς αὐτοὺς ὁλοσχερῶς Μακεδόσι. βραχέος δ’ αἰθύγματος ἐγκαταλειπομένου τῆς προγονικῆς δόξης, ἦσάν τινες οἳ δυσηρεστοῦντο τῇ παρούσῃ καταστάσει καὶ τῷ πάντα πείθεσθαι Μακεδόσι. διὸ καὶ μεγάλην ἀντιπολιτείαν εἶναι συνέβαινε τούτοις πρὸς τοὺς περὶ τὸν Ἀσκώνδαν καὶ Νέωνα, τοὺς Βραχύλλου προγόνους· οὗτοι γὰρ ἦσαν οἱ μάλιστα τότε μακεδονίζοντες. οὐ μὴν ἀλλὰ τέλος κατίσχυσαν οἱ περὶ τὸν Ἀσκώνδαν γενομένης τινὸς περιπετείας τοιαύτης. Ἀντίγονος μετὰ τὸν Δημητρίου θάνατον ἐπιτροπεύσας Φιλίππου, πλέων ἐπί τινας πράξεις πρὸς τὰς ἐσχατιὰς τῆς Βοιωτίας πρὸς Λάρυμναν, παραδόξου γενομένης ἀμπώτεως ἐκάθισαν εἰς τὸ ξηρὸν αἱ νῆες αὐτοῦ. κατὰ δὲ τὸν καιρὸν τοῦτον προσπεπτωκυίας φήμης ὅτι μέλλει κατατρέχειν τὴν χώραν Ἀντίγονος, Νέων, ἱππαρχῶν τότε καὶ πάντας τοὺς Βοιωτῶν ἱππεῖς μεθ’ αὑτοῦ περιαγόμενος χάριν τοῦ παραφυλάττειν τὴν χώραν, ἐπεγένετο τοῖς περὶ τὸν Ἀντίγονον ἀπορουμένοις καὶ δυσχρηστουμένοις διὰ τὸ συμβεβηκός, καὶ δυνάμενος μεγάλα βλάψαι τοὺς Μακεδόνας ἔδοξε φείσασθαι παρὰ τὴν προσδοκίαν αὐτῶν. τοῖς μὲν οὖν ἄλλοις Βοιωτοῖς ἤρεσκε τοῦτο πράξας, τοῖς δὲ Θηβαίοις οὐχ ὅλως εὐδόκει τὸ γεγονός. ὁ δ’ Ἀντίγονος, ἐπελθούσης μετ’ ὀλίγον τῆς πλήμης καὶ κουφισθεισῶν τῶν νεῶν, τῷ μὲν Νέωνι μεγάλην εἶχε χάριν ἐπὶ τῷ μὴ συνεπιτεθεῖσθαι σφίσι κατὰ τὴν περιπέτειαν, αὐτὸς δὲ τὸν προκείμενον ἐτέλει πλοῦν εἰς τὴν Ἀσίαν. διὸ καὶ μετὰ ταῦτα, νικήσας Κλεομένη τὸν Σπαρτιάτην καὶ κύριος γενόμενος τῆς Λακεδαίμονος, ἐπιστάτην ἀπέλειπε τῆς πόλεως Βραχύλλην, ταύτην αὐτῷ χάριν ἀποδιδοὺς τῆς τοῦ πατρὸς Νέωνος εὐεργεσίας· ἐξ ὧν οὐδὲ κατὰ μικρὸν συνέβη τὴν οἰκίαν ἐπανορθωθῆναι τὴν περὶ τὸν Βραχύλλην. οὐ μόνον δὲ ταύτην αὐτῶν ἔσχε τὴν πρόνοιαν, ἀλλὰ καὶ κατὰ τὸ συνεχές, ὁτὲ μὲν αὐτός, ὁτὲ δὲ Φιλίππος, χορηγοῦντες καὶ συνεπισχύοντες αἰεί, ταχέως κατηγωνίσαντο τοὺς ἐν ταῖς Θήβαις αὐτοῖς ἀντιπολιτευομένους καὶ πάντας ἠνάγκασαν μακεδονίζειν πλὴν τελέως ὀλίγων τινῶν. τὰ μὲν οὖν κατὰ τὴν οἰκίαν τὴν Νέωνος τοιαύτην ἔλαβε τὴν ἀρχὴν καὶ τῆς πρὸς Μακεδόνας συστάσεως καὶ τῆς κατὰ τὴν οὐσίαν ἐπιδόσεως·", "st": "20.5"}, {"sp": "N", "t": "τὰ δὲ κοινὰ τῶν Βοιωτῶν εἰς τοσαύτην παραγεγόνει καχεξίαν ὥστε σχεδὸν εἴκοσι καὶ πέντ’ ἐτῶν τὸ δίκαιον μὴ διεξῆχθαι παρ’ αὐτοῖς μήτε περὶ τῶν ἰδιωτικῶν συμβολαίων μήτε περὶ τῶν κοινῶν ἐγκλημάτων, ἀλλ’ οἱ μὲν φρουρὰς παραγγέλλοντες τῶν ἀρχόντων, οἱ δὲ στρατείας κοινάς, ἐξέκοπτον ἀεὶ τὴν δικαιοδοσίαν· ἔνιοι δὲ τῶν στρατηγῶν καὶ μισθοδοσίας ἐποίουν ἐκ τῶν κοινῶν τοῖς ἀπόροις τῶν ἀνθρώπων. ἐξ ὧν ἐδιδάχθη τὰ πλήθη τούτοις προσέχειν καὶ τούτοις περιποιεῖν τὰς ἀρχάς, δι’ ὧν ἔμελλε τῶν μὲν ἀδικημάτων καὶ τῶν ὀφειλημάτων οὐχ ὑφέξειν δίκας, προσλήψεσθαι δὲ τῶν κοινῶν αἰεί τι διὰ τὴν τῶν ἀρχόντων χάριν. πλεῖστα δὲ συνεβάλετο πρὸς τὴν τοιαύτην Ὀφέλτας, αἰεί τι προσεπινοῶν ὃ κατὰ τὸ παρὸν ἐδόκει τοὺς πολλοὺς ὠφελεῖν, μετὰ δὲ ταῦτα πάντας ἀπολεῖν ἔμελλεν ὁμολογουμένως. τούτοις δ’ ἠκολούθησε καὶ ἕτερος ζῆλος οὐκ εὐτυχής. οἱ μὲν γὰρ ἄτεκνοι τὰς οὐσίας οὐ τοῖς κατὰ γένος ἐπιγενομένοις τελευτῶντες ἀπέλειπον, ὅπερ ἦν ἔθος παρ’ αὐτοῖς πρότερον, ἀλλ’ εἰς εὐωχίας καὶ μέθας διετίθεντο καὶ κοινὰς τοῖς φίλοις ἐποίουν· πολλοὶ δὲ καὶ τῶν ἐχόντων γενεὰς ἀπεμέριζον τοῖς συσσιτίοις τὸ πλεῖον μέρος τῆς οὐσίας, ὥστε πολλοὺς εἶναι Βοιωτῶν οἷς ὑπῆρχε δεῖπνα τοῦ μηνὸς πλείω τῶν εἰς τὸν μῆνα διατεταγμένων ἡμερῶν. διὸ καὶ Μεγαρεῖς, μισήσαντες μὲν τὴν τοιαύτην κατάστασιν, μνησθέντες δὲ τῆς προγεγενημένης αὐτοῖς μετὰ τῶν Ἀχαιῶν συμπολιτείας, αὖτις ἀπένευσαν πρὸς τοὺς Ἀχαιοὺς καὶ τὴν ἐκείνων αἵρεσιν. Μεγαρεῖς γὰρ ἐξ ἀρχῆς μὲν ἐπολιτεύοντο μετὰ τῶν Ἀχαιῶν ἀπὸ τῶν κατ’ Ἀντίγονον τὸν Γονατᾶν χρόνων· ὅτε δὲ Κλεομένης εἰς τὸν Ἰσθμὸν προεκάθισεν, διακλεισθέντες προσέθεντο τοῖς Βοιωτοῖς μετὰ τῆς τῶν Ἀχαιῶν γνώμης. βραχὺ δὲ πρὸ τῶν νῦν λεγομένων καιρῶν δυσαρεστήσαντες τῇ πολιτείᾳ τῶν Βοιωτῶν αὖτις ἀπένευσαν πρὸς τοὺς Ἀχαιούς. οἱ δὲ Βοιωτοὶ διοργισθέντες ἐπὶ τῷ καταφρονεῖσθαι δοκεῖν ἐξῆλθον ἐπὶ τοὺς Μεγαρεῖς πανδημεὶ σὺν τοῖς ὅπλοις. οὐδένα δὲ ποιουμένων λόγον τῶν Μεγαρέων τῆς παρουσίας αὐτῶν, οὕτω θυμωθέντες πολιορκεῖν ἐπεβάλοντο καὶ προσβολὰς ποιεῖσθαι τῇ πόλει. πανικοῦ δ’ ἐμπεσόντος αὐτοῖς καὶ φήμης ὅτι πάρεστιν Φιλοποίμην τοὺς Ἀχαιοὺς ἔχων, ἀπολιπόντες πρὸς τῷ τείχει τὰς κλίμακας ἔφυγον προτροπάδην εἰς τὴν οἰκείαν.", "st": "20.6"}, {"sp": "N", "t": "τοιαύτην δ’ ἔχοντες οἱ Βοιωτοὶ τὴν διάθεσιν τῆς πολιτείας, εὐτυχῶς πως διώλισθον καὶ τοὺς κατὰ Φίλιππον καὶ τοὺς κατ’ Ἀντίοχον καιρούς. ἔν γε μὴν τοῖς ἑξῆς οὐ διέφυγον, ἀλλ’ ὥσπερ ἐπίτηδες ἀνταπόδοσιν ἡ τύχη ποιουμένη βαρέως ἔδοξεν αὐτοῖς ἐπεμβαίνειν· ὑπὲρ ὧν ἡμεῖς ἐν τοῖς ἑξῆς ποιησόμεθα μνήμην. — ὅτι οἱ πολλοὶ πρόφασιν μὲν εἶχον τῆς πρὸς Ῥωμαίους ἀλλοτριότητος τὴν ἐπαναίρεσιν τὴν Βραχύλλου καὶ τὴν στρατείαν, ἣν ἐποιήσατο Τίτος ἐπὶ Κορώνειαν διὰ τοὺς ἐπιγινομένους φόνους ἐν ταῖς ὁδοῖς τῶν Ῥωμαίων, τῇ δ’ ἀληθείᾳ καχεκτοῦντες ἦσαν ταῖς ψυχαῖς διὰ τὰς προειρημένας αἰτίας. καὶ γὰρ τοῦ βασιλέως συνεγγίζοντος ἐξῄεσαν ἐπὶ τὴν ἀπάντησιν οἱ τῶν Βοιωτῶν ἄρξαντες· συμμίξαντες δὲ καὶ φιλανθρώπως ὁμιλήσαντες ἦγον αὐτὸν εἰς τὰς Θήβας. —", "st": "20.7"}, {"sp": "N", "t": "Ἀντίοχος δὲ ὁ μέγας ἐπικαλούμενος, ὃν Ῥωμαῖοι καθεῖλον, ὡς ἱστορεῖ Πολύβιος ἐν τῇ εἰκοστῇ, παρελθὼν εἰς Χαλκίδα τῆς Εὐβοίας συνετέλει γάμους, πεντήκοντα μὲν ἔτη γεγονὼς καὶ δύο τὰ μέγιστα τῶν ἔργων ἀνειληφώς, τήν τε τῶν Ἑλλήνων ἐλευθέρωσιν, ὡς αὐτὸς ἐπηγγέλλετο, καὶ τὸν πρὸς Ῥωμαίους πόλεμον. ἐρασθεὶς οὖν παρθένου Χαλκιδικῆς κατὰ τὸν τοῦ πολέμου καιρὸν ἐφιλοτιμήσατο γῆμαι αὐτήν, οἰνοπότης ὢν καὶ μέθαις χαίρων. ἦν δ’ αὕτη Κλεοπτολέμου μὲν θυγάτηρ, ἑνὸς τῶν ἐπιφανῶν, κάλλει δὲ πάσας ὑπερβάλλουσα. καὶ τοὺς γάμους συντελῶν ἐν τῇ Χαλκίδι αὐτόθι διέτριψε τὸν χειμῶνα, τῶν ἐνεστώτων οὐδ’ ἡντινοῦν ποιούμενος πρόνοιαν, ἔθετο δὲ καὶ τῇ παιδὶ ὄνομα Εὔβοιαν. ἡττηθεὶς οὖν τῷ πολέμῳ ἔφυγεν εἰς Ἔφεσον μετὰ τῆς νεογάμου.", "st": "20.8"}, {"sp": "N", "t": "ὅτι οἱ περὶ τὸν Φαινέαν τὸν τῶν Αἰτωλῶν στρατηγὸν μετὰ τὸ γενέσθαι τὴν Ἡράκλειαν ὑποχείριον τοῖς Ῥωμαίοις, ὁρῶντες τὸν περιεστῶτα καιρὸν τὴν Αἰτωλίαν καὶ λαμβάνοντες πρὸ ὀφθαλμῶν τὰ συμβησόμενα ταῖς ἄλλαις πόλεσιν, ἔκριναν διαπέμπεσθαι πρὸς τὸν Μάνιον ὑπὲρ ἀνοχῶν καὶ διαλύσεως. ταῦτα δὲ διαλαβόντες ἐξαπέστειλαν Ἀρχέδαμον καὶ Πανταλέοντα καὶ Χάλεπον· οἳ συμμίξαντες τῷ στρατηγῷ τῶν Ῥωμαίων προέθεντο μὲν καὶ πλείους ποιεῖσθαι λόγους, μεσολαβηθέντες δὲ κατὰ τὴν ἔντευξιν ἐκωλύθησαν. ὁ γὰρ Μάνιος κατὰ μὲν τὸ παρὸν οὐκ ἔφασκεν εὐκαιρεῖν, περισπώμενος ὑπὸ τῆς τῶν ἐκ τῆς Ἡρακλείας λαφύρων οἰκονομίας· δεχημέρους δὲ ποιησάμενος ἀνοχὰς ἐκπέμψειν ἔφη μετ’ αὐτῶν Λεύκιον, πρὸς ὃν ἐκέλευε λέγειν ὑπὲρ ὧν ἂν δέοιντο. γενομένων δὲ τῶν ἀνοχῶν, καὶ τοῦ Λευκίου συνελθόντος εἰς τὴν Ὑπάταν, ἐγένοντο λόγοι καὶ πλείους ὑπὲρ τῶν ἐνεστώτων. οἱ μὲν οὖν Αἰτωλοὶ συνίσταντο τὴν δικαιολογίαν ἀνέκαθεν προφερόμενοι τὰ προγεγονότα σφίσι φιλάνθρωπα πρὸς τοὺς Ῥωμαίους· ὁ δὲ Λεύκιος ἐπιτεμὼν αὐτῶν τὴν ὁρμὴν οὐκ ἔφη τοῖς παροῦσι καιροῖς ἁρμόζειν τοῦτο τὸ γένος τῆς δικαιολογίας· λελυμένων γὰρ τῶν ἐξ ἀρχῆς φιλανθρώπων δι’ ἐκείνους, καὶ τῆς ἐνεστώσης ἔχθρας δι’ Αἰτωλοὺς γεγενημένης, οὐδὲν ἔτι συμβάλλεσθαι τὰ τότε φιλάνθρωπα πρὸς τοὺς νῦν καιρούς. διόπερ ἀφεμένους τοῦ δικαιολογεῖσθαι συνεβούλευε τρέπεσθαι πρὸς τὸν ἀξιωματικὸν λόγον καὶ δεῖσθαι τοῦ στρατηγοῦ συγγνώμης τυχεῖν ἐπὶ τοῖς ἡμαρτημένοις. οἱ δ’ Αἰτωλοὶ καὶ πλείω λόγον ποιησάμενοι περὶ τῶν ὑποπιπτόντων ἔκριναν ἐπιτρέπειν τὰ ὅλα Μανίῳ, δόντες αὑτοὺς εἰς τὴν Ῥωμαίων πίστιν, οὐκ εἰδότες τίνα δύναμιν ἔχει τοῦτο, τῷ δὲ τῆς πίστεως ὀνόματι πλανηθέντες, ὡς ἂν διὰ τοῦτο τελειοτέρου σφίσιν ἐλέους ὑπάρξοντος. παρὰ δὲ Ῥωμαίοις ἰσοδυναμεῖ τό τ’ εἰς τὴν πίστιν αὑτὸν ἐγχειρίσαι καὶ τὸ τὴν ἐπιτροπὴν δοῦναι περὶ αὑτοῦ τῷ κρατοῦντι.", "st": "20.9"}, {"sp": "N", "t": "πλὴν ταῦτα κρίναντες ἐξέπεμψαν ἅμα τῷ Λευκίῳ τοὺς περὶ Φαινέαν διασαφήσοντας τὰ δεδογμένα τῷ Μανίῳ κατὰ σπουδήν· οἳ καὶ συμμίξαντες τῷ στρατηγῷ καὶ πάλιν ὁμοίως δικαιολογηθέντες ὑπὲρ αὑτῶν, ἐπὶ καταστροφῆς εἶπαν διότι κέκριται τοῖς Αἰτωλοῖς σφᾶς αὐτοὺς ἐγχειρίζειν εἰς τὴν Ῥωμαίων πίστιν. ὁ δὲ Μάνιος μεταλαβών \"οὐκοῦν οὕτως ἔχει ταῦτα,\" φησίν, \" ὦ ἄνδρες Αἰτωλοί;\" τῶν δὲ κατανευσάντων, \"τοιγαροῦν πρῶτον μὲν δεήσει μηδένα διαβαίνειν ὑμῶν εἰς τὴν Ἀσίαν, μήτε κατ’ ἰδίαν μήτε μετὰ κοινοῦ δόγματος, δεύτερον Δικαίαρχον ἔκδοτον δοῦναι καὶ Μενέστρατον τὸν Ἠπειρώτην,\" ὃς ἐτύγχανε τότε παραβεβοηθηκὼς εἰς Ναύπακτον, \"σὺν δὲ τούτοις Ἀμύνανδρον τὸν βασιλέα καὶ τῶν Ἀθαμάνων τοὺς ἅμα τούτῳ συναποχωρήσαντας πρὸς αὐτούς. \" ὁ δὲ Φαινέας μεσολαβήσας \"ἀλλ’ οὔτε δίκαιον,\" ἔφησεν, \"οὔθ’ Ἑλληνικόν ἐστιν, ὦ στρατηγέ, τὸ παρακαλούμενον.\" ὁ δὲ Μάνιος οὐχ οὕτως ὀργισθεὶς ὡς βουλόμενος εἰς ἔννοιαν αὐτοὺς ἀγαγεῖν τῆς περιστάσεως καὶ καταπλήξασθαι τοῖς ὅλοις, \"ἔτι γὰρ ὑμεῖς ἑλληνοκοπεῖτε\" φησὶ \"καὶ περὶ τοῦ πρέποντος καὶ καθήκοντος ποιεῖσθε λόγον, δεδωκότες ἑαυτοὺς εἰς τὴν πίστιν; οὓς ἐγὼ δήσας εἰς τὴν ἅλυσιν ἀπάξω πάντας, ἂν τοῦτ’ ἐμοὶ δόξῃ. \" ταῦτα λέγων φέρειν ἅλυσιν ἐκέλευσε καὶ σκύλακα σιδηροῦν ἑκάστῳ περιθεῖναι περὶ τὸν τράχηλον. οἱ μὲν οὖν περὶ τὸν Φαινέαν ἔκθαμβοι γεγονότες ἕστασαν ἄφωνοι πάντες, οἱονεὶ παραλελυμένοι καὶ τοῖς σώμασι καὶ ταῖς ψυχαῖς διὰ τὸ παράδοξον τῶν ἀπαντωμένων· ὁ δὲ Λεύκιος καί τινες ἕτεροι τῶν συμπαρόντων χιλιάρχων ἐδέοντο τοῦ Μανίου μηδὲν βουλεύσασθαι δυσχερὲς ὑπὲρ τῶν παρόντων ἀνδρῶν, ἐπεὶ τυγχάνουσιν ὄντες πρεσβευταί. τοῦ δὲ συγχωρήσαντος ἤρξατο λέγειν ὁ Φαινέας· ἔφη γὰρ αὑτὸν καὶ τοὺς ἀποκλήτους ποιήσειν τὰ προσταττόμενα, προσδεῖσθαι δὲ καὶ τῶν πολλῶν, εἰ μέλλει κυρωθῆναι τὰ παραγγελλόμενα. τοῦ δὲ Μανίου φήσαντος αὐτὸν ὀρθῶς λέγειν, ἠξίου πάλιν ἀνοχὰς αὑτοῖς δοθῆναι δεχημέρους. συγχωρηθέντος δὲ καὶ τούτου, τότε μὲν ἐπὶ τούτοις ἐχωρίσθησαν· παραγενόμενοι δ’ εἰς τὴν Ὑπάταν διεσάφουν τοῖς ἀποκλήτοις τὰ γεγονότα καὶ τοὺς ῥηθέντας λόγους. ὧν ἀκούσαντες τότε πρῶτον ἔννοιαν ἔλαβον Αἰτωλοὶ τῆς αὑτῶν ἀγνοίας καὶ τῆς ἐπιφερομένης αὐτοῖς ἀνάγκης. διὸ γράφειν ἔδοξεν εἰς τὰς πόλεις καὶ συγκαλεῖν τοὺς Αἰτωλοὺς χάριν τοῦ βουλεύσασθαι περὶ τῶν προσταττομένων. διαδοθείσης δὲ τῆς φήμης ὑπὲρ τῶν ἀπηντημένων τοῖς περὶ τὸν Φαινέαν, οὕτως ἀπεθηριώθη τὸ πλῆθος ὥστ’ οὐδ’ ἀπαντᾶν οὐδεὶς ἐπεβάλετο πρὸς τὸ διαβούλιον. τοῦ δ’ ἀδυνάτου κωλύσαντος βουλεύσασθαι περὶ τῶν ἐπιταττομένων, ἅμα δὲ καὶ τοῦ Νικάνδρου κατὰ τὸν καιρὸν τοῦτον καταπλεύσαντος ἐκ τῆς Ἀσίας εἰς τὰ Φάλαρα τοῦ κόλπου τοῦ Μηλιέως, ὅθεν καὶ τὴν ὁρμὴν ἐποιήσατο, καὶ διασαφοῦντος τὴν τοῦ βασιλέως εἰς αὑτὸν προθυμίαν καὶ τὰς εἰς τὸ μέλλον ἐπαγγελίας, ἔτι μᾶλλον ὠλιγώρησαν, τοῦ μηδὲν γενέσθαι πέρας ὑπὲρ τῆς εἰρήνης. ὅθεν ἅμα τῷ διελθεῖν τὰς ἐν ταῖς ἀνοχαῖς ἡμέρας κατάμονος αὖθις ὁ πόλεμος ἐγεγόνει τοῖς Αἰτωλοῖς.", "st": "20.10"}, {"sp": "N", "t": "περὶ δὲ τῆς συμβάσης τῷ Νικάνδρῳ περιπετείας οὐκ ἄξιον παρασιωπῆσαι. παρεγενήθη μὲν γὰρ ἐκ τῆς Ἐφέσου δωδεκαταῖος εἰς τὰ Φάλαρα πάλιν, ἀφ’ ἧς ὥρμηθ’ ἡμέρας· καταλαβὼν δὲ τοὺς Ῥωμαίους ἔτι περὶ τὴν Ἡράκλειαν, τοὺς δὲ Μακεδόνας ἀφεστῶτας μὲν ἀπὸ τῆς Λαμίας, οὐ μακρὰν δὲ στρατοπεδεύοντας τῆς πόλεως, τὰ μὲν χρήματ’ εἰς τὴν Λαμίαν διεκόμισε παραδόξως, αὐτὸς δὲ τῆς νυκτὸς ἐπεβάλετο κατὰ τὸν μεταξὺ τόπον τῶν στρατοπέδων διαπεσεῖν εἰς τὴν Ὑπάταν. ἐμπεσὼν δ’ εἰς τοὺς προκοίτους τῶν Μακεδόνων ἀνήγετο πρὸς τὸν Φίλιππον ἔτι τῆς συνουσίας ἀκμαζούσης, προσδοκῶν πείσεσθαί τι δεινὸν πεσὼν ὑπὸ τοῦ Φιλίππου τὸν θυμὸν ἢ παραδοθήσεσθαι τοῖς Ῥωμαίοις. τοῦ δὲ πράγματος ἀγγελθέντος τῷ βασιλεῖ, ταχέως ἐκέλευσε τοὺς ἐπὶ τούτων ὄντας θεραπεῦσαι τὸν Νίκανδρον καὶ τὴν λοιπὴν ἐπιμέλειαν αὐτοῦ ποιήσασθαι φιλάνθρωπον. μετὰ δέ τινα χρόνον αὐτὸς ἐξαναστὰς συνέμιξε τῷ Νικάνδρῳ καὶ πολλὰ καταμεμψάμενος τὴν κοινὴν τῶν Αἰτωλῶν ἄγνοιαν, ἐξ ἀρχῆς μέν, ὅτι Ῥωμαίους ἐπαγάγοιεν τοῖς Ἕλλησι, μετὰ δὲ ταῦτα πάλιν Ἀντίοχον, ὅμως ἔτι καὶ νῦν παρεκάλει λήθην ποιησαμένους τῶν προγεγονότων ἀντέχεσθαι τῆς πρὸς αὑτὸν εὐνοίας καὶ μὴ θελῆσαι συνεπεμβαίνειν τοῖς κατ’ ἀλλήλων καιροῖς. ταῦτα μὲν οὖν παρῄνει τοῖς προεστῶσι τῶν Αἰτωλῶν ἀναγγέλλειν· αὐτὸν δὲ τὸν Νίκανδρον παρακαλέσας μνημονεύειν τῆς εἰς αὐτὸν γεγενημένης εὐεργεσίας ἐξέπεμπε μετὰ προπομπῆς ἱκανῆς, παραγγείλας τοῖς ἐπὶ τούτῳ τεταγμένοις ἀσφαλῶς εἰς τὴν Ὑπάταν αὐτὸν ἀποκαταστῆσαι. ὁ δὲ Νίκανδρος, τελέως ἀνελπίστου καὶ παραδόξου φανείσης αὐτῷ τῆς ἀπαντήσεως, τότε μὲν ἀνεκομίσθη πρὸς τοὺς οἰκείους, κατὰ δὲ τὸν ἑξῆς χρόνον ἀπὸ ταύτης τῆς συστάσεως εὔνους ὢν διετέλει τῇ Μακεδόνων οἰκίᾳ. διὸ καὶ μετὰ ταῦτα κατὰ τοὺς Περσικοὺς καιροὺς ἐνδεδεμένος τῇ προειρημένῃ χάριτι καὶ δυσχερῶς ἀντιπράττων ταῖς τοῦ Περσέως ἐπιβολαῖς, εἰς ὑποψίας καὶ διαβολὰς ἐμπεσὼν καὶ τέλος ἀνακληθεὶς εἰς Ῥώμην ἐκεῖ μετήλλαξε τὸν βίον. — κόραξ, ὄρος μεταξὺ Καλλιπόλεως καὶ Ναυπάκτου. Πολύβιος εἰκοστῷ. — Ἀπεράντεια, πόλις Θεσσαλίας. Πολύβιος εἰκοστῷ. —", "st": "20.11"}, {"sp": "N", "t": "ἐξ αὑτῶν τὸν ἐροῦντα περὶ τούτων πρὸς αὐτόν· ἀλλ’ ὥσπερ τοῖς ἐπὶ τῶν πλείστων ἐργολαβοῦσι πολλοὶ προσφέρουσι τὰς τοιαύτας χάριτας καὶ ταύτην ἀρχὴν ποιοῦνται φιλίας καὶ συστάσεως, οὕτως ἐπὶ Φιλοποίμενος ὁ προσοίσων ταύτην τὴν χάριν ἑκὼν οὐχ εὑρίσκετο τὸ παράπαν, ἕως [ἂν] ἐξαπορήσαντες ψήφῳ προεχειρίσαντο Τιμόλαον, ὃς ὑπάρχων καὶ ξένος πατρικὸς καὶ συνήθης ἐπὶ πολὺ τῷ Φιλοποίμενι, δὶς εἰς τὴν Μεγάλην πόλιν ἐκδημήσας αὐτοῦ τούτου χάριν οὐκ ἐτόλμησε φθέγξασθαι περὶ τούτων οὐδέν, μέχρις ὅτε μυωπίσας ἑαυτὸν καὶ τρίτον ἐλθὼν ἐθάρρησε μνησθῆναι τῆς δωρεᾶς. τοῦ δὲ Φιλοποίμενος παραδόξως αὐτὸν ἐπὶ τούτοις ἀποδεξαμένου καὶ φιλανθρώπως, ὁ μὲν Τιμόλαος περιχαρὴς ἦν, ὑπολαβὼν καθῖχθαι τῆς ἐπιβολῆς, ὁ δὲ Φιλοποίμην ἥξειν ἔφη μετ’ ὀλίγας ἡμέρας εἰς τὴν Λακεδαίμονα· θέλειν γὰρ εὐχαριστῆσαι πᾶσι τοῖς ἄρχουσι περὶ τούτων. ἐλθὼν δὲ μετὰ ταῦτα καὶ κληθεὶς εἰς τὸ συνέδριον πάλαι μὲν ἔφη γινώσκειν τὴν τῶν Λακεδαιμονίων πρὸς αὑτὸν εὔνοιαν, μάλιστα δ’ ἐκ τοῦ νῦν προτεινομένου στεφάνου καὶ τῆς τοιαύτης τιμῆς. τὴν μὲν οὖν προαίρεσιν αὐτῶν ἔφησεν ἀποδέχεσθαι, τῷ δὲ χειρισμῷ δυσωπεῖσθαι. δεῖν γὰρ οὐ τοῖς φίλοις δίδοσθαι τὰς τοιαύτας τιμὰς καὶ τοὺς στεφάνους, ἐξ ὧν ὁ περιθέμενος οὐδέποτε μὴ τὸν ἰὸν ἐκνίψηται, πολὺ δὲ μᾶλλον τοῖς ἐχθροῖς, ἵν’ οἱ μὲν φίλοι τηροῦντες τὴν παρρησίαν πιστεύωνται παρὰ τοῖς Ἀχαιοῖς, ἐπὰν προθῶνται τῇ πόλει βοηθεῖν, οἱ δ’ ἐχθροὶ καταπιόντες τὸ δέλεαρ ἢ συνηγορεῖν αὐτοῖς ἀναγκάζωνται ἢ σιωπῶντες μηδὲν δύνωνται βλάπτειν. ὅτι οὐχ ὅμοιόν ἐστιν ἐξ ἀκοῆς περὶ πραγμάτων διαλαμβάνειν καὶ γενόμενον αὐτόπτην, ἀλλὰ καὶ μεγάλα διαφέρει, πολὺ δέ τι συμβάλλεσθαι πέφυκεν ἑκάστοις ἡ κατὰ τὴν ἐνάργειαν πίστις.", "st": "20.12"}, {"sp": "HDR", "t": "Βιβλίον ΚΑʹ", "st": "21"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον συνέβη καὶ τὴν ἐκ τῆς Ῥώμης πρεσβείαν, ἣν ἀπέστειλαν οἱ Λακεδαιμόνιοι, παραγενέσθαι διεψευσμένην τῶν ἐλπίδων. ἐπρέσβευον μὲν γὰρ περὶ τῶν ὁμήρων καὶ τῶν κωμῶν· ἡ δὲ σύγκλητος περὶ μὲν τῶν κωμῶν ἔφησεν ἐντολὰς δώσειν τοῖς παρ’ αὐτῶν ἀποστελλομένοις πρέσβεσιν, περὶ δὲ τῶν ὁμήρων ἔτι βουλεύσασθαι θέλειν. περὶ δὲ τῶν φυγάδων τῶν ἀρχαίων θαυμάζειν ἔφησαν, πῶς οὐ κατάγουσιν αὐτοὺς εἰς τὴν οἰκείαν, ἠλευθερωμένης τῆς Σπάρτης. —", "st": "21.1"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς αὐτοὺς καιροὺς ἡ σύγκλητος ἐχρημάτισε τοῖς παρὰ Φιλίππου πρεσβευταῖς· ἧκον γὰρ παρ’ αὐτοῦ πρέσβεις ἀπολογιζόμενοι τὴν εὔνοιαν καὶ προθυμίαν, ἣν παρέσχηται Ῥωμαίοις ὁ βασιλεὺς ἐν τῷ πρὸς Ἀντίοχον πολέμῳ. ὧν διακούσασα τὸν μὲν υἱὸν Δημήτριον ἀπέλυσε τῆς ὁμηρείας παραχρῆμα· ὁμοίως δὲ καὶ τῶν φόρων ἐπηγγείλατο παραλύσειν, διαφυλάξαντος αὐτοῦ τὴν πίστιν ἐν τοῖς ἐνεστῶσι καιροῖς. παραπλησίως δὲ καὶ τοὺς τῶν Λακεδαιμονίων ὁμήρους ἀφῆκε πλὴν Ἀρμένα τοῦ Νάβιδος υἱοῦ· τοῦτον δὲ μετὰ ταῦτα συνέβη νόσῳ μεταλλάξαι τὸν βίον.", "st": "21.2"}, {"sp": "N", "t": "ὅτι τοῖς Ῥωμαίοις τῆς κατὰ τὴν ναυμαχίαν νίκης ἄρτι προσηγγελμένης, πρῶτον μὲν τῷ δήμῳ παρήγγειλαν ἐλινύας ἄγειν ἡμέρας ἐννέα — τοῦτο δ’ ἔστιν σχολάζειν πανδημεὶ καὶ θύειν τοῖς θεοῖς χαριστήρια τῶν εὐτυχημάτων — μετὰ δὲ ταῦτα τοὺς παρὰ τῶν Αἰτωλῶν πρέσβεις καὶ τοὺς παρὰ τοῦ Μανίου προσῆγον τῇ συγκλήτῳ. γενομένων δὲ πλειόνων παρ’ ἀμφοῖν λόγων, ἔδοξε τῷ συνεδρίῳ δύο προτείνειν γνώμας τοῖς Αἰτωλοῖς, ἢ διδόναι τὴν ἐπιτροπὴν περὶ πάντων τῶν καθ’ αὑτοὺς ἢ χίλια τάλαντα παραχρῆμα δοῦναι καὶ τὸν αὐτὸν ἐχθρὸν καὶ φίλον νομίζειν Ῥωμαίοις. τῶν δ’ Αἰτωλῶν ἀξιούντων διασαφῆσαι ῥητῶς ἐπὶ τίσι δεῖ διδόναι τὴν ἐπιτροπήν, οὐ προσδέχεται τὴν διαστολὴν ἡ σύγκλητος. διὸ καὶ τούτοις γέγονε κατάμονος ὁ πόλεμος. —", "st": "21.3"}, {"sp": "N", "t": "ὅτι πολιορκουμένων τῶν Ἀμφισσέων ὑπὸ Μανίου τοῦ Ῥωμαίων στρατηγοῦ, κατὰ τὸν καιρὸν τοῦτον ὁ τῶν Ἀθηναίων δῆμος, πυνθανόμενος τήν τε τῶν Ἀμφισσέων ταλαιπωρίαν καὶ τὴν τοῦ Ποπλίου παρουσίαν, ἐξαπέστειλε πρεσβευτὰς τοὺς περὶ τὸν Ἐχέδημον, ἐντειλάμενος ἅμα μὲν ἀσπάσασθαι τοὺς περὶ τὸν Λεύκιον καὶ Πόπλιον, ἅμα δὲ καταπειράζειν τῆς πρὸς Αἰτωλοὺς διαλύσεως. ὧν παραγενομένων ἀσμένως ἀποδεξάμενος ὁ Πόπλιος ἐφιλανθρώπει τοὺς ἄνδρας, θεωρῶν ὅτι παρέξονται χρείαν αὐτῷ πρὸς τὰς προκειμένας ἐπιβολάς. ὁ γὰρ προειρημένος ἀνὴρ ἐβούλετο θέσθαι μὲν καλῶς τὰ κατὰ τοὺς Αἰτωλούς· εἰ δὲ μὴ συνυπακούοιεν, πάντως διειλήφει παραλιπὼν ταῦτα διαβαίνειν εἰς τὴν Ἀσίαν, σαφῶς γινώσκων διότι τὸ τέλος ἐστὶ τοῦ πολέμου καὶ τῆς ὅλης ἐπιβολῆς οὐκ ἐν τῷ χειρώσασθαι τὸ τῶν Αἰτωλῶν ἔθνος, ἀλλ’ ἐν τῷ νικήσαντας τὸν Ἀντίοχον κρατῆσαι τῆς Ἀσίας. διόπερ ἅμα τῷ μνησθῆναι τοὺς Ἀθηναίους ὑπὲρ τῆς διαλύσεως, ἑτοίμως προσδεξάμενος τοὺς λόγους ἐκέλευσε παραπλησίως πειράζειν αὐτοὺς καὶ τῶν Αἰτωλῶν. οἱ δὲ περὶ τὸν Ἐχέδημον, προδιαπεμψάμενοι καὶ μετὰ ταῦτα πορευθέντες εἰς τὴν Ὑπάταν αὐτοί, διελέγοντο περὶ τῆς διαλύσεως τοῖς ἄρχουσι τῶν Αἰτωλῶν. ἑτοίμως δὲ κἀκείνων συνυπακουόντων κατεστάθησαν οἱ συμμίξοντες τοῖς Ῥωμαίοις· οἳ καὶ παραγενόμενοι πρὸς τοὺς περὶ τὸν Πόπλιον, καταλαβόντες αὐτοὺς στρατοπεδεύοντας ἐν ἑξήκοντα σταδίοις ἀπὸ τῆς Ἀμφίσσης, πολλοὺς διετίθεντο λόγους, ἀναμιμνήσκοντες τῶν γεγονότων σφίσι φιλανθρώπων πρὸς Ῥωμαίους. ἔτι δὲ πρᾳότερον καὶ φιλανθρωπότερον ὁμιλήσαντος τοῦ Ποπλίου καὶ προφερομένου τάς τε κατὰ τὴν Ἰβηρίαν καὶ τὴν Λιβύην πράξεις καὶ διασαφοῦντος τίνα τρόπον κέχρηται τοῖς κατ’ ἐκείνους τοὺς τόπους αὐτῷ πιστεύσασιν καὶ τέλος οἰομένου δεῖν ἐγχειρίζειν σφᾶς αὑτῷ καὶ πιστεύειν, τὰς μὲν ἀρχὰς ἅπαντες οἱ παρόντες εὐέλπιδες ἐγενήθησαν, ὡς αὐτίκα μάλα τελεσιουργηθησομένης τῆς διαλύσεως· ἐπεὶ δέ, πυθομένων τῶν Αἰτωλῶν ἐπὶ τίσι δεῖ ποιεῖσθαι τὴν εἰρήνην, ὁ Λεύκιος διεσάφησεν διότι δυεῖν προκειμένων αὐτοῖς αἵρεσις ὑπάρχει — δεῖν γὰρ ἢ τὴν ἐπιτροπὴν διδόναι περὶ πάντων τῶν καθ’ αὑτοὺς ἢ χίλια τάλαντα παραχρῆμα καὶ τὸν αὐτὸν ἐχθρὸν αἱρεῖσθαι καὶ φίλον Ῥωμαίοις — ἐδυσχρήστησαν μὲν οἱ παρόντες τῶν Αἰτωλῶν ὡς ἔνι μάλιστα διὰ τὸ μὴ γίνεσθαι τὴν ἀπόφασιν ἀκόλουθον τῇ προγενομένῃ λαλιᾷ, πλὴν ἐπανοίσειν ἔφασαν ὑπὲρ τῶν ἐπιταττομένων τοῖς Αἰτωλοῖς.", "st": "21.4"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ἐπανῄεσαν βουλευσόμενοι περὶ τῶν προειρημένων· οἱ δὲ περὶ τὸν Ἐχέδημον συμμίξαντες τοῖς ἀποκλήτοις ἐβουλεύοντο περὶ τῶν προειρημένων. ἦν δὲ τῶν ἐπιταττομένων τὸ μὲν ἀδύνατον διὰ τὸ πλῆθος τῶν χρημάτων, τὸ δὲ φοβερὸν διὰ τὸ πρότερον αὐτοὺς ἀπατηθῆναι, καθ’ ὃν καιρὸν ἐπινεύσαντες ὑπὲρ τῆς ἐπιτροπῆς παρὰ μικρὸν εἰς τὴν ἅλυσιν ἐνέπεσον. διόπερ ἀπορούμενοι καὶ δυσχρηστούμενοι περὶ ταῦτα πάλιν ἐξέπεμπον τοὺς αὐτοὺς δεησομένους ἢ τῶν χρημάτων ἀφελεῖν, ἵνα δύνωνται τελεῖν, ἢ τῆς ἐπιτροπῆς ἐκτὸς ποιῆσαι τοὺς πολιτικοὺς ἄνδρας καὶ τὰς γυναῖκας. οἳ καὶ συμμίξαντες τοῖς περὶ τὸν Πόπλιον διεσάφουν τὰ δεδογμένα. τοῦ δὲ Λευκίου φήσαντος ἐπὶ τούτοις ἔχειν παρὰ τῆς συγκλήτου τὴν ἐξουσίαν, ἐφ’ οἷς ἀρτίως εἶπεν, οὗτοι μὲν αὖθις ἐπανῆλθον, οἱ δὲ περὶ τὸν Ἐχέδημον ἐπακολουθήσαντες εἰς τὴν Ὑπάταν συνεβούλευσαν τοῖς Αἰτωλοῖς, ἐπεὶ τὰ τῆς διαλύσεως ἐμποδίζοιτο κατὰ τὸ παρόν, ἀνοχὰς αἰτησαμένους καὶ τῶν ἐνεστώτων κακῶν ὑπέρθεσιν ποιησαμένους πρεσβεύειν πρὸς τὴν σύγκλητον, κἂν μὲν ἐπιτυγχάνωσι περὶ τῶν ἀξιουμένων· εἰ δὲ μή, τοῖς καιροῖς ἐφεδρεύειν. χείρω μὲν γὰρ ἀδύνατον γενέσθαι τῶν ὑποκειμένων τὰ περὶ σφᾶς, βελτίω γε μὴν οὐκ ἀδύνατον διὰ πολλὰς αἰτίας. φανέντων δὲ καλῶς λέγειν τῶν περὶ τὸν Ἐχέδημον, ἔδοξε πρεσβεύειν τοῖς Αἰτωλοῖς ὑπὲρ τῶν ἀνοχῶν. ἀφικόμενοι δὲ πρὸς τὸν Λεύκιον ἐδέοντο συγχωρηθῆναι σφίσι κατὰ τὸ παρὸν ἑξαμήνους ἀνοχάς, ἵνα πρεσβεύσωσι πρὸς τὴν σύγκλητον. ὁ δὲ Πόπλιος, πάλαι πρὸς τὰς κατὰ τὴν Ἀσίαν πράξεις παρωρμημένος, ταχέως ἔπεισε τὸν ἀδελφὸν ὑπακοῦσαι τοῖς ἀξιουμένοις. γραφεισῶν δὲ τῶν ὁμολογιῶν, ὁ μὲν Μάνιος, λύσας τὴν πολιορκίαν καὶ παραδοὺς ἅπαν τὸ στράτευμα καὶ τὰς χορηγίας τοῖς περὶ τὸν Λεύκιον, εὐθέως ἀπηλλάττετο μετὰ τῶν χιλιάρχων εἰς τὴν Ῥώμην.", "st": "21.5"}, {"sp": "N", "t": "οἱ δὲ Φωκαιεῖς, τὰ μὲν ὑπὸ τῶν ἀπολειφθέντων Ῥωμαίων ἐν ταῖς ναυσὶν ἐπισταθμευόμενοι, τὰ δὲ τὰς ἐπιταγὰς δυσχερῶς φέροντες, ἐστασίαζον. — ὅτι κατὰ τοὺς αὐτοὺς χρόνους οἱ τῶν Φωκαιέων ἄρχοντες, δεδιότες τάς τε τῶν πολλῶν ὁρμὰς διὰ τὴν σιτοδείαν καὶ τὴν τῶν Ἀντιοχιστῶν φιλοτιμίαν, ἐξέπεμψαν πρεσβευτὰς πρὸς Σέλευκον, ὄντα πρὸς τοῖς ὅροις τῆς χώρας αὐτῶν, ἀξιοῦντες μὴ πελάζειν τῆς πόλεως, ὅτι πρόκειται σφίσι τὴν ἡσυχίαν ἄγειν καὶ καραδοκεῖν τὴν τῶν ὅλων κρίσιν, μετὰ δὲ ταῦτα πειθαρχεῖν τοῖς εἰρημένοις. ἦσαν δὲ τῶν πρεσβευτῶν ἴδιοι μὲν τοῦ Σελεύκου καὶ ταύτης τῆς ὑποθέσεως Ἀρίσταρχος καὶ Κάσσανδρος καὶ Ῥόδων, ἐναντίοι δὲ καὶ πρὸς Ῥωμαίους ἀπονενευκότες Ἡγίας καὶ Γελίας. ὧν συμμιξάντων ὁ Σέλευκος εὐθέως τοὺς μὲν περὶ τὸν Ἀρίσταρχον ἀνὰ χεῖρας εἶχε, τοὺς δὲ περὶ τὸν Ἡγίαν παρεώρα. πυθόμενος δὲ τὴν ὁρμὴν τῶν πολλῶν καὶ τὴν σπάνιν τοῦ σίτου, παρεὶς τὸν χρηματισμὸν καὶ τὴν ἔντευξιν τῶν παραγεγονότων προῆγε πρὸς τὴν πόλιν. — ἐξελθόντες μὲν Γάλλοι δύο μετὰ τύπων καὶ προστηθιδίων ἐδέοντο μηδὲν ἀνήκεστον βουλεύεσθαι περὶ τῆς πόλεως. —", "st": "21.6"}, {"sp": "N", "t": "πυρφόρος, ᾧ ἐχρήσατο Παυσίστρατος ὁ τῶν Ῥοδίων ναύαρχος. ἦν δὲ κημός· ἐξ ἑκατέρου δὲ τοῦ μέρους τῆς πρώρρας ἀγκύλαι δύο παρέκειντο παρὰ τὴν ἐντὸς ἐπιφάνειαν τῶν τοίχων, εἰς ἃς ἐνηρμόζοντο κοντοὶ προτείνοντες τοῖς κέρασιν εἰς θάλατταν. ἐπὶ δὲ τὸ τούτων ἄκρον ὁ κημὸς ἁλύσει σιδηρᾷ προσήρτητο πλήρης πυρός, ὥστε κατὰ τὰς ἐμβολὰς καὶ παραβολὰς εἰς μὲν τὴν πολεμίαν ναῦν ἐκτινάττεσθαι πῦρ, ἀπὸ δὲ τῆς οἰκείας πολὺν ἀφεστάναι τόπον διὰ τὴν ἔγκλισιν. — ὅτι Παμφιλίδας ὁ τῶν Ῥοδίων ναύαρχος ἐδόκει πρὸς πάντας τοὺς καιροὺς εὐαρμοστότερος εἶναι τοῦ Παυσιστράτου διὰ τὸ βαθύτερος τῇ φύσει καὶ στασιμώτερος μᾶλλον ἢ τολμηρότερος ὑπάρχειν. ἀγαθοὶ γὰρ οἱ πολλοὶ τῶν ἀνθρώπων οὐκ ἐκ τῶν κατὰ λόγον, ἀλλ’ ἐκ τῶν συμβαινόντων ποιεῖσθαι τὰς διαλήψεις. ἄρτι γὰρ δι’ αὐτὸ τοῦτο προκεχειρισμένοι τὸν Παυσίστρατον, διὰ τὸ πρᾶξιν ἔχειν τινὰ καὶ τόλμαν, παραχρῆμα μετέπιπτον εἰς τἀναντία ταῖς γνώμαις διὰ τὴν περιπέτειαν. —", "st": "21.7"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον εἰς τὴν Σάμον προσέπεσε γράμματα τοῖς περὶ τὸν Λεύκιον καὶ τὸν Εὐμένη παρά τε τοῦ Λευκίου τοῦ τὴν ὕπατον ἀρχὴν ἔχοντος καὶ παρὰ Ποπλίου Σκιπίωνος, δηλοῦντα τὰς πρὸς τοὺς Αἰτωλοὺς γεγενημένας συνθήκας ὑπὲρ τῶν ἀνοχῶν καὶ τὴν ἐπὶ τὸν Ἑλλήσποντον πορείαν τῶν πεζικῶν στρατοπέδων. ὁμοίως δὲ καὶ τοῖς περὶ τὸν Ἀντίοχον καὶ Σέλευκον ταῦτα διεσαφεῖτο παρὰ τῶν Αἰτωλῶν. —", "st": "21.8"}, {"sp": "N", "t": "ὅτι καὶ κατὰ τὴν Ἑλλάδα, πρεσβείας παραγενομένης εἰς Ἀχαΐαν παρ’ Εὐμένους τοῦ βασιλέως ὑπὲρ συμμαχίας, ἁθροισθέντες εἰς ἐκκλησίαν οἱ πολλοὶ τῶν Ἀχαιῶν τήν τε συμμαχίαν ἐπεκύρωσαν καὶ νεανίσκους ἐξαπέστειλαν, πεζοὺς μὲν χιλίους ἱππεῖς δ’ ἑκατόν, ὧν ἡγεῖτο Διοφάνης ὁ Μεγαλοπολίτης. —", "st": "21.9"}, {"sp": "N", "t": "ὅτι Διοφάνης ὁ Μεγαλοπολίτης μεγάλην ἕξιν εἶχεν ἐν τοῖς πολεμικοῖς διὰ τὸ πολυχρονίου γεγονότος τοῦ πρὸς Νάβιν πολέμου τοῖς Μεγαλοπολίταις ἀστυγείτονος πάντα συνεχῶς τὸν χρόνον ὑπὸ τὸν Φιλοποίμενα τεταγμένος τριβὴν ἐσχηκέναι τῶν κατὰ πόλεμον ἔργων ἀληθινήν. χωρίς τε τούτων κατὰ τὴν ἐπιφάνειαν καὶ κατὰ τὴν σωματικὴν χρείαν ἦν ὁ προειρημένος ἀνὴρ δυνατὸς καὶ καταπληκτικός. τὸ δὲ κυριώτατον, πρὸς πόλεμον ὑπῆρχεν ἀνὴρ ἀγαθὸς καὶ τοῖς ὅπλοις ἐχρῆτο διαφερόντως. —", "st": "21.9"}, {"sp": "N", "t": "ὅτι Ἀντίοχος ὁ βασιλεὺς εἰς τὸν Πέργαμον ἐμβαλών, πυθόμενος δὲ τὴν παρουσίαν Εὐμένους τοῦ βασιλέως καὶ θεωρῶν οὐ μόνον τὰς ναυτικάς, ἀλλὰ καὶ τὰς πεζικὰς δυνάμεις ἐπ’ αὐτὸν παραγινομένας, ἐβουλεύετο λόγους ποιήσασθαι περὶ διαλύσεως ὁμοῦ πρός τε Ῥωμαίους καὶ τὸν Εὐμένη καὶ τοὺς Ῥοδίους. ἐξάρας οὖν ἅπαντι τῷ στρατεύματι παρῆν πρὸς τὴν Ἐλαίαν καὶ λαβὼν λόφον τινὰ καταντικρὺ τῆς πόλεως τὸ μὲν πεζικὸν ἐπὶ τούτου κατέστησε, τοὺς δ’ ἱππεῖς παρ’ αὐτὴν τὴν πόλιν παρενέβαλε, πλείους ὄντας ἑξακισχιλίων. αὐτὸς δὲ μεταξὺ τούτων γενόμενος διεπέμπετο πρὸς τοὺς περὶ τὸν Λεύκιον εἰς τὴν πόλιν ὑπὲρ διαλύσεων. ὁ δὲ στρατηγὸς ὁ τῶν Ῥωμαίων συναγαγὼν τούς τε Ῥοδίους καὶ τὸν Εὐμένην ἠξίου λέγειν περὶ τῶν ἐνεστώτων τὸ φαινόμενον. οἱ μὲν οὖν περὶ τὸν Εὔδαμον καὶ Παμφιλίδαν οὐκ ἀλλότριοι τῆς διαλύσεως ἦσαν· ὁ δὲ βασιλεὺς οὔτ’ εὐσχήμονα τὴν διάλυσιν οὔτε δυνατὴν ἔφησε κατὰ τὸ παρὸν εἶναι. \"εὐσχήμονα γάρ\" ἔφη \"πῶς οἷόν τε γίνεσθαι τὴν ἔκβασιν, ἐὰν τειχήρεις ὄντες ποιώμεθα τὰς διαλύσεις; \" καὶ μὴν οὐδὲ δυνατὴν ἔφησε κατὰ τὸ παρόν· \"πῶς γὰρ ἐνδέχεται, μὴ προσδεξαμένους ὕπατον, ἄνευ τῆς ἐκείνου γνώμης βεβαιῶσαι τὰς ὁμολογηθείσας συνθήκας; χωρίς τε τούτων, ἐὰν ὅλως γένηταί τι σημεῖον ὁμολογίας πρὸς Ἀντίοχον, οὔτε τὰς ναυτικὰς δυνάμεις δυνατὸν ἐπανελθεῖν δήπουθεν εἰς τὴν ἰδίαν οὔτε τὰς πεζικάς, ἐὰν μὴ πρότερον ὅ τε δῆμος ἥ τε σύγκλητος ἐπικυρώσῃ τὰ δοχθέντα. λείπεται δὴ καραδοκοῦντας τὴν ἐκείνων ἀπόφασιν παραχειμάζειν ἐνθάδε καὶ πράττειν μὲν μηδέν, ἐκδαπανᾶν δὲ τὰς τῶν ἰδίων συμμάχων χορηγίας καὶ παρασκευάς· ἔπειτ’, ἂν μὴ σφίσι παρῇ τῇ συγκλήτῳ διαλύεσθαι, καινοποιεῖν πάλιν ἀπ’ ἀρχῆς τὸν πόλεμον, παρέντας τοὺς ἐνεστῶτας καιρούς, ἐν οἷς δυνάμεθα θεῶν βουλομένων πέρας ἐπιθεῖναι τοῖς ὅλοις. \" ὁ μὲν οὖν Εὐμένης ταῦτ’ εἶπεν· ὁ δὲ Λεύκιος ἀποδεξάμενος τὴν συμβουλίαν, ἀπεκρίθη τοῖς περὶ τὸν Ἀντίοχον ὅτι πρὸ τοῦ τὸν ἀνθύπατον ἐλθεῖν οὐκ ἐνδέχεται γενέσθαι τὰς διαλύσεις. ὧν ἀκούσαντες οἱ περὶ τὸν Ἀντίοχον παραυτίκα μὲν ἐδῄουν τὴν τῶν Ἐλαϊτῶν χώραν· ἑξῆς δὲ τούτοις Σέλευκος μὲν ἐπὶ τούτων ἔμεινε τῶν τόπων, Ἀντίοχος δὲ κατὰ τὸ συνεχὲς ἐπιπορευόμενος ἐνέβαλεν εἰς τὸ Θήβης καλούμενον πεδίον, καὶ παραβεβληκὼς εἰς χώραν εὐδαίμονα καὶ γέμουσαν ἀγαθῶν ἐπλήρου τὴν στρατιὰν παντοδαπῆς λείας. —", "st": "21.10"}, {"sp": "N", "t": "ὅτι Ἀντίοχος ὁ βασιλεὺς παραγενόμενος εἰς τὰς Σάρδεις ἀπὸ τῆς προρρηθείσης στρατείας διεπέμπετο συνεχῶς πρὸς Προυσίαν, παρακαλῶν αὐτὸν εἰς τὴν σφετέραν συμμαχίαν. ὁ δὲ Προυσίας κατὰ μὲν τοὺς ἀνώτερον χρόνους οὐκ ἀλλότριος ἦν τοῦ κοινωνεῖν τοῖς περὶ τὸν Ἀντίοχον· πάνυ γὰρ ἐδεδίει τοὺς Ῥωμαίους, μὴ ποιῶνται τὴν εἰς Ἀσίαν διάβασιν ἐπὶ καταλύσει πάντων τῶν δυναστῶν. παραγενομένης δ’ ἐπιστολῆς αὐτῷ παρά τε Λευκίου καὶ Ποπλίου τῶν ἀδελφῶν, κομισάμενος ταύτην καὶ διαναγνοὺς ἐπὶ ποσὸν ἔστη τῇ διανοίᾳ καὶ προείδετο τὸ μέλλον ἐνδεχομένως, ἅτε τῶν περὶ τὸν Πόπλιον ἐναργέσι κεχρημένων καὶ πολλοῖς μαρτυρίοις πρὸς πίστιν διὰ τῶν ἐγγράπτων. οὐ γὰρ μόνον ὑπὲρ τῆς ἰδίας προαιρέσεως ἔφερον ἀπολογισμούς, ἀλλὰ καὶ περὶ τῆς κοινῆς ἁπάντων Ῥωμαίων, δι’ ὧν παρεδείκνυον οὐχ οἷον ἀφῃρημένοι τινὸς τῶν ἐξ ἀρχῆς βασιλέων τὰς δυναστείας, ἀλλὰ τινὰς μὲν καὶ προσκατεσκευακότες αὐτοὶ δυνάστας, ἐνίους δ’ ηὐξηκότες καὶ πολλαπλασίους αὐτῶν τὰς ἀρχὰς πεποιηκότες. ὧν κατὰ μὲν τὴν Ἰβηρίαν Ἀνδοβάλην καὶ Κολίχαντα προεφέροντο, κατὰ δὲ τὴν Λιβύην Μασαννάσαν, ἐν δὲ τοῖς κατὰ τὴν Ἰλλυρίδα τόποις Πλευρᾶτον· οὓς ἅπαντας ἔφασαν ἐξ ἐλαφρῶν καὶ τῶν τυχόντων δυναστῶν πεποιηκέναι βασιλεῖς ὁμολογουμένως. ὁμοίως κατὰ τὴν Ἑλλάδα Φίλιππον καὶ Νάβιν, ὧν Φίλιππον μὲν καταπολεμήσαντες καὶ συγκλείσαντες εἰς ὅμηρα καὶ φόρους, βραχεῖαν αὐτοῦ νῦν λαβόντες ἀπόδειξιν εὐνοίας ἀποκαθεστακέναι μὲν αὐτῷ τὸν υἱὸν καὶ τοὺς ἅμα τούτῳ συνομηρεύοντας νεανίσκους, ἀπολελυκέναι δὲ τῶν φόρων, πολλὰς δὲ τῶν πόλεων ἀποδεδωκέναι τῶν ἁλουσῶν κατὰ πόλεμον· Νάβιν δὲ δυνηθέντες ἄρδην ἐπανελέσθαι, τοῦτο μὲν οὐ ποιῆσαι, φείσασθαι δ’ αὐτοῦ, καίπερ ὄντος τυράννου, λαβόντες πίστεις τὰς εἰθισμένας. εἰς ἃ βλέποντα παρεκάλουν τὸν Προυσίαν διὰ τῆς ἐπιστολῆς μὴ δεδιέναι περὶ τῆς ἀρχῆς, θαρροῦντα δ’ αἱρεῖσθαι τὰ Ῥωμαίων· ἔσεσθαι γὰρ ἀμεταμέλητον αὐτῷ τὴν τοιαύτην προαίρεσιν. ὧν ὁ Προυσίας διακούσας ἐπ’ ἄλλης ἐγένετο γνώμης. ὡς δὲ καὶ παρεγενήθησαν πρὸς αὐτὸν πρέσβεις οἱ περὶ τὸν Γάιον Λίβιον, τελέως ἀπέστη τῶν κατὰ τὸν Ἀντίοχον ἐλπίδων, συμμίξας τοῖς προειρημένοις ἀνδράσιν. Ἀντίοχος δὲ ταύτης ἀποπεσὼν τῆς ἐλπίδος παρῆν εἰς Ἔφεσον καὶ συλλογιζόμενος ὅτι μόνως ἂν οὕτω δύναιτο κωλῦσαι τὴν τῶν πεζικῶν στρατοπέδων διάβασιν καὶ καθόλου τὸν πόλεμον ἀπὸ τῆς Ἀσίας ἀποτρίβεσθαι βεβαίως κρατοίη τῆς θαλάττης, προέθετο ναυμαχεῖν καὶ κρίνειν τὰ πράγματα διὰ τῶν κατὰ θάλατταν κινδύνων. —", "st": "21.11"}, {"sp": "N", "t": "Πολύβιος· οἱ δὲ πειραταὶ θεασάμενοι τὸν ἐπίπλουν τῶν Ῥωμαϊκῶν πλοίων, ἐκ μεταβολῆς ἐποιοῦντο τὴν ἀναχώρησιν. —", "st": "21.12"}, {"sp": "N", "t": "ὅτι ὁ Ἀντίοχος μετὰ τὴν κατὰ τὴν ναυμαχίαν γενομένην ἧτταν ἐν ταῖς Σάρδεσιν παριεὶς τοὺς καιροὺς καὶ καταμέλλων ἐν τοῖς ὅλοις, ἅμα τῷ πυθέσθαι τῶν πολεμίων τὴν διάβασιν συντριβεὶς τῇ διανοίᾳ καὶ δυσελπιστήσας ἔκρινεν διαπέμπεσθαι πρὸς τοὺς περὶ τὸν Λεύκιον καὶ Πόπλιον ὑπὲρ διαλύσεων. προχειρισάμενος οὖν Ἡρακλείδην τὸν Βυζάντιον ἐξέπεμψε, δοὺς ἐντολὰς ὅτι παραχωρεῖ τῆς τε τῶν Λαμψακηνῶν καὶ Σμυρναίων, ἔτι δὲ τῆς Ἀλεξανδρέων πόλεως, ἐξ ὧν ὁ πόλεμος ἔλαβε τὰς ἀρχάς· ὁμοίως δὲ κἄν τινας ἑτέρας ὑφαιρεῖσθαι βούλωνται τῶν κατὰ τὴν Αἰολίδα καὶ τὴν Ἰωνίαν, ὅσαι τἀκείνων ᾕρηνται κατὰ τὸν ἐνεστῶτα πόλεμον. πρὸς δὲ τούτοις ὅτι τὴν ἡμίσειαν δώσει τῆς γεγενημένης σφίσι δαπάνης εἰς τὴν πρὸς αὐτὸν διαφοράν. ταύτας μὲν οὖν ὁ πεμπόμενος εἶχε τὰς ἐντολὰς πρὸς τὴν κατὰ κοινὸν ἔντευξιν, ἰδίᾳ δὲ πρὸς τὸν Πόπλιον ἑτέρας, ὑπὲρ ὧν τὰ κατὰ μέρος ἐν τοῖς ἑξῆς δηλώσομεν. ἀφικόμενος δ’ εἰς τὸν Ἑλλήσποντον ὁ προειρημένος πρεσβευτὴς καὶ καταλαβὼν τοὺς Ῥωμαίους μένοντας ἐπὶ τῆς στρατοπεδείας, οὗ πρῶτον κατεσκήνωσαν ἀπὸ τῆς διαβάσεως, τὰς μὲν ἀρχὰς ἥσθη, νομίζων αὑτῷ συνεργὸν εἶναι πρὸς τὴν ἔντευξιν τὸ μένειν ἐπὶ τῶν ὑποκειμένων καὶ πρὸς μηδὲν ὡρμηκέναι τῶν ἑξῆς τοὺς ὑπεναντίους, πυθόμενος δὲ τὸν Πόπλιον ἔτι μένειν ἐν τῷ πέραν ἐδυσχρήστησε διὰ τὸ τὴν πλείστην ῥοπὴν κεῖσθαι τῶν πραγμάτων ἐν τῇ ’κείνου προαιρέσει. αἴτιον δ’ ἦν καὶ τοῦ μένειν τὸ στρατόπεδον ἐπὶ τῆς πρώτης παρεμβολῆς καὶ τοῦ κεχωρίσθαι τὸν Πόπλιον ἀπὸ τῶν δυνάμεων τὸ σάλιον εἶναι τὸν προειρημένον ἄνδρα. τοῦτο δ’ ἔστιν, καθάπερ ἡμῖν ἐν τοῖς περὶ τῆς πολιτείας εἴρηται, τῶν τριῶν ἓν σύστημα, δι’ ὧν συμβαίνει τὰς ἐπιφανεστάτας θυσίας ἐν τῇ Ῥώμῃ συντελεῖσθαι τοῖς θεοῖς· τριακονθήμερον μὴ μεταβαίνειν κατὰ τὸν καιρὸν τῆς θυσίας, ἐν ᾗ ποτ’ ἂν χώρᾳ καταληφθῶσιν [οἱ σάλιοι οὗτοι]. ὃ καὶ τότε συνέβη γενέσθαι Ποπλίῳ· τῆς γὰρ δυνάμεως μελλούσης περαιοῦσθαι κατέλαβεν αὐτὸν οὗτος ὁ χρόνος, ὥστε μὴ δύνασθαι μεταβαλεῖν τὴν χώραν. διὸ συνέβη τόν τε Σκιπίωνα χωρισθῆναι τῶν στρατοπέδων καὶ μεῖναι κατὰ τὴν Εὐρώπην, τὰς δὲ δυνάμεις περαιωθείσας μένειν ἐπὶ τῶν ὑποκειμένων καὶ μὴ δύνασθαι πράττειν τῶν ἑξῆς μηθέν, προσαναδεχομένας τὸν προειρημένον ἄνδρα.", "st": "21.13"}, {"sp": "N", "t": "ὁ δ’ Ἡρακλείδης, μετά τινας ἡμέρας παραγενομένου τοῦ Ποπλίου, κληθεὶς πρὸς τὸ συνέδριον εἰς ἔντευξιν διελέγετο περὶ ὧν εἶχε τὰς ἐντολάς, φάσκων τῆς τε τῶν Λαμψακηνῶν καὶ Σμυρναίων, ἔτι δὲ τῆς τῶν Ἀλεξανδρέων πόλεως ἐκχωρεῖν τὸν Ἀντίοχον, ὁμοίως δὲ καὶ τῶν κατὰ τὴν Αἰολίδα καὶ τὴν Ἰωνίαν, ὅσαι τυγχάνουσιν ᾑρημέναι τὰ Ῥωμαίων· πρὸς δὲ τούτοις τὴν ἡμίσειαν ἀναδέχεσθαι τῆς γεγενημένης αὐτοῖς δαπάνης εἰς τὸν ἐνεστῶτα πόλεμον. πολλὰ δὲ καὶ ἕτερα πρὸς ταύτην τὴν ὑπόθεσιν διελέχθη, παρακαλῶν τοὺς Ῥωμαίους μήτε τὴν τύχην λίαν ἐξελέγχειν ἀνθρώπους ὑπάρχοντας, μήτε τὸ μέγεθος τῆς αὑτῶν ἐξουσίας ἀόριστον ποιεῖν, ἀλλὰ περιγράφειν, μάλιστα μὲν τοῖς τῆς Εὐρώπης ὅροις· καὶ γὰρ ταύτην μεγάλην ὑπάρχειν καὶ παράδοξον διὰ τὸ μηδένα καθῖχθαι τῶν προγεγονότων αὐτῆς· εἰ δὲ πάντως καὶ τῆς Ἀσίας βούλονταί τινα προσεπιδράττεσθαι, διορίσαι ταῦτα· πρὸς πᾶν γὰρ τὸ δυνατὸν προσελεύσεσθαι τὸν βασιλέα. ῥηθέντων δὲ τούτων, ἔδοξε τῷ συνεδρίῳ τὸν στρατηγὸν ἀποκριθῆναι διότι τῆς μὲν δαπάνης οὐ τὴν ἡμίσειαν, ἀλλὰ πᾶσαν δίκαιόν ἐστιν Ἀντίοχον ἀποδοῦναι· φῦναι γὰρ τὸν πόλεμον ἐξ ἀρχῆς οὐ δι’ αὑτούς, ἀλλὰ δι’ ἐκεῖνον· τῶν δὲ πόλεων μὴ τὰς κατὰ τὴν Αἰολίδα καὶ τὴν Ἰωνίαν μόνον ἐλευθεροῦν, ἀλλὰ πάσης τῆς ἐπὶ τάδε τοῦ Ταύρου δυναστείας ἐκχωρεῖν. ὁ μὲν οὖν πρεσβευτὴς ταῦτ’ ἀκούσας παρὰ τοῦ συνεδρίου, διὰ τὸ πολὺ τῶν ἀξιουμένων τὰς ἐπιταγὰς ὑπεραίρειν οὐδένα λόγον ποιησάμενος, τῆς μὲν κοινῆς ἐντεύξεως ἀπέστη, τὸν δὲ Πόπλιον ἐθεράπευσε φιλοτίμως.", "st": "21.14"}, {"sp": "N", "t": "λαβὼν δὲ καιρὸν ἁρμόζοντα διελέγετο περὶ ὧν εἶχε τὰς ἐντολάς. αὗται δ’ ἦσαν διότι πρῶτον μὲν χωρὶς λύτρων ὁ βασιλεὺς αὐτῷ τὸν υἱὸν ἀποδώσει συνέβαινε γὰρ ἐν ἀρχαῖς τοῦ πολέμου τὸν υἱὸν τὸν τοῦ Σκιπίωνος γεγονέναι τοῖς περὶ Ἀντίχον ὑποχείριον· δεύτερον δὲ διότι καὶ κατὰ τὸ παρὸν ἕτοιμός ἐστιν ὁ βασιλεὺς ὅσον ἂν ἀποδείξῃ διδόναι πλῆθος χρημάτων καὶ μετὰ ταῦτα κοινὴν ποιεῖν τὴν ἐκ τῆς βασιλείας χορηγίαν, ἐὰν συνεργήσῃ ταῖς ὑπὸ τοῦ βασιλέως προτεινομέναις διαλύσεσιν. ὁ δὲ Πόπλιος τὴν μὲν κατὰ τὸν υἱὸν ἐπαγγελίαν ἔφη δέχεσθαι καὶ μεγάλην χάριν ἕξειν ἐπὶ τούτοις, ἐὰν βεβαιώσῃ τὴν ὑπόσχεσιν· περὶ δὲ τῶν ἄλλων ἀγνοεῖν αὐτὸν ἔφη καὶ παραπαίειν ὁλοσχερῶς τοῦ σφετέρου συμφέροντος οὐ μόνον κατὰ τὴν πρὸς αὑτὸν ἔντευξιν, ἀλλὰ καὶ κατὰ τὴν πρὸς τὸ συνέδριον. εἰ μὲν γὰρ ἔτι Λυσιμαχείας καὶ τῆς εἰς τὴν Χερρόνησον εἰσόδου κύριος ὑπάρχων ταῦτα προύτεινε, ταχέως ἂν αὐτὸν ἐπιτυχεῖν. ὁμοίως, εἰ καὶ τούτων ἐκχωρήσας παραγεγόνει πρὸς τὸν Ἑλλήσποντον μετὰ τῆς δυνάμεως καὶ δῆλος ὢν ὅτι κωλύσει τὴν διάβασιν ἡμῶν ἐπρέσβευε περὶ τῶν αὐτῶν τούτων, ἦν ἂν οὕτως αὐτὸν ἐφικέσθαι τῶν ἀξιουμένων. ὅτε δ’ ἐάσας ἐπιβῆναι τῆς Ἀσίας τὰς ἡμετέρας δυνάμεις καὶ προσδεξάμενος οὐ μόνον τὸν χαλινόν, ἀλλὰ καὶ τὸν ἀναβάτην παραγίνεται πρεσβεύων περὶ διαλύσεων ἴσων, εἰκότως αὐτὸν ἀποτυγχάνειν καὶ διεψεῦσθαι τῶν ἐλπίδων. διόπερ αὐτῷ παρῄνει βέλτιον βουλεύεσθαι περὶ τῶν ἐνεστώτων καὶ βλέπειν τοὺς καιροὺς ἀληθινῶς. ἀντὶ δὲ τῆς κατὰ τὸν υἱὸν ἐπαγγελίας ὑπισχνεῖτο δώσειν αὐτῷ συμβουλίαν ἀξίαν τῆς προτεινομένης χάριτος· παρεκάλει γὰρ αὐτὸν εἰς πᾶν συγκαταβαίνειν, μάχεσθαι δὲ κατὰ μηδένα τρόπον Ῥωμαίοις. ὁ μὲν οὖν Ἡρακλείδης ταῦτ’ ἀκούσας ἐπανῆλθε καὶ συμμίξας διεσάφει τῷ βασιλεῖ τὰ κατὰ μέρος· Ἀντίοχος δὲ νομίσας οὐδὲν ἂν βαρύτερον αὑτῷ γενέσθαι πρόσταγμα τῶν νῦν ἐπιταττομένων, εἰ λειφθείη μαχόμενος, τῆς μὲν περὶ τὰς διαλύσεις ἀσχολίας ἀπέστη, τὰ δὲ πρὸς ἀγῶνα πάντα καὶ πανταχόθεν ἡτοίμαζεν. —", "st": "21.15"}, {"sp": "N", "t": "ὅτι μετὰ τὴν νίκην οἱ Ῥωμαῖοι τὴν αὑτῶν πρὸς Ἀντίοχον παρειληφότες καὶ τὰς Σάρδεις καὶ τὰς ἀκροπόλεις ἄρτι ἧκε Μουσαῖος ἐπικηρυκευόμενος παρ’ Ἀντιόχου. τῶν δὲ περὶ τὸν Πόπλιον φιλανθρώπως προσδεξαμένων αὐτόν, ἔφη βούλεσθαι τὸν Ἀντίοχον ἐξαποσταλῆναι πρεσβευτὰς τοὺς διαλεχθησομένους ὑπὲρ τῶν ὅλων. διόπερ ἀσφάλειαν ἠξίου δοθῆναι τοῖς παραγινομένοις. τῶν δὲ συγχωρησάντων οὗτος μὲν ἐπανῆλθεν, μετὰ δέ τινας ἡμέρας ἧκον πρέσβεις παρὰ τοῦ βασιλέως Ἀντιόχου Ζεῦξις ὁ πρότερον ὑπάρχων Λυδίας σατράπης καὶ Ἀντίπατρος ἀδελφιδοῦς. οὗτοι δὲ πρῶτον μὲν ἔσπευδον ἐντυχεῖν Εὐμένει τῷ βασιλεῖ, διευλαβούμενοι μὴ διὰ τὴν προγεγενημένην παρατριβὴν φιλοτιμότερος ᾖ πρὸς τὸ βλάπτειν αὐτούς. εὑρόντες δὲ παρὰ τὴν προσδοκίαν μέτριον αὐτὸν καὶ πρᾷον, εὐθέως ἐγίνοντο περὶ τὴν κοινὴν ἔντευξιν. κληθέντες δ’ εἰς τὸ συνέδριον πολλὰ μὲν καὶ ἕτερα διελέχθησαν, παρακαλοῦντες πρᾴως χρήσασθαι καὶ μεγαλοψύχως τοῖς εὐτυχήμασι, φάσκοντες οὐχ οὕτως Ἀντιόχῳ τοῦτο συμφέρειν ὡς αὐτοῖς Ῥωμαίοις, ἐπείπερ ἡ τύχη παρέδωκεν αὐτοῖς τὴν τῆς οἰκουμένης ἀρχὴν καὶ δυναστείαν· τὸ δὲ συνέχον ἠρώτων τί δεῖ ποιήσαντας τυχεῖν τῆς εἰρήνης καὶ τῆς φιλίας τῆς πρὸς Ῥωμαίους. οἱ δ’ ἐν τῷ συνεδρίῳ πρότερον ἤδη συνηδρευκότες καὶ βεβουλευμένοι περὶ τούτων, τότ’ ἐκέλευον διασαφεῖν τὰ δεδογμένα τὸν Πόπλιον.", "st": "21.16"}, {"sp": "N", "t": "ὁ δὲ προειρημένος ἀνὴρ οὔτε νικήσαντας ἔφη Ῥωμαίους οὐδέποτε γενέσθαι βαρυτέρους, διὸ καὶ νῦν αὐτοῖς τὴν αὐτὴν ἀπόκρισιν δοθήσεσθαι παρὰ Ῥωμαίων, ἣν καὶ πρότερον ἔλαβον, ὅτε πρὸ τῆς μάχης παρεγενήθησαν ἐπὶ τὸν Ἑλλήσποντον. δεῖν γὰρ αὐτοὺς ἔκ τε τῆς Εὐρώπης ἐκχωρεῖν καὶ τῆς Ἀσίας τῆς ἐπὶ τάδε τοῦ Ταύρου πάσης. πρὸς δὲ τούτοις Εὐβοϊκὰ τάλαντ’ ἐπιδοῦναι μύρια καὶ πεντακισχίλια Ῥωμαίοις ἀντὶ τῆς εἰς τὸν πόλεμον δαπάνης. τούτων δὲ πεντακόσια μὲν παραχρῆμα, δισχίλια δὲ καὶ πεντακόσια πάλιν, ἐπειδὰν ὁ δῆμος κυρώσῃ τὰς διαλύσεις, τὰ δὲ λοιπὰ τελεῖν ἐν ἔτεσι δώδεκα, διδόντα καθ’ ἕκαστον ἔτος χίλια τάλαντα. ἀποδοῦναι δὲ καὶ Εὐμένει τετρακόσια τάλαντα τὰ προσοφειλόμενα καὶ τὸν ἐλλείποντα σῖτον κατὰ τὰς πρὸς τὸν πατέρα συνθήκας. σὺν δὲ τούτοις Ἀννίβαν ἐκδοῦναι τὸν Καρχηδόνιον καὶ Θόαντα τὸν Αἰτωλὸν καὶ Μνασίλοχον Ἀκαρνᾶνα καὶ Φίλωνα καὶ Εὐβουλίδαν τοὺς Χαλκιδέας. πίστιν δὲ τούτων ὁμήρους εἴκοσι δοῦναι παραχρῆμα τὸν Ἀντίοχον τοὺς παραγραφέντας. ταῦτα μὲν οὖν ὁ Πόπλιος ἀπεφήναθ’ ὑπὲρ παντὸς τοῦ συνεδρίου. συγκαταθεμένων δὲ τῶν περὶ τὸν Ἀντίπατρον καὶ Ζεῦξιν, ἔδοξε πᾶσιν ἐξαποστεῖλαι πρεσβευτὰς εἰς τὴν Ῥώμην τοὺς παρακαλέσοντας τὴν σύγκλητον καὶ τὸν δῆμον ἐπικυρῶσαι τὰς συνθήκας. καὶ τότε μὲν ἐπὶ τούτοις ἐχωρίσθησαν, ταῖς δ’ ἑξῆς ἡμέραις οἱ Ῥωμαῖοι διεῖλον τὰς δυνάμεις μετὰ δέ τινας ἡμέρας παραγενομένων τῶν ὁμήρων εἰς τὴν Ἔφεσον, εὐθέως ἐγίνοντο περὶ τὸ πλεῖν εἰς τὴν Ῥώμην ὅ τ’ Εὐμένης οἵ τε παρ’ Ἀντιόχου πρεσβευταί, παραπλησίως δὲ καὶ παρὰ Ῥοδίων καὶ παρὰ Σμυρναίων καὶ σχεδὸν τῶν ἐπὶ τάδε τοῦ Ταύρου πάντων τῶν κατοικούντων ἐθνῶν καὶ πολιτευμάτων ἐπρέσβευον εἰς τὴν Ῥώμην.", "st": "21.17"}, {"sp": "N", "t": "ὅτι ἤδη τῆς θερείας ἐνισταμένης μετὰ τὴν νίκην τῶν Ῥωμαίων τὴν πρὸς Ἀντίοχον παρῆν ὅ τε βασιλεὺς Εὐμένης οἵ τε παρ’ Ἀντιόχου πρέσβεις οἵ τε παρὰ τῶν Ῥοδίων, ὁμοίως δὲ καὶ παρὰ τῶν ἄλλων· σχεδὸν γὰρ ἅπαντες οἱ κατὰ τὴν Ἀσίαν εὐθέως μετὰ τὸ γενέσθαι τὴν μάχην ἔπεμπον πρεσβευτὰς εἰς τὴν Ῥώμην, διὰ τὸ πᾶσιν τότε καὶ πάσας τὰς ὑπὲρ τοῦ μέλλοντος ἐλπίδας ἐν τῇ συγκλήτῳ κεῖσθαι. ἅπαντας μὲν οὖν τοὺς παραγενομένους ἐπεδέχετο φιλανθρώπως ἡ σύγκλητος, μεγαλομερέστατα δὲ καὶ κατὰ τὴν ἀπάντησιν καὶ τὰς τῶν ξενίων παροχὰς Εὐμένη τὸν βασιλέα, μετὰ δὲ τοῦτον τοὺς Ῥοδίους. ἐπειδὴ δ’ ὁ τῆς ἐντεύξεως καιρὸς ἦλθεν, εἰσεκαλέσαντο πρῶτον τὸν βασιλέα καὶ λέγειν ἠξίουν μετὰ παρρησίας ὧν βούλεται τυχεῖν παρὰ τῆς συγκλήτου. τοῦ δ’ Εὐμένους φήσαντος διότι εἰ καὶ παρ’ ἑτέρων τυχεῖν τινος ἐβούλετο φιλανθρώπου, Ῥωμαίοις ἂν ἐχρήσατο συμβούλοις πρὸς τὸ μήτ’ ἐπιθυμεῖν μηδενὸς παρὰ τὸ δέον μήτ’ ἀξιοῦν μηδ’ ἓν πέρα τοῦ καθήκοντος· ὁπότε δ’ αὐτῶν πάρεστι δεόμενος Ῥωμαίων, ἄριστον εἶναι νομίζει τὸ διδόναι τὴν ἐπιτροπὴν ἐκείνοις καὶ περὶ αὑτοῦ καὶ περὶ τῶν ἀδελφῶν· τῶν δὲ πρεσβυτέρων τινὸς ἀναστάντος καὶ κελεύοντος μὴ κατορρωδεῖν, ἀλλὰ λέγειν τὸ φαινόμενον, διότι πρόκειται τῇ συγκλήτῳ πᾶν αὐτῷ χαρίζεσθαι τὸ δυνατόν, ἔμεινεν ἐπὶ τῆς αὐτῆς γνώμης. χρόνου δ’ ἐγγινομένου ὁ μὲν βασιλεὺς ἐξεχώρησεν, ἡ δὲ ἐντὸς ἐβουλεύετο τί δεῖ ποιεῖν. ἔδοξεν οὖν τὸν Εὐμένη παρακαλεῖν αὐτὸν ὑποδεικνύναι θαρροῦντα περὶ ὧν πάρεστιν· καὶ γὰρ εἰδέναι τὰ διαφέροντα τοῖς ἰδίοις πράγμασιν ἐκεῖνον ἀκριβέστερον τὰ κατὰ τὴν Ἀσίαν. δοξάντων δὲ τούτων εἰσεκλήθη, καὶ τῶν πρεσβυτέρων τινὸς ἀποδείξαντος τὰ δεδογμένα λέγειν ἠναγκάσθη περὶ τῶν προκειμένων.", "st": "21.18"}, {"sp": "N", "t": "ἔφασκεν οὖν ἄλλο μὲν οὐδὲν ἂν εἰπεῖν περὶ τῶν καθ’ αὑτόν, ἀλλὰ μεῖναι τελέως διδοὺς ἐκείνοις τὴν ἐξουσίαν· ἕνα δὲ τόπον ἀγωνιᾶν τὸν κατὰ τοὺς Ῥοδίους· διὸ καὶ προῆχθαι νῦν εἰς τὸ λέγειν ὑπὲρ τῶν ἐνεστώτων. ἐκείνους γὰρ παρεῖναι μὲν οὐδὲν ἧττον ὑπὲρ τῆς σφετέρας πατρίδος συμφερόντως σπουδάζοντας ἤπερ αὑτοὺς ὑπὲρ τῆς ἰδίας ἀρχῆς φιλοτιμεῖσθαι κατὰ τὸ παρόν· τοὺς δὲ λόγους αὐτῶν τὴν ἐναντίαν ἔμφασιν ἔχειν τῇ προθέσει τῇ κατὰ τὴν ἀλήθειαν. τοῦτο δ’ εἶναι ῥᾴδιον καταμαθεῖν. ἐρεῖν μὲν γὰρ αὐτούς, ἐπειδὰν εἰσπορευθῶσιν, διότι πάρεισιν οὔτε παρ’ ὑμῶν αἰτούμενοι τὸ παράπαν οὐδὲν οὔθ’ ἡμᾶς βλάπτειν θέλοντες κατ’ οὐδένα τρόπον, πρεσβεύονται δὲ περὶ τῆς ἐλευθερίας τῶν τὴν Ἀσίαν κατοικούντων Ἑλλήνων. \" τοῦτο δ’ οὐχ οὕτως αὐτοῖς εἶναι κεχαρισμένον φήσουσιν ὡς ὑμῖν καθῆκον καὶ τοῖς γεγονόσιν ἔργοις ἀκόλουθον. ἡ μὲν οὖν διὰ τῶν λόγων φαντασία τοιαύτη τις αὐτῶν ἔσται· τὰ δὲ κατὰ τὴν ἀλήθειαν τὴν ἐναντίαν ἔχοντα τούτοις εὑρεθήσεται διάθεσιν. τῶν γὰρ πόλεων ἐλευθερωθεισῶν, ὡς αὐτοὶ παρακαλοῦσιν, τὴν μὲν τούτων συμβήσεται δύναμιν αὐξηθῆναι πολλαπλασίως, τὴν δ’ ἡμετέραν τρόπον τινὰ καταλυθῆναι. τὸ γὰρ τῆς ἐλευθερίας ὄνομα καὶ τῆς αὐτονομίας ἡμῖν μὲν ἄρδην ἀποσπάσει πάντας οὐ μόνον τοὺς νῦν ἐλευθερωθησομένους, ἀλλὰ καὶ τοὺς πρότερον ἡμῖν ὑποταττομένους, ἐπειδὰν ὑμεῖς ἐπὶ ταύτης ὄντες φανεροὶ γένησθε τῆς προαιρέσεως, τούτοις δὲ προσθήσει πάντας. τὰ γὰρ πράγματα φύσιν ἔχει τοιαύτην· δόξαντες γὰρ ἠλευθερῶσθαι διὰ τούτους ὀνόματι μὲν ἔσονται σύμμαχοι τούτων, τῇ δ’ ἀληθείᾳ πᾶν ποιήσουσι τὸ κελευόμενον ἑτοίμως, τῇ μεγίστῃ χάριτι γεγονότες ὑπόχρεοι. διόπερ, ὦ ἄνδρες, ἀξιοῦμεν ὑμᾶς τοῦτον τὸν τόπον ὑπιδέσθαι, μὴ λάθητε τοὺς μὲν παρὰ τὸ δέον αὔξοντες, τοὺς δ’ ἐλαττοῦντες τῶν φίλων ἀλόγως, ἅμα δὲ τούτοις τοὺς μὲν πολεμίους γεγονότας εὐεργετοῦντες, τοὺς δ’ ἀληθινοὺς φίλους παρορῶντες καὶ κατολιγωροῦντες τούτων.", "st": "21.19"}, {"sp": "N", "t": "ἐγὼ δὲ περὶ μὲν τῶν ἄλλων, ὅτου δέοι, παντὸς ἂν παραχωρήσαιμι τοῖς πέλας ἀφιλονίκως, περὶ δὲ τῆς ὑμετέρας φιλίας καὶ τῆς εἰς ὑμᾶς εὐνοίας ἁπλῶς οὐδέποτ’ ἂν οὐδενὶ τῶν ὄντων ἐκχωρήσαιμι κατὰ δύναμιν. δοκῶ δὲ καὶ τὸν πατέρα τὸν ἡμέτερον, εἴπερ ἔζη, τὴν αὐτὴν ἂν προέσθαι φωνὴν ἐμοί. καὶ γὰρ ἐκεῖνος, πρῶτος μετασχὼν τῆς ὑμετέρας φιλίας καὶ συμμαχίας, σχεδὸν πάντων τῶν [κατὰ] τὴν Ἀσίαν καὶ τὴν Ἑλλάδα νεμομένων, εὐγενέστατα διεφύλαξε ταύτην ἕως τῆς τελευταίας ἡμέρας, οὐ μόνον κατὰ τὴν προαίρεσιν, ἀλλὰ καὶ κατὰ τὰς πράξεις. πάντων γὰρ ὑμῖν ἐκοινώνησε τῶν κατὰ τὴν Ἑλλάδα πολέμων καὶ πλείστας μὲν εἰς τούτους καὶ πεζικὰς καὶ ναυτικὰς δυνάμεις παρέσχετο τῶν ἄλλων συμμάχων, πλείστην δὲ συνεβάλετο χορηγίαν καὶ μεγίστους ὑπέμεινε κινδύνους· τέλος δ’ εἰπεῖν, κατέστρεψε τὸν βίον ἐν αὐτοῖς τοῖς ἔργοις κατὰ τὸν Φιλιππικὸν πόλεμον, παρακαλῶν Βοιωτοὺς εἰς τὴν ὑμετέραν φιλίαν καὶ συμμαχίαν. ἐγὼ δὲ διαδεξάμενος τὴν ἀρχὴν τὴν μὲν προαίρεσιν τὴν τοῦ πατρὸς διεφύλαξα — ταύτην γὰρ οὐχ οἷόν τ’ ἦν ὑπερθέσθαι — τοῖς δὲ πράγμασιν ὑπερεθέμην. οἱ γὰρ καιροὶ τὴν ἐκ πυρὸς βάσανον ἐμοὶ μᾶλλον ἢ ’κείνῳ προσῆγον. Ἀντιόχου γὰρ σπουδάζοντος ἡμῖν θυγατέρα δοῦναι καὶ συνοικειωθῆναι τοῖς ὅλοις, διδόντος δὲ παραχρῆμα μὲν τὰς πρότερον ἀπηλλοτριωμένας ἀφ’ ἡμῶν πόλεις, μετὰ δὲ ταῦτα πᾶν ὑπισχνουμένου ποιήσειν, εἰ μετάσχοιμεν τοῦ πρὸς ὑμᾶς πολέμου, τοσοῦτον ἀπέσχομεν τοῦ προσδέξασθαί τι τούτων, ὡς πλείσταις μὲν καὶ πεζικαῖς καὶ ναυτικαῖς δυνάμεσιν τῶν ἄλλων συμμάχων ἠγωνίσμεθα μεθ’ ὑμῶν πρὸς Ἀντίοχον, πλείστας δὲ χορηγίας συμβεβλήμεθα πρὸς τὰς ὑμετέρας χρείας ἐν τοῖς ἀναγκαιοτάτοις καιροῖς, εἰς πάντας δὲ τοὺς κινδύνους δεδώκαμεν αὑτοὺς ἀπροφασίστως μετά γε τῶν ὑμετέρων ἡγεμόνων. τὸ δὲ τελευταῖον ὑπεμείναμεν συγκλεισθέντες εἰς αὐτὸν τὸν Πέργαμον πολιορκεῖσθαι καὶ κινδυνεύειν ἅμα περὶ τοῦ βίου καὶ τῆς ἀρχῆς διὰ τὴν πρὸς τὸν ὑμέτερον δῆμον εὔνοιαν.", "st": "21.20"}, {"sp": "N", "t": "ὥσθ’ ὑμᾶς, ἄνδρες Ῥωμαῖοι, πολλοὺς μὲν γεγονότας αὐτόπτας, πάντας δὲ γινώσκοντας διότι λέγομεν ἀληθῆ, δίκαιόν ἐστι τὴν ἁρμόζουσαν πρόνοιαν ποιήσασθαι περὶ ἡμῶν. καὶ γὰρ ἂν πάντων γένοιτο δεινότατον, εἰ Μασαννάσαν μὲν τὸν οὐ μόνον ὑπάρξαντα πολέμιον ὑμῖν, ἀλλὰ καὶ τὸ τελευταῖον καταφυγόντα πρὸς ὑμᾶς μετά τινων ἱππέων, τοῦτον, ὅτι καθ’ ἕνα πόλεμον τὸν πρὸς Καρχηδονίους ἐτήρησε τὴν πίστιν, βασιλέα τῶν πλείστων μερῶν τῆς Λιβύης πεποιήκατε, Πλευρᾶτον δέ, πράξαντα μὲν ἁπλῶς οὐδέν, διαφυλάξαντα δὲ μόνον τὴν πίστιν, μέγιστον τῶν κατὰ τὴν Ἰλλυρίδα δυναστῶν ἀναδεδείχατε, ἡμᾶς δὲ τοὺς διὰ προγόνων τὰ μέγιστα καὶ κάλλιστα τῶν ἔργων ὑμῖν συγκατειργασμένους παρ’ οὐδὲν ποιήσεσθε. τί οὖν ἐστιν ὃ παρακαλῶ, καὶ τίνος φημὶ δεῖν ἡμᾶς τυγχάνειν παρ’ ὑμῶν; ἐρῶ μετὰ παρρησίας, ἐπείπερ ἡμᾶς ἐξεκαλέσασθε πρὸς τὸ λέγειν ὑμῖν τὸ φαινόμενον. εἰ μὲν αὐτοὶ κρίνετέ τινας τόπους διακατέχειν τῆς Ἀσίας τῶν ὄντων μὲν ἐπὶ τάδε τοῦ Ταύρου, ταττομένων δὲ πρότερον ὑπ’ Ἀντίοχον, τοῦτο καὶ μάλιστα βουλοίμεθ’ ἂν ἰδεῖν γενόμενον· καὶ γὰρ ἀσφαλέστατα βασιλεύσειν ὑμῖν γειτνιῶντες ὑπολαμβάνομεν καὶ μάλιστα μετέχοντες τῆς ὑμετέρας ἐξουσίας. εἰ δὲ τοῦτο μὴ κρίνετε ποιεῖν, ἀλλ’ ἐκχωρεῖν τῆς Ἀσίας ὁλοσχερῶς, οὐδενί φαμεν δικαιότερον εἶναι παραχωρεῖν ὑμᾶς τῶν ἐκ τοῦ πολέμου γεγονότων ἄθλων ἤπερ ἡμῖν. νὴ Δί’, ἀλλὰ κάλλιόν ἐστι τοὺς δουλεύοντας ἐλευθεροῦν. εἴγε μὴ μετ’ Ἀντιόχου πολεμεῖν ὑμῖν ἐτόλμησαν. ἐπεὶ δὲ τοῦθ’ ὑπέμειναν, πολλῷ κάλλιον τὸ τοῖς ἀληθινοῖς φίλοις τὰς ἁρμοζούσας χάριτας ἀποδιδόναι μᾶλλον ἢ τοὺς πολεμίους γεγονότας εὐεργετεῖν.\"", "st": "21.21"}, {"sp": "N", "t": "ὁ μὲν οὖν Εὐμένης ἱκανῶς εἰπὼν ἀπηλλάγη, τὸ δὲ συνέδριον αὐτόν τε τὸν βασιλέα καὶ τὰ ῥηθέντα φιλοφρόνως ἀπεδέχετο καὶ πᾶν τὸ δυνατὸν προθύμως εἶχεν αὐτῷ χαρίζεσθαι. μετὰ δὲ τοῦτον ἐβούλοντο μὲν εἰσάγειν Ῥοδίους. ἀφυστεροῦντος δέ τινος τῶν πρεσβευτῶν εἰσεκαλέσαντο τοὺς Σμυρναίους. οὗτοι δὲ πολλοὺς μὲν ἀπολογισμοὺς εἰσήνεγκαν περὶ τῆς αὑτῶν εὐνοίας καὶ προθυμίας, ἣν παρέσχηνται Ῥωμαίοις κατὰ τὸν ἐνεστῶτα πόλεμον· οὔσης δὲ τῆς περὶ αὐτῶν δόξης ὁμολογουμένης, διότι γεγόνασι πάντων ἐκτενέστατοι τῶν ἐπὶ τῆς Ἀσίας αὐτονομουμένων, οὐκ ἀναγκαῖον ἡγούμεθ’ εἶναι τοὺς κατὰ μέρος ἐκτίθεσθαι λόγους. ἐπὶ δὲ τούτοις εἰσῆλθον οἱ Ῥόδιοι καὶ βραχέα προενεγκάμενοι περὶ τῶν κατ’ ἰδίαν σφίσι πεπραγμένων εἰς Ῥωμαίους, ταχέως εἰς τὸν περὶ τῆς πατρίδος ἐπανῆλθον λόγον. ἐν ᾧ μέγιστον αὑτοῖς ἔφασαν γεγονέναι σύμπτωμα κατὰ τὴν πρεσβείαν, πρὸς ὃν οἰκειότατα διάκεινται βασιλέα καὶ κοινῇ καὶ κατ’ ἰδίαν, πρὸς τοῦτον αὐτοῖς ἀντιπεπτωκέναι τὴν φύσιν τῶν πραγμάτων. τῇ μὲν γὰρ αὑτῶν πατρίδι δοκεῖν τοῦτο κάλλιστον εἶναι καὶ μάλιστα πρέπον Ῥωμαίοις, τὸ τοὺς ἐπὶ τῆς Ἀσίας Ἕλληνας ἐλευθερωθῆναι καὶ τυχεῖν τῆς αὐτονομίας τῆς ἅπασιν ἀνθρώποις προσφιλεστάτης, Εὐμένει δὲ καὶ τοῖς ἀδελφοῖς ἥκιστα τοῦτο συμφέρειν· φύσει γὰρ πᾶσαν μοναρχίαν τὸ μὲν ἴσον ἐχθαίρειν, ζητεῖν δὲ πάντας, εἰ δὲ μή γ’ ὡς πλείστους, ὑπηκόους εἶναι σφίσι καὶ πειθαρχεῖν. ἀλλὰ καίπερ τοιούτων ὄντων τῶν πραγμάτων, ὅμως ἔφασαν πεπεῖσθαι διότι καθίξονται τῆς προθέσεως, οὐ τῷ πλεῖον Εὐμένους δύνασθαι παρὰ Ῥωμαίοις, ἀλλὰ τῷ δικαιότερα φαίνεσθαι λέγοντες καὶ συμφορώτερα πᾶσιν ὁμολογουμένως. εἰ μὲν γὰρ μὴ δυνατὸν ἦν ἄλλως Εὐμένει χάριν ἀποδοῦναι Ῥωμαίους, εἰ μὴ παραδοῖεν αὐτῷ τὰς αὐτονομουμένας πόλεις, ἀπορεῖν εἰκὸς ἦν περὶ τῶν ἐνεστώτων· ἢ γὰρ φίλον ἀληθινὸν ἔδει παριδεῖν, ἢ τοῦ καλοῦ καὶ καθήκοντος αὑτοῖς ὀλιγωρῆσαι καὶ τὸ τέλος τῶν ἰδίων πράξεων ἀμαυρῶσαι καὶ καταβαλεῖν. \"εἰ δ’ ἀμφοτέρων τούτων ἱκανῶς ἔξεστιν προνοηθῆναι, τίς ἂν ἔτι περὶ τούτου διαπορήσειεν; καὶ μὴν ὥσπερ ἐν δείπνῳ πολυτελεῖ, πάντ’ ἔνεστιν ἱκανὰ πᾶσιν καὶ πλείω τῶν ἱκανῶν. καὶ γὰρ Λυκαονίαν καὶ Φρυγίαν τὴν ἐφ’ Ἑλλησπόντου καὶ τὴν Πισιδικήν, πρὸς δὲ ταύταις Χερρόνησον καὶ τὰ προσοροῦντα ταύτῃ τῆς Εὐρώπης ἔξεστιν ὑμῖν οἷς ἂν βούλησθε προστεθέντα πρὸς τὴν Εὐμένους βασιλείαν δεκαπλασίαν αὐτὴν δύναται ποιεῖν τῆς νῦν ὑπαρχούσης· πάντων δὲ τούτων ἢ τῶν πλείστων αὐτῇ προσμερισθέντων, οὐδεμιᾶς ἂν γένοιτο τῶν ἄλλων δυναστειῶν καταδεεστέρα.", "st": "21.22"}, {"sp": "N", "t": "ἔξεστιν οὖν, ὦ ἄνδρες Ῥωμαῖοι, καὶ τοὺς φίλους μεγαλομερῶς σωματοποιῆσαι καὶ τὸ τῆς ἰδίας ὑποθέσεως λαμπρὸν μὴ καταβαλεῖν. οὐ γάρ ἐστιν ὑμῖν καὶ τοῖς ἄλλοις ἀνθρώποις ταὐτὸν τέλος τῶν ἔργων, ἀλλ’ ἕτερον. οἱ μὲν γὰρ ἄλλοι πάντες ὁρμῶσιν πρὸς τὰς πράξεις ὀρεγόμενοι τοῦ καταστρέψασθαι καὶ προσλαβεῖν πόλεις, χορηγίαν, ναῦς· ὑμᾶς δὲ πάντων τούτων ἀπροσδεήτους οἱ θεοὶ πεποιήκασι, πάντα τὰ κατὰ τὴν οἰκουμένην τεθεικότες [μὲν] ὑπὸ τὴν ὑμετέραν ἐξουσίαν. τίνος οὖν ἔτι προσδεῖσθε, καὶ τίνος ἂν ἔτι δέοι πρόνοιαν ὑμᾶς ποιεῖσθαι τὴν ἰσχυροτάτην; δῆλον ὡς ἐπαίνου καὶ δόξης παρ’ ἀνθρώποις, ἃ καὶ κτήσασθαι μέν ἐστι δυσχερές, δυσχερέστερον δὲ κτησαμένους διαφυλάξαι. γνοίητε δ’ ἂν τὸ λεγόμενον οὕτως. ἐπολεμήσατε πρὸς Φίλιππον καὶ πᾶν ὑπεμείνατε χάριν τῆς τῶν Ἑλλήνων ἐλευθερίας· τοῦτο γὰρ προέθεσθε, καὶ τοῦθ’ ὑμῖν ἆθλον ἐξ ἐκείνου τοῦ πολέμου περιγέγονεν, ἕτερον δ’ ἁπλῶς οὐδέν. ἀλλ’ ὅμως εὐδοκεῖτε τούτῳ μᾶλλον ἢ τοῖς παρὰ Καρχηδονίων φόροις· καὶ μάλα δικαίως· τὸ μὲν γὰρ ἀργύριόν ἐστι κοινόν τι πάντων ἀνθρώπων κτῆμα, τὸ δὲ καλὸν καὶ πρὸς ἔπαινον καὶ τιμὴν ἀνῆκον θεῶν καὶ τῶν ἔγγιστα τούτοις πεφυκότων ἀνδρῶν ἐστιν. τοιγαροῦν σεμνότατον τῶν ὑμετέρων ἔργων ἡ τῶν Ἑλλήνων ἐλευθέρωσις. τούτῳ νῦν ἐὰν μὲν προσθῆτε τἀκόλουθον, τελειωθήσεται τὰ τῆς ὑμετέρας δόξης. ἐὰν δὲ παρίδητε, καὶ τὰ πρὶν ἐλαττωθήσεται φανερῶς. ἡμεῖς μὲν οὖν, ὦ ἄνδρες, καὶ τῆς προαιρέσεως γεγονότες αἱρετισταὶ καὶ τῶν μεγίστων ἀγώνων καὶ κινδύνων ἀληθινῶς ὑμῖν μετεσχηκότες, καὶ νῦν οὐκ ἐγκαταλείπομεν τὴν τῶν φίλων τάξιν, ἀλλ’ ἅ γε νομίζομεν ὑμῖν καὶ πρέπειν καὶ συμφέρειν, οὐκ ὠκνήσαμεν ὑπομνῆσαι μετὰ παρρησίας, οὐδενὸς στοχασάμενοι τῶν ἄλλων οὐδὲ περὶ πλείονος οὐδὲν ποιησάμενοι τοῦ καθήκοντος αὑτοῖς.\" οἱ μὲν οὖν Ῥόδιοι ταῦτ’ εἰπόντες πᾶσιν ἐδόκουν μετρίως καὶ καλῶς διειλέχθαι περὶ τῶν προκειμένων.", "st": "21.23"}, {"sp": "N", "t": "ἐπὶ δὲ τούτοις εἰσήγαγον τοὺς παρ’ Ἀντιόχου πρεσβευτὰς Ἀντίπατρον καὶ Ζεῦξιν. ὧν μετ’ ἀξιώσεως καὶ παρακλήσεως ποιησαμένων τοὺς λόγους, εὐδόκησαν ταῖς γεγενημέναις ὁμολογίαις πρὸς τοὺς περὶ τὸν Σκιπίωνα κατὰ τὴν Ἀσίαν, καὶ μετά τινας ἡμέρας τοῦ δήμου συνεπικυρώσαντος ἔτεμον ὅρκια περὶ τούτων πρὸς τοὺς περὶ τὸν Ἀντίπατρον. μετὰ δὲ ταῦτα καὶ τοὺς ἄλλους εἰσῆγον, ὅσοι παρῆσαν ἀπὸ τῆς Ἀσίας πρεσβεύοντες· ὧν ἐπὶ βραχὺ μὲν διήκουσαν, ἅπασιν δὲ τὴν αὐτὴν ἔδωκαν ἀπόκρισιν. αὕτη δ’ ἦν ὅτι δέκα πρεσβεύοντας ἐξαποστελοῦσι τοὺς ὑπὲρ ἁπάντων τῶν ἀμφισβητουμένων ταῖς πόλεσι διαγνωσομένους. δόντες δὲ ταύτας τὰς ἀποκρίσεις μετὰ ταῦτα κατέστησαν δέκα πρεσβευτάς, οἷς περὶ μὲν τῶν κατὰ μέρος ἔδωκαν τὴν ἐπιτροπήν, περὶ δὲ τῶν ὅλων αὐτοὶ διέλαβον ὅτι δεῖ τῶν ἐπὶ τάδε τοῦ Ταύρου κατοικούντων, ὅσοι μὲν ὑπ’ Ἀντίοχον ἐτάττοντο, τούτους Εὐμένει δοθῆναι πλὴν Λυκίαν καὶ Καρίας τὰ μέχρι τοῦ Μαιάνδρου ποταμοῦ, ταῦτα δὲ Ῥοδίων ὑπάρχειν, τῶν δὲ πόλεων τῶν Ἑλληνίδων ὅσαι μὲν Ἀττάλῳ φόρον ὑπετέλουν, ταύτας τὸν αὐτὸν Εὐμένει τελεῖν, ὅσαι δ’ Ἀντιόχῳ, μόνον ταύταις ἀφεῖσθαι τὸν φόρον. δόντες δὲ τοὺς τύπους τούτους ὑπὲρ τῆς ὅλης διοικήσεως, ἐξέπεμπον τοὺς δέκα πρὸς Γνάιον τὸν ὕπατον εἰς τὴν Ἀσίαν. ἤδη δὲ τούτων διῳκημένων, προσῆλθον αὖθις οἱ Ῥόδιοι πρὸς τὴν σύγκλητον, ἀξιοῦντες περὶ Σόλων τῶν Κιλικίων· διὰ γὰρ τὴν συγγένειαν ἔφασαν καθήκειν αὑτοῖς προνοεῖσθαι τῆς πόλεως ταύτης. εἶναι γὰρ Ἀργείων ἀποίκους Σολεῖς, καθάπερ καὶ Ῥοδίους· ἐξ ὧν ἀδελφικὴν οὖσαν ἀπεδείκνυον τὴν συγγένειαν πρὸς ἀλλήλους. ὧν ἕνεκα δίκαιον ἔφασαν εἶναι τυχεῖν αὐτοὺς τῆς ἐλευθερίας ὑπὸ Ῥωμαίων διὰ τῆς Ῥοδίων χάριτος. ἡ δὲ σύγκλητος διακούσασα περὶ τούτων εἰσεκαλέσατο τοὺς παρ’ Ἀντιόχου πρεσβευτάς, καὶ τὸ μὲν πρῶτον ἐπέταττε πάσης Κιλικίας ἐκχωρεῖν τὸν Ἀντίοχον· οὐ προσδεχομένων δὲ τῶν περὶ τὸν Ἀντίπατρον διὰ τὸ παρὰ τὰς συνθήκας εἶναι, πάλιν ὑπὲρ αὐτῶν Σόλων ἐποιοῦντο τὸν λόγον. φιλοτίμως δὲ πρὸς τοῦτο διερειδομένων τῶν πρεσβευτῶν, τούτους μὲν ἀπέλυσαν, τοὺς δὲ Ῥοδίους εἰσκαλεσάμενοι διεσάφουν τὰ συναντώμενα παρὰ τῶν περὶ τὸν Ἀντίπατρον καὶ προσεπέλεγον ὅτι πᾶν ὑπομενοῦσιν, εἰ πάντως τοῦτο κέκριται Ῥοδίοις. τῶν δὲ πρεσβευτῶν εὐδοκουμένων τῇ φιλοτιμίᾳ τῆς συγκλήτου καὶ φασκόντων οὐδὲν ἔτι πέρα ζητεῖν, ταῦτα μὲν ἐπὶ τῶν ὑποκειμένων ἔμεινεν. ἤδη δὲ πρὸς ἀναζυγὴν τῶν δέκα καὶ τῶν ἄλλων πρεσβευτῶν ὄντων, κατέπλευσαν τῆς Ἰταλίας εἰς Βρεντέσιον οἵ τε περὶ τὸν Σκιπίωνα καὶ Λεύκιον οἱ τῇ ναυμαχίᾳ νικήσαντες τὸν Ἀντίοχον· οἳ καὶ μετά τινας ἡμέρας εἰσελθόντες εἰς τὴν Ῥώμην ἦγον θριάμβους.", "st": "21.24"}, {"sp": "N", "t": "ὅτι Ἀμύνανδρος ὁ τῶν Ἀθαμάνων βασιλεύς, δοκῶν ἤδη τὴν ἀρχὴν ἀνειληφέναι βεβαίως, εἰς Ῥώμην ἐξέπεμπε πρεσβευτὰς καὶ πρὸς τοὺς Σκιπίωνας εἰς τὴν Ἀσίαν — ἔτι γὰρ ἦσαν περὶ τοὺς κατὰ τὴν Ἔφεσον τόπους — τὰ μὲν ἀπολογούμενος τῷ δοκεῖν δι’ Αἰτωλῶν πεποιῆσθαι τὴν κάθοδον, τὰ δὲ κατηγορῶν τοῦ Φιλίππου, τὸ δὲ πολὺ παρακαλῶν προσδέξασθαι πάλιν αὐτὸν εἰς τὴν συμμαχίαν. οἱ δ’ Αἰτωλοὶ νομίσαντες ἔχειν εὐφυῆ καιρὸν πρὸς τὸ τὴν Ἀμφιλοχίαν καὶ τὴν Ἀπεραντίαν ἀνακτήσασθαι, προέθεντο στρατεύειν εἰς τοὺς προειρημένους τόπους. ἁθροίσαντος δὲ Νικάνδρου τοῦ στρατηγοῦ πάνδημον στρατιάν, ἐνέβαλον εἰς τὴν Ἀμφιλοχίαν. τῶν δὲ πλείστων αὐτοῖς ἐθελοντὴν προσχωρησάντων μετῆλθον εἰς τὴν Ἀπεραντίαν. καὶ τούτων δὲ προσθεμένων ἑκουσίως ἐστράτευσαν εἰς τὴν Δολοπίαν. οὗτοι δὲ βραχὺν μέν τινα χρόνον ὑπέδειξαν ὡς ἀντιποιησόμενοι, τηρήσαντες τὴν πρὸς Φίλιππον πίστιν· λαβόντες δὲ πρὸ ὀφθαλμῶν τὰ περὶ τοὺς Ἀθαμᾶνας καὶ τὴν τοῦ Φιλίππου, ταχέως μετενόησαν καὶ προσέθεντο πρὸς τοὺς Αἰτωλούς. γενομένης δὲ τῆς τῶν πραγμάτων εὐροίας τοιαύτης, ἀπήγαγε τὴν στρατιὰν ὁ Νίκανδρος εἰς τὴν οἰκείαν, δοκῶν ἠσφαλίσθαι τὰ κατὰ τὴν Αἰτωλίαν τοῖς προειρημένοις ἔθνεσι καὶ τόποις τοῦ μηδένα δύνασθαι κακοποιεῖν τὴν χώραν αὐτῶν. ἄρτι δὲ τούτων συμβεβηκότων καὶ τῶν Αἰτωλῶν ἐπὶ τοῖς γεγονόσι φρονηματιζομένων, προσέπεσε φήμη περὶ τῆς κατὰ τὴν Ἀσίαν μάχης, ἐν ᾗ γνόντες ἡττημένον ὁλοσχερῶς τὸν Ἀντίοχον αὖθις ἀνετράπησαν ταῖς ψυχαῖς. ὡς δὲ παραγενηθεὶς ἐκ τῆς Ῥώμης ὁ Δαμοτέλης τόν τε πόλεμον ἀνήγγειλε διότι μένει κατάμονος, καὶ τὴν τοῦ Μάρκου καὶ τῶν δυνάμεων διάβασιν ἐπ’ αὐτούς, τότε δὴ παντελῶς εἰς ἀμηχανίαν ἐνέπιπτον καὶ διηπόρουν πῶς δεῖ χρήσασθαι τοῖς ἐπιφερομένοις πράγμασιν. ἔδοξεν οὖν αὐτοῖς πρός τε Ῥοδίους πέμπειν καὶ πρὸς Ἀθηναίους, ἀξιοῦντας καὶ παρακαλοῦντας πρεσβεῦσαι περὶ αὐτῶν εἰς τὴν Ῥώμην καὶ παραιτησαμένους τὴν ὀργὴν τῶν Ῥωμαίων ποιήσασθαί τινα λύσιν τῶν περιεστώτων κακῶν τὴν Αἰτωλίαν. ὁμοίως δὲ καὶ παρ’ αὑτῶν ἐξέπεμψαν πάλιν πρεσβευτὰς εἰς τὴν Ῥώμην, Ἀλέξανδρον τὸν Ἴσιον ἐπικαλούμενον καὶ Φαινέαν, σὺν δὲ τούτοις Χάλεπον. ἔτι δ’ Ἄλυπον τὸν Ἀμβρακιώτην καὶ Λύκωπον. —", "st": "21.25"}, {"sp": "N", "t": "ὅτι παραγενομένων πρὸς τὸν στρατηγὸν τῶν Ῥωμαίων ἐξ ἠπείρου πρεσβευτῶν, ἐκοινολογεῖτο τούτοις περὶ τῆς ἐπὶ τοὺς Αἰτωλοὺς στρατείας. τῶν δὲ πρεσβευτῶν στρατεύειν ἐπὶ τὴν Ἀμβρακίαν συμβουλευόντων — συνέβαινε γὰρ τότε πολιτεύεσθαι τοὺς Ἀμβρακιώτας μετὰ τῶν Αἰτωλῶν — καὶ φερόντων ἀπολογισμοὺς διότι καὶ πρὸς τὸ μάχεσθαι τοῖς στρατοπέδοις, ἐὰν εἰς τοῦτο βούλωνται συγκαταβαίνειν Αἰτωλοί, καλλίστους εἶναι τόπους συμβαίνει περὶ τὴν προειρημένην πόλιν, κἂν ἀποδειλιῶσιν, εὐφυῶς αὐτὴν κεῖσθαι πρὸς πολιορκίαν· καὶ γὰρ ἀφθόνους ἔχειν τὴν χώραν τὰς χορηγίας πρὸς τὰς τῶν ἔργων παρασκευάς, καὶ τὸν Ἄρατθον ποταμὸν ῥέοντα παρὰ τὴν πόλιν συνεργήσειν πρός τε τὰς τοῦ στρατοπέδου χρείας, ἅτε θέρους ὄντος καὶ πρὸς τὴν τῶν ἔργων ἀσφάλειαν· δοξάντων δὲ τῶν πρεσβευτῶν καλῶς συμβουλεύειν, ἀναζεύξας ὁ στρατηγὸς ἦγε διὰ τῆς Ἠπείρου τὸν στρατὸν ἐπὶ τὴν Ἀμβρακίαν. ἀφικόμενος δέ, καὶ τῶν Αἰτωλῶν οὐ τολμώντων ἀπαντᾶν, περιῄει κατοπτεύων τὴν πόλιν καὶ ἐνήργει τὰ τῆς πολιορκίας φιλοτίμως. καὶ οἱ μὲν ὑπὸ τῶν Αἰτωλῶν εἰς τὴν Ῥώμην ἀποσταλέντες πρέσβεις, παρατηρηθέντες ὑπὸ Σιβύρτου τοῦ Πετραίου περὶ τὴν Κεφαλληνίαν, κατήχθησαν εἰς Χάραδρον. τοῖς δ’ Ἠπειρώταις ἔδοξεν τὰς μὲν ἀρχὰς εἰς Βούχετον ἀποθέσθαι καὶ φυλάττειν ἐπιμελῶς τοὺς ἄνδρας· μετὰ δέ τινας ἡμέρας ἀπῄτουν αὐτοὺς λύτρα διὰ τὸ πόλεμον ὑπάρχειν σφίσιν πρὸς τοὺς Αἰτωλούς. συνέβαινε δὲ τὸν μὲν Ἀλέξανδρον πλουσιώτατον εἶναι πάντων τῶν Ἑλλήνων, τοὺς δὲ λοιποὺς οὐ καθυστερεῖν τοῖς βίοις, πολὺ δὲ λείπεσθαι τοῦ προειρημένου ταῖς οὐσίαις. καὶ τὸ μὲν πρῶτον ἐκέλευον ἕκαστον ἀποδοῦναι πέντε τάλαντα. τοῦτο δὲ τοῖς μὲν ἄλλοις οὐδ’ ὅλως ἀπήρεσκεν, ἀλλ’ ἐβούλοντο, περὶ πλείστου ποιούμενοι τὴν σφῶν αὐτῶν σωτηρίαν· ὁ δ’ Ἀλέξανδρος οὐκ ἂν ἔφη συγχωρῆσαι, πολὺ γὰρ εἶναι τἀργύριον [φαίνεται], καὶ τὰς νύκτας διαγρυπνῶν διωλοφύρετο πρὸς αὑτόν, εἰ δεήσει πέντε τάλαντα καταβάλλειν. οἱ δ’ Ἠπειρῶται προορώμενοι τὸ μέλλον καὶ διαγωνιῶντες μὴ γνόντες οἱ Ῥωμαῖοι διότι πρεσβεύοντας πρὸς αὐτοὺς κατεσχήκασι, κἄπειτα γράψαντες παρακαλῶσι καὶ κελεύωσιν ἀπολύειν τοὺς ἄνδρας, συγκαταβάντες τρία τάλαντα πάλιν ἀπῄτουν ἕκαστον. ἀσμένως δὲ τῶν ἄλλων προσδεξαμένων, οὗτοι μὲν διεγγυηθέντες ἐπανῆλθον, ὁ δ’ Ἀλέξανδρος οὐκ ἂν ἔφη δοῦναι πλεῖον ταλάντου· καὶ γὰρ τοῦτ’ εἶναι πολύ. καὶ τέλος ἀπογνοὺς αὑτὸν ἔμεινεν ἐν τῇ φυλακῇ, πρεσβύτερος ἄνθρωπος, πλειόνων ἢ διακοσίων ταλάντων ἔχων οὐσίαν· καί μοι δοκεῖ κἂν ἐκλιπεῖν τὸν βίον ἐφ’ ᾧ μὴ δοῦναι τὰ τρία τάλαντα. τοσαύτη τις ἐνίοις πρὸς τὸ πλεῖον ὁρμὴ παρίσταται καὶ προθυμία. τότε δ’ ἐκείνῳ καὶ ταὐτόματον συνήργησεν πρὸς τὴν φιλαργυρίαν, ὥστε παρὰ πᾶσιν ἐπαίνου καὶ συγκαταθέσεως τυχεῖν τὴν ἀλογιστίαν αὐτοῦ διὰ τὴν περιπέτειαν· μετὰ γὰρ ὀλίγας ἡμέρας γραμμάτων παραγενηθέντων ἐκ τῆς Ῥώμης περὶ τῆς ἀφέσεως, αὐτὸς μόνος ἀπελύθη χωρὶς λύτρων. οἱ δ’ Αἰτωλοί, γνόντες τὴν αὐτοῦ περιπέτειαν, Δαμοτέλη προεχειρίσαντο πάλιν εἰς τὴν Ῥώμην πρεσβευτήν. ὃς ἐκπλεύσας μέχρι τῆς Λευκάδος καὶ γνοὺς προάγοντα διὰ τῆς Ἠπείρου μετὰ τῶν δυνάμεων Μάρκον ἐπὶ τὴν Ἀμβρακίαν, ἀπογνοὺς τὴν πρεσβείαν αὖθις ἀνεχώρησεν εἰς τὴν Αἰτωλίαν. —", "st": "21.26"}, {"sp": "N", "t": "Αἰτωλοὶ ὑπὸ τοῦ τῶν Ῥωμαίων ὑπάτου Μάρκου πολιορκούμενοι τῇ προσβολῇ τῶν μηχανημάτων καὶ τῶν κριῶν γενναίως ἀντιπαρετάξαντο. οὗτος γὰρ ἀσφαλισάμενος τὰ κατὰ τὰς στρατοπεδείας συνίστατο μεγαλομερῶς τὴν πολιορκίαν καὶ τρία μὲν ἔργα κατὰ τὸ Πύρρειον προσῆγεν διὰ τῶν ἐπιπέδων [τόπων], διεστῶτα μὲν ἀπ’ ἀλλήλων, παράλληλα δέ, τέταρτον δὲ κατὰ τὸ Ἀσκληπιεῖον, πέμπτον δὲ κατὰ τὴν ἀκρόπολιν. γινομένης δὲ τῆς προσαγωγῆς ἐνεργοῦ κατὰ πάντας ἅμα τοὺς τόπους, ἐκπληκτικὴν συνέβαινε γίνεσθαι τοῖς ἔνδον τὴν τοῦ μέλλοντος προσδοκίαν. τῶν δὲ κριῶν τυπτόντων ἐνεργῶς τὰ τείχη, καὶ τῶν δορυδρεπάνων ἀποσυρόντων τὰς ἐπάλξεις, ἐπειρῶντο μὲν οἱ κατὰ τὴν πόλιν ἀντιμηχανᾶσθαι πρὸς ταῦτα, τοῖς μὲν κριοῖς διὰ κεραιῶν ἐνιέντες σηκώματα μολιβδᾶ καὶ λίθους καὶ στύπη δρύινα· τοῖς δὲ δρεπάνοις σιδηρᾶς περιτιθέντες ἀγκύρας καὶ κατασπῶντες ταῦτ’ ἔσω τοῦ τείχους, ὥστ’ ἐπὶ τὴν ἔπαλξιν συντριβέντος τοῦ δόρατος ἐγκρατεῖς γίνεσθαι τῶν δρεπάνων. τὸ δὲ πλεῖον ἐπεξιόντες ἐμάχοντο γενναίως, ποτὲ μὲν ἐπιτιθέμενοι νύκτωρ τοῖς ἐπικοιτοῦσιν ἐπὶ τῶν ἔργων, ποτὲ δὲ τοῖς ἐφημερεύουσι μεθ’ ἡμέραν προφανῶς ἐγχειροῦντες, καὶ τριβὴν ἐνεποίουν τῇ πολιορκίᾳ. — τοῦ γὰρ Νικάνδρου ἐκτὸς ἀναστρεφομένου καὶ πέμψαντος πεντακοσίους ἱππεῖς εἰς τὴν πόλιν, οἳ καὶ παραβιασάμενοι τὸν μεταξὺ χάρακα τῶν πολεμίων εἰσέφρησαν εἰς τὴν πόλιν, παραγγείλας, καθ’ ἣν ἐτάξαντο ἡμέραν, αὐτοὺς μὲν ἐξελθόντας ποιήσασθαι, συνεπιλαβέσθαι δὲ αὐτὸν τούτοις τοῦ κινδύνου. αὐτῶν μὲν εὐψύχως τῆς πόλεως ἐξορμησάντων καὶ γενναίως ἀγωνισαμένων, τοῦ δὲ Νικάνδρου καθυστερήσαντος, εἴτε καταπλαγέντος τὸν κίνδυνον εἴτε καὶ ἀναγκαῖα νομίσαντος τὰ ἐν οἷς διέτριβε πράγμασιν, ἡττήθησαν τῆς ἐπιβολῆς. —", "st": "21.27"}, {"sp": "N", "t": "οἱ δὲ Ῥωμαῖοι συνεχῶς ἐνεργοῦντες τοῖς κριοῖς ἀεί τι παρέλυον τῶν τειχῶν· οὐ μὴν εἴς γε τὴν πόλιν ἐδύναντο βιάσασθαι διὰ τῶν πτωμάτων, τῷ καὶ τὴν ἀντοικοδομίαν ὑπὸ τῶν ἔνδον ἐνεργὸν εἶναι καὶ μάχεσθαι γενναίως ἐπὶ τοῦ πίπτοντος μέρους τοὺς Αἰτωλούς. διόπερ ἀπορούμενοι κατήντησαν ἐπὶ τὸ μεταλλεύειν καὶ χρῆσθαι τοῖς ὀρύγμασιν ὑπὸ γῆς. ἀσφαλισάμενοι δὲ τὸ μέσον ἔργον τῶν τριῶν τῶν προϋπαρχόντων καὶ σκεπάσαντες ἐπιμελῶς [τὴν σύριγγα] τοῖς γέρροις, προεβάλοντο στοὰν παράλληλον τῷ τείχει σχεδὸν ἐπὶ δύο πλέθρα. καὶ λαβόντες ἀρχὴν ἐκ ταύτης ὤρυττον ἀδιαπαύστως καὶ τὴν νύκτα καὶ τὴν ἡμέραν ἐκ διαδοχῆς. ἐφ’ ἱκανὰς μὲν οὖν ἡμέρας ἐλάνθανον τοὺς ἔνδον φέροντες ἔξω τὸν χοῦν διὰ τῆς σύριγγος. ὡς δὲ μέγας ὁ σωρὸς ἐγένετο τῆς ἐκφερομένης γῆς καὶ σύνοπτος τοῖς ἐκ τῆς πόλεως, οἱ προεστῶτες τῶν πολιορκουμένων ὤρυττον τάφρον ἔσωθεν ἐνεργῶς παράλληλον τῷ τείχει καὶ τῇ στοᾷ τῇ πρὸ τῶν πύργων. ἐπειδὴ δὲ βάθος ἔσχεν ἱκανόν, ἑξῆς ἔθηκαν παρὰ τὸν ἕνα τοῖχον τῆς τάφρου τὸν ἐγγὺς τῷ τείχει χαλκώματα συνεχῆ, λεπτότατα ταῖς κατασκευαῖς, καὶ παρὰ ταῦτα διὰ τῆς τάφρου παριόντες ἠκροῶντο τοῦ ψόφου τῶν ὀρυττόντων ἔξωθεν. ἐπεὶ δ’ ἐσημειώσαντο τὸν τόπον, καθ’ ὃν ἐδήλου τινὰ τῶν χαλκωμάτων διὰ τῆς συμπαθείας, ὤρυττον ἔσωθεν ἐπικαρσίαν πρὸς τὴν ὑπάρχουσαν ἄλλην κατὰ γῆς τάφρον ὑπὸ τὸ τεῖχος, στοχαζόμενοι τοῦ συμπεσεῖν ἐναντίοι τοῖς πολεμίοις. ταχὺ δὲ τούτου γενομένου, διὰ τὸ τοὺς Ῥωμαίους μὴ μόνον ἀφῖχθαι πρὸς τὸ τεῖχος ὑπὸ γῆς, ἀλλὰ καὶ διεστυλωκέναι τόπον ἱκανὸν τοῦ τείχους ἐφ’ ἑκάτερον τὸ μέρος τοῦ μετάλλου, συνέπεσον ἀλλήλοις. καὶ τὸ μὲν πρῶτον ἐμάχοντο ταῖς σαρίσαις ὑπὸ γῆν· ἐπεὶ δ’ οὐδὲν ἠδύναντο μέγα ποιεῖν διὰ τὸ προβάλλεσθαι θυρεοὺς καὶ γέρρα πρὸ αὑτῶν ἀμφότεροι, τὸ τηνικάδ’ ὑπέθετό τις τοῖς πολιορκουμένοις πίθον προθεμένους ἁρμοστὸν κατὰ τὸ πλάτος τῷ μετάλλῳ τρυπῆσαι τὸν πυθμένα καὶ διώσαντας αὐλίσκον σιδηροῦν ἴσον τῷ τεύχει πλῆσαι τὸν πίθον ὅλον πτίλων λεπτῶν καὶ πυρὸς παντελῶς μικρὸν ἐμβαλεῖν ὑπ’ αὐτὸ τὸ τοῦ πίθου περιστόμιον· κἄπειτα σιδηροῦν πῶμα τρημάτων πλῆρες τῷ στόματι περιθέντας ἀσφαλῶς εἰσάγειν διὰ τοῦ μετάλλου, νεύοντι τῷ στόματι πρὸς τοὺς ὑπεναντίους· ὁπότε δ’ ἐγγίσαιεν τοῖς πολεμίοις, περισάξαντας τὰ χείλη τοῦ πίθου πανταχόθεν τρήματα δύο καταλιπεῖν ἐξ ἑκατέρου τοῦ μέρους, δι’ ὧν διωθοῦντες τὰς σαρίσας οὐκ ἐάσουσι προσιέναι τῷ πίθῳ τοὺς ὑπεναντίους· μετὰ δὲ ταῦτα λαβόντας ἀσκόν, ᾧπερ οἱ χαλκεῖς χρῶνται, καὶ προσαρμόσαντας πρὸς τὸν αὐλὸν τὸν σιδηροῦν φυσᾶν ἐνεργῶς τὸ πρὸς τῷ στόματι πῦρ ἐν τοῖς πτίλοις ἐγκείμενον, κατὰ τοσοῦτον ἐπαγομένους ἀεὶ τὸν αὐλὸν ἐκτός, καθ’ ὅσον ἂν ἐκκάηται τὰ πτίλα. γενομένων δὲ πάντων καθάπερ προείρηται, τό τε πλῆθος τοῦ καπνοῦ συνέβαινε πολὺ γίνεσθαι καὶ τῇ δριμύτητι διαφέρον διὰ τὴν φύσιν τῶν πτίλων, φέρεσθαί τε πᾶν εἰς τὸ τῶν πολεμίων μέταλλον. ὥστε καὶ λίαν κακοπαθεῖν καὶ δυσχρηστεῖσθαι τοὺς Ῥωμαίους, οὔτε κωλύειν οὔθ’ ὑπομένειν δυναμένους ἐν τοῖς ὀρύγμασι τὸν καπνόν. τοιαύτην δὲ λαμβανούσης τριβὴν τῆς πολιορκίας ὁ στρατηγὸς τῶν Αἰτωλῶν πρεσβεύειν ἔγνω πρὸς τὸν στρατηγὸν τῶν Ῥωμαίων. —", "st": "21.28"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον οἱ παρὰ τῶν Ἀθηναίων καὶ τῶν Ῥοδίων πρέσβεις ἧκον ἐπὶ τὸ στρατόπεδον τῶν Ῥωμαίων, συνεπιληψόμενοι τῶν διαλύσεων. ὅ τε βασιλεὺς τῶν Ἀθαμάνων Ἀμύνανδρος παρεγένετο σπουδάζων ἐξελέσθαι τοὺς Ἀμβρακιώτας ἐκ τῶν περιεστώτων κακῶν, δοθείσης αὐτῷ τῆς ἀσφαλείας ὑπὸ τοῦ Μάρκου διὰ τὸν καιρόν· πάνυ γὰρ οἰκείως εἶχε πρὸς τοὺς Ἀμβρακιώτας διὰ τὸ καὶ πλείω χρόνον ἐν τῇ πόλει ταύτῃ διατετριφέναι κατὰ φυγήν. ἧκον δὲ καὶ παρὰ τῶν Ἀκαρνάνων μετ’ ὀλίγας ἡμέρας ἄγοντές τινες τοὺς περὶ Δαμοτέλην· ὁ γὰρ Μάρκος πυθόμενος τὴν περιπέτειαν αὐτῶν ἔγραψε τοῖς Θυρρειεῦσιν ἀνακομίζειν τοὺς ἄνδρας ὡς αὑτόν. πάντων δὲ τούτων ἡθροισμένων ἐνηργεῖτο φιλοτίμως τὰ πρὸς τὰς διαλύσεις. ὁ μὲν οὖν Ἀμύνανδρος κατὰ τὴν αὑτοῦ πρόθεσιν εἴχετο τῶν Ἀμβρακιωτῶν, παρακαλῶν σῴζειν σφᾶς αὐτούς εἶναι δὲ τοῦτον οὐ μακράν, ἐὰν μὴ βουλεύσωνται βέλτιον περὶ αὑτῶν. πλεονάκις δὲ προσπελάζοντος αὐτοῦ τῷ τείχει καὶ διαλεγομένου περὶ τούτων, ἔδοξε τοῖς Ἀμβρακιώταις εἰσκαλέσασθαι τὸν Ἀμύνανδρον εἰς τὴν πόλιν. τοῦ δὲ στρατηγοῦ συγχωρήσαντος τῷ βασιλεῖ τὴν εἴσοδον, οὗτος μὲν εἰσελθὼν διελέγετο τοῖς Ἀμβρακιώταις περὶ τῶν ἐνεστώτων, οἱ δὲ παρὰ τῶν Ἀθηναίων καὶ τῶν Ῥοδίων πρέσβεις λαμβάνοντες εἰς τὰς χεῖρας τὸν στρατηγὸν τῶν Ῥωμαίων καὶ ποικίλως ὁμιλοῦντες, πραΰνειν ἐπειρῶντο τὴν ὀργὴν αὐτοῦ. τοῖς δὲ περὶ τὸν Δαμοτέλη καὶ Φαινέαν ὑπέθετό τις ἔχεσθαι καὶ θεραπεύειν τὸν Γάιον Οὐαλέριον· οὗτος δ’ ἦν Μάρκου μὲν υἱὸς τοῦ πρώτου συνθεμένου πρὸς Αἰτωλοὺς τὴν συμμαχίαν, Μάρκου δὲ τοῦ τότε στρατηγοῦντος ἀδελφὸς ἐκ μητρός· ἄλλως δὲ πρᾶξιν ἔχων νεανικὴν ἦν μάλιστα παρὰ τῷ στρατηγῷ πιστευόμενος. ὃς παρακληθεὶς ὑπὸ τῶν περὶ τὸν Δαμοτέλη καὶ νομίσας ἴδιον εἶναι τὸ πρᾶγμα καὶ καθήκειν αὑτῷ τὸ προστατῆσαι τῶν Αἰτωλῶν, πᾶσαν εἰσεφέρετο σπουδὴν καὶ φιλοτιμίαν, ἐξελέσθαι σπουδάζων τὸ ἔθνος ἐκ τῶν περιεστώτων κακῶν. ἐνεργῶς δὲ πανταχόθεν προσαγομένης τῆς φιλοτιμίας, ἔλαβε τὸ πρᾶγμα συντέλειαν. οἱ μὲν γὰρ Ἀμβρακιῶται πεισθέντες ὑπὸ τοῦ βασιλέως ἐπέτρεψαν τὰ καθ’ αὑτοὺς τῷ στρατηγῷ τῶν Ῥωμαίων καὶ παρέδωκαν τὴν πόλιν ἐφ’ ᾧ τοὺς Αἰτωλοὺς ὑποσπόνδους ἀπελθεῖν· τοῦτο γὰρ ὑφείλοντο πρῶτον, τηροῦντες τὴν πρὸς τοὺς συμμάχους πίστιν.", "st": "21.29"}, {"sp": "N", "t": "ὁ δὲ Μάρκος συγκατέθετο τοῖς Αἰτωλοῖς ἐπὶ τούτῳ ποιήσασθαι τὰς διαλύσεις, ὥστε διακόσια μὲν Εὐβοϊκὰ τάλαντα παραχρῆμα λαβεῖν, τριακόσια δ’ ἐν ἔτεσιν ἕξ, πεντήκοντα καθ’ ἕκαστον ἔτος· ἀποκατασταθῆναι δὲ καὶ τοὺς αἰχμαλώτους καὶ τοὺς αὐτομόλους Ῥωμαίοις ἅπαντας τοὺς παρ’ αὐτοῖς ὄντας ἐν ἓξ μησὶ χωρὶς λύτρων· πόλιν δὲ μηδεμίαν ἔχειν ἐν τῇ συμπολιτείᾳ μηδὲ μετὰ ταῦτα προσλαβέσθαι τούτων, ὅσαι μετὰ τὴν Λευκίου Κορνηλίου διάβασιν ἑάλωσαν ὑπὸ Ῥωμαίων ἢ φιλίαν ἐποιήσαντο πρὸς Ῥωμαίους· Κεφαλληνίους δὲ πάντας ἐκσπόνδους εἶναι τούτων τῶν συνθηκῶν. ταῦτα μὲν οὖν ὑπετυπώθη τότε κεφαλαιωδῶς περὶ τῶν διαλύσεων· ἔδει δὲ τούτοις πρῶτον μὲν εὐδοκῆσαι τοὺς Αἰτωλούς, μετὰ δὲ ταῦτα γίνεσθαι τὴν ἀναφορὰν ἐπὶ Ῥωμαίους. οἱ μὲν οὖν Ἀθηναῖοι καὶ Ῥόδιοι παρέμενον αὐτοῦ, καραδοκοῦντες τὴν τῶν Αἰτωλῶν ἀπόφασιν· οἱ δὲ περὶ τὸν Δαμοτέλην ἐπανελθόντες διεσάφουν τοῖς Αἰτωλοῖς περὶ τῶν συγκεχωρημένων. τοῖς μὲν οὖν ὅλοις εὐδόκουν· καὶ γὰρ ἦν αὐτοῖς ἅπαντα παρὰ τὴν προσδοκίαν· περὶ δὲ τῶν πόλεων τῶν πρότερον συμπολιτευομένων αὐτοῖς διαπορήσαντες ἐπὶ ποσὸν τέλος συγκατέθεντο τοῖς προτεινομένοις. ὁ δὲ Μάρκος παραλαβὼν τὴν Ἀμβρακίαν τοὺς μὲν Αἰτωλοὺς ἀφῆκεν ὑποσπόνδους, τὰ δ’ ἀγάλματα καὶ τοὺς ἀνδριάντας καὶ τὰς γραφὰς ἀπήγαγεν ἐκ τῆς πόλεως, ὄντα καὶ πλείω διὰ τὸ γεγονέναι βασίλειον Πύρρου τὴν Ἀμβρακίαν. ἐδόθη δ’ αὐτῷ καὶ στέφανος ἀπὸ ταλάντων ἑκατὸν καὶ πεντήκοντα. ταῦτα δὲ διοικησάμενος ἐποιεῖτο τὴν πορείαν εἰς τὴν μεσόγειον τῆς Αἰτωλίας, θαυμάζων ἐπὶ τῷ μηδὲν αὐτῷ παρὰ τῶν Αἰτωλῶν ἀπαντᾶσθαι. παραγενόμενος δὲ πρὸς Ἄργος τὸ καλούμενον Ἀμφιλοχικὸν κατεστρατοπέδευσεν, ὅπερ ἀπέχει τῆς Ἀμβρακίας ἑκατὸν ὀγδοήκοντα σταδίους. ἐκεῖ δὲ συμμιξάντων αὐτῷ τῶν περὶ τὸν Δαμοτέλην καὶ διασαφούντων ὅτι δέδοκται τοῖς Αἰτωλοῖς βεβαιοῦν τὰς δι’ ἑαυτῶν γεγενημένας ὁμολογίας, διεχωρίσθησαν, Αἰτωλοὶ μὲν εἰς τὴν οἰκείαν, Μάρκος δ’ εἰς τὴν Ἀμβρακίαν. κἀκεῖσε παραγενόμενος οὗτος μὲν ἐγίνετο περὶ τὸ περαιοῦν τὴν δύναμιν εἰς τὴν Κεφαλληνίαν, οἱ δ’ Αἰτωλοὶ προχειρισάμενοι Φαινέαν καὶ Νίκανδρον πρεσβευτὰς ἐξέπεμψαν εἰς τὴν Ῥώμην περὶ τῆς εἰρήνης· ἁπλῶς γὰρ οὐδὲν ἦν κύριον τῶν προειρημένων, εἰ μὴ καὶ τῷ δήμῳ δόξαι τῷ τῶν Ῥωμαίων.", "st": "21.30"}, {"sp": "N", "t": "οὗτοι μὲν οὖν παραλαβόντες τούς τε Ῥοδίους καὶ τοὺς Ἀθηναίους ἔπλεον ἐπὶ τὸ προκείμενον· παραπλησίως δὲ καὶ Μάρκος ἐξαπέστειλε Γάιον τὸν Οὐαλέριον καί τινας ἑτέρους τῶν φίλων πράξοντας τὰ περὶ τῆς εἰρήνης. ἀφικομένων δ’ εἰς τὴν Ῥώμην, πάλιν ἐκαινοποιήθη τὰ τῆς ὀργῆς πρὸς Αἰτωλοὺς διὰ Φιλίππου τοῦ βασιλέως· ἐκεῖνος γὰρ δοκῶν ἀδίκως ὑπὸ τῶν Αἰτωλῶν ἀφῃρῆσθαι τὴν Ἀθαμανίαν καὶ τὴν Δολοπίαν διεπέμψατο πρὸς τοὺς φίλους, ἀξιῶν αὐτοὺς συνοργισθῆναι καὶ μὴ προσδέξασθαι τὰς διαλύσεις. διὸ καὶ τῶν μὲν Αἰτωλῶν εἰσπορευθέντων παρήκουεν ἡ σύγκλητος, τῶν δὲ Ῥοδίων καὶ τῶν Ἀθηναίων ἀξιούντων ἐνετράπη καὶ προσέσχε τὸν νοῦν. καὶ γὰρ ἐδόκει μετὰ Δάμων’ ὁ Κιχησίου λέων ἄλλα τε καλῶς εἰπεῖν καὶ παραδείγματι πρὸς τὸ παρὸν οἰκείῳ χρήσασθαι κατὰ τὸν λόγον. ἔφη γὰρ ὀργίζεσθαι μὲν εἰκότως τοῖς Αἰτωλοῖς· πολλὰ γὰρ εὖ πεπονθότας τοὺς Αἰτωλοὺς ὑπὸ Ῥωμαίων οὐ χάριν ἀποδεδωκέναι τούτων, ἀλλ’ εἰς μέγαν ἐνηνοχέναι κίνδυνον τὴν Ῥωμαίων ἡγεμονίαν ἐκκαύσαντας τὸν πρὸς Ἀντίοχον πόλεμον· ἐν τούτῳ δὲ διαμαρτάνειν τὴν σύγκλητον, ἐν ᾧ τὴν ὀργὴν φέρειν ἐπὶ τοὺς πολλούς. εἶναι γὰρ τὸ συμβαῖνον ἐν ταῖς πολιτείαις περὶ τὰ πλήθη παραπλήσιον τῷ γινομένῳ περὶ τὴν θάλατταν. καὶ γὰρ ἐκείνην κατὰ μὲν τὴν αὑτῆς φύσιν ἀεί ποτ’ εἶναι γαληνὴν καὶ καθεστηκυῖαν καὶ συλλήβδην τοιαύτην ὥστε μηδέποτ’ ἂν ἐνοχλῆσαι μηδένα τῶν προσπελαζόντων αὐτῇ καὶ χρωμένων· ἐπειδὰν δ’ ἐμπεσόντες εἰς αὐτὴν ἄνεμοι βίαιοι ταράξωσι καὶ παρὰ φύσιν ἀναγκάσωσι κινεῖσθαι, τότε μηθὲν ἔτι δεινότερον εἶναι μηδὲ φοβερώτερον θαλάττης· ὃ καὶ νῦν τοῖς κατὰ τὴν Αἰτωλίαν συμπεσεῖν. \"ἕως μὲν γὰρ ἦσαν ἀκέραιοι, πάντων τῶν Ἑλλήνων ὑπῆρχον ὑμῖν εὐνούστατοι καὶ βεβαιότατοι συνεργοὶ πρὸς τὰς πράξεις· ἐπεὶ δ’ ἀπὸ μὲν τῆς Ἀσίας πνεύσαντες Θόας καὶ Δικαίαρχος, ἀπὸ δὲ τῆς Εὐρώπης Μενεστᾶς καὶ Δαμόκριτος συνετάραξαν τοὺς ὄχλους καὶ παρὰ φύσιν ἠνάγκασαν πᾶν καὶ λέγειν καὶ πράττειν, τότε δὴ κακῶς φρονοῦντες ἐβουλήθησαν μὲν ὑμῖν, ἐγένοντο δ’ αὑτοῖς αἴτιοι κακῶν. ἀνθ’ ὧν ὑμᾶς δεῖ πρὸς ἐκείνους ἔχειν ἀπαραιτήτως, ἐλεεῖν δὲ τοὺς πολλοὺς καὶ διαλύεσθαι πρὸς αὐτούς, εἰδότας ὅτι γενόμενοι πάλιν ἀκέραιοι, καὶ πρὸς τοῖς ἄλλοις ἔτι νῦν ὑφ’ ὑμῶν σωθέντες, εὐνούστατοι πάλιν ἔσονται πάντων Ἑλλήνων. \" ὁ μὲν οὖν Ἀθηναῖος ταῦτ’ εἰπὼν ἔπεισε τὴν σύγκλητον διαλύεσθαι πρὸς τοὺς Αἰτωλούς.", "st": "21.31"}, {"sp": "N", "t": "δόξαντος δὲ τῷ συνεδρίῳ, καὶ τοῦ δήμου συνεπιψηφίσαντος, ἐκυρώθη τὰ κατὰ τὰς διαλύσεις. τὰ δὲ κατὰ μέρος ἦν τῶν συνθηκῶν ταῦτα. \"ὁ δῆμος ὁ τῶν Αἰτωλῶν τὴν ἀρχὴν καὶ τὴν δυναστείαν τοῦ δήμου τῶν Ῥωμαίων. πολεμίους μὴ διιέτω διὰ τῆς χώρας καὶ τῶν πόλεων ἐπὶ Ῥωμαίους ἢ τοὺς συμμάχους καὶ φίλους αὐτῶν, μηδὲ χορηγείτω μηδὲν δημοσίᾳ βουλῇ. καὶ ἐὰν πολεμῶσιν πρός τινας Ῥωμαῖοι, πολεμείτω πρὸς αὐτοὺς ὁ δῆμος ὁ τῶν Αἰτωλῶν. τοὺς δὲ αὐτομόλους, τοὺς δραπέτας, τοὺς αἰχμαλώτους πάντας τοὺς Ῥωμαίων καὶ τῶν συμμάχων ἀποδότωσαν Αἰτωλοί, χωρὶς τῶν ὅσοι κατὰ πόλεμον ἁλόντες εἰς τὴν ἰδίαν ἀπῆλθον καὶ πάλιν ἑάλωσαν, καὶ χωρὶς τῶν ὅσοι πολέμιοι Ῥωμαίων ἐγένοντο, καθ’ ὃν καιρὸν Αἰτωλοὶ μετὰ Ῥωμαίων συνεπολέμουν, ἐν ἡμέραις ἑκατὸν ἀφ’ ἧς ἂν τὰ ὅρκια τελεσθῇ, τῷ ἄρχοντι τῷ ἐν Κερκύρᾳ· ἐὰν δὲ μὴ εὑρεθῶσίν τινες ἐν τῷ χρόνῳ τούτῳ, ὅταν ἐμφανεῖς γένωνται, τότε ἀποδότωσαν χωρὶς δόλου· καὶ τούτοις μετὰ τὰ ὅρκια μὴ ἔστω ἐπάνοδος εἰς τὴν Αἰτωλίαν. δότωσαν δὲ Αἰτωλοὶ ἀργυρίου μὴ χείρονος Ἀττικοῦ παραχρῆμα μὲν τάλαντα Εὐβοϊκὰ διακόσια τῷ στρατηγῷ τῷ ἐν τῇ Ἑλλάδι, ἀντὶ τρίτου μέρους τοῦ ἀργυρίου χρυσίον, ἐὰν βούλωνται, διδόντες, τῶν δέκα μνῶν ἀργυρίου χρυσίου μνᾶν διδόντες, ἀφ’ ἧς δ’ ἂν ἡμέρας τὰ ὅρκια τμηθῇ ἐν ἔτεσι τοῖς πρώτοις ἓξ κατὰ ἔτος ἕκαστον τάλαντα πεντήκοντα· καὶ τὰ χρήματα καθιστάτωσαν ἐν Ῥώμῃ. δότωσαν Αἰτωλοὶ ὁμήρους τῷ στρατηγῷ τετταράκοντα, μὴ νεωτέρους ἐτῶν δώδεκα μηδὲ πρεσβυτέρους τετταράκοντα, εἰς ἔτη ἕξ, οὓς ἂν Ῥωμαῖοι προκρίνωσιν, χωρὶς στρατηγοῦ καὶ ἱππάρχου καὶ δημοσίου γραμματέως καὶ τῶν ὡμηρευκότων ἐν Ῥώμῃ. καὶ τὰ ὅμηρα καθιστάτωσαν εἰς Ῥώμην· ἐὰν δέ τις ἀποθάνῃ τῶν ὁμήρων, ἄλλον ἀντικαθιστάτωσαν. περὶ δὲ Κεφαλληνίας μὴ ἔστω ἐν ταῖς συνθήκαις. ὅσαι χῶραι καὶ πόλεις καὶ ἄνδρες, οἷς οὗτοι ἐχρῶντο, ἐπὶ Λευκίου Κοϊντίου καὶ Γναΐου Δομετίου στρατηγῶν ἢ ὕστερον ἑάλωσαν ἢ εἰς φιλίαν ἦλθον Ῥωμαίοις, τούτων τῶν πόλεων καὶ τῶν ἐν ταύταις μηδένα προσλαβέτωσαν Αἰτωλοί. ἡ δὲ πόλις καὶ ἡ χώρα ἡ τῶν Οἰνιαδῶν Ἀκαρνάνων ἔστω.\" τμηθέντων δὲ τῶν ὁρκίων ἐπὶ τούτοις συνετετέλεστο τὰ τῆς εἰρήνης. καὶ τὰ μὲν κατὰ τοὺς Αἰτωλοὺς καὶ καθόλου τοὺς Ἕλληνας τοιαύτην ἔσχε τὴν ἐπιγραφήν. —", "st": "21.32"}, {"sp": "N", "t": "ὅτι καθ’ ὃν καιρὸν ἐν τῇ Ῥώμῃ τὰ περὶ τὰς συνθήκας τὰς πρὸς Ἀντίοχον καὶ καθόλου περὶ τῆς Ἀσίας αἱ πρεσβεῖαι διεπράττοντο, κατὰ δὲ τὴν Ἑλλάδα τὸ τῶν Αἰτωλῶν ἔθνος ἐπολεμεῖτο, κατὰ τοῦτον συνέβη τὸν περὶ τὴν Ἀσίαν πρὸς τοὺς Γαλάτας πόλεμον ἐπιτελεσθῆναι, περὶ οὗ νῦν ἐνιστάμεθα τὴν διήγησιν. — ὁ δὲ κατευδοκήσας τῷ νεανίσκῳ κατὰ τὴν ἀπάντησιν, τοῦτον ἀπέλυσε παραχρῆμ’ εἰς τὸ Πέργαμον. —", "st": "21.33"}, {"sp": "N", "t": "ὅτι Μοαγέτης ἦν τύραννος Κιβύρας, ὠμὸς γεγονὼς καὶ δόλιος, καὶ οὐκ ἄξιός ἐστιν ἐκ παραδρομῆς, ἀλλὰ μετ’ ἐπιστάσεως τυχεῖν τῆς ἁρμοζούσης μνήμης. — πλὴν συνεγγίζοντος Γναΐου ὑπάτου Ῥωμαίων τῇ Κιβύρᾳ, καὶ τοῦ Ἑλουίου πεμφθέντος εἰς ἀπόπειραν ἐπὶ τίνος ἐστὶ γνώμης, πρεσβευτὰς ἐξέπεμψε, παρακαλῶν μὴ φθεῖραι τὴν χώραν, ὅτι φίλος ὑπάρχει Ῥωμαίων καὶ πᾶν ποιήσει τὸ παραγγελλόμενον. καὶ ταῦτα λέγων ἅμα προύτεινε στέφανον ἀπὸ πεντεκαίδεκα ταλάντων. ὧν ἀκούσας αὐτὸς μὲν ἀφέξεσθαι τῆς χώρας ἔφη, πρὸς δὲ τὸν στρατηγὸν ἐκέλευσε πρεσβεύειν ὑπὲρ τῶν ὅλων· ἕπεσθαι γὰρ αὐτὸν μετὰ τῆς στρατείας κατὰ πόδας. γενομένου δὲ τούτου, καὶ πέμψαντος τοῦ Μοαγέτου μετὰ τῶν πρεσβευτῶν καὶ τὸν ἀδελφόν, ἀπαντήσας κατὰ πορείαν ὁ Γνάιος ἀνατατικῶς καὶ πικρῶς ὡμίλησε τοῖς πρεσβευταῖς, φάσκων οὐ μόνον ἀλλοτριώτατον γεγονέναι Ῥωμαίων τὸν Μοαγέτην πάντων τῶν κατὰ τὴν Ἀσίαν δυναστῶν, ἀλλὰ καὶ κατὰ τὴν ῥώμην ὅλην εἰς καθαίρεσιν τῆς ἀρχῆς καὶ ἐπιστροφῆς εἶναι καὶ κολάσεως. οἱ δὲ πρεσβευταὶ καταπλαγέντες τὴν ἐπίφασιν τῆς ὀργῆς τῶν μὲν ἄλλων ἐντολῶν ἀπέστησαν, ἠξίουν δ’ αὐτὸν εἰς λόγους ἐλθεῖν. συγχωρήσαντος δὲ τότε μὲν ἐπανῆλθον εἰς τὴν Κιβύραν, εἰς δὲ τὴν ἐπαύριον ἐξῆλθεν μετὰ τῶν φίλων ὁ τύραννος κατά τε τὴν ἐσθῆτα καὶ τὴν ἄλλην προστασίαν λιτὸς καὶ ταπεινός, ἔν τε τοῖς ἀπολογισμοῖς κατολοφυρόμενος τὴν ἀδυναμίαν τὴν αὑτοῦ καὶ τὴν ἀσθένειαν ὧν ἐπῆρχε πόλεων, καὶ πρὸς τούτοις ἠξίου προσδέξασθαι τὰ πεντεκαίδεκα τάλαντα τὸν Γνάιον· ἐκράτει δὲ τῆς Κιβύρας καὶ Συλείου καὶ τῆς ἐν Λίμνῃ πόλεως. ὁ δὲ Γνάιος καταπλαγεὶς τὴν ἀπόνοιαν ἄλλο μὲν οὐδὲν εἶπε πρὸς αὐτόν, ἐὰν δὲ μὴ διδῷ πεντακόσια τάλαντα μετὰ μεγάλης χάριτος, οὐ τὴν χώραν ἔφη φθερεῖν, ἀλλὰ τὴν πόλιν αὐτὴν πολιορκήσειν καὶ διαρπάσειν. ὅθεν ὁ Μοαγέτης κατορρωδήσας τὸ μέλλον ἐδεῖτο μηδὲν ποιῆσαι τοιοῦτον, καὶ προσετίθει κατὰ βραχὺ τῶν χρημάτων, καὶ τέλος ἔπεισε τὸν Γνάιον ἑκατὸν τάλαντα καὶ μυρίους μεδίμνους λαβόντα πυρῶν προσδέξασθαι πρὸς τὴν φιλίαν αὐτόν. —", "st": "21.34"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν ἡνίκα Γνάιος διῄει τὸν Κολοβάτον προσαγορευόμενον ποταμόν, ἦλθον πρὸς αὐτὸν πρέσβεις ἐκ τῆς Ἰσίνδης προσαγορευομένης πόλεως, δεόμενοι σφίσι βοηθῆσαι· τοὺς γὰρ Τερμησσεῖς, ἐπισπασαμένους Φιλόμηλον, τήν τε χώραν ἔφασαν αὑτῶν ἀνάστατον πεποιηκέναι καὶ τὴν πόλιν διηρπακέναι, νῦν τε πολιορκεῖν τὴν ἄκραν, συμπεφευγότων εἰς αὐτὴν πάντων τῶν πολιτῶν ὁμοῦ γυναιξὶ καὶ τέκνοις. ὧν διακούσας ὁ Γνάιος ἐκείνοις μὲν ὑπέσχετο βοηθήσειν μετὰ μεγάλης χάριτος, αὐτὸς δὲ νομίσας ἑρμαῖον εἶναι τὸ προσπεπτωκὸς ἐποιεῖτο τὴν πορείαν ὡς ἐπὶ τῆς Παμφυλίας. ὁ δὲ Γνάιος συνεγγίσας τῇ Τερμησσῷ, πρὸς μὲν τούτους συνέθετο φιλίαν, λαβὼν πεντήκοντα τάλαντα, παραπλησίως δὲ καὶ πρὸς Ἀσπενδίους. ἀποδεξάμενος δὲ καὶ τοὺς παρὰ τῶν ἄλλων πόλεων πρεσβευτὰς κατὰ τὴν Παμφυλίαν καὶ τὴν προειρημένην δόξαν ἐνεργασάμενος ἑκάστοις κατὰ τὰς ἐντεύξεις, ἅμα δὲ καὶ τοὺς Ἰσινδεῖς ἐξελόμενος ἐκ τῆς πολιορκίας, αὖθις ἐποιεῖτο τὴν πορείαν ὡς ἐπὶ τοὺς Γαλάτας. —", "st": "21.35"}, {"sp": "N", "t": "ὅτι Κύρμασα πόλιν λαβὼν ὁ Γνάιος καὶ λείαν ἄφθονον ἀνέζευξεν. προαγόντων δ’ αὐτῶν παρὰ τὴν λίμνην, παρεγένοντο πρέσβεις ἐκ Λυσινόης διδόντες αὑτοὺς εἰς τὴν πίστιν. οὓς προσδεξάμενος ἐνέβαλεν εἰς τὴν τῶν Σαγαλασσέων γῆν καὶ πολὺ πλῆθος ἐξελασάμενος λείας ἀπεκαραδόκει τοὺς ἐκ τῆς πόλεως ἐπὶ τίνος ἔσονται γνώμης. παραγενομένων δὲ πρεσβευτῶν ὡς αὐτόν, ἀποδεξάμενος τοὺς ἄνδρας καὶ λαβὼν πεντήκοντα ταλάντων στέφανον καὶ δισμυρίους κριθῶν μεδίμνους καὶ δισμυρίους πυρῶν, προσεδέξατο τούτους εἰς τὴν φιλίαν. —", "st": "21.36"}, {"sp": "N", "t": "ὅτι Γνάιος ὁ στρατηγὸς τῶν Ῥωμαίων πρέσβεις ἐξαπέστειλε πρὸς τὸν Ἐποσόγνατον τὸν Γαλάτην, ὅπως πρεσβεύσῃ πρὸς τοὺς τῶν Γαλατῶν βασιλεῖς. καὶ [ὁ] Ἐποσόγνατος ἔπεμψε πρὸς Γνάιον πρέσβεις καὶ παρεκάλει [τὸν Γνάιον] τὸν τῶν Ῥωμαίων στρατηγὸν μὴ προεξαναστῆναι μηδ’ ἐπιβαλεῖν χεῖρας τοῖς Τολιστοβογίοις Γαλάταις, καὶ διότι πρεσβεύσει πρὸς τοὺς βασιλεῖς αὐτῶν Ἐποσόγνατος καὶ ποιήσεται λόγους ὑπὲρ τῆς φιλίας, καὶ πεπεῖσθαι πρὸς πᾶν αὐτοὺς παραστήσεσθαι τὸ καλῶς ἔχον. — Γνάιος ὁ ὕπατος Ῥωμαίων διερχόμενος ἐγεφύρωσε τὸν Σαγγάριον ποταμόν, τελέως κοῖλον ὄντα καὶ δύσβατον. καὶ παρ’ αὐτὸν τὸν ποταμὸν στρατοπεδευσαμένου παραγίνονται Γάλλοι παρ’ Ἄττιδος καὶ Βαττάκου τῶν ἐκ Πεσσινοῦντος ἱερέων τῆς Μητρὸς τῶν θεῶν, ἔχοντες προστηθίδια καὶ τύπους, φάσκοντες προσαγγέλλειν τὴν θεὸν νίκην καὶ κράτος. οὓς ὁ Γνάιος φιλανθρώπως ὑπεδέξατο. — ὄντος δὲ τοῦ Γναΐου πρὸς τὸ πολισμάτιον τὸ καλούμενον Γορδίειον, ἧκον παρ’ Ἐποσογνάτου πρέσβεις ἀποδηλοῦντες ὅτι πορευθεὶς διαλεχθείη τοῖς τῶν Γαλατῶν βασιλεῦσιν, οἱ δ’ ἁπλῶς εἰς οὐδὲν συγκαταβαίνοιεν φιλάνθρωπον, ἀλλ’ ἡθροικότες ὁμοῦ τέκνα καὶ γυναῖκας καὶ τὴν ἄλλην κτῆσιν ἅπασαν εἰς τὸ καλούμενον ὄρος Ὄλυμπον ἕτοιμοι πρὸς μάχην εἰσίν. —", "st": "21.37"}, {"sp": "N", "t": "Χιομάραν δὲ συνέβη τὴν Ὀρτιάγοντος αἰχμάλωτον γενέσθαι μετὰ τῶν ἄλλων γυναικῶν, ὅτε Ῥωμαῖοι καὶ Γνάιος ἐνίκησαν μάχῃ τοὺς ἐν Ἀσίᾳ Γαλάτας. ὁ δὲ λαβὼν αὐτὴν ταξίαρχος ἐχρήσατο τῇ τύχῃ στρατιωτικῶς καὶ κατῄσχυνεν. ἦν δ’ ἄρα καὶ πρὸς ἡδονὴν καὶ ἀργύριον ἀμαθὴς καὶ ἀκρατὴς ἄνθρωπος, ἡττήθη δ’ ὅμως ὑπὸ τῆς φιλαργυρίας, καὶ χρυσίου συχνοῦ διομολογηθέντος ὑπὲρ τῆς γυναικὸς ἦγεν αὐτὴν ἀπολυτρώσων, ποταμοῦ τινος ἐν μέσῳ διείργοντος. ὡς δὲ διαβάντες οἱ Γαλάται τὸ χρυσίον ἔδωκαν αὐτῷ καὶ παρελάμβανον τὴν Χιομάραν, ἡ μὲν ἀπὸ νεύματος προσέταξεν ἑνὶ παῖσαι τὸν Ῥωμαῖον ἀσπαζόμενον αὐτὴν καὶ φιλοφρονούμενον, ἐκείνου δὲ πεισθέντος καὶ τὴν κεφαλὴν ἀποκόψαντος, ἀραμένη καὶ περιστείλασα τοῖς κόλποις ἀπήλαυνεν. ὡς δ’ ἦλθε πρὸς τὸν ἄνδρα καὶ τὴν κεφαλὴν αὐτῷ προύβαλεν, ἐκείνου θαυμάσαντος καὶ εἰπόντος \"ὦ γύναι, καλὸν ἡ πίστις\" \"ναί\", εἶπεν \"ἀλλὰ κάλλιον ἕνα μόνον ζῆν ἐμοὶ συγγεγενημένον\". ταύτῃ μὲν ὁ Πολύβιός φησι διὰ λόγων ἐν Σάρδεσι γενόμενος θαυμάσαι τό τε φρόνημα καὶ τὴν σύνεσιν. —", "st": "21.38"}, {"sp": "N", "t": "ὅτι τῶν Ῥωμαίων μετὰ τὴν τῶν Γαλατῶν νίκην αὐτῶν πραχθεῖσαν στρατοπεδευόντων περὶ τὴν Ἄγκυραν πόλιν, καὶ τοῦ Γναΐου τοῦ στρατηγοῦ προάγειν εἰς τοὔμπροσθεν μέλλοντος, παραγίνονται πρέσβεις παρὰ τῶν Τεκτοσάγων, ἀξιοῦντες τὸν Γνάιον τὰς μὲν δυνάμεις ἐᾶσαι κατὰ χώραν, αὐτὸν δὲ κατὰ τὴν ἐπιοῦσαν ἡμέραν προελθεῖν εἰς τὸν μεταξὺ τόπον τῶν στρατοπέδων· ἥξειν δὲ καὶ τοὺς παρ’ αὑτῶν βασιλεῖς κοινολογησομένους ὑπὲρ τῶν διαλύσεων. τοῦ δὲ Γναΐου συγκαταθεμένου καὶ παραγενηθέντος κατὰ τὸ συνταχθὲν μετὰ πεντακοσίων ἱππέων, τότε μὲν οὐκ ἦλθον οἱ βασιλεῖς· ἀνακεχωρηκότος δ’ αὐτοῦ πρὸς τὴν ἰδίαν παρεμβολήν, αὖθις ἧκον οἱ πρέσβεις ὑπὲρ μὲν τῶν βασιλέων σκήψεις τινὰς λέγοντες, ἀξιοῦντες δὲ πάλιν ἐλθεῖν αὐτόν, ἐπειδὴ τοὺς πρώτους ἄνδρας ἐκπέμψουσιν κοινολογησομένους ὑπὲρ τῶν ὅλων. ὁ δὲ Γνάιος κατανεύσας ἥξειν αὐτὸς μὲν ἔμεινεν ἐπὶ τῆς ἰδίας στρατοπεδείας, Ἄτταλον δὲ καὶ τῶν χιλιάρχων τινὰς ἐξαπέστειλεν μετὰ τριακοσίων ἱππέων. οἱ δὲ τῶν Γαλατῶν πρέσβεις ἦλθον μὲν κατὰ τὸ συνταχθὲν καὶ λόγους ἐποιήσαντο περὶ τῶν πραγμάτων, τέλος δ’ ἐπιθεῖναι τοῖς προειρημένοις ἢ κυρῶσαί τι τῶν δοξάντων οὐκ ἔφασαν εἶναι δυνατόν· τοὺς δὲ βασιλεῖς τῇ κατὰ πόδας ἥξειν διωρίζοντο, συνθησομένους καὶ πέρας ἐπιθήσοντας, εἰ καὶ Γνάιος ὁ στρατηγὸς ἔλθοι πρὸς αὐτούς. τῶν δὲ περὶ τὸν Ἄτταλον ἐπαγγειλαμένων ἥξειν τὸν Γνάιον, τότε μὲν ἐπὶ τούτοις διελύθησαν. ἐποιοῦντο δὲ τὰς ὑπερθέσεις ταύτας οἱ Γαλάται καὶ διεστρατήγουν τοὺς Ῥωμαίους βουλόμενοι τῶν τε σωμάτων τινὰ τῶν ἀναγκαίων καὶ τῶν χρημάτων ὑπερθέσθαι πέραν Ἅλυος ποταμοῦ, μάλιστα δὲ τὸν στρατηγὸν τῶν Ῥωμαίων, εἰ δυνηθεῖεν, λαβεῖν ὑποχείριον· εἰ δὲ μή γε, πάντως ἀποκτεῖναι. ταῦτα δὲ προθέμενοι κατὰ τὴν ἐπιοῦσαν ἐκαραδόκουν τὴν παρουσίαν τῶν Ῥωμαίων, ἑτοίμους ἔχοντες ἱππεῖς εἰς χιλίους. ὁ δὲ Γνάιος διακούσας τῶν περὶ τὸν Ἄτταλον καὶ πεισθεὶς ἥξειν τοὺς βασιλεῖς, ἐξῆλθεν, καθάπερ εἰώθει, μετὰ πεντακοσίων ἱππέων. συνέβη δὲ ταῖς πρότερον ἡμέραις τοὺς ἐπὶ τὰς ξυλείας καὶ χορτολογίας ἐκπορευομένους ἐκ τοῦ τῶν Ῥωμαίων χάρακος ἐπὶ ταῦτα τὰ μέρη πεποιῆσθαι τὴν ἔξοδον, ἐφεδρείᾳ χρωμένους τοῖς ἐπὶ τὸν σύλλογον πορευομένοις ἱππεῦσιν. οὗ καὶ τότε γενομένου καὶ πολλῶν ἐξεληλυθότων, συνέταξαν οἱ χιλίαρχοι καὶ τοὺς εἰθισμένους ἐφεδρεύειν τοῖς προνομεύουσιν ἱππεῖς ἐπὶ ταῦτα τὰ μέρη ποιήσασθαι τὴν ἔξοδον. ὧν ἐκπορευθέντων, αὐτομάτως τὸ δέον ἐγενήθη πρὸς τὴν ἐπιφερομένην χρείαν. —", "st": "21.39"}, {"sp": "N", "t": "ὁ δὲ Φολούιος πραξικοπήσας νυκτὸς κατέλαβε τὸ μέρος τῆς ἀκροπόλεως καὶ τοὺς Ῥωμαίους εἰσήγαγε. —", "st": "21.40"}, {"sp": "N", "t": "ὅτι τὸ καλὸν καὶ τὸ συμφέρον σπανίως εἴωθε συντρέχειν, καὶ σπάνιοι τῶν ἀνδρῶν εἰσιν οἱ δυνάμενοι ταῦτα συνάγειν καὶ συναρμόζειν πρὸς ἄλληλα. κατὰ μὲν γὰρ τὸ πολὺ πάντες ἴσμεν διότι τό τε καλὸν φεύγει τὴν τοῦ παραυτίκα λυσιτελοῦς φύσιν καὶ τὸ λυσιτελὲς τὴν τοῦ καλοῦ. πλὴν ὁ Φιλοποίμην προέθετο ταῦτα καὶ καθίκετο τῆς ἐπιβολῆς· καλὸν μὲν γὰρ τὸ κατάγειν τοὺς αἰχμαλώτους φυγάδας εἰς τὴν Σπάρτην, συμφέρον δὲ τὸ ταπεινῶσαι τὴν τῶν Λακεδαιμονίων πόλιν, καταφονεύσαντα τοὺς δεδορυφορηκότας τῇ τῶν τυράννων δυναστείᾳ. θεωρῶν δ’ ὅτι πάσης βασιλείας ἐπανορθώσεως αἴτια τὰ χρήματα γέγονεν, ἅτε φύσει νουνεχὴς ὢν καὶ στρατηγικός, περιεβα … γένοιτο κομιδὴ τῶν ἔξω ποριζομένων χρημάτων.", "st": "21.41"}, {"sp": "N", "t": "ἐν … η … τῆς πράξεως τῆς περὶ τὸν Ἀριαράθην εἰς τὴν παροιμίαν· ἔχοντες γὰρ π … διετε … οι τοῖς πολεμίοις ἐγένοντο.", "st": "21.42"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς καιροὺς τούτους κατὰ τὴν Ἀσίαν Γναΐου τοῦ τῶν Ῥωμαίων στρατηγοῦ παραχειμάζοντος ἐν Ἐφέσῳ, κατὰ τὸν τελευταῖον ἐνιαυτὸν τῆς ὑποκειμένης ὀλυμπιάδος, παρεγένοντο πρεσβεῖαι παρά τε τῶν Ἑλληνίδων πόλεων τῶν ἐπὶ τῆς Ἀσίας καὶ παρ’ ἑτέρων πλειόνων, συμφοροῦσαι στεφάνους τῷ Γναΐῳ διὰ τὸ νενικηκέναι τοὺς Γαλάτας. ἅπαντες γὰρ οἱ τὴν ἐπὶ τάδε τοῦ Ταύρου κατοικοῦντες οὐχ οὕτως ἐχάρησαν Ἀντιόχου λειφθέντος ἐπὶ τῷ δοκεῖν ἀπολελύσθαι τινὲς μὲν φόρων, οἱ δὲ φρουρᾶς, καθόλου δὲ πάντες βασιλικῶν προσταγμάτων, ὡς ἐπὶ τῷ τὸν ἀπὸ τῶν βαρβάρων αὐτοῖς φόβον ἀφῃρῆσθαι καὶ δοκεῖν ἀπηλλάχθαι τῆς τούτων ὕβρεως καὶ παρανομίας. ἦλθε δὲ καὶ παρ’ Ἀντιόχου Μουσαῖος καὶ παρὰ τῶν Γαλατῶν πρεσβευταί, βουλόμενοι μαθεῖν ἐπὶ τίσιν αὐτοὺς δεῖ ποιεῖσθαι τὴν φιλίαν. ὁμοίως δὲ καὶ παρ’ Ἀριαράθου τοῦ τῶν Καππαδοκῶν βασιλέως· καὶ γὰρ οὗτος, μετασχὼν Ἀντιόχῳ τῶν αὐτῶν ἐλπίδων καὶ κοινωνήσας τῆς πρὸς Ῥωμαίους μάχης, ἐδεδίει καὶ διηπορεῖτο περὶ τῶν καθ’ αὑτόν. διὸ καὶ πλεονάκις πέμπων πρεσβευτὰς ἐβούλετο μαθεῖν τί δοὺς ἢ τί πράξας δύναιτ’ ἂν παραιτήσασθαι τὴν σφετέραν ἄγνοιαν. ὁ δὲ στρατηγὸς τὰς μὲν παρὰ τῶν πόλεων πρεσβείας πάσας ἐπαινέσας καὶ φιλανθρώπως ἀποδεξάμενος ἐξαπέστειλε, τοῖς δὲ Γαλάταις ἀπεκρίθη διότι προσδεξάμενος Εὐμένη τὸν βασιλέα, τότε ποιήσεται τὰς πρὸς αὐτοὺς συνθήκας. τοῖς δὲ περὶ Ἀριαράθην εἶπεν ἑξακόσια τάλαντα δόντας τὴν εἰρήνην ἔχειν. πρὸς δὲ τὸν Ἀντιόχου πρεσβευτὴν συνετάξατο μετὰ τῆς δυνάμεως ἥξειν ἐπὶ τοὺς τῆς Παμφυλίας ὅρους, τά τε δισχίλια τάλαντα καὶ πεντακόσια κομιούμενος καὶ τὸν σῖτον ὃν ἔδει δοῦναι τοῖς στρατιώταις αὐτοῦ πρὸ τῶν συνθηκῶν κατὰ τὰς πρὸς Λεύκιον ὁμολογίας. μετὰ δὲ ταῦτα καθαρμὸν ποιησάμενος τῆς δυνάμεως, καὶ τῆς ὥρας παραδιδούσης, παραλαβὼν Ἄτταλον ἀνέζευξεν καὶ παραγενόμενος εἰς Ἀπάμειαν ὀγδοαῖος ἐπέμεινε τρεῖς ἡμέρας, κατὰ δὲ τὴν τετάρτην ἀναζεύξας προῆγε, χρώμενος ἐνεργοῖς ταῖς πορείαις. ἀφικόμενος δὲ τριταῖος εἰς τὸν συνταχθέντα τόπον τοῖς περὶ Ἀντίοχον, αὐτοῦ κατεστρατοπέδευσε. συμμιξάντων δὲ τῶν περὶ τὸν Μουσαῖον καὶ παρακαλούντων αὐτὸν ἐπιμεῖναι, διότι καθυστεροῦσιν αἵ θ’ ἅμαξαι καὶ τὰ κτήνη τὰ παρακομίζοντα τὸν σῖτον καὶ τὰ χρήματα, πεισθεὶς τούτοις ἐπέμεινε τρεῖς ἡμέρας. τῆς δὲ χορηγίας ἐλθούσης τὸν μὲν σῖτον ἐμέτρησε ταῖς δυνάμεσι, τὰ δὲ χρήματα παραδούς τινι τῶν χιλιάρχων συνέταξεν παρακομίζειν εἰς Ἀπάμειαν.", "st": "21.43"}, {"sp": "N", "t": "αὐτὸς δὲ πυνθανόμενος τὸν ἐπὶ τῆς Πέργης καθεσταμένον ὑπ’ Ἀντιόχου φρούραρχον οὔτε τὴν φρουρὰν ἐξάγειν οὔτ’ αὐτὸν ἐκχωρεῖν ἐκ τῆς πόλεως, ὥρμησε μετὰ τῆς δυνάμεως ἐπὶ τὴν Πέργην. ἐγγίζοντος δ’ αὐτοῦ τῇ πόλει, παρῆν ἀπαντῶν ὁ τεταγμένος ἐπὶ τῆς φρουρᾶς, ἀξιῶν καὶ δεόμενος μὴ προκαταγινώσκειν αὑτοῦ· ποιεῖν γὰρ ἕν τι τῶν καθηκόντων· παραλαβὼν γὰρ ἐν πίστει παρ’ Ἀντιόχου τὴν πόλιν τηρεῖν ἔφη ταύτην, ἕως ἂν διασαφηθῇ πάλιν παρὰ τοῦ πιστεύσαντος τί δεῖ ποιεῖν· μέχρι δὲ τοῦ νῦν ἁπλῶς οὐδὲν αὐτῷ παρ’ οὐδενὸς ἀποδεδηλῶσθαι. διόπερ ἠξίου τριάκονθ’ ἡμέρας χάριν τοῦ διαπεμψάμενος ἐρέσθαι τὸν βασιλέα τί δεῖ πράττειν. ὁ δὲ Γνάιος, θεωρῶν τὸν Ἀντίοχον ἐν πᾶσι τοῖς ἄλλοις εὐσυνθετοῦντα, συνεχώρησε πέμπειν καὶ πυνθάνεσθαι τοῦ βασιλέως· καὶ μετά τινας ἡμέρας πυθόμενος παρέδωκε τὴν πόλιν. κατὰ δὲ τὸν καιρὸν τοῦτον οἱ δέκα πρεσβευταὶ καὶ [ὁ] βασιλεὺς Εὐμένης εἰς Ἔφεσον κατέπλευσαν, ἤδη τῆς θερείας ἐναρχομένης· καὶ δύ’ ἡμέρας ἐκ τοῦ πλοῦ προσαναλαβόντες αὑτοὺς ἀνέβαινον εἰς τὴν Ἀπάμειαν. ὁ δὲ Γνάιος, προσπεσούσης αὐτῷ τῆς τούτων παρουσίας, Λεύκιον μὲν τὸν ἀδελφὸν μετὰ τετρακισχιλίων ἐξαπέστειλε πρὸς τοὺς Ὀροανδεῖς, πειθανάγκης ἔχοντας διάθεσιν χάριν τοῦ κομίσασθαι τὰ προσοφειλόμενα τῶν ὁμολογηθέντων χρημάτων, αὐτὸς δὲ μετὰ τῆς δυνάμεως ἀναζεύξας ἠπείγετο, σπεύδων συνάψαι τοῖς περὶ τὸν Εὐμένη. παραγενόμενος δ’ εἰς τὴν Ἀπάμειαν καὶ καταλαβὼν τόν τε βασιλέα καὶ τοὺς δέκα, συνήδρευεν περὶ τῶν πραγμάτων. ἔδοξεν οὖν αὐτοῖς κυρῶσαι πρῶτον τὰ πρὸς Ἀντίοχον ὅρκια καὶ τὰς συνθήκας, ὑπὲρ ὧν οὐδὲν ἂν δέοι πλείω διατίθεσθαι λόγον, ἀλλ’ ἐξ αὐτῶν τῶν ἐγγράπτων ποιεῖσθαι τὰς διαλήψεις.", "st": "21.44"}, {"sp": "N", "t": "ἦν δὲ τοιαύτη τις ἡ τῶν κατὰ μέρος διάταξις· φιλίαν ὑπάρχειν Ἀντιόχῳ καὶ Ῥωμαίοις εἰς ἅπαντα τὸν χρόνον ποιοῦντι τὰ κατὰ τὰς συνθήκας. μὴ διιέναι βασιλέα Ἀντίοχον καὶ τοὺς ὑποταττομένους διὰ τῆς αὑτῶν χώρας ἐπὶ Ῥωμαίους καὶ τοὺς συμμάχους πολεμίους μηδὲ χορηγεῖν αὐτοῖς μηδέν· ὁμοίως δὲ καὶ Ῥωμαίους καὶ τοὺς συμμάχους ἐπ’ Ἀντίοχον καὶ τοὺς ὑπ’ ἐκεῖνον ταττομένους. μὴ πολεμῆσαι δὲ Ἀντίοχον τοῖς ἐπὶ ταῖς νήσοις μηδὲ τοῖς κατὰ τὴν Εὐρώπην. ἐκχωρείτω δὲ πόλεων καὶ χώρας. μὴ ἐξαγέτω μηδὲν πλὴν τῶν ὅπλων ὧν φέρουσιν οἱ στρατιῶται· εἰ δέ τι τυγχάνουσιν ἀπενηνεγμένοι, καθιστάτωσαν πάλιν εἰς τὰς αὐτὰς πόλεις. μηδ’ ὑποδεχέσθωσαν τοὺς ἐκ τῆς Εὐμένους τοῦ βασιλέως μήτε στρατιώτας μήτ’ ἄλλον μηδένα. εἰ δέ τινες ἐξ ὧν ἀπολαμβάνουσιν οἱ Ῥωμαῖοι πόλεων μετὰ δυνάμεώς εἰσιν Ἀντιόχου, τούτους εἰς Ἀπάμειαν ἀποκαταστησάτωσαν. τοῖς δὲ Ῥωμαίοις καὶ τοῖς συμμάχοις εἴ τινες εἶεν ἐκ τῆς Ἀντιόχου βασιλείας, εἶναι τὴν ἐξουσίαν καὶ μένειν, εἰ βούλονται, καὶ ἀποτρέχειν. τοὺς δὲ δούλους Ῥωμαίων καὶ τῶν συμμάχων ἀποδότω Ἀντίοχος καὶ οἱ ὑπ’ αὐτὸν ταττόμενοι, καὶ τοὺς ἁλόντας καὶ τοὺς αὐτομολήσαντας, καὶ εἴ τινα αἰχμάλωτόν ποθεν εἰλήφασιν. ἀποδότω δὲ Ἀντίοχος, ἐὰν ᾖ δυνατὸν αὐτῷ, καὶ Ἀννίβαν Ἀμίλκου Καρχηδόνιον καὶ Μνασίλοχον Ἀκαρνᾶνα καὶ Θόαντα Αἰτωλόν, καὶ Εὐβουλίδαν καὶ Φίλωνα Χαλκιδεῖς, καὶ τῶν Αἰτωλῶν ὅσοι κοινὰς εἰλήφασιν ἀρχάς, καὶ τοὺς ἐλέφαντας τοὺς ἐν Ἀπαμείᾳ πάντας, καὶ μηκέτι ἄλλους ἐχέτω. ἀποδότω δὲ καὶ τὰς ναῦς τὰς μακρὰς καὶ τὰ ἐκ τούτων ἄρμενα καὶ τὰ σκεύη, καὶ μηκέτι ἐχέτω πλὴν δέκα καταφράκτων· μηδὲ λέμβον πλείοσι τριάκοντα κωπῶν ἐχέτω ἐλαυνόμενον, μηδὲ μονήρη πολέμου ἕνεκεν, οὗ αὐτὸς κατάρχει. μηδὲ πλείτωσαν ἐπὶ τάδε τοῦ Καλυκάδνου καὶ Σαρπηδονίου ἀκρωτηρίου, εἰ μὴ φόρους ἢ πρέσβεις ἢ ὁμήρους ἄγοιεν. μὴ ἐξέστω δὲ Ἀντιόχῳ μηδὲ ξενολογεῖν ἐκ τῆς ὑπὸ Ῥωμαίους ταττομένης μηδ’ ὑποδέχεσθαι τοὺς φεύγοντας. ὅσαι δὲ οἰκίαι Ῥοδίων ἢ τῶν συμμάχων ἦσαν ἐν τῇ ὑπὸ βασιλέα Ἀντίοχον ταττομένῃ ταύτας εἶναι Ῥοδίων, ὡς καὶ πρὸ τοῦ τὸν πόλεμον ἐξενεγκεῖν. καὶ εἴ τι χρῆμα ὀφείλετ’ αὐτοῖς, ὁμοίως ἔστω πράξιμον· καὶ εἴ τι ἀπελήφθη ἀπ’ αὐτῶν, ἀναζητηθὲν ἀποδοθήτω. ἀτελῆ δὲ ὁμοίως ὡς καὶ πρὸ τοῦ πολέμου τὰ πρὸς τοὺς Ῥοδίους ὑπαρχέτω. εἰ δέ τινας τῶν πόλεων, ἃς ἀποδοῦναι δεῖ Ἀντίοχον, ἑτέροις δέδωκεν Ἀντίοχος, ἐξαγέτω καὶ ἐκ τούτων τὰς φρουρὰς καὶ τοὺς ἄνδρας. ἐὰν δέ τινες ὕστερον ἀποτρέχειν βούλωνται, μὴ προσδεχέσθω. ἀργυρίου δὲ δότω Ἀντίοχος Ἀττικοῦ Ῥωμαίοις ἀρίστου τάλαντα μύρια δισχίλια ἐν ἔτεσι δώδεκα, διδοὺς καθ’ ἕκαστον ἔτος χίλια· μὴ ἔλαττον δ’ ἑλκέτω τὸ τάλαντον λιτρῶν Ῥωμαϊκῶν ὀγδοήκοντα· καὶ μοδίους σίτου πεντηκοντακισμυρίους καὶ τετρακισμυρίους. δότω δὲ Εὐμένει τῷ βασιλεῖ τάλαντα τριακόσια πεντήκοντα ἐν ἔτεσι τοῖς πρώτοις πέντε, ἑβδομήκοντα κατὰ τὸ ἔτος, τῷ ἐπιβαλλομένῳ καιρῷ, ᾧ καὶ τοῖς Ῥωμαίοις ἀποδίδωσι, καὶ τοῦ σίτου, καθὼς ἐτίμησεν ὁ βασιλεὺς Ἀντίοχος, τάλαντα ἑκατὸν εἴκοσιν ἑπτὰ καὶ δραχμὰς χιλίας διακοσίας ὀκτώ· ἃ συνεχώρησεν Εὐμένης λαβεῖν, γάζαν εὐαρεστουμένην ἑαυτῷ. ὁμήρους δὲ εἴκοσι διδότω Ἀντίοχος, δι’ ἐτῶν τριῶν ἄλλους ἀνταποστέλλων, μὴ νεωτέρους ἐτῶν ὀκτωκαίδεκα μηδὲ πρεσβυτέρους τετταράκοντα πέντε. ἐὰν δέ τι διαφωνήσῃ τῶν ἀποδιδομένων χρημάτων, τῷ ἐχομένῳ ἔτει ἀποδότωσαν. ἂν δέ τινες τῶν πόλεων ἢ τῶν ἐθνῶν, πρὸς ἃ γέγραπται μὴ πολεμεῖν Ἀντίοχον, πρότεροι ἐκφέρωσι πόλεμον, ἐξέστω πολεμεῖν Ἀντιόχῳ. τῶν δὲ ἐθνῶν καὶ πόλεων τούτων μὴ ἐχέτω τὴν κυρίαν αὐτὸς μηδ’ εἰς φιλίαν προσαγέσθω. περὶ δὲ τῶν ἀδικημάτων τῶν πρὸς ἀλλήλους γινομένων εἰς κρίσιν προκαλείσθωσαν. ἐὰν δέ τι θέλωσι πρὸς τὰς συνθήκας ἀμφότεροι κοινῷ δόγματι προστεθῆναι ἢ ἀφαιρεθῆναι ἀπ’ αὐτῶν, ἐξέστω.", "st": "21.45"}, {"sp": "N", "t": "τμηθέντων δὲ τῶν ὁρκίων ἐπὶ τούτοις, εὐθέως ὁ στρατηγὸς Κόιντον Μινύκιον Θέρμον καὶ Λεύκιον τὸν ἀδελφόν, ἄρτι κεκομικότα τὰ χρήματα παρὰ τῶν Ὀροανδέων, εἰς Συρίαν ἐξαπέστειλε, συντάξας κομίζεσθαι τοὺς ὅρκους παρὰ τοῦ βασιλέως καὶ διαβεβαιώσασθαι τὰ κατὰ μέρος ὑπὲρ τῶν συνθηκῶν. πρὸς δὲ Κόιντον Φάβιον τὸν ἐπὶ τοῦ ναυτικοῦ στρατηγὸν ἐξέπεμψε γραμματοφόρους, κελεύων πάλιν πλεῖν αὐτὸν εἰς Πάταρα καὶ παραλαβόντα τὰς ὑπαρχούσας αὐτόθι ναῦς διαπρῆσαι. —", "st": "21.46"}, {"sp": "N", "t": "Μάλιος ὁ ἀνθύπατος τριακόσια τάλαντα πραξάμενος παρ’ Ἀριαράθου φίλον αὐτὸν ἐποιήσατο Ῥωμαίων. —", "st": "21.47"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Ἀπάμειαν οἵ τε δέκα καὶ Γνάιος ὁ στρατηγὸς τῶν Ῥωμαίων, διακούσαντες πάντων τῶν ἀπηντηκότων, τοῖς μὲν περὶ χώρας ἢ χρημάτων ἤ τινος ἑτέρου διαφερομένοις πόλεις ἀπέδωκαν ὁμολογουμένας ἀμφοτέροις, ἐν αἷς διακριθήσονται περὶ τῶν ἀμφισβητουμένων· τὴν δὲ περὶ τῶν ὅλων ἐποιήσαντο διάληψιν τοιαύτην. ὅσαι μὲν τῶν αὐτονόμων πόλεων πρότερον ὑπετέλουν Ἀντιόχῳ φόρον, τότε δὲ διεφύλαξαν τὴν πρὸς Ῥωμαίους πίστιν, ταύτας μὲν ἀπέλυσαν τῶν φόρων· ὅσαι δ’ Ἀττάλῳ σύνταξιν ἐτέλουν, ταύταις ἐπέταξαν τὸν αὐτὸν Εὐμένει διδόναι φόρον. εἰ δέ τινες ἀποστᾶσαι τῆς Ῥωμαίων φιλίας Ἀντιόχῳ συνεπολέμουν, ταύτας ἐκέλευσαν Εὐμένει διδόναι τοὺς Ἀντιόχῳ διατεταγμένους φόρους. Κολοφωνίους δὲ τοὺς τὸ Νότιον οἰκοῦντας καὶ Κυμαίους καὶ Μυλασεῖς ἀφορολογήτους ἀφῆκαν, Κλαζομενίοις δὲ καὶ δωρεὰν προσέθηκαν τὴν Δρυμοῦσσαν καλουμένην νῆσον, Μιλησίοις δὲ τὴν ἱερὰν χώραν ἀποκατέστησαν, ἧς διὰ τοὺς πολέμους πρότερον ἐξεχώρησαν. Χίους δὲ καὶ Σμυρναίους, ἔτι δ’ Ἐρυθραίους, ἔν τε τοῖς ἄλλοις προῆγον καὶ χώραν προσένειμαν, ἧς ἕκαστοι κατὰ τὸ παρὸν ἐπεθύμουν καὶ σφίσι καθήκειν ὑπελάμβανον, ἐντρεπόμενοι τὴν εὔνοιαν καὶ σπουδήν, ἣν παρέσχηντο κατὰ τὸν πόλεμον αὐτοῖς. ἀπέδωκαν δὲ καὶ Φωκαιεῦσι τὸ πάτριον πολίτευμα καὶ τὴν χώραν, ἣν καὶ πρότερον εἶχον. μετὰ δὲ ταῦτα Ῥοδίοις ἐχρημάτισαν, διδόντες Λυκίαν καὶ Καρίας τὰ μέχρι Μαιάνδρου ποταμοῦ πλὴν Τελμεσσοῦ. περὶ δὲ τοῦ βασιλέως Εὐμένους καὶ τῶν ἀδελφῶν ἔν τε ταῖς πρὸς Ἀντίοχον συνθήκαις τὴν ἐνδεχομένην πρόνοιαν ἐποιήσαντο καὶ τότε τῆς μὲν Εὐρώπης αὐτῷ προσέθηκαν Χερρόνησον καὶ Λυσιμάχειαν καὶ τὰ προσοροῦντα τούτοις ἐρύματα καὶ χώραν, ἧς Ἀντίοχος ἐπῆρχεν· τῆς δ’ Ἀσίας Φρυγίαν τὴν ἐφ’ Ἑλλησπόντου, Φρυγίαν τὴν μεγάλην, Μυσούς, οὓς Προυσίας πρότερον αὐτοῦ παρεσπάσατο, Λυκαονίαν, Μιλυάδα, Λυδίαν, Τράλλεις, Ἔφεσον, Τελμεσσόν. ταύτας μὲν οὖν ἔδωκαν Εὐμένει τὰς δωρεάς· περὶ δὲ τῆς Παμφυλίας, Εὐμένους μὲν εἶναι φάσκοντος αὐτὴν ἐπὶ τάδε τοῦ Ταύρου, τῶν δὲ παρ’ Ἀντιόχου πρεσβευτῶν ἐπέκεινα, διαπορήσαντες ἀνέθεντο περὶ τούτων εἰς τὴν σύγκλητον. σχεδὸν δὲ τῶν ἀναγκαιοτάτων καὶ πλείστων αὐτοῖς διῳκημένων, ἀναζεύξαντες προῆγον ἐφ’ Ἑλλήσποντον, βουλόμενοι κατὰ τὴν πάροδον ἔτι τὰ πρὸς τοὺς Γαλάτας ἀσφαλίσασθαι. —", "st": "21.48"}, {"sp": "N", "t": "ὅτι τῶν Ῥωμαίων κατὰ τὴν ἐπάνοδον παρὰ τῶν Θρᾳκῶν πολλὰ δεινὰ … ναρ … Ῥωμαίων στρατιω … … οὐκ ἂν φήσειε κα … … εὐμαρὲς φυλα … δι … … ἂν περὶ τὰς ἰδίας … βαιν … … εστιν … ν … ησαμενους … … ν … εναιρομ … ν … ς πράξεις … …", "st": "21.48"}, {"sp": "HDR", "t": "Βιβλίον ΚΒʹ", "st": "22"}, {"sp": "N", "t": "ὅτι κατὰ τὴν ὀγδόην καὶ μʹ ὀλυμπιάδα πρὸς ταῖς ρʹ πρεσβειῶν παρουσίαι ἐγένοντο πρὸς Ῥωμαίους παρὰ Φιλίππου καὶ παρὰ τῶν· προσορούντων τῇ Μακεδονίᾳ. τὰ δόξαντα τῇ συγκλήτῳ περὶ τῶν πρέσβεων. ὅτι κατὰ τὴν Ἑλλάδα Φιλίππου διαφορὰ πρὸς Θετταλοὺς καὶ Περραιβοὺς περὶ τῶν πόλεων ὧν κατεῖχε Φίλιππος ἐκ τῶν Ἀντιοχικῶν καιρῶν τῆς Θετταλίας καὶ Περραιβίας. ἡ γενομένη δικαιολογία περὶ τούτων ἐπὶ Κοΐντου Καικιλίου περὶ τὰ Τέμπη. τὰ κριθέντα διὰ τῶν περὶ τὸν Καικίλιον. κρίσις ἄλλη περὶ τῶν ἐπὶ Θρᾴκης πόλεων Φιλίππῳ πρὸς τοὺς παρ’ Εὐμένους πρεσβευτὰς καὶ τοὺς ἐκ Μαρωνείας φυγάδας, καὶ τὰ ῥηθέντα περὶ τούτων ἐν Θετταλονίκῃ καὶ τὰ δόξαντα τοῖς περὶ τὸν Καικίλιον. ἡ γενομένη σφαγὴ διὰ Φιλίππου τοῦ βασιλέως ἐν Μαρωνείᾳ. παρουσία πρεσβευτῶν ἐκ Ῥώμης καὶ τὰ προσταχθέντα διὰ τούτων. αἰτίαι δι’ ἃς ἐγένετο Ῥωμαίοις πρὸς Περσέα πόλεμος. κατὰ τὴν Πελοπόννησον πρεσβευτῶν παρουσία παρά τε Πτολεμαίου τοῦ βασιλέως καὶ παρὰ Εὐμένους καὶ παρὰ Σελεύκου. καὶ τὰ δόξαντα τοῖς Ἀχαιοῖς ὑπέρ τε τῆς πρὸς Πτολεμαῖον συμμαχίας καὶ τῶν δωρεῶν τῶν προτεινομένων αὐτοῖς ὑπὸ τῶν προειρημένων βασιλέων. παρουσία Κοίντου Καικιλίου καὶ μέμψις ὑπὲρ τῶν κατὰ Λακεδαίμονα διῳκημένων. ὡς Ἀρεὺς καὶ Ἀλκιβιάδης ὄντες τῶν ἀρχαίων φυγάδων ἐκ Λακεδαίμονος ἐπρέσβευσαν εἰς τὴν Ῥώμην καὶ κατηγορίαν ἐποιήσαντο Φιλοποίμενος καὶ τῶν Ἀχαιῶν. περὶ πρέσβεων Ῥωμαίων πρὸς ἐθνικούς", "st": "22.1"}, {"sp": "N", "t": "ὅτι κατὰ τὴν ὀγδόην καὶ μʹ ὀλυμπιάδα πρὸς ταῖς ρʹ παρουσία ἐγένετο πρεσβευτῶν Ῥωμαίων εἰς Κλείτορα καὶ σύνοδος τῶν Ἀχαιῶν. καὶ οἱ ῥηθέντες ὑπὸ ἀμφοτέρων λόγοι περὶ τῶν κατὰ Λακεδαίμονα πραγμάτων καὶ τὰ δόξαντα τοῖς Ἀχαιοῖς. ταῦτα κεφαλαιωδῶς.", "st": "22.1"}, {"sp": "N", "t": "ὅτι μετὰ τὴν ἐν τῷ Κομπασίῳ τῶν ἀνθρώπων ἐπαναίρεσιν δυσαρεστήσαντές τινες τῶν ἐν τῇ Λακεδαίμονι τοῖς γεγονόσι καὶ νομίσαντες ὑπὸ τοῦ Φιλοποίμενος ἅμα τὴν δύναμιν καὶ τὴν προστασίαν καταλελύσθαι τὴν Λακεδαιμονίων, ἐλθόντες εἰς Ῥώμην κατηγορίαν ἐποιήσαντο τῶν διῳκημένων καὶ τοῦ Φιλοποίμενος. καὶ τέλος ἐξεπορίσαντο γράμματα πρὸς τοὺς Ἀχαιοὺς παρὰ Μάρκου Λεπέδου τοῦ μετὰ ταῦτα γενηθέντος ἀρχιερέως, τότε δὲ τὴν ὕπατον ἀρχὴν εἰληφότος· ὃς ἔγραφε τοῖς Ἀχαιοῖς, φάσκων οὐκ ὀρθῶς αὐτοὺς κεχειρικέναι τὰ κατὰ τοὺς Λακεδαιμονίους. ὧν πρεσβευόντων, εὐθέως ὁ Φιλοποίμην πρεσβευτὰς καταστήσας τοὺς περὶ Νικόδημον τὸν Ἠλεῖον ἐξέπεμψεν εἰς τὴν Ῥώμην. κατὰ δὲ τὸν καιρὸν τοῦτον ἧκε καὶ παρὰ Πτολεμαίου πρεσβευτὴς Δημήτριος Ἀθηναῖος, ἀνανεωσόμενος τὴν προϋπάρχουσαν συμμαχίαν τῷ βασιλεῖ πρὸς τὸ ἔθνος τῶν Ἀχαιῶν. ὧν προθύμως ἀναδεξαμένων τὴν ἀνανέωσιν, κατεστάθησαν πρεσβευταὶ πρὸς Πτολεμαῖον Λυκόρτας ὁ παρ’ ἡμῶν πατὴρ καὶ Θεοδωρίδας καὶ Ῥωσιτέλης Σικυώνιοι χάριν τοῦ δοῦναι τοὺς ὅρκους ὑπὲρ τῶν Ἀχαιῶν καὶ λαβεῖν παρὰ τοῦ βασιλέως. ἐγενήθη δέ τι κατὰ τὸν καιρὸν τοῦτον πάρεργον μὲν ἴσως, ἄξιον δὲ μνήμης. μετὰ γὰρ τὸ συντελεσθῆναι τὴν ἀνανέωσιν τῆς συμμαχίας, ὑπὲρ τῶν Ἀχαιῶν ὑπεδέξατο τὸν πρεσβευτὴν ὁ Φιλοποίμην· γενομένης δὲ παρὰ τὴν συνουσίαν μνήμης τοῦ βασιλέως, ἐπιβαλὼν ὁ πρεσβευτὴς πολλούς τινας διετίθετο λόγους ἐγκωμιάζων τὸν Πτολεμαῖον καί τινας ἀποδείξεις προεφέρετο τῆς τε περὶ τὰς κυνηγίας εὐχερείας καὶ τόλμης, ἑξῆς τε τῆς περὶ τοὺς ἵππους καὶ τὰ ὅπλα δυνάμεως καὶ τῆς ἐν τούτοις ἀσκήσεως. τελευταίῳ δ’ ἐχρήσατο μαρτυρίῳ πρὸς πίστιν τῶν εἰρημένων· ἔφη γὰρ αὐτὸν κυνηγετοῦντα ταῦρον βαλεῖν ἀφ’ ἵππου μεσαγκύλῳ. —", "st": "22.3"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Βοιωτίαν μετὰ τὸ συντελεσθῆναι τὰς πρὸς Ἀντίοχον Ῥωμαίοις συνθήκας ἀποκοπεισῶν τῶν ἐλπίδων πᾶσι τοῖς καινοτομεῖν ἐπιβαλλομένοις, ἄλλην ἀρχὴν καὶ διάθεσιν ἐλάμβανον αἱ πολιτεῖαι. διὸ καὶ τῆς δικαιοδοσίας ἑλκομένης παρ’ αὐτοῖς σχεδὸν ἐξ εἴκοσι καὶ πέντ’ ἐτῶν, τότε λόγοι διεδίδοντο κατὰ τὰς πόλεις, φασκόντων τινῶν διότι δεῖ γίνεσθαι διέξοδον καὶ συντέλειαν τῶν πρὸς ἀλλήλους. πολλῆς δὲ περὶ τούτων ἀμφισβητήσεως ὑπαρχούσης διὰ τὸ πλείους εἶναι τοὺς καχέκτας τῶν εὐπόρων, ἐγίνετό τι συνέργημα τοῖς τὰ βέλτισθ’ αἱρουμένοις ἐκ ταὐτομάτου τοιοῦτον. ὁ γὰρ Τίτος ἐν τῇ Ῥώμῃ πάλαι μὲν ἐσπούδαζε περὶ τοῦ καταπορευθῆναι τὸν Ζεύξιππον εἰς τὴν Βοιωτίαν, ἅτε κεχρημένος αὐτῷ συνεργῷ πρὸς πολλὰ κατὰ τοὺς Ἀντιοχικοὺς καὶ Φιλιππικοὺς καιρούς. κατὰ δὲ τοὺς τότε χρόνους ἐξείργαστο γράψαι τὴν σύγκλητον τοῖς Βοιωτοῖς διότι δεῖ κατάγειν Ζεύξιππον καὶ τοὺς ἅμ’ αὐτῷ φυγόντας εἰς τὴν οἰκείαν. ὧν προσπεσόντων, δείσαντες οἱ Βοιωτοὶ μὴ κατελθόντων τῶν προειρημένων ἀποσπασθῶσιν ἀπὸ τῆς Μακεδόνων εὐνοίας, βουλόμενοι κατακηρυχθῆναι τὰς κρίσεις τὰς κατὰ τῶν περὶ τὸν Ζεύξιππον, ἃς ἦσαν πρότερον αὐτοῖς ἐπιγεγραμμένοι, καὶ τούτῳ τῷ τρόπῳ τῶν δικῶν μίαν μὲν αὐτῶν κατεδίκασαν ἱεροσυλίας, διότι λεπίσαιεν τὴν τοῦ Διὸς τράπεζαν ἀργυρᾶν οὖσαν, μίαν δὲ θανάτου διὰ τὸν Βραχύλλου φόνον. ταῦτα δὲ διοικήσαντες οὐκέτι προσεῖχον τοῖς γραφομένοις, ἀλλ’ ἔπεμπον πρεσβευτὰς εἰς τὴν Ῥώμην τοὺς περὶ Καλλίκριτον, φάσκοντες οὐ δύνασθαι τὰ κατὰ τοὺς νόμους ᾠκονομημένα παρ’ αὑτοῖς ἄκυρα ποιεῖν. ἐν δὲ τοῖς καιροῖς τούτοις πρεσβεύσαντος αὐτοῦ τοῦ Ζευξίππου πρὸς τὴν σύγκλητον, οἱ Ῥωμαῖοι τὴν τῶν Βοιωτῶν προαίρεσιν ἔγραψαν πρός τε τοὺς Αἰτωλοὺς καὶ πρὸς Ἀχαιούς, κελεύοντες κατάγειν Ζεύξιππον εἰς τὴν οἰκείαν. οἱ δ’ Ἀχαιοὶ τοῦ μὲν διὰ στρατοπέδων ποιεῖσθαι τὴν ἔφοδον ἀπέσχον, πρεσβευτὰς δὲ προεχειρίσαντο πέμπειν τοὺς παρακαλέσοντας τοὺς Βοιωτοὺς τοῖς λεγομένοις ὑπὸ τῶν Ῥωμαίων πειθαρχεῖν καὶ τὴν δικαιοδοσίαν, καθάπερ καὶ τὴν ἐν αὐτοῖς, οὕτω καὶ τὴν πρὸς αὐτοὺς ἐπὶ τέλος ἀγαγεῖν. συνέβαινε γὰρ καὶ τὰ πρὸς τούτους συναλλάγματα παρέλκεσθαι πολὺν ἤδη χρόνον. ὧν διακούσαντες οἱ Βοιωτοί, στρατηγοῦντος Ἱππίου παρ’ αὐτοῖς, παραχρῆμα μὲν ὑπέσχοντο ποιήσειν τὰ παρακαλούμενα, μετ’ ὀλίγον δὲ πάντων ὠλιγώρησαν. διόπερ ὁ Φιλοποίμην, Ἱππίου μὲν ἀποτεθειμένου τὴν ἀρχήν, Ἀλκέτου δὲ παρειληφότος, ἀπέδωκε τοῖς αἰτουμένοις τὰ ῥύσια κατὰ τῶν Βοιωτῶν. ἐξ ὧν ἐγίνετο καταρχὴ διαφορᾶς τοῖς ἔθνεσιν οὐκ εὐκαταφρόνητος. παραυτίκα γὰρ ἔλαχε τῶν Μυρρίχου θρεμμάτων καὶ τοῦ Σίμωνος· καὶ περὶ ταῦτα γενομένης συμπλοκῆς, οὐκέτι πολιτικῆς διαφορᾶς, ἀλλὰ πολεμικῆς ἔχθρας ἐγένετο καταρχὴ καὶ προοίμιον. εἰ μὲν οὖν ἡ σύγκλητος προσέθηκε τἀκόλουθον περὶ τῆς καθόδου τῶν περὶ τὸν Ζεύξιππον, ταχέως ἂν ἐξεκαύθη πόλεμος· νῦν δ’ ἐκείνη τε παρεσιώπησεν, οἵ τε Μεγαρεῖς ἐπέσχον τὰ ῥύσια, διαπρεσβευσαμένων τοῖς συναλλάγμασιν. —", "st": "22.4"}, {"sp": "N", "t": "ὅτι ἐγένετο Λυκίοις διαφορὰ πρὸς Ῥοδίους διὰ τοιαύτας αἰτίας. καθ’ οὓς καιροὺς οἱ δέκα διῴκουν τὰ περὶ τὴν Ἀσίαν, τότε παρεγενήθησαν πρέσβεις, παρὰ μὲν Ῥοδίων Θεαίδητος καὶ Φιλόφρων, ἀξιοῦντες αὑτοῖς δοθῆναι τὰ κατὰ Λυκίαν καὶ Καρίαν χάριν τῆς εὐνοίας καὶ προθυμίας, ἣν παρέσχηνται σφίσι κατὰ τὸν Ἀντιοχικὸν πόλεμον· παρὰ δὲ τῶν Ἰλιέων ἧκον Ἵππαρχος καὶ Σάτυρος, ἀξιοῦντες διὰ τὴν πρὸς αὑτοὺς οἰκειότητα συγγνώμην δοθῆναι Λυκίοις τῶν ἡμαρτημένων. ὧν οἱ δέκα διακούσαντες ἐπειράθησαν ἑκατέρων στοχάσασθαι κατὰ τὸ δυνατόν. διὰ μὲν γὰρ τοὺς Ἰλιεῖς οὐθὲν ἐβουλεύσαντο περὶ αὐτῶν ἀνήκεστον, τοῖς δὲ Ῥοδίοις χαριζόμενοι προσένειμαν ἐν δωρεᾷ τοὺς Λυκίους. ἐκ ταύτης τῆς διαλήψεως ἐγενήθη στάσις καὶ διαφορὰ τοῖς Λυκίοις πρὸς αὐτοὺς τοὺς Ῥοδίους οὐκ εὐκαταφρόνητος. οἱ μὲν γὰρ Ἰλιεῖς ἐπιπορευόμενοι τὰς πόλεις αὐτῶν ἀπήγγελλον ὅτι παρῄτηνται τὴν ὀργὴν τῶν Ῥωμαίων καὶ παραίτιοι γεγόνασιν αὐτοῖς τῆς ἐλευθερίας· οἱ δὲ περὶ τὸν Θεαίδητον ἐποιήσαντο τὴν ἀγγελίαν ἐν τῇ πατρίδι, φάσκοντες Λυκίαν καὶ Καρίας τὰ μέχρι τοῦ Μαιάνδρου δεδόσθαι Ῥοδίοις ὑπὸ Ῥωμαίων ἐν δωρεᾷ. λοιπὸν οἱ μὲν Λύκιοι πρεσβεύοντες ἧκον εἰς τὴν Ῥόδον ὑπὲρ συμμαχίας, οἱ δὲ Ῥόδιοι προχειρισάμενοί τινας τῶν πολιτῶν ἐξαπέστελλον τοὺς διατάξοντας ταῖς κατὰ Λυκίαν καὶ Καρίαν πόλεσιν ὡς ἕκαστα δεῖ γενέσθαι. μεγάλης δ’ οὔσης τῆς παραλλαγῆς περὶ τὰς ἑκατέρων ὑπολήψεις, ἕως μέν τινος οὐ πᾶσιν ἔκδηλος ἦν ἡ διαφορὰ τῶν προειρημένων· ὡς δ’ εἰσελθόντες εἰς τὴν ἐκκλησίαν οἱ Λύκιοι διελέγοντο περὶ συμμαχίας, καὶ μετὰ τούτους Ποθίων ὁ πρύτανις τῶν Ῥοδίων ἀναστὰς ἐφώτισε τὴν ἑκατέρων αἵρεσιν καὶ προσεπετίμησε τοῖς Λυκίοις πᾶν γὰρ ὑπομένειν ἔφασαν μᾶλλον ἢ ποιήσειν Ῥοδίοις τὸ προσταττόμενον.", "st": "22.5"}, {"sp": "N", "t": "βασιλέα καὶ θεων αιμα τοῦτον λέγοντες καταχρώμενοι τευξεσθαι τινος ἐλέους καὶ συγγνώμης ἐπὶ τῳ … σασθαι τον βασιλεα … ων γε μὴν καὶ βασιλικώτερος. … ονων ων ἀθετηθῆναι γὰρ υφ ετερων κρειττον ἦν ἢ πρότερον αὐτὸν ἀθετεῖν τὰς πίστεις καὶ μὴν ἀδικεῖσθαι μᾶλλον η … και ⟨ανου⟩ς φασιν συμπάσχειν τοις αδικοις π … ἔγγιστα τῆς θείας φυσεως εἶναι …, … νους τυγχάνειν τιμῶν η υπ … θεὸς γὰρ οὐδεὶς πρότερος κακῶς ποιεῖ τοὺς ανους … τα του προς … ς θαυμάζουσι μὲν πάντες Φίλιππον διὰ τὴν ορ … ς μεγαλοψυχίαν ὅτι κακῶς οὐ μόνον ἀκούων, ἀλλὰ καὶ πάσχων ὑπ’ Ἀθηναίων, νικήσας αὐτοὺς τὴν περὶ Χαιρώνειαν μάχην τοσοῦτον ἀπέσχε τοῦ χρήσασθαι τῷ καιρῷ πρὸς τὴν κατὰ τῶν ἐχθρῶν βλάβην ὥστε τοὺς μὲν τεθνεῶτας τῶν Ἀθηναίων κηδεύσας ἔθαψε, τοὺς δ’ αἰχμαλώτους χωρὶς λύτρων προσαμφιέσας ἐξαπέστειλε τοῖς ἀναγκαίοις· μιμοῦνται δ’ ἥκιστα τὴν τοιαύτην προαίρεσιν, ἁμιλλῶνται δὲ τοῖς θυμοῖς καὶ ταῖς τιμωρίαις πρὸς τούτους, οἷς πολεμοῦσι τούτων αὐτῶν ἕνεκα. πλὴν ὅγε Πτολεμαῖος δήσας τοὺς ἀνθρώπους γυμνοὺς ταῖς ἁμάξαις εἷλκε καὶ μετὰ ταῦτα τιμωρησάμενος ἀπέκτεινεν. —", "st": "22.6"}, {"sp": "N", "t": "ὅτι Πτολεμαῖος ὁ βασιλεὺς Αἰγύπτου ὅτε τὴν Λύκων πόλιν ἐπολιόρκησε, καταπλαγέντες τὸ γεγονὸς οἱ δυνάσται τῶν Αἰγυπτίων ἔδωκαν σφᾶς αὐτοὺς εἰς τὴν τοῦ βασιλέως πίστιν. οἷς κακῶς ἐχρήσατο καὶ εἰς κινδύνους πολλοὺς ἐνέπεσεν. παραπλήσιον δέ τι συνέβη καὶ κατὰ τοὺς καιρούς, ἡνίκα Πολυκράτης τοὺς ἀποστάτας ἐχειρώσατο. οἱ γὰρ περὶ τὸν Ἀθίνιν καὶ Παυσίραν καὶ Χέσουφον καὶ τὸν Ἰρόβαστον, οἵπερ ἦσαν ἔτι διασῳζόμενοι τῶν δυναστῶν, εἴξαντες τοῖς πράγμασι παρῆσαν εἰς τὴν Σάιν, σφᾶς αὐτοὺς εἰς τὴν τοῦ βασιλέως ἐγχειρίζοντες πίστιν· ὁ δὲ Πτολεμαῖος ἀθετήσας τὰς πίστεις καὶ δήσας τοὺς ἀνθρώπους γυμνοὺς ταῖς ἁμάξαις εἷλκε καὶ μετὰ ταῦτα τιμωρησάμενος ἀπέκτεινεν. καὶ παραγενόμενος εἰς τὴν Ναύκρατιν μετὰ τῆς στρατιᾶς, καὶ παραστήσαντος αὐτῷ τοὺς ἐξενολογημένους ἄνδρας ἐκ τῆς Ἑλλάδος Ἀριστονίκου, προσδεξάμενος τούτους ἀπέπλευσεν εἰς Ἀλεξάνδρειαν, τῶν μὲν τοῦ πολέμου πράξεων οὐδεμιᾶς κεκοινωνηκὼς διὰ τὴν Πολυκράτους ἀδικοδοξίαν, καίπερ ἔχων ἔτη πέντε καὶ εἴκοσιν.", "st": "22.7"}, {"sp": "N", "t": "ὅτι φησὶν ὁ Πολύβιος ἐν τῷ εἰκοστῷ δευτέρῳ· περὶ δὲ τὴν τῶν ἐν Μακεδονίᾳ βασιλέων οἰκίαν ἤδη τις ἀπὸ τούτων τῶν καιρῶν ἐφύετο κακῶν ἀνηκέστων ἀρχή. καίτοι γ’ οὐκ ἀγνοῶ διότι τινὲς τῶν συγγραφόντων περὶ τοῦ συστάντος Ῥωμαίοις πολέμου πρὸς Περσέα, βουλόμενοι τὰς αἰτίας ἡμῖν ἐπιδεικνύναι τῆς διαφορᾶς, πρῶτον μὲν ἀποφαίνουσι τὴν Ἀβρουπόλιος ἔκπτωσιν ἐκ τῆς ἰδίας δυναστείας, ὡς καταδραμόντος αὐτοῦ τὰ περὶ τὸ Πάγγαιον μέταλλα μετὰ τὸν τοῦ Φιλίππου θάνατον· Περσεὺς δὲ παραβοηθήσας καὶ τρεψάμενος ὁλοσχερῶς ἐξέβαλε τὸν προειρημένον ἐκ τῆς ἰδίας ἀρχῆς· ἑξῆς δὲ ταύτῃ τὴν εἰς Δολοπίαν εἰσβολὴν καὶ τὴν εἰς Δελφοὺς παρουσίαν Περσέως, ἔτι δὲ τὴν κατ’ Εὐμένους τοῦ βασιλέως ἐπιβουλὴν γενομένην ἐν Δελφοῖς καὶ τὴν τῶν ἐκ Βοιωτίας πρεσβευτῶν ἐπαναίρεσιν, ἐξ ὧν ἔνιοί φασι φῦναι Περσεῖ τὸν πρὸς Ῥωμαίους πόλεμον. ἐγὼ δέ φημι κυριώτατον μὲν εἶναι καὶ τοῖς συγγράφουσι καὶ τοῖς φιλομαθοῦσι τὸ γινώσκειν τὰς αἰτίας, ἐξ ὧν ἕκαστα γεννᾶται καὶ φύεται τῶν πραγμάτων· συγκέχυται δὲ ταῦτα παρὰ τοῖς πλείστοις τῶν συγγραφέων διὰ τὸ μὴ κρατεῖσθαι τίνι διαφέρει πρόφασις αἰτίας καὶ πάλιν προφάσεως ἀρχὴ πολέμου. καὶ νῦν δὲ τῶν πραγμάτων αὐτῶν προσυπομιμνησκόντων ἠνάγκασμαι πάλιν ἀνανεώσασθαι τὸν αὐτὸν λόγον. τῶν γὰρ ἄρτι ῥηθέντων πραγμάτων τὰ μὲν πρῶτα προφάσεις εἰσί, τὰ δὲ τελευταῖα τὰ περὶ τὴν κατὰ τοῦ βασιλέως Εὐμένους ἐπιβουλὴν καὶ τὰ περὶ τὴν τῶν πρεσβευτῶν ἀναίρεσιν καὶ τούτοις ἕτερα παραπλήσια τῶν κατὰ τοὺς αὐτοὺς καιροὺς γεγονότων ἀρχαὶ πρόδηλοι τοῦ συστάντος Ῥωμαίοις καὶ Περσεῖ πολέμου καὶ τοῦ καταλυθῆναι τὴν Μακεδόνων ἀρχήν· αἰτία δὲ τούτων ἁπλῶς ἐστιν οὐδεμία. δῆλον δὲ τοῦτ’ ἔσται διὰ τῶν ἑξῆς ῥηθησομένων. καθάπερ γὰρ εἴπομεν Φίλιππον τὸν Ἀμύντου διανοηθῆναι καὶ προθέσθαι συντελεῖν τὸν πρὸς τοὺς Πέρσας πόλεμον, Ἀλέξανδρον δὲ τοῖς ὑπ’ ἐκείνου κεκριμένοις ἐπιγενέσθαι χειριστὴν τῶν πράξεων, οὕτω καὶ νῦν Φίλιππον μὲν τὸν Δημητρίου φαμὲν διανοηθῆναι πρότερον πολεμεῖν Ῥωμαίοις τὸν τελευταῖον πόλεμον καὶ τὰς παρασκευὰς ἑτοίμας πάσας πρὸς ταύτην ἔχειν τὴν ἐπιβολήν, ἐκείνου δ’ ἐκχωρήσαντος Περσέα γενέσθαι χειριστὴν τῶν πράξεων· εἰ δὲ τοῦτ’ ἀληθές, κἀκεῖνο σαφές· οὐ γὰρ οἷόν τε τὰς αἰτίας ὕστερον γενέσθαι τῆς τελευτῆς τοῦ κρίναντος καὶ προθεμένου πολεμεῖν· ὃ συμβαίνει τοῖς ὑπὸ τῶν ἄλλων συγγραφέων εἰρημένοις· πάντα γάρ ἐστι τὰ λεγόμενα παρ’ αὐτοῖς ὕστερα τῆς Φιλίππου τελευτῆς. —", "st": "22.8"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς αὐτοὺς καιροὺς ἧκον εἰς τὴν Ῥώμην παρά τε τοῦ βασιλέως Εὐμένους πρεσβευταὶ διασαφοῦντες τὸν ἐξιδιασμὸν τοῦ Φιλίππου τῶν ἐπὶ Θρᾴκης πόλεων, καὶ παρὰ Μαρωνειτῶν οἱ φυγάδες κατηγοροῦντες καὶ τὴν αἰτίαν ἀναφέροντες τῆς αὑτῶν ἐκπτώσεως ἐπὶ τὸν Φίλιππον, ἅμα δὲ τούτοις Ἀθαμᾶνες, Περραιβοί, Θετταλοί, φάσκοντες κομίζεσθαι δεῖν αὑτοὺς τὰς πόλεις, ἃς παρείλετο Φίλιππος αὐτῶν κατὰ τὸν Ἀντιοχικὸν πόλεμον. ἧκον δὲ καὶ παρὰ τοῦ Φιλίππου πρέσβεις πρὸς ἅπαντας τοὺς κατηγορήσαντας ἀπολογησόμενοι. γενομένων δὲ πλειόνων λόγων πᾶσι τοῖς προειρημένοις πρὸς τοὺς παρὰ τοῦ Φιλίππου πρεσβευτάς, ἔδοξε τῇ συγκλήτῳ παραυτίκα καταστῆσαι πρεσβείαν τὴν ἐπισκεψομένην τὰ κατὰ τὸν Φίλιππον καὶ παρέξουσαν ἀσφάλειαν τοῖς βουλομένοις κατὰ πρόσωπον λέγειν τὸ φαινόμενον καὶ κατηγορεῖν τοῦ βασιλέως. καὶ κατεστάθησαν οἱ περὶ τὸν Κόιντον Καικίλιον καὶ Μάρκον Βαίβιον καὶ Τεβέριον Κλαύδιον. — συνέβαινε τοὺς Αἰνίους πάλαι μὲν στασιάζειν, προσφάτως δ’ ἀπονεύειν τοὺς μὲν πρὸς Εὐμένη, τοὺς δὲ πρὸς Μακεδονίαν.", "st": "22.9"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Πελοπόννησον ὡς μέν, ἔτι Φιλοποίμενος στρατηγοῦντος, εἴς τε τὴν Ῥώμην ἐξαπέστειλε πρεσβευτὰς τὸ τῶν Ἀχαιῶν ἔθνος ὑπὲρ τῆς Λακεδαιμονίων πόλεως πρός τε τὸν βασιλέα Πτολεμαῖον τοὺς ἀνανεωσομένους τὴν προϋπάρχουσαν αὐτῷ συμμαχίαν, ἐδηλώσαμεν, φησὶν ὁ Πολύβιος. κατὰ δὲ τὸν ἐνεστῶτα χρόνον, Ἀρισταίνου στρατηγοῦντος, οἵ τε παρὰ Πτολεμαίου τοῦ βασιλέως πρέσβεις ἧκον, ἐν Μεγάλῃ πόλει τῆς συνόδου τῶν Ἀχαιῶν ὑπαρχούσης· ἐξαπεστάλκει δὲ καὶ πρὸς τούτοις ὁ βασιλεὺς Εὐμένης πρεσβευτάς, ἐπαγγελλόμενος ἑκατὸν καὶ εἴκοσι τάλαντα δώσειν τοῖς Ἀχαιοῖς, ἐφ’ ᾧ, δανειζομένων τούτων, ἐκ τῶν τόκων μισθοδοτεῖσθαι τὴν βουλὴν τῶν Ἀχαιῶν ἐπὶ ταῖς κοιναῖς συνόδοις. ἧκον δὲ καὶ παρὰ Σελεύκου τοῦ βασιλέως πρεσβευταί, τήν τε φιλίαν ἀνανεωσόμενοι καὶ δεκαναΐαν μακρῶν πλοίων ἐπαγγελλόμενοι δώσειν τοῖς Ἀχαιοῖς. ἐχούσης δὲ τῆς συνόδου πραγματικῶς, πρῶτοι παρῆλθον οἱ περὶ Νικόδημον τὸν Ἠλεῖον καὶ τούς τε ῥηθέντας ἐν τῇ συγκλήτῳ λόγους ὑφ’ αὑτῶν ὑπὲρ τῆς τῶν Λακεδαιμονίων πόλεως διῆλθον τοῖς Ἀχαιοῖς καὶ τὰς ἀποκρίσεις ἀνέγνωσαν, ἐξ ὧν ἦν λαμβάνειν ἐκδοχὴν ὅτι δυσαρεστοῦνται μὲν καὶ τῇ τῶν τειχῶν συντελέσει καὶ τῇ καταλύσει τῶν ἐν τῷ Κομπασίῳ διαφθαρέντων, οὐ μὴν ἄκυρόν τι ποιεῖν. οὐθενὸς δ’ οὔτ’ ἀντειπόντος οὔτε συνηγορήσαντος, οὕτω πως παρεπέμφθη. μετὰ δὲ τούτους εἰσῆλθον οἱ παρ’ Εὐμένους πρέσβεις καὶ τήν τε συμμαχίαν τὴν πατρικὴν ἀνενεώσαντο καὶ τὴν ὑπὲρ τῶν χρημάτων ἐπαγγελίαν διεσάφησαν τοῖς πολλοῖς. καὶ πλείω δὲ πρὸς ταύτας τὰς ὑποθέσεις διαλεχθέντες καὶ μεγάλην εὔνοιαν καὶ φιλανθρωπίαν τοῦ βασιλέως ἐμφήναντες πρὸς τὸ ἔθνος, κατέπαυσαν τὸν λόγον.", "st": "22.10"}, {"sp": "N", "t": "μεθ’ οὓς Ἀπολλωνίδας ὁ Σικυώνιος ἀναστὰς κατὰ μὲν τὸ πλῆθος τῶν διδομένων χρημάτων ἀξίαν ἔφη τὴν δωρεὰν τῶν Ἀχαιῶν, κατὰ δὲ τὴν προαίρεσιν τοῦ διδόντος καὶ τὴν χρείαν, εἰς ἣν δίδοται, πασῶν αἰσχίστην καὶ παρανομωτάτην. τῶν γὰρ νόμων κωλυόντων μηθένα μήτε τῶν ἰδιωτῶν μήτε τῶν ἀρχόντων παρὰ βασιλέως δῶρα λαμβάνειν κατὰ μηδ’ ὁποίαν πρόφασιν, πάντας ἅμα δωροδοκεῖσθαι προφανῶς, προσδεξαμένους τὰ χρήματα, πάντων εἶναι παρανομώτατον, πρὸς δὲ τούτοις αἴσχιστον ὁμολογουμένως. τὸ γὰρ ὀψωνιάζεσθαι τὴν βουλὴν ὑπ’ Εὐμένους καθ’ ἕκαστον ἔτος καὶ βουλεύεσθαι περὶ τῶν κοινῶν καταπεπωκότας οἱονεὶ δέλεαρ, πρόδηλον ἔχειν τὴν αἰσχύνην καὶ τὴν βλάβην. νῦν μὲν γὰρ Εὐμένη διδόναι χρήματα, μετὰ δὲ ταῦτα Προυσίαν δώσειν, καὶ πάλιν Σέλευκον. τῶν δὲ πραγμάτων ἐναντίαν φύσιν ἐχόντων τοῖς βασιλεῦσι καὶ ταῖς δημοκρατίαις, καὶ τῶν πλείστων καὶ μεγίστων διαβουλίων αἰεὶ γινομένων περὶ τῶν πρὸς τοὺς βασιλεῖς ἡμῖν διαφερόντων, φανερῶς ἀνάγκη δυεῖν θάτερον ἢ τὸ τῶν βασιλέων λυσιτελὲς ἐπίπροσθεν γίνεσθαι τοῦ κατ’ ἰδίαν συμφέροντος ἢ τούτου μὴ συμβαίνοντος ἀχαρίστους φαίνεσθαι πᾶσιν, ἀντιπράττοντας τοῖς αὑτῶν μισθοδόταις. διὸ μὴ μόνον ἀπείπασθαι παρεκάλει τοὺς Ἀχαιούς, ἀλλὰ καὶ μισεῖν τὸν Εὐμένη διὰ τὴν ἐπίνοιαν τῆς δόσεως. μετὰ δὲ τοῦτον ἀναστὰς Κάσσανδρος Αἰγινήτης ἀνέμνησε τοὺς Ἀχαιοὺς τῆς Αἰγινητῶν ἀκληρίας, ᾗ περιέπεσον διὰ τὸ μετὰ τῶν Ἀχαιῶν συμπολιτεύεσθαι, ὅτε Πόπλιος Σολπίκιος ἐπιπλεύσας τῷ στόλῳ πάντας ἐξηνδραποδίσατο τοὺς ταλαιπώρους Αἰγινήτας· ὑπὲρ ὧν διεσαφήσαμεν, τίνα τρόπον Αἰτωλοί, κύριοι γενόμενοι τῆς πόλεως κατὰ τὰς πρὸς Ῥωμαίους συνθήκας, Ἀττάλῳ παραδοῖεν, τριάκοντα τάλαντα παρ’ αὐτοῦ λαβόντες. ταῦτ’ οὖν τιθεὶς τοῖς Ἀχαιοῖς πρὸ ὀφθαλμῶν ἠξίου τὸν Εὐμένη μὴ διάφορα προτείνοντα θηρεύειν τὴν τῶν Ἀχαιῶν εὔνοιαν, ἀλλὰ τὴν πόλιν ἀποδιδόντα τυγχάνειν πάντων τῶν φιλανθρώπων ἀναντιρρήτως. τοὺς δ’ Ἀχαιοὺς παρεκάλει μὴ δέχεσθαι τοιαύτας δωρεάς, δι’ ὧν φανήσονται καὶ τὰς εἰς τὸ μέλλον ἐλπίδας ἀφαιρούμενοι τῆς Αἰγινητῶν σωτηρίας. τοιούτων δὲ γενομένων λόγων, ἐπὶ τοσοῦτον παρέστη τὸ πλῆθος ὥστε μὴ τολμῆσαι μηθένα συνειπεῖν τῷ βασιλεῖ, πάντας δὲ μετὰ κραυγῆς ἐκβαλεῖν τὴν προτεινομένην δωρεάν, καίτοι δοκούσης αὐτῆς ἔχειν τι δυσαντοφθάλμητον διὰ τὸ πλῆθος τῶν προτεινομένων χρημάτων.", "st": "22.11"}, {"sp": "N", "t": "ἐπὶ δὲ τοῖς προειρημένοις εἰσήχθη τὸ περὶ Πτολεμαίου διαβούλιον· ἐν ᾧ προκληθέντων τῶν ἀποσταλέντων πρεσβευτῶν ὑπὸ τῶν Ἀχαιῶν πρὸς Πτολεμαῖον, προελθὼν Λυκόρτας μετὰ τῶν πρεσβευτῶν ἀπελογίσατο πρῶτον μὲν τίνα τρόπον καὶ δοῖεν καὶ λάβοιεν τοὺς ὅρκους ὑπὲρ τῆς συμμαχίας, εἶτα διότι κομίζοιεν δωρεὰν κοινῇ τοῖς Ἀχαιοῖς ἑξακισχίλια μὲν ὅπλα χαλκᾶ πελταστικά, διακόσια δὲ τάλαντα νομίσματος ἐπισήμου χαλκοῦ· πρὸς δὲ τούτοις ἐπῄνεσε τὸν βασιλέα καὶ βραχέα περὶ τῆς εὐνοίας αὐτοῦ καὶ προθυμίας τῆς εἰς τὸ ἔθνος εἰπὼν κατέστρεψε τὸν λόγον. ἐφ’ οἷς ἀναστὰς ὁ τῶν Ἀχαιῶν στρατηγὸς Ἀρίσταινος ἤρετο τόν τε παρὰ τοῦ Πτολεμαίου πρεσβευτὴν καὶ τοὺς ἐξαπεσταλμένους ὑπὸ τῶν Ἀχαιῶν ἐπὶ τὴν ἀνανέωσιν, ποίαν ἧκε συμμαχίαν ἀνανεωσάμενος. οὐδενὸς δ’ ἀποκρινομένου, πάντων δὲ διαλαλούντων πρὸς ἀλλήλους, πλῆρες ἦν τὸ βουλευτήριον ἀπορίας. ἦν δὲ τὸ ποιοῦν τὴν ἀλογίαν τοιοῦτον. οὐσῶν καὶ πλειόνων συμμαχιῶν τοῖς Ἀχαιοῖς πρὸς τὴν Πτολεμαίου βασιλείαν, καὶ τούτων ἐχουσῶν μεγάλας διαφορὰς κατὰ τὰς τῶν καιρῶν περιστάσεις, οὔθ’ ὁ παρὰ τοῦ Πτολεμαίου πρεσβευτὴς οὐδεμίαν ἐποιήσατο διαστολήν, ὅτ’ ἀνενεοῦτο, καθολικῶς δὲ περὶ τοῦ πράγματος ἐλάλησεν, οὔθ’ οἱ πεμφθέντες πρέσβεις, ἀλλ’ ὡς μιᾶς ὑπαρχούσης αὐτοί τε τοὺς ὅρκους ἔδοσαν καὶ παρὰ τοῦ βασιλέως ἔλαβον. ὅθεν προφερομένου τοῦ στρατηγοῦ πάσας τὰς συμμαχίας καὶ κατὰ μέρος ἐν ἑκάστῃ διαστελλομένου, μεγάλης οὔσης διαφορᾶς, ἐζήτει τὸ πλῆθος εἰδέναι ποίαν ἀνανεοῖτο συμμαχίαν. οὐ δυναμένου δὲ λόγον ὑποσχεῖν οὔτε τοῦ Φιλοποίμενος, ὃς ἐποιήσατο στρατηγῶν τὴν ἀνανέωσιν, οὔτε τῶν περὶ τὸν Λυκόρταν τῶν πρεσβευσάντων εἰς τὴν Ἀλεξάνδρειαν, οὗτοι μὲν ἐσχεδιακότες ἐφαίνοντο τοῖς κοινοῖς πράγμασιν, ὁ δ’ Ἀρίσταινος μεγάλην ἐφείλκετο φαντασίαν ὡς μόνος εἰδὼς τί λέγει, καὶ τέλος οὐκ εἴασε κυρωθῆναι τὸ διαβούλιον, ἀλλ’ εἰς ὑπέρθεσιν ἤγαγε διὰ τὴν προειρημένην ἀλογίαν. τῶν δὲ παρὰ τοῦ Σελεύκου πρέσβεων εἰσελθόντων, ἔδοξε τοῖς Ἀχαιοῖς τὴν μὲν φιλίαν ἀνανεώσασθαι πρὸς τὸν Σέλευκον, τὴν δὲ τῶν πλοίων δωρεὰν κατὰ τὸ παρὸν ἀπείπασθαι. καὶ τότε μὲν περὶ τούτων βουλευσάμενοι διέλυσαν εἰς τὰς ἰδίας ἕκαστοι πόλεις.", "st": "22.12"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα, τῆς πανηγύρεως ἀκμαζούσης, ἦλθε Κόιντος Καικίλιος ἐκ Μακεδονίας, ἀνακάμπτων ἀπὸ τῆς πρεσβείας ἧς ἐπρέσβευσε πρὸς Φίλιππον. καὶ συναγαγόντος Ἀρισταίνου τοῦ στρατηγοῦ τὰς ἀρχὰς εἰς τὴν τῶν Ἀργείων πόλιν, εἰσελθὼν ὁ Κόιντος ἐμέμφετο, φάσκων αὐτοὺς βαρύτερον καὶ πικρότερον τοῦ δέοντος κεχρῆσθαι τοῖς Λακεδαιμονίοις, καὶ παρεκάλει διὰ πλειόνων διορθώσασθαι τὴν προγεγενημένην ἄγνοιαν. ὁ μὲν οὖν Ἀρίσταινος εἶχε τὴν ἡσυχίαν, δῆλος ὢν ἐξ αὐτοῦ τοῦ σιωπᾶν ὅτι δυσαρεστεῖται τοῖς ᾠκονομημένοις καὶ συνευδοκεῖ τοῖς ὑπὸ Καικιλίου λεγομένοις· ὁ δὲ Διοφάνης ὁ Μεγαλοπολίτης, ἄνθρωπος στρατιωτικώτερος ἢ πολιτικώτερος, ἀναστὰς οὐχ οἷον ἀπελογήθη τι περὶ τῶν Ἀχαιῶν, ἀλλὰ καὶ προσυπέδειξε τῷ Καικιλίῳ διὰ τὴν πρὸς τὸν Φιλοποίμενα παρατριβὴν ἕτερον ἔγκλημα κατὰ τῶν Ἀχαιῶν. ἔφη γὰρ οὐ μόνον τὰ κατὰ Λακεδαίμονα κεχειρίσθαι κακῶς, ἀλλὰ καὶ τὰ κατὰ Μεσσήνην· ἦσαν δὲ περὶ τῶν φυγαδικῶν τοῖς Μεσσηνίοις ἀντιρρήσεις τινὲς πρὸς ἀλλήλους περὶ τὸ τοῦ Τίτου διάγραμμα καὶ τὴν τοῦ Φιλοποίμενος διόρθωσιν. ὅθεν ὁ Καικίλιος, δοκῶν ἔχειν καὶ τῶν Ἀχαιῶν αὐτῶν τινας ὁμογνώμονας, μᾶλλον ἠγανάκτει τῷ μὴ κατακολουθεῖν ἑτοίμως τοῖς ὑπ’ αὐτοῦ παρακαλουμένοις τοὺς συνεληλυθότας. τοῦ δὲ Φιλοποίμενος καὶ Λυκόρτα, σὺν δὲ τούτοις Ἄρχωνος, πολλοὺς καὶ ποικίλους διαθεμένων λόγους ὑπὲρ τοῦ καλῶς μὲν διῳκῆσθαι τὰ κατὰ τὴν Σπάρτην καὶ συμφερόντως αὐτοῖς μάλιστα τοῖς Λακεδαιμονίοις, ἀδύνατον δ’ εἶναι τὸ κινῆσαί τι τῶν ὑποκειμένων ἄνευ τοῦ παραβῆναι καὶ τὰ πρὸς τοὺς ἀνθρώπους δίκαια καὶ τὰ πρὸς τοὺς θεοὺς ὅσια, μένειν ἔδοξε τοῖς παροῦσιν ἐπὶ τῶν ὑποκειμένων καὶ ταύτην δοῦναι τῷ πρεσβευτῇ τὴν ἀπόκρισιν. ὁ δὲ Καικίλιος ὁρῶν τὴν τούτων προαίρεσιν, ἠξίου τοὺς πολλοὺς αὑτῷ συναγαγεῖν εἰς ἐκκλησίαν. οἱ δὲ τῶν Ἀχαιῶν ἄρχοντες ἐκέλευον αὐτὸν δεῖξαι τὰς ἐντολάς, ἃς εἶχε παρὰ τῆς συγκλήτου περὶ τούτων. τοῦ δὲ παρασιωπῶντος, οὐκ ἔφασαν αὐτῷ συνάξειν τὴν ἐκκλησίαν· τοὺς γὰρ νόμους οὐκ ἐᾶν, ἐὰν μὴ φέρῃ τις ἔγγραπτα παρὰ τῆς συγκλήτου, περὶ ὧν οἴεται δεῖν συνάγειν. ὁ δὲ Καικίλιος ἐπὶ τοσοῦτον ὠργίσθη διὰ τὸ μηθὲν αὐτῷ συγχωρεῖσθαι τῶν ἀξιουμένων, ὥστ’ οὐδὲ τὴν ἀπόκρισιν ἠβουλήθη δέξασθαι παρὰ τῶν ἀρχόντων, ἀλλ’ ἀναπόκριτος ἀπῆλθεν. οἱ δ’ Ἀχαιοὶ τὴν αἰτίαν ἀνέφερον καὶ τῆς πρότερον παρουσίας ἅμα τῆς Μάρκου τοῦ Φολουίου καὶ τῆς τότε τῶν περὶ τὸν Καικίλιον ἐπὶ τὸν Ἀρίσταινον καὶ τὸν Διοφάνην, ὡς τούτους ἀντισπασαμένους διὰ τὴν ἀντιπολιτείαν τὴν πρὸς τὸν Φιλοποίμενα· καί τις ἦν ὑποψία τῶν πολλῶν πρὸς τοὺς προειρημένους ἄνδρας. καὶ τὰ μὲν κατὰ Πελοπόννησον ἐν τούτοις ἦν.", "st": "22.13"}, {"sp": "N", "t": "ὅτι Φιλοποίμην πρὸς Ἄρχωνα τὸν στρατηγὸν λόγοις τισὶ διεφέρετο. ὁ μὲν οὖν Φιλοποίμην εὐδοκήσας ἐκ τοῦ καιροῦ τοῖς λεγομένοις καὶ μεταγνοὺς ἐπῄνει τὸν Ἄρχωνα φιλοφρόνως, ὡς ἐντρεχῶς καὶ πανούργως τῷ καιρῷ κεχρημένον. ἔμοιγε μήν, φησὶν ὁ Πολύβιος, οὔτε τότε παρόντι τὸ ῥηθὲν εὐηρέστησεν, ὥστ’ ἐπαινοῦντά τινα κακῶς ἅμα ποιεῖν, οὔτε μετὰ ταῦτα τῆς ἡλικίας προβαινούσης· πολὺ γὰρ δή τι μοι δοκεῖ κεχωρίσθαι κατὰ τὴν αἵρεσιν ὁ πραγματικὸς ἀνὴρ τοῦ κακοπράγμονος καὶ παραπλησίαν ἔχειν διαφορὰν τῷ κακεντρεχεῖ πρὸς τὸν ἐντρεχῆ· ἃ μὲν γάρ ἐστι κάλλιστα τῶν ὄντων ὡς ἔπος εἰπεῖν, ἃ δὲ τοὐναντίον· ἀλλὰ διὰ τὴν νῦν ἐπιπολάζουσαν ἀκρισίαν βραχείας ἔχοντα κοινότητας τὰ προειρημένα τῆς αὐτῆς ἐπισημασίας καὶ ζήλου τυγχάνει παρὰ τοῖς ἀνθρώποις.", "st": "22.14"}, {"sp": "N", "t": "ὅτι τῶν περὶ τὸν Καικίλιον ἀνακεχωρηκότων ἐκ τῆς Ἑλλάδος καὶ διασεσαφηκότων τῇ συγκλήτῳ περί τε τῶν κατὰ Μακεδονίαν καὶ τῶν κατὰ Πελοπόννησον, εἰσῆγον εἰς τὴν σύγκλητον τοὺς περὶ τούτων παραγεγονότας πρεσβευτάς. εἰσελθόντων δὲ πρῶτον τῶν παρὰ τοῦ Φιλίππου καὶ παρ’ Εὐμένους, ἔτι δὲ τῶν ἐξ Αἴνου καὶ Μαρωνείας φυγάδων, καὶ ποιησαμένων τοὺς λόγους ἀκολούθως τοῖς ἐν Θετταλονίκῃ ῥηθεῖσιν ἐπὶ τῶν περὶ τὸν Καικίλιον, ἔδοξε τῇ συγκλήτῳ πέμπειν πάλιν ἄλλους πρεσβευτὰς πρὸς τὸν Φίλιππον τοὺς ἐπισκεψομένους πρῶτον μὲν εἰ παρακεχώρηκε τῶν ἐν Θετταλίᾳ καὶ Περραιβίᾳ πόλεων κατὰ τὴν τῶν περὶ τὸν Καικίλιον ἀπόκρισιν, εἶτα τοὺς ἐπιτάξοντας αὐτῷ τὰς φρουρὰς ἐξάγειν ἐξ Αἴνου καὶ Μαρωνείας, καὶ συλλήβδην ἀποβαίνειν ἀπὸ τῶν παραθαλαττίων τῆς Θρᾴκης ἐρυμάτων καὶ τόπων καὶ πόλεων. μετὰ δὲ τούτους εἰσῆγον τοὺς ἀπὸ Πελοποννήσου παραγεγονότας. οἵ τε γὰρ Ἀχαιοὶ πρεσβευτὰς ἀπεστάλκεισαν τοὺς περὶ Ἀπολλωνίδαν τὸν Σικυώνιον δικαιολογησομένους πρὸς τὸν Καικίλιον ὑπὲρ τοῦ μὴ λαβεῖν αὐτὸν ἀπόκρισιν καὶ καθόλου διδάξοντας ὑπὲρ τῶν κατὰ Λακεδαίμονα πραγμάτων, ἔκ τε τῆς Σπάρτης Ἀρεὺς καὶ Ἀλκιβιάδης ἐπρέσβευσαν· οὗτοι δ’ ἦσαν τῶν ἀρχαίων φυγάδων τῶν ὑπὸ τοῦ Φιλοποίμενος καὶ τῶν Ἀχαιῶν νεωστὶ κατηγμένων εἰς τὴν οἰκείαν. ὃ καὶ μάλιστα τοὺς Ἀχαιοὺς εἰς ὀργὴν ἦγε τῷ δοκεῖν, μεγάλης οὔσης καὶ προσφάτου τῆς εἰς τοὺς φυγάδας εὐεργεσίας, ἐξ αὐτῆς ἐπὶ τοσοῦτον ἀχαριστεῖσθαι παρ’ αὐτοῖς ὥστε καὶ καταπρεσβεύειν καὶ κατηγορίαν ποιεῖσθαι πρὸς τοὺς κρατοῦντας τῶν ἀνελπίστως αὐτοὺς σωσάντων καὶ καταγαγόντων εἰς τὴν πατρίδα.", "st": "22.15"}, {"sp": "N", "t": "ποιησαμένων δὲ καὶ τούτων πρὸς ἀλλήλους ἐκ συγκαταθέσεως τὴν δικαιολογίαν, καὶ διδασκόντων τὴν σύγκλητον τῶν μὲν περὶ τὸν Ἀπολλωνίδαν τὸν Σικυώνιον ὡς ἀδύνατον εἴη τὸ παράπαν ἄμεινον χειρισθῆναι τὰ κατὰ τὴν Σπάρτην ἢ νῦν κεχείρισται διὰ τῶν Ἀχαιῶν καὶ διὰ Φιλοποίμενος, τῶν δὲ περὶ τὸν Ἀρέα τἀναντία πειρωμένων λέγειν καὶ φασκόντων πρῶτον μὲν καταλελύσθαι τὴν τῆς πόλεως δύναμιν ἐξηγμένου τοῦ πλήθους μετὰ βίας, εἶτ’ ἐν αὐτοῖς ἐπισφαλῆ καὶ ἀπαρρησίαστον καταλείπεσθαι τὴν πολιτείαν, ἐπισφαλῆ μὲν ὀλίγοις οὖσιν καὶ τούτοις τῶν τειχῶν περιῃρημένων, ἀπαρρησίαστον δὲ διὰ τὸ μὴ μόνον τοῖς κοινοῖς δόγμασιν τῶν Ἀχαιῶν πειθαρχεῖν, ἀλλὰ καὶ κατ’ ἰδίαν ὑπηρετεῖν τοῖς ἀεὶ καθισταμένοις ἄρχουσιν, διακούσασα καὶ τούτων ἡ σύγκλητος ἔκρινε τοῖς αὐτοῖς πρεσβευταῖς δοῦναι καὶ περὶ τούτων ἐντολάς, καὶ κατέστησεν πρεσβευτὰς ἐπὶ τὴν Μακεδονίαν καὶ τὴν Ἑλλάδα τοὺς περὶ Ἄππιον Κλαύδιον. Ἀπελογήθησαν δὲ καὶ πρὸς τὸν Καικίλιον ὑπὲρ τῶν ἀρχόντων οἱ παρὰ τῶν Ἀχαιῶν πρέσβεις ἐν τῇ συγκλήτῳ, φάσκοντες οὐθὲν ἀδικεῖν αὐτοὺς οὐδ’ ἀξίους ἐγκλήματος ὑπάρχειν ἐπὶ τῷ μὴ συνάγειν τὴν ἐκκλησίαν· νόμον γὰρ εἶναι παρὰ τοῖς Ἀχαιοῖς μὴ συγκαλεῖν τοὺς πολλούς, ἐὰν μὴ περὶ συμμαχίας ἢ πολέμου δέῃ γίνεσθαι διαβούλιον ἢ παρὰ τῆς συγκλήτου τις ἐνέγκῃ γράμματα. διὸ καὶ δικαίως τότε βουλεύσασθαι μὲν τοὺς ἄρχοντας συγκαλεῖν τοὺς Ἀχαιοὺς εἰς ἐκκλησίαν, κωλύεσθαι δ’ ὑπὸ τῶν νόμων διὰ τὸ μήτε γράμματα φέρειν αὐτὸν παρὰ τῆς συγκλήτου μήτε τὰς ἐντολὰς ἐγγράπτους ἐθέλειν δοῦναι τοῖς ἄρχουσιν. ὧν ῥηθέντων ἀναστὰς Καικίλιος τῶν τε περὶ τὸν Φιλοποίμενα καὶ Λυκόρταν κατηγόρησεν καὶ καθόλου τῶν Ἀχαιῶν καὶ τῆς οἰκονομίας, ᾗ περὶ τῆς τῶν Λακεδαιμονίων ἐκέχρηντο πόλεως. ἡ δὲ σύγκλητος διακούσασα τῶν λεγομένων ἔδωκε τοῖς Ἀχαιοῖς ἀπόκρισιν ὅτι περὶ μὲν τῶν κατὰ Λακεδαίμονα πέμψει τοὺς ἐπισκεψομένους· τοῖς δὲ πρεσβευταῖς τοῖς αἰεὶ παρ’ ἑαυτῶν ἐκπεμπομένοις παρῄνει προσέχειν τὸν νοῦν καὶ καταδοχὴν ποιεῖσθαι τὴν ἁρμόζουσαν, καθάπερ καὶ Ῥωμαῖοι ποιοῦνται τῶν παραγινομένων πρὸς αὐτοὺς πρεσβευτῶν.", "st": "22.16"}, {"sp": "N", "t": "ὅτι Φίλιππος ὁ βασιλεύς, διαπεμψαμένων πρὸς αὐτὸν ἐκ τῆς Ῥώμης τῶν ἰδίων πρεσβευτῶν καὶ δηλούντων ὅτι δεήσει κατ’ ἀνάγκην ἀποβαίνειν ἀπὸ τῶν ἐπὶ Θρᾴκης πόλεων, πυθόμενος ταῦτα καὶ βαρέως φέρων ἐπὶ τῷ δοκεῖν πανταχόθεν αὐτοῦ περιτέμνεσθαι τὴν ἀρχήν, ἐναπηρείσατο τὴν ὀργὴν εἰς τοὺς ταλαιπώρους Μαρωνείτας. μεταπεμψάμενος γὰρ Ὀνόμαστον τὸν ἐπὶ Θρᾴκης τεταγμένον ἐκοινολογήθη τούτῳ περὶ τῆς πράξεως. ὁ δ’ Ὀνόμαστος ἀναχωρήσας ἐξαπέστειλε Κάσσανδρον εἰς Μαρώνειαν, συνήθη τοῖς πολλοῖς ὑπάρχοντα διὰ τὸ ποιεῖσθαι τὸν πλείονα χρόνον ἐκεῖ τὴν διατριβήν, ἅτε τοῦ Φιλίππου πάλαι τοὺς αὐλικοὺς ἐγκαθεικότος εἰς τὰς πόλεις ταύτας καὶ συνήθεις πεποιηκότος τοὺς ἐγχωρίους ταῖς τούτων παρεπιδημίαις. μετὰ δέ τινας ἡμέρας ἑτοιμασθέντων τῶν Θρᾳκῶν, καὶ τούτων ἐπεισελθόντων διὰ τοῦ Κασσάνδρου νυκτός, ἐγένετο μεγάλη σφαγὴ καὶ πολλοὶ τῶν Μαρωνειτῶν ἀπέθανον. κολασάμενος δὲ τῷ τοιούτῳ τρόπῳ τοὺς ἀντιπράττοντας ὁ Φίλιππος καὶ πληρώσας τὸν ἴδιον θυμόν, ἐκαραδόκει τὴν τῶν πρεσβευτῶν παρουσίαν [πεπεισμένος μηδένα τολμήσειν κατηγορήσειν αὐτοῦ διὰ τὸν φόβον]. μετὰ δέ τινα χρόνον παραγενομένων τῶν περὶ τὸν Ἄππιον καὶ ταχέως πυθομένων τὰ γεγονότα κατὰ τὴν Μαρώνειαν καὶ πικρῶς τῷ Φιλίππῳ μεμψιμοιρούντων ἐπὶ τούτοις, ἐβούλετο μὲν ἀπολογεῖσθαι, φάσκων μὴ κεκοινωνηκέναι τῆς παρανομίας, ἀλλ’ αὐτοὺς ἐν αὑτοῖς στασιάζοντας Μαρωνείτας, [καὶ] τοὺς μὲν ἀποκλίνοντας πρὸς Εὐμένη κατὰ τὴν εὔνοιαν, τοὺς δὲ πρὸς ἑαυτόν, εἰς ταύτην ἐμπεπτωκέναι τὴν ἀτυχίαν. καλεῖν δ’ ἐκέλευε κατὰ πρόσωπον, εἴ τις αὐτοῦ κατηγορεῖ. τοῦτο δ’ ἐποίει πεπεισμένος μηδένα τολμήσειν διὰ τὸν φόβον, τῷ δοκεῖν τὴν μὲν ἐκ Φιλίππου τιμωρίαν ἐκ χειρὸς ἔσεσθαι τοῖς ἀντιπράξασιν, τὴν δὲ Ῥωμαίων ἐπικουρίαν μακρὰν ἀφεστάναι. τῶν δὲ περὶ τὸν Ἄππιον οὐ φασκόντων προσδεῖσθαι δικαιολογίας, σαφῶς γὰρ εἰδέναι τὰ γεγονότα καὶ τὸν αἴτιον τούτων, εἰς ἀπορίαν ἐνέπιπτεν ὁ Φίλιππος. καὶ τὴν μὲν πρώτην ἔντευξιν ἄχρι τούτου προβάντες ἔλυσαν·", "st": "22.17"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐπιοῦσαν ἡμέραν οἱ περὶ τὸν Ἄππιον πέμπειν ἐπέταττον τῷ Φιλίππῳ τὸν Ὀνόμαστον καὶ τὸν Κάσσανδρον ἐξ αὐτῆς εἰς τὴν Ῥώμην [ἵνα πύθηται περὶ τῶν γεγονότων]. ὁ δὲ βασιλεύς, διατραπεὶς ὡς ἔνι μάλιστα καὶ ἀπορήσας ἐπὶ πολὺν χρόνον, τὸν μὲν Κάσσανδρον ἔφη πέμψειν, τὸν αὐθέντην γεγονότα τῆς πράξεως, ὡς ἐκεῖνοί φασιν, ἵνα πύθηται παρὰ τούτου τὰς ἀληθείας ἡ σύγκλητος. τὸν δ’ Ὀνόμαστον ἐξῃρεῖτο καὶ παρ’ αὐτὰ καὶ μετὰ ταῦτα τοῖς πρεσβευταῖς ἐντυγχάνων, ἀφορμῇ μὲν χρώμενος τῷ μὴ οἷον ἐν τῇ Μαρωνείᾳ παραγεγονέναι τὸν Ὀνόμαστον κατὰ τὸν τῆς σφαγῆς καιρόν, ἀλλὰ μηδ’ ἐπὶ τῶν σύνεγγυς τόπων γεγονέναι, τῇ δ’ ἀληθείᾳ δεδιὼς μὴ παραγενηθεὶς εἰς τὴν Ῥώμην, καὶ πολλῶν ἔργων αὐτῷ κεκοινωνηκὼς τοιούτων, οὐ μόνον τὰ κατὰ τοὺς Μαρωνείτας, ἀλλὰ καὶ τἄλλα πάντα διασαφήσῃ τοῖς Ῥωμαίοις. καὶ τέλος τὸν μὲν Ὀνόμαστον ἐξείλετο, τὸν δὲ Κάσσανδρον μετὰ τὸ τοὺς πρεσβευτὰς ἀπελθεῖν ἀποστείλας καὶ παραπέμψας ἕως Ἠπείρου φαρμάκῳ διέφθειρεν. οἱ δὲ περὶ τὸν Ἄππιον, κατεγνωκότες τοῦ Φιλίππου καὶ περὶ τῆς εἰς τοὺς Μαρωνείτας παρανομίας καὶ περὶ τῆς πρὸς Ῥωμαίους ἀλλοτριότητος, τοιαύτας ἔχοντες διαλήψεις ἐχωρίσθησαν. ὁ δὲ βασιλεὺς γενόμενος καθ’ ἑαυτὸν καὶ συμμεταδοὺς τῶν φίλων Ἀπελλῇ καὶ Φιλοκλεῖ περὶ τῶν ἐνεστώτων, ἔγνω σαφῶς ἐπὶ πολὺ προβεβηκυῖαν αὑτοῦ τὴν πρὸς Ῥωμαίους διαφοράν, καὶ ταύτην οὐκέτι λανθάνουσαν, ἀλλὰ καταφανῆ τοῖς πλείστοις οὖσαν. καθόλου μὲν οὖν πρόθυμος ἦν εἰς τὸ κατὰ πάντα τρόπον ἀμύνασθαι καὶ μετελθεῖν αὐτούς· πρὸς ἔνια δὲ τῶν ἐπινοουμένων ἀπόχειρος ὢν ἐπεβάλετο πῶς ἂν ἔτι γένοιτό τις ἀναστροφὴ καὶ λάβοι χρόνον πρὸς τὰς εἰς τὸν πόλεμον παρασκευάς. ἔδοξεν οὖν αὐτῷ τὸν νεώτατον υἱὸν Δημήτριον πέμπειν εἰς τὴν Ῥώμην, τὰ μὲν ἀπολογησόμενον ὑπὲρ τῶν ἐγκαλουμένων, τὰ δὲ καὶ παραιτησόμενον, εἰ καί τις ἄγνοιά ποτ’ ἐγεγόνει περὶ αὐτόν. πάνυ γὰρ ἐπέπειστο διὰ τούτου πᾶν τὸ προτεθὲν ἀνύεσθαι παρὰ τῆς συγκλήτου διὰ τὴν ὑπεροχὴν τὴν γεγενημένην τοῦ νεανίσκου κατὰ τὴν ὁμηρείαν. ταῦτα δὲ διανοηθεὶς ἅμα μὲν ἐγίνετο περὶ τὴν ἐκπομπὴν τούτου καὶ τῶν ἅμα τούτῳ συνεξαποσταλησομένων φίλων, ἅμα δὲ τοῖς Βυζαντίοις ὑπέσχετο βοηθήσειν, οὐχ οὕτως ἐκείνων στοχαζόμενος ὡς ἐπὶ τῇ ’κείνων προφάσει βουλόμενος καταπλήξασθαι τοὺς τῶν Θρᾳκῶν δυνάστας τῶν ὑπὲρ τὴν Προποντίδα κατοικούντων χάριν τῆς προκειμένης ἐπιβολῆς.", "st": "22.18"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Κρήτην, κοσμοῦντος ἐν Γορτύνῃ Κύδα τοῦ Ἀντάλκους, κατὰ πάντα τρόπον ἐλαττούμενοι Γορτύνιοι τοὺς Κνωσίους, ἀποτεμόμενοι τῆς χώρας αὐτῶν τὸ μὲν καλούμενον Λυκάστιον προσένειμαν Ῥαυκίοις, τὸ δὲ Διατόνιον Λυττίοις. κατὰ δὲ τὸν καιρὸν τοῦτον παραγενομένων πρεσβευτῶν ἐκ τῆς Ῥώμης εἰς τὴν Κρήτην τῶν περὶ τὸν Ἄππιον χάριν τοῦ διαλῦσαι τὰς ἐνεστώσας αὐτοῖς πρὸς ἀλλήλους διαφοράς, καὶ ποιησαμένων λόγους ὑπὲρ τούτων ἐν τῇ Κνωσίων καὶ Γορτυνίων, πεισθέντες οἱ Κρηταιεῖς ἐπέτρεψαν τὰ καθ’ αὑτοὺς τοῖς περὶ τὸν Ἄππιον. οἱ δὲ [πεισθέντες] Κνωσίοις μὲν ἀποκατέστησαν τὴν χώραν, Κυδωνιάταις δὲ προσέταξαν τοὺς μὲν ὁμήρους ἀπολαβεῖν, οὓς ἐγκατέλειπον δόντες τοῖς περὶ Χαρμίωνα πρότερον, τὴν δὲ Φαλάσαρναν ἀφεῖναι μηδὲν ἐξ αὐτῆς νοσφισαμένους. περὶ δὲ τῶν κατὰ κοινοδίκιον συνεχώρησαν αὐτοῖς βουλομένοις μὲν [αὐτοῖς] ἐξεῖναι μετέχειν, μὴ βουλομένοις δὲ καὶ τοῦτ’ ἐξεῖναι, πάσης ἀπεχομένοις τῆς ἄλλης Κρήτης αὐτοῖς τε καὶ τοῖς ἐκ Φαλασάρνης φυγάσιν. ἀπέκτειναν τοὺς περὶ Μενοίτιον, ἐπιφανεστάτους ὄντας τῶν πολιτῶν.", "st": "22.19"}, {"sp": "N", "t": "ὅτι Ἀπολλωνίς, ἡ Ἀττάλου τοῦ πατρὸς Εὐμένους τοῦ βασιλέως γαμετή, Κυζικηνὴ ἦν, γυνὴ διὰ πλείους αἰτίας ἀξία μνήμης καὶ παρασημασίας. καὶ γὰρ ὅτι δημότις ὑπάρχουσα βασίλισσα ἐγεγόνει καὶ ταύτην διεφύλαξε τὴν ὑπεροχὴν μέχρι τῆς τελευταίας, οὐχ ἑταιρικὴν προσφερομένη πιθανότητα, σωφρονικὴν δὲ καὶ πολιτικὴν σεμνότητα καὶ καλοκαγαθίαν, δικαία τυγχάνειν τῆς ἐπ’ ἀγαθῷ μνήμης ἐστίν, καὶ καθότι τέτταρας υἱοὺς γεννήσασα πρὸς πάντας τούτους ἀνυπέρβλητον διεφύλαξε τὴν εὔνοιαν καὶ φιλοστοργίαν μέχρι τῆς τοῦ βίου καταστροφῆς, καίτοι χρόνον οὐκ ὀλίγον ὑπερβιώσασα τἀνδρός. πλὴν οἵγε περὶ τὸν Ἄτταλον ἐν τῇ παρεπιδημίᾳ καλὴν περιεποιήσαντο φήμην, ἀποδιδόντες τῇ μητρὶ τὴν καθήκουσαν χάριτα καὶ τιμήν. ἄγοντες γὰρ ἐξ ἀμφοῖν τοῖν χεροῖν μέσην αὑτῶν τὴν μητέρα περιῄεσαν τά θ’ ἱερὰ καὶ τὴν πόλιν μετὰ τῆς θεραπείας. ἐφ’ οἷς οἱ θεώμενοι μεγάλως τοὺς νεανίσκους ἀπεδέχοντο καὶ κατηξίουν καὶ μνημονεύοντες τῶν περὶ τὸν Κλέοβιν καὶ Βίτωνα συνέκρινον τὰς αἱρέσεις αὐτῶν, καὶ τὸ τῆς προθυμίας τῆς ἐκείνων λαμπρὸν τῷ τῆς ὑπεροχῆς τῶν βασιλέων ἀξιώματι συναναπληροῦντες. ταῦτα δ’ ἐτελέσθη ἐν Κυζίκῳ μετὰ τὴν διάλυσιν τὴν πρὸς Προυσίαν τὸν βασιλέα. —", "st": "22.20"}, {"sp": "N", "t": "ὅτι Ὀρτιάγων ὁ Γαλάτης, τῶν ἐν τῇ Ἀσίᾳ βασιλεύων, ἐπεβάλετο τὴν ἁπάντων τῶν Γαλατῶν δυναστείαν εἰς αὑτὸν μεταστῆσαι, καὶ πολλὰ πρὸς τοῦτο τὸ μέρος ἐφόδια προσεφέρετο καὶ φύσει καὶ τριβῇ. καὶ γὰρ εὐεργετικὸς ἦν καὶ μεγαλόψυχος καὶ κατὰ τὰς ἐντεύξεις εὔχαρις καὶ συνετός, τὸ δὲ συνέχον παρὰ Γαλάταις, ἀνδρώδης ἦν καὶ δυναμικὸς πρὸς τὰς πολεμικὰς χρείας.", "st": "22.21"}, {"sp": "N", "t": "ὅτι Ἀριστόνικος ὁ τοῦ Πτολεμαίου τοῦ βασιλέως Αἰγύπτου εὐνοῦχος μὲν ἦν, ἐκ παιδίου δ’ ἐγεγόνει σύντροφος τῷ βασιλεῖ. τῆς δ’ ἡλικίας προβαινούσης ἀνδρωδεστέραν εἶχεν ἢ κατ’ εὐνοῦχον τόλμαν καὶ προαίρεσιν. καὶ γὰρ φύσει στρατιωτικὸς ἦν καὶ τὴν πλείστην ἐποιεῖτο διατριβὴν ἐν τούτοις καὶ περὶ ταῦτα. παραπλησίως δὲ καὶ κατὰ τὰς ἐντεύξεις ἱκανὸς ὑπῆρχε καὶ τὸν κοινὸν νοῦν εἶχεν, ὃ σπάνιόν ἐστι. πρὸς δὲ τούτοις πρὸς εὐεργεσίαν ἀνθρώπων πεφύκει καλῶς.", "st": "22.22"}, {"sp": "HDR", "t": "Βιβλίον ΚΓʹ", "st": "23"}, {"sp": "N", "t": "ὅτι κατὰ τὴν ἐνάτην καὶ τετταρακοστὴν ὀλυμπιάδα πρὸς ταῖς ἑκατὸν εἰς τὴν Ῥώμην ἡθροίσθησαν πρεσβειῶν πλῆθος ἀπὸ τῆς Ἑλλάδος, ὅσον οὐ ταχέως πρότερον. τοῦ γὰρ Φιλίππου συγκλεισθέντος εἰς τὴν κατὰ τὸ σύμβολον δικαιοδοσίαν πρὸς τοὺς ἀστυγείτονας, καὶ τῶν Ῥωμαίων γνωσθέντων ὅτι προσδέχονται τὰς κατὰ Φιλίππου κατηγορίας καὶ πρόνοιαν ποιοῦνται τῆς ἀσφαλείας τῶν πρὸς αὐτὸν ἀμφισβητούντων, ἅπαντες οἱ παρακείμενοι τῇ Μακεδονίᾳ παρῆσαν, οἱ μὲν κατ’ ἰδίαν, οἱ δὲ κατὰ πόλιν, οἱ δὲ κατὰ τὰς ἐθνικὰς συστάσεις, ἐγκαλοῦντες τῷ Φιλίππῳ. σὺν δὲ τούτοις οἱ παρ’ Εὐμένους ἧκον ἅμ’ Ἀθηναίῳ τῷ τοῦ βασιλέως ἀδελφῷ, κατηγορήσοντες αὐτοῦ περί τε τῶν ἐπὶ Θρᾴκης πόλεων καὶ περὶ τῆς ἀποσταλείσης Προυσίᾳ βοηθείας. ἧκε δὲ καὶ Δημήτριος ὁ τοῦ Φιλίππου πρὸς πάντας τούτους ἀπολογησόμενος, ἔχων Ἀπελλῆν καὶ Φιλοκλῆ μεθ’ αὑτοῦ, τοὺς τότε δοκοῦντας εἶναι πρώτους φίλους τοῦ βασιλέως. παρῆσαν δὲ καὶ παρὰ Λακεδαιμονίων πρέσβεις, ἀφ’ ἑκάστου γένους τῶν ἐν τῇ πόλει. πρῶτον μὲν οὖν ἡ σύγκλητος εἰσεκαλέσατο τὸν Ἀθήναιον καὶ δεξαμένη τὸν στέφανον, ὃν ἐκόμιζεν ἀπὸ μυρίων καὶ πεντακισχιλίων χρυσῶν, ἐπῄνεσέ τε μεγαλομερῶς τὸν Εὐμένη καὶ τοὺς ἀδελφοὺς διὰ τῆς ἀποκρίσεως καὶ παρεκάλεσε μένειν ἐπὶ τῆς αὐτῆς αἱρέσεως. ἐπὶ δὲ τούτῳ τὸν Δημήτριον εἰσαγαγόντες οἱ στρατηγοὶ παρεκαλέσαντο τοὺς κατηγοροῦντας τοῦ Φιλίππου πάντας καὶ παρῆγον κατὰ μίαν πρεσβείαν. οὐσῶν δὲ τῶν πρεσβειῶν πολλῶν, καὶ τῆς εἰσόδου τούτων γενομένης ἐπὶ τρεῖς ἡμέρας, εἰς ἀπορίαν ἐνέπιπτεν ἡ σύγκλητος περὶ τοῦ πῶς δεῖ χειρισθῆναι τὰ κατὰ μέρος. παρά τε γὰρ Θετταλῶν καὶ κατὰ κοινὸν ἧκον καὶ κατ’ ἰδίαν ἀφ’ ἑκάστης πόλεως πρεσβευταί, παρά τε Περραιβῶν, ὁμοίως δὲ καὶ παρ’ Ἀθαμάνων καὶ παρ’ Ἠπειρωτῶν καὶ παρ’ Ἰλλυριῶν· ὧν οἱ μὲν περὶ χώρας, οἱ δὲ περὶ σωμάτων, οἱ δὲ περὶ θρεμμάτων ἧκον ἀμφισβητοῦντες, ἔνιοι δὲ περὶ συμβολαίων καὶ τῶν εἰς αὑτοὺς ἀδικημάτων, τινὲς μὲν οὐ φάσκοντες δύνασθαι τυχεῖν τοῦ δικαίου κατὰ τὸ σύμβολον διὰ τὸ τὸν Φίλιππον ἐκκόπτειν τὴν δικαιοδοσίαν, τινὲς δ’ ἐγκαλοῦντες τοῖς κρίμασιν ὡς παραβεβραβευμένοι, διαφθείραντος τοῦ Φιλίππου τοὺς δικαστάς. καθόλου δὲ ποικίλη τις ἦν ἀκρισία καὶ δυσχώρητος ἐκ τῶν κατηγορουμένων.", "st": "23.1"}, {"sp": "N", "t": "ὅθεν ἡ σύγκλητος, οὔτ’ αὐτὴ δυναμένη διευκρινεῖν οὔτε τὸν Δημήτριον κρίνουσα δεῖν ἑκάστοις τούτων λόγον ὑπέχειν, ἅτε καὶ φιλανθρώπως πρὸς αὐτὸν διακειμένη καὶ θεωροῦσα νέον ὄντα κομιδῇ καὶ πολὺ τῆς τοιαύτης συστροφῆς καὶ ποικιλίας ἀπολειπόμενον, μάλιστα δὲ βουλομένη μὴ τῶν Δημητρίου λόγων ἀκούειν, ἀλλὰ τῆς Φιλίππου γνώμης ἀληθινὴν λαβεῖν πεῖραν, αὐτὸν Δημήτριον παρέλυσε τῆς δικαιολογίας, ἤρετο δὲ τὸν νεανίσκον καὶ τοὺς σὺν αὐτῷ φίλους εἴ τινα περὶ τούτων ὑπομνηματισμὸν ἔχουσι παρὰ τοῦ βασιλέως. τοῦ δὲ Δημητρίου φήσαντος ἔχειν καὶ προτείναντός τι βυβλίδιον οὐ μέγα, λέγειν αὐτὸν ἐκέλευσεν ἥνπερ τὰ ὑπομνήματα περιεῖχε πρὸς ἕκαστον τῶν κατηγορουμένων ἀπόφασιν κεφαλαιώδη. ὁ δὲ τὸ μὲν πεποιηκέναι τὸ προσταχθὲν ὑπὸ Ῥωμαίων ἔφασκεν, ἢ τὴν αἰτίαν τοῦ μὴ πεπρᾶχθαι τοῖς ἐγκαλοῦσιν ἀνετίθει. προσέκειτο δὲ πρὸς ταῖς πλείσταις ἀποφάσεσι \"καίτοι οὐκ ἴσως χρησαμένων ἡμῖν τῶν πρεσβευτῶν τῶν περὶ Καικίλιον ἐν τούτοις\" καὶ πάλιν \"καίτοι γε οὐ δικαίως ἡμῶν ταῦτα πασχόντων\". τοιαύτης δ’ οὔσης τῆς Φιλίππου γνώμης ἐν πάσαις ταῖς ἀποφάσεσι, διακούσασα τῶν παραγεγονότων ἡ σύγκλητος μίαν ἐποιήσατο περὶ πάντων διάληψιν. ἀποδεξαμένη γὰρ τὸν Δημήτριον μεγαλομερῶς καὶ φιλανθρώπως διὰ τοῦ στρατηγοῦ, πολλοὺς καὶ παρακλητικοὺς πρὸς αὐτὸν διαθεμένη λόγους, ἀπόκρισιν ἔδωκε διότι περὶ πάντων καὶ τῶν εἰρημένων ὑπ’ αὐτοῦ καὶ τῶν ἀνεγνωσμένων Δημητρίῳ πιστεύει διότι τὰ μὲν γέγονε, τὰ δ’ ἔσται, καθάπερ δίκαιόν ἐστι γίνεσθαι. ἵνα δὲ καὶ Φίλιππος εἰδῇ διότι τὴν χάριν ταύτην ἡ σύγκλητος Δημητρίῳ δίδωσιν, ἐξαποστελεῖν ἔφη πρεσβευτὰς ἐποψομένους εἰ γίνεται πάντα κατὰ τὴν τῆς συγκλήτου βούλησιν, ἅμα δὲ διασαφήσοντας τῷ βασιλεῖ διότι τῆς συμπεριφορᾶς τυγχάνει ταύτης διὰ Δημήτριον. καὶ ταῦτα μὲν τοιαύτης ἔτυχε διεξαγωγῆς.", "st": "23.2"}, {"sp": "N", "t": "μετὰ δὲ τούτους εἰσῆλθον οἱ παρ’ Εὐμένους πρέσβεις καὶ περί τε τῆς βοηθείας τῆς ἀποσταλείσης ὑπὸ τοῦ Φιλίππου τῷ Προυσίᾳ κατηγόρησαν καὶ περὶ τῶν ἐπὶ Θρᾴκης τόπων, φάσκοντες οὐδ’ ἔτι καὶ νῦν αὐτὸν ἐξαγηοχέναι τὰς φρουρὰς ἐκ τῶν πόλεων. τοῦ δὲ Φιλοκλέους ὑπὲρ τούτων βουληθέντος ἀπολογεῖσθαι διὰ τὸ καὶ πρὸς τὸν Προυσίαν πεπρεσβευκέναι καὶ τότε περὶ τούτων ἐξαπεστάλθαι πρὸς τὴν σύγκλητον ὑπὸ τοῦ Φιλίππου, βραχύν τινα χρόνον ἡ σύγκλητος ἐπιδεξαμένη τοὺς λόγους ἔδωκεν ἀπόκρισιν διότι, τῶν ἐπὶ Θρᾴκης τόπων ἐὰν μὴ καταλάβωσιν οἱ πρεσβευταὶ πάντα διῳκημένα κατὰ τὴν τῆς συγκλήτου γνώμην καὶ πάσας τὰς πόλεις εἰς τὴν Εὐμένους πίστιν ἐγκεχειρισμένας, οὐκέτι δυνήσεται φέρειν οὐδὲ καρτερεῖν παρακουομένη περὶ τούτων. καὶ τῆς μὲν Φιλίππου καὶ Ῥωμαίων παρατριβῆς ἐπὶ πολὺ προβαινούσης ἐπίστασις ἐγενήθη κατὰ τὸ παρὸν διὰ τὴν τοῦ Δημητρίου παρουσίαν· πρὸς μέντοι γε τὴν καθόλου τῆς οἰκίας ἀτυχίαν οὐ μικρὰ συνέβη τὴν εἰς τὴν Ῥώμην τοῦ νεανίσκου πρεσβείαν συμβαλέσθαι. ἥ τε γὰρ σύγκλητος ἀπερεισαμένη τὴν χάριν ἐπὶ τὸν Δημήτριον ἐμετεώρισε μὲν τὸ μειράκιον, ἐλύπησε δὲ καὶ τὸν Περσέα καὶ τὸν Φίλιππον ἰσχυρῶς τῷ δοκεῖν μὴ δι’ αὐτούς, ἀλλὰ διὰ Δημήτριον τυγχάνειν τῆς παρὰ Ῥωμαίων φιλανθρωπίας. ὅ τε Τίτος ἐκκαλεσάμενος τὸ μειράκιον καὶ προβιβάσας εἰς λόγους ἀπορρήτους, οὐκ ὀλίγα συνεβάλετο πρὸς τὴν αὐτὴν ὑπόθεσιν. τόν τε γὰρ νεανίσκον ἐψυχαγώγησεν, ὡς αὐτίκα μάλα συγκατασκευασόντων αὐτῷ Ῥωμαίων τὴν βασιλείαν, τούς τε περὶ τὸν Φίλιππον ἠρέθισε, γράψας ἐξ αὐτῆς τὸν Δημήτριον ἀποστέλλειν πάλιν εἰς τὴν Ῥώμην μετὰ τῶν φίλων ὡς πλείστων καὶ χρησιμωτάτων. ταύταις γὰρ ταῖς ἀφορμαῖς χρησάμενος ὁ Περσεὺς μετ’ ὀλίγον ἔπεισε τὸν πατέρα συγκαταθέσθαι τῷ Δημητρίου θανάτῳ. περὶ μὲν οὖν τούτων ὡς ἐχειρίσθη τὰ κατὰ μέρος ἐν τοῖς ἑξῆς δηλώσομεν.", "st": "23.3"}, {"sp": "N", "t": "ἐπὶ δὲ τούτοις εἰσεκλήθησαν οἱ παρὰ τῶν Λακεδαιμονίων πρέσβεις. τούτων δ’ ἦσαν διαφοραὶ τέτταρες. οἱ μὲν γὰρ περὶ Λῦσιν ἥκοντες ὑπὲρ τῶν ἀρχαίων φυγάδων ἐπρέσβευον, φάσκοντες δεῖν ἔχειν αὐτοὺς πάσας τὰς κτήσεις, ἀφ’ ὧν ἐξ ἀρχῆς ἔφυγον· οἱ δὲ περὶ τὸν Ἀρέα καὶ τὸν Ἀλκιβιάδην, ἐφ’ ᾧ ταλαντιαίαν λαβόντες κτῆσιν ἐκ τῶν ἰδίων τὰ λοιπὰ διαδοῦναι τοῖς ἀξίοις τῆς πολιτείας. Σήριππος δ’ ἐπρέσβευε περὶ τοῦ μένειν τὴν ὑποκειμένην κατάστασιν, ἣν ἔχοντές ποτε συνεπολιτεύοντο μετὰ τῶν Ἀχαιῶν. ἀπὸ δὲ τῶν τεθανατωμένων καὶ τῶν ἐκπεπτωκότων κατὰ τὰ τῶν Ἀχαιῶν δόγματα παρῆσαν οἱ περὶ Χαίρωνα, κάθοδον αὑτοῖς ἀξιοῦντες συγχωρηθῆναι καὶ τὴν πολιτείαν ἀποκατασταθῆναι τοιαύτην, ἐποιοῦντο πρὸς τοὺς Ἀχαιοὺς οἰκείους ταῖς ἰδίαις ὑποθέσεσι λόγους. οὐ δυναμένη δὲ διευκρινεῖν ἡ σύγκλητος τὰς κατὰ μέρος διαφοράς, προεχειρίσατο τρεῖς ἄνδρας τοὺς καὶ πρότερον ἤδη πεπρεσβευκότας περὶ τούτων εἰς τὴν Πελοπόννησον· οὗτοι δ’ ἦσαν Τίτος, Κόιντος Καικίλιος, Ἄππιος Κλαύδιος. ἐφ’ οἷς γενομένων λόγων πλειόνων, ὑπὲρ μὲν τοῦ καταπορεύεσθαι τοὺς πεφευγότας καὶ τεθανατωμένους καὶ περὶ τοῦ μένειν τὴν πόλιν μετὰ τῶν Ἀχαιῶν ἐγένετο πᾶσι σύμφωνον, περὶ δὲ τῶν κτήσεων, πότερον δεῖ τὸ τάλαντον εἰς ἑκάστους τοὺς φυγάδας ἐκ τῶν ἰδίων ἐκλέξασθαι, περὶ τούτων διημφισβήτουν πρὸς ἀλλήλους. ἵνα δὲ μὴ πάλιν ἐξ ἀκεραίου περὶ πάντων ἀντιλέγοιεν, ἔγγραπτον ὑπὲρ τῶν ὁμολογουμένων, ἐφ’ ὃ πάντες ἐπεβάλοντο τὰς ἰδίας σφραγῖδας. οἱ δὲ περὶ τὸν Τίτον βουλόμενοι καὶ τοὺς Ἀχαιοὺς εἰς τὴν ὁμολογίαν ἐμπλέξαι, προσεκαλέσαντο τοὺς περὶ Ξέναρχον. οὗτοι γὰρ ἐπρέσβευον τότε παρὰ τῶν Ἀχαιῶν, ἅμα μὲν ἀνανεούμενοι τὴν συμμαχίαν, ἅμα δὲ τῇ τῶν Λακεδαιμονίων διαφορᾷ προσεδρεύοντες. καὶ παρὰ τὴν προσδοκίαν ἐρωτώμενοι περὶ τῶν γραφομένων, εἰ συνευδοκοῦσιν, οὐκ οἶδ’ ὅπως εἰς ἀπορίαν ἐνέπεσον. δυσηρεστοῦντο μὲν γὰρ τῇ καθόδῳ τῶν φυγάδων καὶ τῶν τεθανατωμένων διὰ τὸ γίνεσθαι παρὰ τὰ τῶν Ἀχαιῶν δόγματα καὶ παρὰ τὴν στήλην, εὐδοκοῦντο δὲ τοῖς ὅλοις τῷ γράφεσθαι διότι δεῖ τὴν πόλιν τῶν Λακεδαιμονίων πολιτεύειν μετὰ τῶν Ἀχαιῶν. καὶ πέρας τὰ μὲν ἀπορούμενοι, τὰ δὲ καταπληττόμενοι τοὺς ἄνδρας, ἐπεβάλοντο τὴν σφραγῖδα. ἡ δὲ σύγκλητος προχειρισαμένη Κόιντον Μάρκιον πρεσβευτὴν ἐξαπέστελλεν ἐπί τε τὰ κατὰ Μακεδονίαν καὶ τὰ κατὰ Πελοπόννησον. —", "st": "23.4"}, {"sp": "N", "t": "ὅτι Δεινοκράτης ὁ Μεσσήνιος παραγενόμενος εἰς τὴν Ῥώμην πρεσβευτὴς καὶ καταλαβὼν τὸν Τίτον πρεσβευτὴν καθεσταμένον ὑπὸ τῆς συγκλήτου πρός τε Προυσίαν καὶ τὸν Σέλευκον, περιχαρὴς ἐγενήθη, νομίζων τὸν Τίτον διά τε τὴν πρὸς αὐτὸν φιλίαν — ἐγεγόνει γὰρ αὐτῷ συνήθης κατὰ τὸν Λακωνικὸν πόλεμον — καὶ διὰ τὴν πρὸς τὸν Φιλοποίμενα διαφοράν, παραγενόμενον εἰς τὴν Ἑλλάδα, χειριεῖν τὰ κατὰ τὴν Μεσσήνην πάντα κατὰ τὴν αὐτοῦ προαίρεσιν. διὸ καὶ παρεὶς τἄλλα προσεκαρτέρει τῷ Τίτῳ καὶ πάσας εἰς τοῦτον ἀπηρείσατο τὰς ἐλπίδας. — ὅτι Δεινοκράτης ὁ Μεσσήνιος ἦν οὐ μόνον κατὰ τὴν τριβήν, ἀλλὰ καὶ κατὰ τὴν φύσιν αὐλικὸς καὶ στρατιωτικὸς ἄνθρωπος. τὸν δὲ πραγματικὸν τρόπον ἐπέφαινε μὲν τέλειον, ἦν δὲ ψευδεπίγραφος καὶ ῥωπικός. ἔν τε γὰρ τοῖς πολεμικοῖς κατὰ μὲν τὴν εὐχέρειαν καὶ τὴν τόλμαν πολὺ διέφερε τῶν ἄλλων καὶ λαμπρὸς ἦν ἐν τοῖς κατ’ ἰδίαν κινδύνοις. ὁμοίως δὲ καὶ κατὰ τὴν ἄλλην διάθεσιν ἐν μὲν ταῖς ὁμιλίαις εὔχαρις καὶ πρόχειρος ἦν, παρά τε τὰς συνουσίας εὐτράπελος καὶ πολιτικός, ἅμα δὲ τούτοις φιλέραστος, περὶ δὲ κοινῶν ἢ πολιτικῶν πραγμάτων ἀτενίσαι καὶ προϊδέσθαι τὸ μέλλον ἀσφαλῶς, ἔτι δὲ παρασκευάσασθαι καὶ διαλεχθῆναι πρὸς πλῆθος, εἰς τέλος ἀδύνατος. καὶ τότε κεκινηκὼς ἀρχὴν μεγάλων κακῶν τῇ πατρίδι, τελείως οὐδὲν ᾤετο ποιεῖν, ἀλλὰ τὴν αὐτὴν ἀγωγὴν ἦγε τοῦ βίου, προορώμενος οὐδὲν τῶν μελλόντων, ἐρῶν δὲ καὶ κωθωνιζόμενος ἀφ’ ἡμέρας καὶ τοῖς ἀκροάμασι τὰς ἀκοὰς ἀνατεθεικώς. βραχεῖαν δέ τινα τῆς περιστάσεως ἔμφασιν ὁ Τίτος αὐτὸν ἠνάγκασε λαβεῖν. ἰδὼν γὰρ αὐτὸν παρὰ πότον ἐν μακροῖς ἱματίοις ὀρχούμενον, παρ’ αὐτὰ μὲν ἐσιώπησε, τῇ δ’ αὔριον ἐντυγχάνοντος αὐτοῦ καί τι περὶ τῆς πατρίδος ἀξιοῦντος \" ἐγὼ μέν, ὦ Δεινοκράτη, πᾶν\" ἔφη \"ποιήσω τὸ δυνατόν· ἐπὶ δὲ σοῦ θαυμάζω πῶς δύνῃ παρὰ πότον ὀρχεῖσθαι, τηλικούτων πραγμάτων ἀρχὴν κεκινηκὼς ἐν τοῖς Ἕλλησιν. \" ἐδόκει δὲ τότε βραχύ τι συσταλῆναι καὶ μαθεῖν ὡς ἀνοίκειον ὑπόθεσιν τῆς ἰδίας αἱρέσεως καὶ φύσεως ἀποδέδωκε. πλὴν τότε παρῆν εἰς τὴν Ἑλλάδα μετὰ τοῦ Τίτου πεπεισμένος ἐξ ἐφόδου τὰ κατὰ τὴν Μεσσήνην χειρισθήσεσθαι κατὰ τὴν αὑτοῦ βούλησιν. οἱ δὲ περὶ τὸν Φιλοποίμενα, σαφῶς ἐπεγνωκότες ὅτι περὶ τῶν Ἑλληνικῶν ὁ Τίτος οὐδεμίαν ἐντολὴν ἔχει παρὰ τῆς συγκλήτου, τὴν ἡσυχίαν εἶχον, καραδοκοῦντες αὐτοῦ τὴν παρουσίαν. ἐπεὶ δὲ καταπλεύσας εἰς Ναύπακτον ἔγραψε τῷ στρατηγῷ καὶ τοῖς δαμιουργοῖς τῶν Ἀχαιῶν, κελεύων συνάγειν τοὺς Ἀχαιοὺς εἰς ἐκκλησίαν, ἀντέγραψαν αὐτῷ διότι ποιήσουσιν, ἂν γράψῃ περὶ τίνων βούλεται διαλεχθῆναι τοῖς Ἀχαιοῖς· τοὺς γὰρ νόμους ταῦτα τοῖς ἄρχουσιν ἐπιτάττειν. τοῦ δὲ μὴ τολμῶντος γράφειν, αἱ μὲν τοῦ Δεινοκράτους ἐλπίδες καὶ τῶν ἀρχαίων λεγομένων φυγάδων, τότε δὲ προσφάτως ἐκ τῆς Λακεδαίμονος ἐκπεπτωκότων, καὶ συλλήβδην ἡ τοῦ Τίτου παρουσία καὶ προσδοκία τοῦτον τὸν τρόπον διέπεσεν.", "st": "23.5"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς αὐτοὺς καιροὺς ἐξαπεστάλησαν ὑπὸ τῶν ἐκ Λακεδαίμονος φυγάδων πρέσβεις εἰς τὴν Ῥώμην, ἐν οἷς ἦν Ἀρκεσίλαος καὶ Ἀγησίπολις, ὃς ἔτι παῖς ὢν ἐγενήθη βασιλεὺς ἐν τῇ Σπάρτῃ. τούτους μὲν οὖν λῃσταί τινες περιπεσόντες ἐν τῷ πελάγει διέφθειραν, οἱ δὲ μετὰ τούτων κατασταθέντες διεκομίσθησαν εἰς τὴν Ῥώμην.", "st": "23.6"}, {"sp": "N", "t": "ὅτι τοῦ Δημητρίου παραγενηθέντος ἐκ τῆς Ῥώμης εἰς τὴν Μακεδονίαν καὶ κομίζοντος τὰς ἀποκρίσεις, ἐν αἷς οἱ Ῥωμαῖοι πᾶσαν τὴν ἐξ αὑτῶν χάριν καὶ πίστιν εἰς τὸν Δημήτριον ἀπηρείδοντο καὶ διὰ τοῦτον ἔφασαν πάντα πεποιηκέναι καὶ ποιήσειν, οἱ μὲν Μακεδόνες ἀπεδέχοντο τὸν Δημήτριον, μεγάλων ὑπολαμβάνοντες ἀπολελύσθαι φόβων καὶ κινδύνων — προσεδόκων γὰρ ὅσον οὔπω τὸν ἀπὸ Ῥωμαίων πόλεμον ἐπ’ αὐτοὺς ἥξειν διὰ τὰς τοῦ Φιλίππου παρατριβάς — ὁ δὲ Φίλιππος καὶ Περσεὺς οὐχ ἡδέως ἑώρων τὸ γινόμενον, οὐδ’ ἤρεσεν αὐτοῖς τὸ δοκεῖν τοὺς Ῥωμαίους αὐτῶν μὲν μηθένα λόγον ποιεῖσθαι, τῷ δὲ Δημητρίῳ πᾶσαν ἀνατιθέναι τὴν ἐξ αὑτῶν χάριν. οὐ μὴν ἀλλ’ ὁ μὲν Φίλιππος ἐπεκρύπτετο τὴν ἐπὶ τούτοις δυσαρέστησιν, ὁ δὲ Περσεύς, οὐ μόνον ἐν τῇ πρὸς Ῥωμαίους εὐνοίᾳ παρὰ πολὺ τἀδελφοῦ λειπόμενος, ἀλλὰ καὶ περὶ τἄλλα πάντα καθυστερῶν καὶ τῇ φύσει καὶ τῇ κατασκευῇ, δυσχερῶς ἔφερε· τὸ δὲ συνέχον, ἐδεδίει περὶ τῆς ἀρχῆς, μὴ πρεσβύτερος ὢν ἐξωσθῇ διὰ τὰς προειρημένας αἰτίας. διὸ τούς τε φίλους ἔφθειρε τοὺς τοῦ Δημητρίου. —", "st": "23.7"}, {"sp": "N", "t": "ὅτι τῶν περὶ τὸν Κόιντον τὸν Μάρκιον πρεσβευσάντων εἰς Μακεδονίαν, ἀπέβη μὲν ἀπὸ τῶν ἐπὶ Θρᾴκης Ἑλληνίδων πόλεων ὁλοσχερῶς ὁ Φίλιππος καὶ τὰς φρουρὰς ἐξήγαγεν, ἀπέβη δὲ βαρυνόμενος καὶ στένων. διωρθώσατο δὲ καὶ τἄλλα πάντα, περὶ ὧν οἱ Ῥωμαῖοι προσεπέταττον, βουλόμενος ἐκείνοις μὲν μηδεμίαν ἔμφασιν ποιεῖν ἀλλοτριότητος, λαμβάνειν δ’ ἀναστροφὴν πρὸς τὰς εἰς τὸν πόλεμον παρασκευάς. τηρῶν δὲ τὴν προκειμένην ὑπόθεσιν, ἐξῆγε στρατιὰν ἐπὶ τοὺς βαρβάρους. διελθὼν δὲ διὰ μέσης τῆς Θρᾴκης ἐνέβαλεν εἰς Ὀδρύσας καὶ Βέσσους καὶ Δενθηλήτους. παραγενόμενος δ’ ἐπὶ τὴν προσαγορευομένην Φιλίππου πόλιν, φυγόντων τῶν ἐνοικούντων εἰς τὰς ἀκρωρείας, ἐξ ἐφόδου κατέσχε τὴν πόλιν. μετὰ δὲ ταῦτα πᾶν τὸ πεδίον ἐπιδραμὼν καὶ τοὺς μὲν ἐκπορθήσας, παρ’ ὧν δὲ πίστεις λαβών, ἐπανῆλθε, φρουρὰν καταλιπὼν ἐν τῇ Φιλίππου πόλει. ταύτην δὲ συνέβη μετά τινα χρόνον ἐκπεσεῖν ὑπὸ τῶν Ὀδρυσῶν, ἀθετησάντων τὰς πρὸς τὸν βασιλέα πίστεις.", "st": "23.8"}, {"sp": "N", "t": "ὅτι κατὰ τὸ δεύτερον ἔτος ἡ σύγκλητος, παραγενομένων πρέσβεων παρ’ Εὐμένους καὶ Φαρνάκου καὶ Φιλίππου καὶ παρὰ τοῦ τῶν Ἀχαιῶν ἔθνους, ἔτι δὲ παρὰ τῶν ἐκ τῆς Λακεδαίμονος ἐκπεπτωκότων καὶ παρὰ τῶν κατεχόντων τὴν πόλιν, ἐχρημάτισε τούτοις. ἧκον δὲ καὶ Ῥόδιοι πρεσβεύοντες ὑπὲρ τῆς Σινωπέων ἀτυχίας. τούτοις μὲν οὖν καὶ τοῖς παρ’ Εὐμένους καὶ Φαρνάκου πρεσβεύουσιν ἡ σύγκλητος ἀπεκρίθη διότι πέμψει πρεσβευτὰς τοὺς ἐπισκεψομένους περί τε Σινωπέων καὶ περὶ τῶν τοῖς βασιλεῦσιν ἀμφισβητουμένων. τοῦ δὲ Κοΐντου Μαρκίου προσφάτως ἐκ τῆς Ἑλλάδος παραγεγονότος καὶ περί τε τῶν ἐν Μακεδονίᾳ καὶ περὶ τῶν ἐν Πελοποννήσῳ διασεσαφηκότος, οὐκέτι πολλῶν προσεδεήθη λόγων ἡ σύγκλητος, ἀλλ’ εἰσκαλεσαμένη καὶ τοὺς ἀπὸ Πελοποννήσου καὶ Μακεδονίας πρεσβεύοντας διήκουσε μὲν τῶν λόγων, τάς γε μὴν ἀποκρίσεις ἔδωκε καὶ τὴν διάληψιν ἐποιήσατο τῶν πραγμάτων οὐ πρὸς τοὺς τῶν πρεσβευτῶν λόγους, ἀλλὰ πρὸς τὴν ἀποπρεσβείαν ἁρμοσαμένη τοῦ Μαρκίου. ὃς ὑπὲρ μὲν τοῦ Φιλίππου τοῦ βασιλέως ἀπηγγέλκει διότι πεποίηκε μὲν τὰ προσταττόμενα, πεποίηκε δὲ τὰ πάντα βαρυνόμενος, καὶ καθότι λαβὼν καιρὸν πᾶν τι ποιήσει κατὰ Ῥωμαίων. διὸ καὶ τοῖς μὲν παρὰ τοῦ Φιλίππου πρεσβευταῖς τοιαύτην ἔδωκε τὴν ἀπόκρισιν, δι’ ἧς ἐπὶ μὲν τοῖς γεγονόσιν ἐπῄνει τὸν Φίλιππον, εἰς δὲ τὸ λοιπὸν ᾤετο δεῖν προσέχειν αὐτὸν ἵνα μηδὲν ὑπεναντίον φαίνηται πράττων Ῥωμαίοις. περὶ δὲ τῶν κατὰ Πελοπόννησον ὁ Μάρκιος τοιαύτην ἐπεποίητο τὴν ἀπαγγελίαν διότι, τῶν Ἀχαιῶν οὐ βουλομένων ἀναφέρειν οὐδὲν ἐπὶ τὴν σύγκλητον, ἀλλὰ φρονηματιζομένων καὶ πάντα δι’ ἑαυτῶν πράττειν ἐπιβαλλομένων, ἐὰν παρακούσωσι μόνον αὐτῶν κατὰ τὸ παρὸν καὶ βραχεῖαν ἔμφασιν ποιήσωσιν δυσαρεστήσεως, ταχέως ἡ Λακεδαίμων τῇ Μεσσήνῃ συμφρονήσει. τούτου δὲ γενομένου μετὰ μεγάλης χάριτος ἥξειν τοὺς Ἀχαιοὺς ἔφη καταπεφευγότας ἐπὶ Ῥωμαίους. διότι τοῖς μὲν ἐκ τῆς Λακεδαίμονος ἀπεκρίθησαν τοῖς περὶ Σήριππον, βουλόμενοι μετέωρον ἐᾶσαι τὴν πόλιν, διότι πάντα πεποιήκασιν αὐτοῖς τὰ δυνατά, κατὰ δὲ τὸ παρὸν οὐ νομίζουσιν εἶναι τοῦτο τὸ πρᾶγμα πρὸς αὑτούς. τῶν δ’ Ἀχαιῶν παρακαλούντων, εἰ μὲν δυνατόν ἐστιν, βοήθειαν αὐτοῖς πέμψαι κατὰ τὴν συμμαχίαν ἐπὶ τοὺς Μεσσηνίους, εἰ δὲ μή, προνοηθῆναι γ’ ἵνα μηθεὶς τῶν ἐξ Ἰταλίας μήθ’ ὅπλα μήτε σῖτον εἰς τὴν Μεσσήνην εἰσαγάγῃ, τούτων μὲν οὐδενὶ προσεῖχον, ἀπεκρίθησαν δὲ διότι οὐδ’ ἂν ὁ Λακεδαιμονίων ἢ Κορινθίων ἢ τῶν Ἀργείων ἀφίστηται δῆμος, οὐ δεήσει τοὺς Ἀχαιοὺς θαυμάζειν ἐὰν μὴ πρὸς αὐτοὺς ἡγῶνται. ταύτην δὲ τὴν ἀπόκρισιν ἐκθέμενοι, κηρύγματος ἔχουσαν διάθεσιν τοῖς βουλομένοις ἕνεκεν Ῥωμαίων ἀφίστασθαι τῆς τῶν Ἀχαιῶν πολιτείας, λοιπὸν τοὺς πρεσβευτὰς παρακατεῖχον, καραδοκοῦντες τὰ κατὰ τὴν Μεσσήνην, πῶς προχωρήσει τοῖς Ἀχαιοῖς. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν.", "st": "23.9"}, {"sp": "N", "t": "ὅτι τῷ βασιλεῖ Φιλίππῳ καὶ τῇ συμπάσῃ Μακεδονίᾳ κατὰ τοῦτον τὸν καιρὸν δεινή τις ἀρχὴ κακῶν ἐνέπεσε καὶ πολλῆς ἐπιστάσεως καὶ μνήμης ἀξία. καθάπερ γὰρ ἂν εἰ δίκην ἡ τύχη βουλομένη λαβεῖν ἐν καιρῷ παρ’ αὐτοῦ πάντων τῶν ἀσεβημάτων καὶ παρανομημάτων ὧν εἰργάσατο κατὰ τὸν βίον, τότε παρέστησέ τινας ἐρινῦς καὶ ποινὰς καὶ προστροπαίους τῶν δι’ ἐκεῖνον ἠτυχηκότων· οἳ συνόντες αὐτῷ καὶ νύκτωρ καὶ μεθ’ ἡμέραν τοιαύτας ἔλαβον παρ’ αὐτοῦ τιμωρίας, ἕως οὗ τὸ ζῆν ἐξέλιπεν, ὡς καὶ πάντας ἀνθρώπους ὁμολογῆσαι διότι κατὰ τὴν παροιμίαν ἔστι Δίκης ὀφθαλμός, ἧς μηδέποτε δεῖ καταφρονεῖν ἀνθρώπους ὑπάρχοντας. πρῶτον μὲν γὰρ αὐτῷ ταύτην παρεστήσαντο τὴν ἔννοιαν ὅτι δεῖ μέλλοντα πολεμεῖν πρὸς Ῥωμαίους ἐκ τῶν ἐπιφανεστάτων καὶ παραθαλαττίων πόλεων τοὺς μὲν πολιτικοὺς ἄνδρας μετὰ τέκνων καὶ γυναικῶν ἀναστάτους ποιήσαντα μεταγαγεῖν εἰς τὴν νῦν μὲν Ἠμαθίαν, τὸ δὲ παλαιὸν Παιονίαν προσαγορευομένην, πληρῶσαι δὲ καὶ Θρᾳκῶν καὶ βαρβάρων τὰς πόλεις, ὡς βεβαιοτέρας αὐτῷ τῆς ἐκ τούτων πίστεως ὑπαρξούσης κατὰ τὰς περιστάσεις. οὗ συντελουμένου, καὶ τῶν ἀνθρώπων ἀνασπάστων γινομένων, τηλικοῦτο συνέβη γενέσθαι πένθος καὶ τηλικοῦτον θόρυβον ὥστε δοριάλωτον δοκεῖν ἅπασαν γίνεσθαι. ἐξ ὧν κατάραι καὶ θεοκλυτήσεις ἐγίνοντο κατὰ τοῦ βασιλέως, οὐκέτι λάθρᾳ μόνον, ἀλλὰ καὶ φανερῶς. μετὰ δὲ ταῦτα βουληθεὶς μηδὲν ἀλλότριον ὑποκαθέσθαι μηδὲ δυσμενὲς μηδὲν ἀπολιπεῖν πρὸς τὴν βασιλείαν, ἔγραψε τοῖς ἐπὶ τῶν πόλεων διατεταγμένοις ἀναζητήσασι τοὺς υἱοὺς καὶ τὰς θυγατέρας τῶν ὑπ’ αὐτοῦ Μακεδόνων ἀνῃρημένων, εἰς φυλακὴν ἀποθέσθαι, μάλιστα μὲν φέρων ἐπὶ τοὺς περὶ Ἄδμητον καὶ Πύρριχον καὶ Σάμον καὶ τοὺς μετὰ τούτων ἀπολομένους· ἅμα δὲ τούτοις συμπεριέλαβε καὶ τοὺς ἄλλους ἅπαντας, ὅσοι κατὰ βασιλικὸν πρόσταγμα τοῦ ζῆν ἐστερήθησαν, ἐπιφθεγξάμενος, ὥς φασι, τὸν στίχον τοῦτον· νήπιος ὃς πατέρα κτείνας υἱοὺς καταλείπει. ὄντων δὲ τῶν πλείστων ἐπιφανῶν διὰ τὰς τῶν πατέρων προαγωγάς, ἐπιφανῆ καὶ τὴν τούτων ἀτυχίαν συνέβαινε γίνεσθαι καὶ παρὰ πᾶσιν ἐλεεινήν. τρίτον δ’ ἡ τύχη δρᾶμα κατὰ τὸν αὐτὸν καιρὸν ἐπεισήγαγεν τὸ κατὰ τοὺς υἱούς, ἐν ᾧ τῶν μὲν νεανίσκων ἀλλήλοις ἐπιβουλευόντων, τῆς δ’ ἀναφορᾶς περὶ τούτων ἐπ’ αὐτὸν γινομένης, καὶ δέον διαλαμβάνειν ποτέρου δεῖ γίνεσθαι τῶν υἱῶν φονέα καὶ πότερον αὐτῶν δεδιέναι μᾶλλον κατὰ τὸν ἑξῆς βίον, μὴ γηράσκων αὐτὸς πάθῃ τὸ παραπλήσιον, ἐστροβεῖτο νύκτωρ καὶ μεθ’ ἡμέραν περὶ τούτων διανοούμενος. ἐν τοιαύταις δ’ οὔσης ἀτυχίαις καὶ ταραχαῖς τῆς αὐτοῦ ψυχῆς, τίς οὐκ ἂν εἰκότως ὑπολάβοι θεῶν τινων αὐτῷ μῆνιν εἰς τὸ γῆρας κατασκῆψαι διὰ τὰς ἐν τῷ προγεγονότι βίῳ παρανομίας; τοῦτο δ’ ἔτι μᾶλλον ἔσται δῆλον ἐκ τῶν ἑξῆς ῥηθησομένων. — ὅτι Φίλιππος ὁ Μακεδόνων βασιλεὺς πολλοὺς τῶν Μακεδόνων ἀνελὼν καὶ τοὺς υἱοὺς αὐτῶν ἐπανεῖλεν, ὥς φασι, τὸν στίχον τοῦτον εἰπών· νήπιος ὃς πατέρα κτείνας υἱοὺς καταλείπει. καὶ διὰ ταῦτα τῆς ψυχῆς οἱονεὶ λυττώσης αὐτοῦ, καὶ τὸ κατὰ τοὺς υἱοὺς νεῖκος ἅμα τοῖς προειρημένοις ἐξεκαύθη, τῆς τύχης ὥσπερ ἐπίτηδες ἀναβιβαζούσης ἐπὶ σκηνὴν ἐν ἑνὶ καιρῷ τὰς τούτων συμφοράς. — ἐναγίζουσιν οὖν τῷ Ξανθῷ Μακεδόνες καὶ καθαρμὸν ποιοῦσι σὺν ἵπποις ὡπλισμένοις. —", "st": "23.10"}, {"sp": "N", "t": "ὅτι \"δεῖ μὴ μόνον ἀναγινώσκειν τὰς τραγῳδίας καὶ τοὺς μύθους καὶ τὰς ἱστορίας, ἀλλὰ καὶ γινώσκειν καὶ συνεφιστάνειν ἐπὶ τοῦτο τὸ μέρος. ἐν οἷς ἅπασιν ἔστιν ὁρᾶν, ὅσοι μὲν τῶν ἀδελφῶν εἰς τὴν πρὸς ἀλλήλους ὀργὴν καὶ φιλονικίαν ἐμπεσόντες ἐπὶ πολὺ προύβησαν, ἅπαντας τοὺς τοιούτους οὐ μόνον σφᾶς ἀπολωλεκότας, ἀλλὰ καὶ βίον καὶ τέκνα καὶ πόλεις ἄρδην κατεστραφότας, ὅσοι δὲ μετρίως ἐζήλωσαν τὸ στέργειν αὑτοὺς καὶ φέρειν τὰς ἀλλήλων ἀγνοίας, τούτους ἅπαντας σωτῆρας γεγονότας ὧν ἀρτίως εἶπον καὶ μετὰ τῆς καλλίστης φήμης καὶ δόξης βεβιωκότας. καὶ μὴν ἐπὶ τοὺς ἐν τῇ Λακεδαίμονι βασιλεῖς πολλάκις ὑμᾶς ἐπέστησα, λέγων ὅτι τοσοῦτον χρόνον διετήρησαν σφῶν τῇ πατρίδι τὴν τῶν Ἑλλήνων ἡγεμονίαν ὅσον πειθαρχοῦντες ὥσπερ γονεῦσι τοῖς ἐφόροις ἠνείχοντο συμβασιλεύοντες ἀλλήλοις· ὅτε δὲ διαφωνήσαντες εἰς μοναρχίαν τὰ πράγματα μετέστησαν, τότε πάντων ἅμα τῶν κακῶν πεῖραν ἐποίησαν λαβεῖν τὴν Σπάρτην· τὸ δὲ τελευταῖον ὡσανεὶ κατ’ ἔνδειξιν ὑμῖν λέγων καὶ τιθεὶς ἐναργῶς ὑπὸ τὴν ὄψιν διετέλουν τούτους τοὺς περὶ τὸν Εὐμένη καὶ τὸν Ἄτταλον, ὅτι παραλαβόντες οὗτοι μικρὰν ἀρχὴν καὶ τὴν τυχοῦσαν ηὐξήκασι ταύτην, ὥστε μηδεμιᾶς εἶναι καταδεεστέραν, δι’ οὐθὲν ἕτερον ἢ διὰ τὴν πρὸς αὑτοὺς ὁμόνοιαν καὶ συμφωνίαν καὶ τὸ δύνασθαι καταξίωσιν ἀλλήλοις διαφυλάττειν· ὧν ὑμεῖς ἀκούοντες οὐχ οἷον εἰς νοῦν ἐλαμβάνετε, τὸ δ’ ἐναντίον ἠκονᾶτ’, ἐμοὶ δοκεῖ, τοὺς κατ’ ἀλλήλων θυμούς.\"", "st": "23.11"}, {"sp": "N", "t": "Πολύβιος. ὁ δ’ ἐξαναστὰς προῆγε, τὰ μὲν ὑπὸ τῆς ἀρρωστίας, τὰ δ’ ὑπὸ τῆς ἡλικίας βαρυνόμενος· εἶχε γὰρ ἑβδομηκοστὸν ἔτος. Πολύβιος· διαβιασάμενος δὲ τὴν ἀσθένειαν τῇ συνηθείᾳ τῇ πρὸ τοῦ παρῆν ἐξ Ἄργους εἰς Μεγάλην πόλιν αὐθημερόν. — ὅτι Φιλοποίμην ὁ τῶν Ἀχαιῶν στρατηγὸς συλληφθεὶς ὑπὸ Μεσσηνίων ἀνῃρέθη φαρμάκῳ, ἀνὴρ γενόμενος οὐδενὸς τῶν πρὸ τοῦ κατ’ ἀρετὴν δεύτερος, τῆς τύχης μέντοι γ’ ἥττων, καίτοι δόξας ἐν παντὶ τῷ πρὸ τοῦ βίῳ συνεργὸν ἐσχηκέναι ταύτην· ἀλλά μοι δοκεῖ κατὰ τὴν κοινὴν παροιμίαν εὐτυχῆσαι μὲν ἄνθρωπον ὄντα δυνατόν, διευτυχῆσαί γε μὴν ἀδύνατον· διὸ καὶ μακαριστέον τῶν προγεγονότων οὐχ ὡς διευτυχηκότας τινάς· τίς γὰρ ἀνάγκη ψευδεῖ λόγῳ χρωμένοις ματαίως προσκυνεῖν τὴν τύχην; ἀλλὰ τοὺς ὡς πλεῖστον χρόνον ἐν τῷ ζῆν ἵλεων ἔχοντας ταύτην, κἄν ποτε μετανοῇ, μετρίαις περιπεσόντας συμφοραῖς. — Μετ. … Λυκόρταν, ὃς ἦν οὐδὲν ἥττων τούτου. — ὅτι Φιλοποίμην τετταράκοντ’ ἔτη συνεχῶς φιλοδοξήσας ἐν δημοκρατικῷ καὶ πολυειδεῖ πολιτεύματι, πάντῃ πάντως διέφυγε τὸν τῶν πολλῶν φθόνον, τὸ πλεῖον οὐ πρὸς χάριν, ἀλλὰ μετὰ παρρησίας πολιτευόμενος· ὃ σπανίως ἂν εὕροι τις γεγονός. —", "st": "23.12"}, {"sp": "N", "t": "ὅτι θαυμαστόν ἐστι καὶ μέγιστον σημεῖον γεγονέναι τῇ φύσει τὸν ἄνδρα τοῦτον ἡγεμονικὸν καὶ πολύ τι διαφέροντα τῶν ἄλλων πρὸς τὸν πραγματικὸν τρόπον· ἑπτακαίδεκα γὰρ ἔτη μείνας ἐν τοῖς ὑπαίθροις πλεῖστά τ’ ἔθνη καὶ βάρβαρα διεξελθὼν καὶ πλείστοις ἀνδράσιν ἀλλοφύλοις καὶ ἑτερογλώττοις χρησάμενος συνεργοῖς πρὸς ἀπηλπισμένας καὶ παραδόξους ἐπιβολάς, ὑπ’ οὐθενὸς οὔτ’ ἐπεβουλεύθη τὸ παράπαν οὔτ’ ἐγκατελείφθη τῶν ἅπαξ αὐτῷ κοινωνησάντων καὶ δόντων ἑαυτοὺς εἰς χεῖρας. —", "st": "23.13"}, {"sp": "N", "t": "ὅτι Πόπλιος φιλοδοξήσας ἐν ἀριστοκρατικῷ πολιτεύματι τηλικαύτην περιεποιήσατο παρὰ μὲν τοῖς ὄχλοις εὔνοιαν παρὰ δὲ τῷ συνεδρίῳ πίστιν ὥστ’, ἐν μὲν τῷ δήμῳ κρίνειν τινὸς ἐπιβαλομένου κατὰ τὰ Ῥωμαίων ἔθη καὶ πολλὰ κατηγορήσαντος καὶ πικρῶς, ἄλλο μὲν οὐθὲν εἶπε προελθών, οὐκ ἔφη δὲ πρέπον εἶναι τῷ δήμῳ τῶν Ῥωμαίων οὐθενὸς ἀκούειν κατηγοροῦντος Ποπλίου Κορνηλίου Σκιπίωνος, δι’ ὃν αὐτὴν τὴν τοῦ λέγειν ἐξουσίαν ἔχουσιν οἱ κατηγοροῦντες. ὧν ἀκούσαντες οἱ πολλοὶ παραχρῆμα διελύθησαν πάντες ἐκ τῆς ἐκκλησίας, ἀπολιπόντες τὸν κατηγοροῦντα μόνον. — ὅτι Πόπλιος ἐν τῷ συνεδρίῳ χρείας ποτὲ χρημάτων οὔσης εἴς τινα κατεπείγουσαν οἰκονομίαν, τοῦ δὲ ταμίου διά τινα νόμον οὐ φάσκοντος ἀνοίξειν τὸ ταμιεῖον κατ’ ἐκείνην τὴν ἡμέραν, αὐτὸς ἔφη λαβὼν τὰς κλεῖς ἀνοίξειν· αὐτὸς γὰρ αἴτιος γεγονέναι καὶ τοῦ κλείεσθαι τὸ ταμιεῖον. πάλιν δέ ποτε λόγον ἀπαιτοῦντός τινος ἐν τῷ συνεδρίῳ τῶν χρημάτων ὧν ἔλαβε παρ’ Ἀντιόχου πρὸ τῶν συνθηκῶν εἰς τὴν τοῦ στρατοπέδου μισθοδοσίαν, ἔχειν μὲν ἔφη τὸν λογισμόν, οὐ δεῖν δ’ αὐτὸν ὑποσχεῖν οὐδενὶ λόγον· τοῦ δ’ ἐπικειμένου καὶ κελεύοντος φέρειν ἠξίωσε τὸν ἀδελφὸν ἐνεγκεῖν· κομισθέντος δὲ τοῦ βυβλίου, προτείνας αὐτὸ καὶ κατασπαράξας πάντων ὁρώντων τὸν μὲν ἀπαιτοῦντα τὸν λόγον ἐκ τούτων ζητεῖν ἐκέλευσε, τοὺς δ’ ἄλλους ἤρετο πῶς τῶν μὲν τρισχιλίων ταλάντων τὸν λόγον ἐπιζητοῦσι πῶς ἐδαπανήθη καὶ διὰ τίνων, τῶν δὲ μυρίων καθόλου καὶ πεντακισχιλίων ὧν παρ’ Ἀντιόχου λαμβάνουσιν, οὐκέτι ζητοῦσι πῶς εἰσπορεύεται καὶ διὰ τίνων, οὐδὲ πῶς τῆς Ἀσίας καὶ τῆς Λιβύης, ἔτι δὲ τῆς Ἰβηρίας κεκυριεύκασιν. ὥστε μὴ μόνον καταπλαγῆναι πάντας, ἀλλὰ καὶ τὸν ζητήσαντα τὸν λόγον ἀποσιωπῆσαι. ταῦτα μὲν οὖν ἡμῖν εἰρήσθω τῆς τε τῶν μετηλλαχότων ἀνδρῶν εὐκλείας ἕνεκεν καὶ τῆς τῶν ἐπιγινομένων παρορμήσεως πρὸς τὰ καλὰ τῶν ἔργων. —", "st": "23.14"}, {"sp": "N", "t": "ὅτι οὐ καλὸν τὸ φθείρειν τοὺς καρποὺς τῶν ὑπεναντίων· φησὶ γὰρ ὁ Πολύβιος οὐδέποτε δ’ ἐγὼ συντίθεμαι τὴν γνώμην τοῖς ἐπὶ τοσοῦτον διατιθεμένοις τὴν ὀργὴν εἰς τοὺς ὁμοφύλους ὥστε μὴ μόνον τοὺς ἐπετείους καρποὺς παραιρεῖσθαι τῶν πολεμίων, ἀλλὰ καὶ τὰ δένδρα καὶ τὰ κατασκευάσματα διαφθείρειν, μηδὲ μεταμελείας καταλείποντας τόπον. ἀλλά μοι δοκοῦσι μεγαλείως ἀγνοεῖν οἱ ταῦτα πράττοντες· καθ’ ὅσον γὰρ ὑπολαμβάνουσι καταπλήττεσθαι τοὺς πολεμίους λυμαινόμενοι τὴν χώραν καὶ παραιρούμενοι πάσας, οὐ μόνον τὰς κατὰ τὸ παρόν, ἀλλὰ καὶ τὰς εἰς τὸ μέλλον ἐλπίδας τῶν πρὸς τὸν βίον ἀναγκαίων, κατὰ τοσοῦτον ἀποθηριοῦντες τοὺς ἀνθρώπους ἀμετάθετον ποιοῦσι τὴν πρὸς αὑτοὺς ὀργὴν τῶν ἅπαξ ἐξαμαρτόντων. —", "st": "23.15"}, {"sp": "N", "t": "ὅτι ὁ Λυκόρτας ὁ τῶν Ἀχαιῶν στρατηγὸς τοὺς Μεσσηνίους καταπληξάμενος τῷ πολέμῳ πάλαι μὲν οἱ Μεσσήνιοι καταπεπληγμένοι τὸν πρὸ τοῦ χρόνον τοὺς προεστῶτας, τότε μόλις ἐθάρρησάν τινες αὐτῶν φωνὴν ἀφιέναι, πιστεύσαντες τῇ τῶν πολεμίων ἐφεδρείᾳ, καὶ λέγειν ὅτι δεῖ πρεσβεύειν ὑπὲρ διαλύσεως. οἱ μὲν οὖν περὶ τὸν Δεινοκράτην οὐκέτι δυνάμενοι πρὸς τὸ πλῆθος ἀντοφθαλμεῖν διὰ τὸ περιέχεσθαι τοῖς πράγμασιν εἴξαντες ἀνεχώρησαν εἰς τὰς ἰδίας οἰκήσεις. οἱ δὲ πολλοὶ παρακληθέντες ὑπό τε τῶν πρεσβυτέρων καὶ μάλιστα τῶν ἐκ Βοιωτίας πρεσβευτῶν, οἳ πρότερον ἤδη παραγεγονότες ἐπὶ τὰς διαλύσεις, Ἐπαίνετος καὶ Ἀπολλόδωρος, εὐκαίρως τότε παρέτυχον ἐν τῇ Μεσσήνῃ, ταχέως ἐπακολουθήσαντες ἐπὶ τὰς διαλύσεις οἱ Μεσσήνιοι κατέστησαν πρεσβευτὰς καὶ τούτους ἐξέπεμψαν, δεόμενοι τυχεῖν συγγνώμης ἐπὶ τοῖς ἡμαρτημένοις. ὁ δὲ στρατηγὸς τῶν Ἀχαιῶν παραλαβὼν τοὺς συνάρχοντας καὶ διακούσας τῶν παραγεγονότων μίαν ἔφη Μεσσηνίοις πρὸς τὸ ἔθνος εἶναι διάλυσιν, ἐὰν μὲν τοὺς αἰτίους τῆς ἀποστάσεως καὶ τῆς Φιλοποίμενος ἀναιρέσεως ἤδη παραδῶσιν αὐτῷ, περὶ δὲ τῶν ἄλλων ἁπάντων ἐπιτροπὴν δῶσιν τοῖς Ἀχαιοῖς, εἰς δὲ τὴν ἄκραν εἰσδέξωνται παραχρῆμα φυλακήν. ἀναγγελθέντων δὲ τούτων εἰς τοὺς ὄχλους, οἱ μὲν πάλαι πικρῶς διακείμενοι πρὸς τοὺς αἰτίους τοῦ πολέμου πρόθυμοι τούτους ἦσαν ἐκδιδόναι καὶ συλλαμβάνειν, οἱ δὲ πεπεισμένοι μηδὲν πείσεσθαι δεινὸν ὑπὸ τῶν Ἀχαιῶν ἑτοίμως συγκατέβαινον εἰς τὴν ὑπὲρ τῶν ὅλων ἐπιτροπήν. τὸ δὲ συνέχον, οὐκ ἔχοντες αἵρεσιν περὶ τῶν παρόντων ὁμοθυμαδὸν ἐδέξαντο τὰ προτεινόμενα. τὴν μὲν οὖν ἄκραν εὐθέως παραλαβὼν ὁ στρατηγὸς τοὺς πελταστὰς εἰς αὐτὴν παρήγαγεν, μετὰ δὲ ταῦτα προσλαβὼν τοὺς ἐπιτηδείους ἐκ τοῦ στρατοπέδου παρῆλθεν εἰς τὴν πόλιν καὶ συναγαγὼν τοὺς ὄχλους παρεκάλεσε τὰ πρέποντα τοῖς ἐνεστῶσι καιροῖς, ἐπαγγελλόμενος ἀμεταμέλητον αὐτοῖς ἔσεσθαι τὴν πίστιν. τῆς μὲν οὖν ὑπὲρ τῶν ὅλων διαλήψεως τὴν ἀναφορὰν ἐπὶ τὸ ἔθνος ἐποιήσατο — καὶ γὰρ ὥσπερ ἐπίτηδες συνέβαινε τότε πάλιν συνάγεσθαι τοὺς Ἀχαιοὺς εἰς Μεγάλην πόλιν ἐπὶ τὴν δευτέραν σύνοδον — τῶν δ’ ἐν ταῖς αἰτίαις ὅσοι μὲν μετέσχον τοῦ παρ’ αὐτὸν τὸν καιρὸν ἐπανελέσθαι τὸν Φιλοποίμενα, τούτοις ἐπέταξε παραχρῆμα πάντας αὐτοὺς ἐξάγειν ἐκ τοῦ ζῆν —", "st": "23.16"}, {"sp": "N", "t": "ὅτι οἱ Μεσσήνιοι διὰ τὴν αὑτῶν ἄγνοιαν εἰς τὴν ἐσχάτην παραγενόμενοι διάθεσιν ἀποκατέστησαν εἰς τὴν ἐξ ἀρχῆς κατάστασιν τῆς συμπολιτείας διὰ τὴν Λυκόρτα καὶ τῶν Ἀχαιῶν μεγαλοψυχίαν. ἡ δ’ Ἀβία καὶ Θουρία καὶ Φαραὶ κατὰ τὸν καιρὸν τοῦτον ἀπὸ μὲν τῆς Μεσσήνης ἐχωρίσθησαν, ἰδίᾳ δὲ θέμεναι στήλην ἑκάστη μετεῖχεν τῆς κοινῆς συμπολιτείας. Ῥωμαῖοι δὲ πυθόμενοι κατὰ λόγον κεχωρηκέναι τοῖς Ἀχαιοῖς τὰ κατὰ τὴν Μεσσήνην, οὐδένα λόγον ποιησάμενοι τῆς πρότερον ἀποφάσεως ἄλλην ἔδωκαν τοῖς αὐτοῖς πρεσβευταῖς ἀπόκρισιν, διασαφοῦντες ὅτι πρόνοιαν πεποίηνται τοῦ μηθένα τῶν ἐξ Ἰταλίας μήθ’ ὅπλα μήτε σῖτον εἰσάγειν εἰς τὴν Μεσσήνην. ἐξ οὗ καταφανεῖς ἅπασιν ἐγενήθησαν ὅτι τοσοῦτον ἀπέχουσιν τοῦ τὰ μὴ λίαν ἀναγκαῖα τῶν ἐκτὸς πραγμάτων ἀποτρίβεσθαι καὶ παρορᾶν, ὡς τοὐναντίον καὶ δυσχεραίνουσιν ἐπὶ τῷ μὴ πάντων τὴν ἀναφορὰν ἐφ’ ἑαυτοὺς γίνεσθαι καὶ πάντα πράττεσθαι μετὰ τῆς αὑτῶν γνώμης. εἰς δὲ τὴν Λακεδαίμονα παραγενομένων τῶν πρεσβευτῶν ἐκ τῆς Ῥώμης καὶ κομιζόντων τὴν ἀπόκρισιν, εὐθέως ὁ στρατηγὸς τῶν Ἀχαιῶν μετὰ τὸ συντελέσαι τὰ κατὰ τὴν Μεσσήνην συνῆγε τοὺς πολλοὺς εἰς τὴν τῶν Σικυωνίων πόλιν. ἁθροισθέντων δὲ τῶν Ἀχαιῶν ἀνεδίδου διαβούλιον ὑπὲρ τοῦ προσλαβέσθαι τὴν Σπάρτην εἰς τὴν συμπολιτείαν, φάσκων Ῥωμαίους μὲν ἀποτρίβεσθαι τὴν πρότερον αὐτοῖς δοθεῖσαν ἐπιτροπὴν ὑπὲρ τῆς πόλεως ταύτης· ἀποκεκρίσθαι γὰρ αὐτοὺς νῦν μηθὲν εἶναι τῶν κατὰ Λακεδαίμονα πραγμάτων πρὸς αὑτούς· τοὺς δὲ κυριεύοντας τῆς Σπάρτης κατὰ τὸ παρὸν βούλεσθαι σφίσιν μετέχειν τῆς συμπολιτείας. διὸ παρεκάλει προσδέχεσθαι τὴν πόλιν· εἶναι γὰρ τοῦτο κατὰ δύο τρόπους συμφέρον, καθ’ ἕνα μέν, ὅτι τούτους μέλλουσι προσλήψεσθαι τοὺς διατετηρηκότας τὴν πρὸς τὸ ἔθνος πίστιν, καθ’ ἕτερον δέ, διότι τῶν ἀρχαίων φυγάδων τοὺς ἀχαρίστως καὶ ἀσεβῶς ἀνεστραμμένους εἰς αὐτοὺς οὐχ ἕξουσι κοινωνοὺς τῆς πολιτείας, ἀλλ’ ἑτέρων αὐτοὺς ἐκκεκλεικότων τῆς πόλεως, βεβαιώσαντες τὰς ἐκείνων προαιρέσεις ἅμα τὴν ἁρμόζουσαν αὐτοῖς χάριν ἀποδώσουσι μετὰ τῆς τῶν θεῶν προνοίας. ὁ μὲν οὖν Λυκόρτας ταῦτα καὶ τὰ τοιαῦτα λέγων παρεκάλει τοὺς Ἀχαιοὺς προσδέξασθαι τὴν πόλιν· ὁ δὲ Διοφάνης καί τινες ἕτεροι βοηθεῖν ἐπειρῶντο τοῖς φυγάσι καὶ παρεκάλουν τοὺς Ἀχαιοὺς μὴ συνεπιθέσθαι τοῖς ἐκπεπτωκόσιν μηδὲ δι’ ὀλίγους ἀνθρώπους συνεπισχῦσαι τοῖς ἀσεβῶς καὶ παρανόμως αὐτοὺς ἐκ τῆς πατρίδος ἐκβεβληκόσιν.", "st": "23.17"}, {"sp": "N", "t": "τοιαῦτα μὲν ἦν τὰ ῥηθέντα παρ’ ἑκατέρων. οἱ δ’ Ἀχαιοὶ διακούσαντες ἀμφοτέρων ἔκριναν προσλαβέσθαι τὴν πόλιν, καὶ μετὰ ταῦτα στήλης προγραφείσης συνεπολιτεύετο μετὰ τῶν Ἀχαιῶν ἡ Σπάρτη, προσδεξαμένων τῶν ἐν τῇ πόλει τούτους τῶν ἀρχαίων φυγάδων, ὅσοι μηδὲν ἐδόκουν ἄγνωμον πεποιηκέναι κατὰ τοῦ τῶν Ἀχαιῶν ἔθνους. οἱ δ’ Ἀχαιοὶ ταῦτα κυρώσαντες πρεσβευτὰς ἀπέστειλαν εἰς τὴν Ῥώμην τοὺς περὶ Βίππον τὸν Ἀργεῖον, διασαφήσοντας τῇ συγκλήτῳ περὶ πάντων. ὁμοίως δὲ καὶ Λακεδαιμόνιοι τοὺς περὶ Χαίρωνα κατέστησαν. ἐξαπέστειλαν δ’ οἱ φυγάδες τοὺς περὶ Κλῆτιν καὶ Διακτόριον τοὺς συγκαταστησομένους ἐν τῇ συγκλήτῳ πρὸς τοὺς παρὰ τῶν Ἀχαιῶν πρεσβευτάς.", "st": "23.18"}, {"sp": "HDR", "t": "Βιβλίον ΚΔʹ", "st": "24"}, {"sp": "N", "t": "εἰς δὲ τὴν Ῥώμην παραγεγονότων τῶν πρεσβευτῶν παρά τε τῶν Λακεδαιμονίων καὶ τῶν ἐκ Λακεδαίμονος φυγάδων, ἔτι δὲ παρὰ τῶν Ἀχαιῶν, ἅμα δὲ καὶ τῶν παρ’ Εὐμένους καὶ παρ’ Ἀριαράθου τοῦ βασιλέως ἡκόντων καὶ τῶν παρὰ Φαρνάκου, τούτοις πρῶτον ἐχρημάτισεν ἡ σύγκλητος. βραχεῖ δὲ χρόνῳ πρότερον ἀνηγγελκότων τῶν περὶ τὸν Μάρκον πρεσβευτῶν, οὓς ἀπεστάλκεισαν ἐπὶ τὸν Εὐμένει καὶ Φαρνάκῃ συνεστηκότα πόλεμον, καὶ διασεσαφηκότων περί τε τῆς Εὐμένους μετριότητος ἐν πᾶσιν καὶ περὶ τῆς Φαρνάκου πλεονεξίας καὶ καθόλου τῆς ὑπερηφανίας, οὐκέτι πολλῶν προσεδεήθη λόγων ἡ σύγκλητος διακούσασα τῶν παραγεγονότων, ἀπεκρίθη δὲ διότι πάλιν πέμψει πρεσβευτὰς τοὺς φιλοτιμότερον ἐπισκεψομένους ὑπὲρ τῶν διαφερόντων τοῖς προειρημένοις. μετὰ δὲ ταῦτα τῶν ἐκ τῆς Λακεδαίμονος φυγάδων εἰσπορευθέντων καὶ τῶν ἐκ τῆς πόλεως ἅμα τούτοις, ἐπὶ πολὺ διακούσασα τοῖς μὲν ἐκ τῆς πόλεως οὐδὲν ἐπετίμησε περὶ τῶν γεγονότων, τοῖς δὲ φυγάσιν ἐπηγγείλατο γράψειν πρὸς τοὺς Ἀχαιοὺς περὶ τοῦ κατελθεῖν αὐτοὺς εἰς τὴν οἰκείαν. μετὰ δέ τινας ἡμέρας εἰσπορευθέντων τῶν περὶ Βίππον τὸν Ἀργεῖον, οὓς ἀπεστάλκει τὸ τῶν Ἀχαιῶν ἔθνος, καὶ διασαφούντων περὶ τῆς Μεσσηνίων ἀποκαταστάσεως, οὐθενὶ δυσαρεστήσασα περὶ τῶν οἰκονουμένων ἡ σύγκλητος ἀπεδέξατο φιλανθρώπως τοὺς πρεσβευτάς.", "st": "24.1"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Πελοπόννησον παραγενομένων ἐκ Ῥώμης τῶν ἐκ τῆς Λακεδαίμονος φυγάδων καὶ κομιζόντων παρὰ τῆς συγκλήτου γράμματα τοῖς Ἀχαιοῖς ὑπὲρ τοῦ προνοηθῆναι περὶ τῆς αὑτῶν καθόδου καὶ σωτηρίας εἰς τὴν οἰκείαν, ἔδοξε τοῖς Ἀχαιοῖς ὑπερθέσθαι τὸ διαβούλιον, ἕως ἂν οἱ παρ’ αὐτῶν ἔλθωσι πρεσβευταί. ταῦτα δὲ τοῖς φυγάσιν ἀποκριθέντες συνέθεντο τὴν πρὸς Μεσσηνίους στήλην, συγχωρήσαντες αὐτοῖς πρὸς τοῖς ἄλλοις φιλανθρώποις καὶ τριῶν ἐτῶν ἀτέλειαν, ὥστε τὴν τῆς χώρας καταφθορὰν μηδὲν ἧττον βλάψαι τοὺς Ἀχαιοὺς ἢ Μεσσηνίους. τῶν δὲ περὶ τὸν Βίππον παραγενομένων ἐκ τῆς Ῥώμης καὶ διασαφούντων γραφῆναι τὰ γράμματα περὶ τῶν φυγάδων οὐ διὰ τὴν τῆς συγκλήτου σπουδήν, ἀλλὰ διὰ τὴν τῶν φυγάδων φιλοτιμίαν, ἔδοξε τοῖς Ἀχαιοῖς μένειν ἐπὶ τῶν ὑποκειμένων. —", "st": "24.2"}, {"sp": "N", "t": "πρὸς μὲν οὖν τῷ Πόντῳ τὸ Αἷμόν ἐστιν ὄρος, μέγιστον τῶν ταύτῃ καὶ ὑψηλότατον, μέσην πως διαιροῦν τὴν Θρᾴκην· ἀφ’ οὗ φησι Πολύβιος ἀμφοτέρας καθορᾶσθαι τὰς θαλάττας, οὐκ ἀληθῆ λέγων· καὶ γὰρ τὸ διάστημα μέγα τὸ πρὸς τὸν Ἀδρίαν καὶ τὰ ἐπισκοτοῦντα πολλά.", "st": "24.3"}, {"sp": "N", "t": "κατὰ δὲ τὴν Κρήτην ἀρχὴ πραγμάτων ἐκινεῖτο μεγάλων, εἰ χρὴ λέγειν ἀρχὴν πραγμάτων ἐν Κρήτῃ· διὰ γὰρ τὴν συνέχειαν τῶν ἐμφυλίων πολέμων καὶ τὴν ὑπερβολὴν τῆς εἰς ἀλλήλους ὠμότητος ταὐτὸν ἀρχὴ καὶ τέλος ἐστὶν ἐν Κρήτῃ, καὶ τὸ δοκοῦν παραδόξως τισὶν εἰρῆσθαι τοῦτ’ ἐκεῖ θεωρεῖται συνεχῶς [τὸ] γινόμενον.", "st": "24.4"}, {"sp": "N", "t": "ὅτι γενομένων συνθηκῶν πρὸς ἀλλήλους Φαρνάκου καὶ Ἀττάλου καὶ τῶν λοιπῶν, ἅπαντες μετὰ τῶν οἰκείων δυνάμεων ἀνεχώρησαν εἰς τὴν οἰκείαν. Εὐμένης δὲ κατὰ τὸν καιρὸν τοῦτον ἀπολελυμένος τῆς ἀρρωστίας καὶ διατρίβων ἐν Περγάμῳ, παραγενομένου τἀδελφοῦ καὶ διασαφοῦντος περὶ τῶν ᾠκονομημένων, εὐδοκήσας τοῖς γεγονόσιν προέθετο πέμπειν τοὺς ἀδελφοὺς ἅπαντας εἰς τὴν Ῥώμην, ἅμα μὲν ἐλπίζων πέρας ἐπιθήσειν τῷ πρὸς τὸν Φαρνάκην πολέμῳ διὰ τῆς τούτων πρεσβείας, ἅμα δὲ συστῆσαι σπουδάζων τοὺς ἀδελφοὺς τοῖς τ’ ἰδίᾳ φίλοις καὶ ξένοις ὑπάρχουσιν αὐτῶν ἐν τῇ Ῥώμῃ καὶ τῇ συγκλήτῳ κατὰ κοινόν. προθύμων δὲ καὶ τῶν περὶ τὸν Ἄτταλον ὑπαρχόντων, ἐγένοντο περὶ τὴν ἐκδημίαν. καὶ τούτων παραγενομένων εἰς τὴν Ῥώμην, καὶ κατ’ ἰδίαν μὲν πάντες ἀπεδέχοντο τοὺς νεανίσκους φιλανθρώπως, ἅτε συνήθειαν ἐσχηκότες ἐν ταῖς περὶ τὴν Ἀσίαν στρατείαις, ἔτι δὲ μεγαλομερέστερον ἡ σύγκλητος ἀπεδέξατο τὴν παρουσίαν αὐτῶν· καὶ γὰρ ξένια καὶ παροχὰς τὰς μεγίστας ἐξέθηκεν αὐτοῖς καὶ πρὸς τὴν ἔντευξιν καλῶς ἀπήντησεν. οἱ δὲ περὶ τὸν Ἄτταλον εἰσελθόντες εἰς τὴν σύγκλητον τά τε προϋπάρχοντα φιλάνθρωπα διὰ πλειόνων λόγων ἀνενεώσαντο καὶ τοῦ Φαρνάκου κατηγορήσαντες παρεκάλουν ἐπιστροφήν τινα ποιήσασθαι, δι’ ἧς τεύξεται τῆς ἁρμοζούσης δίκης. ἡ δὲ σύγκλητος διακούσασα φιλανθρώπως ἀπεκρίθη διότι πέμψει πρεσβευτὰς τοὺς κατὰ πάντα τρόπον λύσοντας τὸν πόλεμον. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν οὕτως εἶχεν.", "st": "24.5"}, {"sp": "N", "t": "ὅτι περὶ τοὺς αὐτοὺς καιροὺς Πτολεμαῖος ὁ βασιλεύς, βουλόμενος ἐμπλέκεσθαι τῷ τῶν Ἀχαιῶν ἔθνει, διεπέμψατο πρεσβευτήν, ἐπαγγελλόμενος δεκαναΐαν δώσειν ἐντελῆ πεντηκοντηρικῶν πλοίων. οἱ δ’ Ἀχαιοὶ καὶ διὰ τὸ δοκεῖν τὴν δωρεὰν ἀξίαν εἶναι χάριτος ἀσμένως ἀπεδέξαντο τὴν ἐπαγγελίαν. [δοκεῖ γὰρ ἡ δαπάνη οὐ πολὺ λείπειν τῶν δέκα ταλάντων]. ταῦτα δὲ βουλευσάμενοι προεχειρίσαντο πρεσβευτὰς Λυκόρταν καὶ Πολύβιον καὶ σὺν τούτοις Ἄρατον, υἱὸν Ἀράτου τοῦ Σικυωνίου, τοὺς ἅμα μὲν εὐχαριστήσοντας τῷ βασιλεῖ περί τε τῶν ὅπλων ὧν πρότερον ἀπέστειλε καὶ τοῦ νομίσματος, ἅμα δὲ παραληψομένους τὰ πλοῖα καὶ πρόνοιαν ποιησομένους περὶ τῆς ἀποκομιδῆς αὐτῶν. κατέστησαν δὲ τὸν μὲν Λυκόρταν διὰ τὸ κατὰ τὸν καιρόν, καθ’ ὃν ἐποιεῖτο τὴν ἀνανέωσιν τῆς συμμαχίας ὁ Πτολεμαῖος, στρατηγοῦντα τότε συνεργῆσαι φιλοτίμως αὐτῷ, τὸν δὲ Πολύβιον, νεώτερον ὄντα τῆς κατὰ τοὺς νόμους ἡλικίας, διὰ τὸ τήν τε συμμαχίαν αὐτοῦ τὸν πατέρα πρεσβεύσαντα πρὸς Πτολεμαῖον ἀνανεώσασθαι καὶ τὴν δωρεὰν τῶν ὅπλων καὶ τοῦ νομίσματος ἀγαγεῖν τοῖς Ἀχαιοῖς, παραπλησίως δὲ καὶ τὸν Ἄρατον διὰ τὰς προγονικὰς συστάσεις πρὸς τὴν βασιλείαν. οὐ μὴν συνέβη γε τὴν πρεσβείαν ταύτην ἐξελθεῖν διὰ τὸ μεταλλάξαι τὸν Πτολεμαῖον περὶ τοὺς καιροὺς τούτους. —", "st": "24.6"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς αὐτοὺς καιροὺς ἦν τις ἐν τῇ Λακεδαίμονι Χαίρων, ὃς ἐτύγχανε τῷ πρότερον ἔτει πεπρεσβευκὼς εἰς τὴν Ῥώμην, ἄνθρωπος ἀγχίνους μὲν καὶ πρακτικός, νέος δὲ καὶ ταπεινὸς καὶ δημοτικῆς ἀγωγῆς τετευχώς. οὗτος ὀχλαγωγῶν καὶ κινήσας ὃ μηθεὶς ἕτερος ἐθάρρει, ταχέως περιεποιήσατο φαντασίαν παρὰ τοῖς πολλοῖς. καὶ τὸ μὲν πρῶτον ἀφελόμενος τὴν χώραν, ἣν οἱ τύραννοι συνεχώρησαν ταῖς ὑπολειφθείσαις τῶν φυγάδων ἀδελφαῖς καὶ γυναιξὶ καὶ μητράσι καὶ τέκνοις, ταύτην διέδωκε τοῖς λεπτοῖς εἰκῇ καὶ ἀνίσως κατὰ τὴν ἰδίαν ἐξουσίαν· μετὰ δὲ ταῦτα τοῖς κοινοῖς ὡς ἰδίοις χρώμενος ἐξεδαπάνα τὰς προσόδους, οὐ νόμου στοχαζόμενος, οὐ κοινοῦ δόγματος, οὐκ ἄρχοντος. ἐφ’ οἷς τινες ἀγανακτήσαντες ἐσπούδαζον κατασταθῆναι δοκιμαστῆρες τῶν κοινῶν κατὰ τοὺς νόμους. ὁ δὲ Χαίρων θεωρῶν τὸ γινόμενον καὶ συνειδὼς αὑτῷ κακῶς κεχειρικότι τὰ τῆς πόλεως, τὸν ἐπιφανέστατον τῶν δοκιμαστήρων Ἀπολλωνίδαν καὶ μάλιστα δυνάμενον ἐρευνῆσαι τὴν πλεονεξίαν αὐτοῦ, τοῦτον ἀποπορευόμενον ἡμέρας ἐκ βαλανείου προσπέμψας τινὰς ἐξεκέντησεν. ὧν προσπεσόντων τοῖς Ἀχαιοῖς, καὶ τοῦ πλήθους ἀγανακτήσαντος ἐπὶ τοῖς γεγονόσιν, ἐξ αὐτῆς ὁ στρατηγὸς ὁρμήσας καὶ παραγενόμενος εἰς τὴν Λακεδαίμονα τόν τε Χαίρωνα παρήγαγεν εἰς κρίσιν ὑπὲρ τοῦ φόνου τοῦ κατὰ τὸν Ἀπολλωνίδαν καὶ κατακρίνας ἐποίησε δέσμιον, τούς τε λοιποὺς δοκιμαστῆρας παρώξυνε πρὸς τὸ ποιεῖσθαι τὴν ζήτησιν τῶν δημοσίων ἀληθινήν, φροντίσαι δὲ καὶ περὶ τοῦ κομίσασθαι τὰς οὐσίας τοὺς τῶν φυγάδων ἀναγκαίους πάλιν, ἃς ὁ Χαίρων αὐτῶν ἀφείλετο βραχεῖ χρόνῳ πρότερον. —", "st": "24.7"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Ἀσίαν Φαρνάκης ὁ βασιλεύς, πάλιν ὀλιγωρήσας τῆς γεγενημένης ἐπὶ Ῥωμαίους ἀναφορᾶς, Λεώκριτον μὲν ἔτι κατὰ χειμῶνα μετὰ μυρίων στρατιωτῶν ἐξαπέστειλε πορθήσοντα τὴν Γαλατίαν, αὐτὸς δὲ τῆς ἐαρινῆς ὥρας ὑποφαινούσης ἥθροιζε τὰς δυνάμεις, ὡς ἐμβαλῶν εἰς τὴν Καππαδοκίαν. ἃ πυνθανόμενος Εὐμένης δυσχερῶς μὲν ἔφερε τὸ συμβαῖνον διὰ τὸ πάντας τοὺς τῆς πίστεως ὅρους ὑπερβαίνειν τὸν Φαρνάκην, ἠναγκάζετο δὲ τὸ παραπλήσιον ποιεῖν. ἤδη δ’ αὐτοῦ συνηθροικότος τὰς δυνάμεις, κατέπλευσαν ἐκ τῆς Ῥώμης οἱ περὶ τὸν Ἄτταλον. ὁμοῦ δὲ γενόμενοι καὶ κοινολογηθέντες ἀλλήλοις ἀνέζευξαν παραχρῆμα μετὰ τῆς στρατιᾶς. ἀφικόμενοι δ’ εἰς τὴν Γαλατίαν τὸν μὲν Λεώκριτον οὐκέτι κατέλαβον· τοῦ δὲ Κασσιγνάτου καὶ τοῦ Γαιζατόριγος διαπεμπομένων πρὸς αὐτοὺς ὑπὲρ ἀσφαλείας, οἵτινες ἐτύγχανον ἔτει πρότερον ᾑρημένοι τὰ Φαρνάκου, καὶ πᾶν ὑπισχνουμένων ποιήσειν τὸ προσταττόμενον, ἀπειπάμενοι τούτους διὰ τὴν προγεγενημένην ἀθεσίαν, ἐξάραντες παντὶ τῷ στρατεύματι προῆγον ἐπὶ τὸν Φαρνάκην. παραγενόμενοι δ’ ἐκ Καλπίτου πεμπταῖοι πρὸς τὸν Ἅλυν ποταμὸν ἑκταῖοι πάλιν ἀνέζευξαν εἰς Παρνασσόν. ἔνθα καὶ Ἀριαράθης ὁ τῶν Καππαδοκῶν βασιλεὺς συνέμιξεν αὐτοῖς μετὰ τῆς οἰκείας δυνάμεως, καὶ παρεισῆλθον εἰς τὴν Μωκισσέων χώραν. ἄρτι δὲ κατεστρατοπεδευκότων αὐτῶν προσέπεσε παραγενέσθαι τοὺς ἐκ τῆς Ῥώμης πρεσβευτὰς ἐπὶ τὰς διαλύσεις. ὧν ἀκούσας ὁ βασιλεὺς Εὐμένης Ἄτταλον μὲν ἐξαπέστειλε τούτους ἐκδεξόμενον, αὐτὸς δὲ τὰς δυνάμεις ἐδιπλασίαζε καὶ διεκόσμει φιλοτίμως, ἅμα μὲν ἁρμοζόμενος πρὸς τὰς ἀληθινὰς χρείας, ἅμα δὲ βουλόμενος ἐνδείκνυσθαι τοῖς Ῥωμαίοις ὅτι δι’ αὑτοῦ δυνατός ἐστι τὸν Φαρνάκην ἀμύνασθαι καὶ καταπολεμεῖν.", "st": "24.8"}, {"sp": "N", "t": "παραγενομένων δὲ τῶν πρέσβεων καὶ παρακαλούντων λύειν τὸν πόλεμον, ἔφασαν μὲν οἱ περὶ τὸν Εὐμένη καὶ τὸν Ἀριαράθην ἕτοιμοι πρὸς πᾶν εἶναι τὸ παρακαλούμενον, ἠξίουν δὲ τοὺς Ῥωμαίους, εἰ μέν ἐστι δυνατόν, εἰς σύλλογον αὐτοὺς συναγαγεῖν πρὸς τὸν Φαρνάκην, ἵνα κατὰ πρόσωπον λεγομένων τῶν λόγων ἴδωσι τὴν ἀθεσίαν αὐτοῦ καὶ τὴν ὠμότητα διὰ πλειόνων· εἰ δὲ μὴ τοῦτ’ εἴη δυνατόν, αὐτοὺς γενέσθαι κριτὰς τῶν πραγμάτων ἴσους καὶ δικαίους. τῶν δὲ πρεσβευτῶν ἀναδεχομένων πάντα τὰ δυνατὰ καὶ καλῶς ἔχοντα ποιήσειν, ἀξιούντων δὲ τὴν στρατιὰν ἀπάγειν ἐκ τῆς χώρας· ἄτοπον γὰρ εἶναι παρόντων πρέσβεων καὶ λόγους ποιουμένων ὑπὲρ διαλύσεων, ἅμα παρεῖναι τὰ τοῦ πολέμου καὶ κακοποιεῖν ἀλλήλους· συνεχώρησαν οἱ περὶ τὸν Εὐμένη, καὶ τῇ κατὰ πόδας εὐθέως ἀναζεύξαντες οὗτοι προῆγον ὡς ἐπὶ Γαλατίας. οἱ δὲ Ῥωμαῖοι πρὸς τὸν Φαρνάκην συμμίξαντες πρῶτον μὲν ἠξίουν αὐτὸν εἰς λόγους ἐλθεῖν τοῖς περὶ τὸν Εὐμένη· μάλιστα γὰρ ἂν οὕτω τυχεῖν τὰ πράγματα διεξαγωγῆς. τοῦ δὲ πρὸς τοῦτο τὸ μέρος ἀντιβαίνοντος καὶ τέλος ἀπειπαμένου, δῆλον μὲν εὐθέως ἦν τοῦτο καὶ Ῥωμαίοις ὅτι καταγινώσκει προφανῶς ἑαυτοῦ καὶ διαπιστεῖ τοῖς σφετέροις πράγμασι· πάντῃ δὲ πάντως βουλόμενοι λῦσαι τὸν πόλεμον προσεκαρτέρουν, ἕως οὗ συνεχώρησε πέμψειν αὐτοκράτορας ἐπὶ τὸν Πέργαμον κατὰ θάλατταν τοὺς συνθησομένους τὴν εἰρήνην, ἐφ’ οἷς ἂν οἱ πρεσβευταὶ κελεύσωσιν. ἀφικομένων δὲ τῶν πρέσβεων, καὶ συνελθόντων ὁμοῦ τῶν τε Ῥωμαίων καὶ τῶν περὶ Εὐμένη, καὶ τούτων μὲν εἰς ἅπαν ἑτοίμως συγκαταβαινόντων χάριν τοῦ συντελεσθῆναι τὴν εἰρήνην, τῶν δὲ παρὰ τοῦ Φαρνάκου πρὸς πᾶν διαφερομένων καὶ τοῖς ὁμολογηθεῖσιν οὐκ ἐμμενόντων, ἀλλ’ αἰεί τι προσεπιζητούντων καὶ μεταμελομένων, ταχέως τοῖς Ῥωμαίοις ἐγένετο δῆλον ὅτι ματαιοπονοῦσιν. οὐ γὰρ οἷος τ’ ἦν συγκαταβαίνειν ὁ Φαρνάκης εἰς τὰς διαλύσεις. ὅθεν ἀπράκτου γενομένης τῆς κοινολογίας, καὶ τῶν Ῥωμαίων ἀπαλλαγέντων ἐκ τοῦ Περγάμου, καὶ τῶν παρὰ τοῦ Φαρνάκου πρέσβεων ἀπολυθέντων εἰς τὴν οἰκείαν, ὁ μὲν πόλεμος ἐγεγένητο κατάμονος, οἱ δὲ περὶ τὸν Εὐμένη πάλιν ἐγίνοντο περὶ τὰς εἰς τοῦτον παρασκευάς. ἐν ᾧ καιρῷ τῶν Ῥοδίων ἐπισπασαμένων τὸν Εὐμένη [καὶ] φιλοτίμως, οὗτος μὲν ἐξώρμησε μετὰ πολλῆς σπουδῆς, πράξων τὰ κατὰ τοὺς Λυκίους", "st": "24.9"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἀναδόντος Ὑπερβάτου τοῦ στρατηγοῦ διαβούλιον ὑπὲρ τῶν γραφομένων παρὰ Ῥωμαίων ὑπὲρ τῆς τῶν ἐκ Λακεδαίμονος φυγάδων καθόδου τί δεῖ ποιεῖν, οἱ μὲν περὶ τὸν Λυκόρταν παρεκάλουν μένειν ἐπὶ τῶν ὑποκειμένων, διότι Ῥωμαῖοι ποιοῦσι μὲν τὸ καθῆκον αὐτοῖς, συνυπακούοντες τοῖς ἀκληρεῖν δοκοῦσιν εἰς τὰ μέτρια τῶν ἀξιουμένων· ὅταν μέντοι γε διδάξῃ τις αὐτοὺς ὅτι τῶν παρακαλουμένων τὰ μέν ἐστιν ἀδύνατα, τὰ δὲ μεγάλην αἰσχύνην ἐπιφέροντα καὶ βλάβην τοῖς φίλοις, οὔτε φιλονικεῖν εἰώθασιν οὔτε παραβιάζεσθαι περὶ τῶν τοιούτων. διὸ καὶ νῦν, ἐάν τις αὐτοὺς διδάξῃ διότι συμβήσεται τοῖς Ἀχαιοῖς, ἂν πειθαρχήσωσι τοῖς γραφομένοις, παραβῆναι τοὺς ὅρκους, τοὺς νόμους, τὰς στήλας, ἃ συνέχει τὴν κοινὴν συμπολιτείαν ἡμῶν, ἀναχωρήσουσιν καὶ συγκαταθήσονται διότι καλῶς ἐπέχομεν καὶ παραιτούμεθα περὶ τῶν γραφομένων. ταῦτα μὲν οὖν οἱ περὶ τὸν Λυκόρταν ἔλεγον· οἱ δὲ περὶ τὸν Ὑπέρβατον καὶ Καλλικράτην πειθαρχεῖν τοῖς γραφομένοις παρῄνουν καὶ μήτε νόμον μήτε στήλην μήτ’ ἄλλο μηθὲν τούτου νομίζειν ἀναγκαιότερον. τοιαύτης δ’ οὔσης τῆς ἀντιλογίας ἔδοξε τοῖς Ἀχαιοῖς πρεσβευτὰς ἐξαποστεῖλαι πρὸς τὴν σύγκλητον τοὺς διδάξοντας ἃ Λυκόρτας λέγει. καὶ παραυτίκα κατέστησαν πρεσβευτὰς Καλλικράτην Λεοντήσιον, Λυδιάδαν Μεγαλοπολίτην, Ἄρατον Σικυώνιον· καὶ δόντες ἐντολὰς ἀκολούθους τοῖς προειρημένοις ἐξαπέστειλαν. ὧν παραγενομένων εἰς τὴν Ῥώμην, εἰσελθὼν ὁ Καλλικράτης εἰς τὴν σύγκλητον τοσοῦτον ἀπέσχε τοῦ ταῖς ἐντολαῖς ἀκολούθως διδάσκειν τὸ συνέδριον ὥστε τοὐναντίον ἐκ καταβολῆς ἐπεχείρησεν οὐ μόνον τῶν ἀντιπολιτευομένων κατηγορεῖν θρασέως, ἀλλὰ καὶ τὴν σύγκλητον νουθετεῖν.", "st": "24.10"}, {"sp": "N", "t": "ἔφη γὰρ αὐτοὺς τοὺς Ῥωμαίους αἰτίους εἶναι τοῦ μὴ πειθαρχεῖν αὐτοῖς τοὺς Ἕλληνας, ἀλλὰ παρακούειν καὶ τῶν γραφομένων καὶ τῶν παραγγελλομένων. δυεῖν γὰρ οὐσῶν αἱρέσεων κατὰ τὸ παρὸν ἐν πάσαις ταῖς δημοκρατικαῖς πολιτείαις, καὶ τῶν μὲν φασκόντων δεῖν ἀκολουθεῖν τοῖς γραφομένοις ὑπὸ Ῥωμαίων καὶ μήτε νόμον μήτε στήλην μήτ’ ἄλλο μηθὲν προυργιαίτερον νομίζειν τῆς Ῥωμαίων προαιρέσεως, τῶν δὲ τοὺς νόμους προφερομένων καὶ τοὺς ὅρκους καὶ στήλας καὶ παρακαλούντων τὰ πλήθη μὴ ῥᾳδίως ταῦτα παραβαίνειν, ἀχαϊκωτέραν εἶναι παρὰ πολὺ ταύτην τὴν ὑπόθεσιν καὶ νικητικωτέραν ἐν τοῖς πολλοῖς. ἐξ οὗ τοῖς μὲν αἱρουμένοις τὰ Ῥωμαίων ἀδοξίαν συνεξακολουθεῖν παρὰ τοῖς ὄχλοις καὶ διαβολήν, τοῖς δ’ ἀντιπράττουσιν τἀναντία. ἐὰν μὲν οὖν ὑπὸ τῆς συγκλήτου γίνηταί τις ἐπισημασία, ταχέως καὶ τοὺς πολιτευομένους μεταθέσθαι πρὸς τὴν Ῥωμαίων αἵρεσιν, καὶ τοὺς πολλοὺς τούτοις ἐπακολουθήσειν διὰ τὸν φόβον. ἐὰν δὲ παρορᾶται τοῦτο τὸ μέρος, ἅπαντας ἀπονεύσειν ἐπ’ ἐκείνην τὴν ὑπόθεσιν· ἐνδοξοτέραν γὰρ εἶναι καὶ καλλίω παρὰ τοῖς ὄχλοις. διὸ καὶ νῦν ἤδη τινὰς οὐθὲν ἕτερον προσφερομένους δίκαιον πρὸς φιλοδοξίαν, δι’ αὐτὸ τοῦτο τῶν μεγίστων τυγχάνειν τιμῶν παρὰ τοῖς ἰδίοις πολιτεύμασιν διὰ τὸ δοκεῖν ἀντιλέγειν τοῖς ὑφ’ ὑμῶν γραφομένοις, χάριν τοῦ διαμένειν τοὺς νόμους ἰσχυροὺς καὶ τὰ δόγματα τὰ γινόμενα παρ’ αὐτοῖς. εἰ μὲν οὖν ἀδιαφόρως ἔχουσιν ὑπὲρ τοῦ πειθαρχεῖν αὐτοῖς τοὺς Ἕλληνας καὶ συνυπακούειν τοῖς γραφομένοις, ἄγειν αὐτοὺς ἐκέλευε τὴν ἀγωγήν, ἣν καὶ νῦν ἄγουσιν· εἰ δὲ βούλονται γίνεσθαι σφίσι τὰ παραγγελλόμενα καὶ μηθένα καταφρονεῖν τῶν γραφομένων, ἐπιστροφὴν ποιήσασθαι παρεκάλει τοῦ μέρους τούτου τὴν ἐνδεχομένην. εἰ δὲ μή, σαφῶς εἰδέναι δεῖν ὅτι τἀναντία συμβήσεται ταῖς ἐπινοίαις αὐτῶν· ὃ καὶ νῦν ἤδη γεγονέναι. πρῴην μὲν γὰρ ἐν τοῖς Μεσσηνιακοῖς πολλὰ ποιήσαντος Κοΐντου Μαρκίου πρὸς τὸ μηδὲν τοὺς Ἀχαιοὺς βουλεύσασθαι περὶ Μεσσηνίων ἄνευ τῆς Ῥωμαίων προαιρέσεως, παρακούσαντας καὶ ψηφισαμένους αὐτοὺς τὸν πόλεμον οὐ μόνον τὴν χώραν αὐτῶν καταφθεῖραι πᾶσαν ἀδίκως, ἀλλὰ καὶ τοὺς ἐπιφανεστάτους τῶν πολιτῶν οὓς μὲν φυγαδεῦσαι, τινὰς δ’ αὐτῶν ἐκδότους λαβόντας αἰκισαμένους πᾶσαν αἰκίαν ἀποκτεῖναι, διότι προεκαλοῦντο περὶ τῶν ἀμφισβητουμένων ἐπὶ Ῥωμαίους. νῦν δὲ πάλιν ἐκ πλείονος χρόνου γραφόντων αὐτῶν ὑπὲρ τῆς καθόδου τῶν ἐκ Λακεδαίμονος φυγάδων, τοσοῦτον ἀπέχειν τοῦ πειθαρχεῖν ὡς καὶ στήλην τεθεῖσθαι καὶ πεποιῆσθαι πρὸς τοὺς κατέχοντας τὴν πόλιν ὅρκους ὑπὲρ τοῦ μηδέποτε κατελεύσεσθαι τοὺς φυγάδας. εἰς ἃ βλέποντας αὐτοὺς ἠξίου πρόνοιαν ποιεῖσθαι τοῦ μέλλοντος.", "st": "24.11"}, {"sp": "N", "t": "ὁ μὲν οὖν Καλλικράτης ταῦτα καὶ τοιαῦτ’ εἰπὼν ἀπῆλθεν. οἱ φυγάδες δ’ ἐπεισελθόντες καὶ βραχέα περὶ αὑτῶν διδάξαντες καί τινα τῶν πρὸς τὸν κοινὸν ἔλεον εἰπόντες ἀνεχώρησαν. ἡ δὲ σύγκλητος δόξασα τὸν Καλλικράτην λέγειν τι τῶν αὐτῇ συμφερόντων καὶ διδαχθεῖσα διότι δεῖ τοὺς μὲν τοῖς αὐτῆς δόγμασιν συνηγοροῦντας αὔξειν, τοὺς δ’ ἀντιλέγοντας ταπεινοῦν, οὕτως καὶ τότε πρῶτον ἐπεβάλετο τοὺς μὲν κατὰ τὸ βέλτιστον ἱσταμένους ἐν τοῖς ἰδίοις πολιτεύμασιν ἐλαττοῦν, τοὺς δὲ καὶ δικαίως καὶ ἀδίκως προστρέχοντας αὐτῇ σωματοποιεῖν. ἐξ ὧν αὐτῇ συνέβη κατὰ βραχύ, τοῦ χρόνου προβαίνοντος, κολάκων μὲν εὐπορεῖν, φίλων δὲ σπανίζειν ἀληθινῶν. οὐ μὴν ἀλλὰ τότε περὶ μὲν τῆς καθόδου τῶν φυγάδων οὐ μόνον τοῖς Ἀχαιοῖς ἔγραψε, παρακαλοῦσα συνεπισχύειν, ἀλλὰ καὶ τοῖς Αἰτωλοῖς καὶ τοῖς Ἠπειρώταις, σὺν δὲ τούτοις Ἀθηναίοις, Βοιωτοῖς, Ἀκαρνᾶσιν, πάντας ὡσανεὶ προσδιαμαρτυρομένη χάριν τοῦ συντρῖψαι τοὺς Ἀχαιούς. περὶ δὲ τοῦ Καλλικράτους αὐτοῦ κατ’ ἰδίαν παρασιωπήσασα τοὺς συμπρεσβευτὰς κατέταξεν εἰς τὴν ἀπόκρισιν διότι δεῖ τοιούτους ὑπάρχειν ἐν τοῖς πολιτεύμασιν ἄνδρας οἷός ἐστι Καλλικράτης. ὁ δὲ προειρημένος ἔχων τὰς ἀποκρίσεις ταύτας παρῆν εἰς τὴν Ἑλλάδα περιχαρής, οὐκ εἰδὼς ὅτι μεγάλων κακῶν ἀρχηγὸς γέγονε πᾶσι μὲν τοῖς Ἕλλησι, μάλιστα δὲ τοῖς Ἀχαιοῖς. ἔτι γὰρ τούτοις ἐξῆν καὶ κατ’ ἐκείνους τοὺς χρόνους κατὰ ποσὸν ἰσολογίαν ἔχειν πρὸς Ῥωμαίους διὰ τὸ τετηρηκέναι τὴν πίστιν ἐν τοῖς ἐπιφανεστάτοις καιροῖς, ἐξ οὗ τὰ Ῥωμαίων εἵλοντο, λέγω δὲ τοῖς κατὰ Φίλιππον καὶ Ἀντίοχον, οὕτω δὲ τοῦ τῶν Ἀχαιῶν ἔθνους ηὐξημένου καὶ προκοπὴν εἰληφότος κατὰ τὸ βέλτιστον ἀφ’ ὧν ἡμεῖς ἱστοροῦμεν χρόνων, αὕτη πάλιν ἀρχὴ τῆς ἐπὶ τὸ χεῖρον ἐγένετο μεταβολῆς, τὸ Καλλικράτους θράσος Ῥωμαῖοι ὄντες ἄνθρωποι καὶ ψυχῇ χρώμενοι λαμπρᾷ καὶ προαιρέσει καλῇ πάντας μὲν ἐλεοῦσι τοὺς ἐπταικότας καὶ πᾶσι πειρῶνται χαρίζεσθαι τοῖς καταφεύγουσιν ὡς αὐτούς· ὅταν μέντοι γέ τις ὑπέμνησε τῶν δικαίων, τετηρηκὼς τὴν πίστιν, ἀνατρέχουσι καὶ διορθοῦνται σφᾶς αὐτοὺς κατὰ δύναμιν ἐν τοῖς πλείστοις. ὁ δὲ Καλλικράτης πρεσβεύσας κατὰ τοὺς ἐνεστῶτας καιροὺς εἰς τὴν Ῥώμην χάριν τοῦ λέγειν τὰ δίκαια περὶ τῶν Ἀχαιῶν, χρησάμενος κατὰ τοὐναντίον τοῖς πράγμασιν καὶ συνεπισπασάμενος τὰ κατὰ Μεσσηνίους, ὑπὲρ ὧν οὐδ’ ἐνεκάλουν Ῥωμαῖοι, παρῆν εἰς Ἀχαΐαν προσανατεινόμενος τὸν ἀπὸ Ῥωμαίων φόβον· καὶ διὰ τὴν ἀποπρεσβείαν καταπληξάμενος καὶ συντρίψας τοὺς ὄχλους διὰ τὸ μηδὲν εἰδέναι τῶν ὑπ’ αὐτοῦ κατ’ ἀλήθειαν εἰρημένων ἐν τῇ συγκλήτῳ τοὺς πολλούς, πρῶτον μὲν ᾑρέθη στρατηγός, πρὸς τοῖς ἄλλοις κακοῖς καὶ δωροδοκηθείς, ἑξῆς δὲ τούτοις παραλαβὼν τὴν ἀρχὴν κατῆγε τοὺς ἐκ τῆς Λακεδαίμονος καὶ τοὺς ἐκ τῆς Μεσσήνης φυγάδας. —", "st": "24.12"}, {"sp": "N", "t": "ὅτι Φιλοποίμενα καὶ Ἀρίσταινον τοὺς Ἀχαιοὺς συνέβη οὔτε τὴν φύσιν ὁμοίαν σχεῖν οὔτε τὴν αἵρεσιν τῆς πολιτείας. ἦν γὰρ ὁ μὲν Φιλοποίμην εὖ πεφυκὼς πρὸς τὰς πολεμικὰς χρείας καὶ κατὰ τὸ σῶμα καὶ κατὰ τὴν ψυχήν, ὁ δ’ ἕτερος πρὸς τὰ πολιτικὰ τῶν διαβουλίων. τῇ δ’ αἱρέσει κατὰ τὴν πολιτείαν τοῦτο διέφερον ἀλλήλων. τῆς γὰρ Ῥωμαίων ὑπεροχῆς ἤδη τοῖς Ἑλληνικοῖς πράγμασιν ἐμπλεκομένης ὁλοσχερῶς κατά τε τοὺς Φιλιππικοὺς καὶ τοὺς Ἀντιοχικοὺς καιρούς, ὁ μὲν Ἀρίσταινος ἦγε τὴν ἀγωγὴν τῆς πολιτείας οὕτως ὥστε πᾶν τὸ πρόσφορον Ῥωμαίοις ἐξ ἑτοίμου ποιεῖν, ἔνια δὲ καὶ πρὶν ἢ προστάξαι ’κείνους. ἐπειρᾶτο μέντοι γε τῶν νόμων ἔχεσθαι δοκεῖν καὶ τὴν τοιαύτην ἐφείλκετο φαντασίαν, εἴκων, ὁπότε τούτων ἀντιπίπτοι τις προδήλως τοῖς ὑπὸ Ῥωμαίων γραφομένοις. ὁ δὲ Φιλοποίμην, ὅσα μὲν εἴη τῶν παρακαλουμένων ἀκόλουθα τοῖς νόμοις καὶ τῇ συμμαχίᾳ, πάντα συγκατῄνει καὶ συνέπραττεν ἀπροφασίστως, ὅσα δὲ τούτων ἐκτὸς ἐπιτάττοιεν, οὐχ οἷός τ’ ἦν ἐθελοντὴν συνυπακούειν, ἀλλὰ τὰς μὲν ἀρχὰς ἔφη δεῖν δικαιολογεῖσθαι, μετὰ δὲ ταῦτα πάλιν ἀξιοῦν· εἰ δὲ μηδ’ οὕτως πείθοιεν, τέλος οἷον ἐπιμαρτυρομένους εἴκειν καὶ τότε ποιεῖν τὸ παραγγελλόμενον. —", "st": "24.13"}, {"sp": "N", "t": "ὅτι τοιούτοις ἀπολογισμοῖς Ἀρίσταινος ἐχρῆτο πρὸς τοὺς Ἀχαιοὺς περὶ τῆς ἰδίας αἱρέσεως· ἔφη γὰρ οὐκ εἶναι δυνατὸν καὶ τὸ δόρυ καὶ τὸ κηρύκειον ἅμα προτεινομένους συνέχειν τὴν πρὸς Ῥωμαίους φιλίαν· \"ἀλλ’ εἰ μὲν οἷοί τ’ ἐσμὲν ἀντοφθαλμεῖν καὶ δυνάμεθα τοῦτο ποιεῖν … εἰ δὲ μηδ’ ὁ Φιλοποίμην εἰπεῖν τοῦτο τολμᾷ … καιροῖς ἕνα Ῥωμαίοις, διὰ τί ἀδυνάτων ὀρεγόμενοι τὰ δυνατὰ παρίεμεν;\" δύο γὰρ ἔφη σκοποὺς εἶναι πάσης πολιτείας, τό τε καλὸν καὶ τὸ συμφέρον. οἷς μὲν οὖν ἐφικτός ἐστιν ἡ τοῦ καλοῦ κτῆσις, ταύτης ἀντέχεσθαι δεῖν τοὺς ὀρθῶς πολιτευομένους· οἷς δ’ ἀδύνατος, ἐπὶ τὴν τοῦ συμφέροντος μερίδα καταφεύγειν· τὸ δ’ ἑκατέρων ἀποτυγχάνειν μέγιστον εἶναι τεκμήριον ἀβουλίας. πάσχειν δὲ τοῦτο προφανῶς τοὺς ἀπροφασίστως ὁμολογοῦντας μὲν πᾶν τὸ παραγγελλόμενον, ἀκουσίως δὲ τοῦτο πράττοντας καὶ μετὰ προσκοπῆς· διόπερ ἢ τοῦτ’ εἶναι δεικτέον ὡς ἐσμὲν ἱκανοὶ πρὸς τὸ μὴ πειθαρχεῖν ἢ μηδὲ λέγειν τοῦτο τολμῶντας ὑπακουστέον ἑτοίμως εἶναι πᾶσι τοῖς παραγγελλομένοις.", "st": "24.14"}, {"sp": "N", "t": "ὁ δὲ Φιλοποίμην οὐκ ἐπὶ τοσοῦτον ἔφη δεῖν ἀμαθίαν αὑτοῦ καταγινώσκειν ὥστε μὴ δύνασθαι μετρεῖν μήτε τὴν διαφορὰν τοῦ πολιτεύματος τῶν Ῥωμαίων καὶ τῶν Ἀχαιῶν μήτε τὴν ὑπερβολὴν τῆς δυνάμεως \" ἀλλὰ πάσης ὑπεροχῆς φύσιν ἐχούσης ἀεὶ βαρύτερον χρῆσθαι τοῖς ὑποταττομένοις, πότερον\" ἔφη \"συμφέρει συνεργεῖν ταῖς ὁρμαῖς ταῖς τῶν κρατούντων καὶ μηθὲν ἐμποδὼν ποιεῖν, ἵν’ ὡς τάχιστα πεῖραν λάβωμεν τῶν βαρυτάτων ἐπιταγμάτων ἢ τοὐναντίον, καθ’ ὅσον οἷοί τ’ ἐσμέν, συμπαλαίοντας προσαντέχειν ἐπὶ τοσοῦτον, ἐφ’ ὅσον μέλλομεν τελέως … … κἂν ἐπιτάττωσιν … καὶ τούτων ὑπομιμνήσκοντες αὐτοὺς ἐπιλαμβανώμεθα τῆς ὁρμῆς, παρακαθέξομεν ἐπὶ ποσὸν τὸ πικρὸν αὐτῶν τῆς ἐξουσίας, ἄλλως τε δὴ καὶ περὶ πλείονος ποιουμένων Ῥωμαίων ἕως γε τοῦ νῦν, ὡς αὐτὸς φής, Ἀρίσταινε, τὸ τηρεῖν τοὺς ὅρκους καὶ τὰς συνθήκας καὶ τὴν πρὸς τοὺς συμμάχους πίστιν. ἐὰν δ’ αὐτοὶ καταγνόντες τῶν ἰδίων δικαίων αὐτόθεν εὐθέως καθάπερ οἱ δοριάλωτοι πρὸς πᾶν τὸ κελευόμενον ἑτοίμους ἡμᾶς αὐτοὺς παρασκευάζωμεν, τί διοίσει τὸ τῶν Ἀχαιῶν ἔθνος Σικελιωτῶν καὶ Καπυανῶν τῶν ὁμολογουμένως καὶ πάλαι δουλευόντων; \" διόπερ ἔφη δεῖν ἢ τοῦτο συγχωρεῖν ὡς οὐδὲν ἰσχύει δίκαιον παρὰ Ῥωμαίοις ἢ μηδὲ τολμῶντας τοῦτο λέγειν χρῆσθαι τοῖς δικαίοις καὶ μὴ προΐεσθαι σφᾶς, ἔχοντάς γε δὴ μεγίστας καὶ καλλίστας ἀφορμὰς πρὸς Ῥωμαίους. ὅτι μὲν γὰρ ἥξει ποτὲ τοῖς Ἕλλησιν ὁ καιρὸς οὗτος, ἐν ᾧ δεήσει ποιεῖν κατ’ ἀνάγκην πᾶν τὸ παραγγελλόμενον, σαφῶς ἔφη γινώσκειν· \"ἀλλὰ πότερα τοῦτον ὡς τάχιστά τις ἂν ἰδεῖν βουληθείη γενόμενον ἢ τοὐναντίον ὡς βραδύτατα; δοκῶ μὲν γὰρ ὡς βραδύτατα. \" διὸ καὶ τούτῳ διαφέρειν ἔφη τὴν Ἀρισταίνου πολιτείαν τῆς ἑαυτοῦ· ἐκεῖνον μὲν γὰρ σπουδάζειν ὡς τάχιστα τὸ χρεὼν ἰδεῖν γενόμενον καὶ συνεργεῖν τούτῳ κατὰ δύναμιν· αὐτὸς δὲ πρὸς τοῦτ’ ἀντερείδειν καὶ διωθεῖσθαι, καθ’ ὅσον ἐστὶ δυνατός. οὐ μὴν ἀλλ’ ἐκ τῶν προειρημένων δῆλον ὡς συνέβαινε γίνεσθαι τοῦ μὲν καλήν, τοῦ δ’ εὐσχήμονα τὴν πολιτείαν, ἀμφοτέρας γε μὴν ἀσφαλεῖς· τοιγαροῦν μεγίστων καιρῶν τότε περιστάντων καὶ Ῥωμαίους καὶ τοὺς Ἕλληνας τῶν τε κατὰ Φίλιππον καὶ κατ’ Ἀντίοχον, ὅμως ἀμφότεροι διετήρησαν ἀκέραια τὰ δίκαια τοῖς Ἀχαιοῖς πρὸς Ῥωμαίους· φήμη δέ τις ἐνέτρεχεν ὡς Ἀρισταίνου Ῥωμαίοις εὐνουστέρου μᾶλλον ἢ Φιλοποίμενος ὑπάρχοντος.", "st": "24.15"}, {"sp": "HDR", "t": "Βιβλίον ΚΕʹ", "st": "25"}, {"sp": "N", "t": "Πολυβίου δ’ εἰπόντος τριακοσίας αὐτῶν καταλῦσαι πόλεις Τεβέριον Γράκχον, κωμῳδῶν φησι τοῦτο τῷ Γράκχῳ χαρίσασθαι τὸν ἄνδρα, τοὺς πύργους καλοῦντα πόλεις, ὥσπερ ἐν ταῖς θριαμβικαῖς πομπαῖς. καὶ ἴσως οὐκ ἄπιστον τοῦτο λέγει· καὶ γὰρ οἱ στρατηγοὶ καὶ οἱ συγγραφεῖς ῥᾳδίως ἐπὶ τοῦτο φέρονται τὸ ψεῦσμα, καλλωπίζοντες τὰς πράξεις.", "st": "25.1"}, {"sp": "N", "t": "ὅτι ὁ Φαρνάκης, ἐξαπιναίου καὶ βαρείας αὐτῷ τῆς ἐφόδου γενομένης, ἕτοιμος ἦν πρὸς πᾶν τὸ προτεινόμενον· πρέσβεις γὰρ ἐξαπέστειλε πρὸς Εὐμένη καὶ Ἀριαράθην. τῶν δὲ περὶ Εὐμένη καὶ Ἀριαράθην προσδεξαμένων τοὺς λόγους καὶ παραχρῆμα συνεξαποστειλάντων πρεσβευτὰς παρ’ αὑτῶν πρὸς τὸν Φαρνάκην, καὶ τούτου γενομένου πλεονάκις παρ’ ἑκατέρων, ἐκυρώθησαν αἱ διαλύσεις ἐπὶ τούτοις· εἰρήνην ὑπάρχειν Εὐμένει καὶ Προυσίᾳ καὶ Ἀριαράθῃ πρὸς Φαρνάκην καὶ Μιθριδάτην εἰς τὸν πάντα χρόνον. Γαλατίας μὴ ἐπιβαίνειν Φαρνάκην κατὰ μηδένα τρόπον. ὅσαι γεγόνασιν πρότερον συνθῆκαι Φαρνάκῃ πρὸς Γαλάτας, ἀκύρους ὑπάρχειν. ὁμοίως Παφλαγονίας ἐκχωρεῖν, ἀποκαταστήσαντα τοὺς οἰκήτορας, οὓς πρότερον ἐξαγηόχει, σὺν δὲ τούτοις ὅπλα καὶ βέλη καὶ τὰς ἄλλας παρασκευάς. ἀποδοῦναι δὲ καὶ Ἀριαράθῃ τῶν τε χωρίων ὅσα παρῄρητο μετὰ τῆς προϋπαρχούσης κατασκευῆς καὶ τοὺς ὁμήρους. ἀποδοῦναι δὲ καὶ Τίον παρὰ τὸν Πόντον, ὃν μετά τινα χρόνον Εὐμένης ἔδωκε Προυσίᾳ πεισθεὶς μετὰ μεγάλης χάριτος. ἐγράφη δὲ καὶ τοὺς αἰχμαλώτους ἀποκαταστῆσαι Φαρνάκην χωρὶς λύτρων καὶ τοὺς αὐτομόλους ἅπαντας· πρὸς δὲ τούτοις τῶν χρημάτων καὶ τῆς γάζης, ἧς ἀπήνεγκε παρὰ Μορζίου καὶ Ἀριαράθου, ἀποδοῦναι τοῖς προειρημένοις βασιλεῦσιν ἐνακόσια τάλαντα, καὶ τοῖς περὶ τὸν Εὐμένη τριακόσια προσθεῖναι τῆς εἰς τὸν πόλεμον δαπάνης. ἐπεγράφη δὲ καὶ Μιθριδάτῃ τῷ τῆς Ἀρμενίας σατράπῃ τριακόσια τάλαντα, διότι παραβὰς τὰς πρὸς Εὐμένη συνθήκας ἐπολέμησεν Ἀριαράθῃ. περιελήφθησαν δὲ ταῖς συνθήκαις τῶν μὲν κατὰ τὴν Ἀσίαν δυναστῶν Ἀρταξίας ὁ τῆς πλείστης Ἀρμενίας ἄρχων καὶ Ἀκουσίλοχος, τῶν δὲ κατὰ τὴν Εὐρώπην Γάταλος ὁ Σαρμάτης, τῶν δ’ αὐτονομουμένων Ἡρακλεῶται, Μεσημβριανοί, Χερρονησῖται, σὺν δὲ τούτοις Κυζικηνοί. περὶ δὲ τῶν ὁμήρων τελευταῖον ἐγράφη πόσους δεήσει καὶ τίνας δοῦναι τὸν Φαρνάκην· ὧν καὶ παραγενηθέντων ἐξ αὐτῆς ἀνέζευξαν αἱ δυνάμεις. καὶ τοῦ μὲν Εὐμένει καὶ Ἀριαράθῃ πρὸς Φαρνάκην συστάντος πολέμου τοιοῦτον ἀπέβη τὸ τέλος.", "st": "25.2"}, {"sp": "N", "t": "ὅτι Περσεὺς ἀνανεωσάμενος τὴν φιλίαν τὴν πρὸς Ῥωμαίους εὐθέως ἑλληνοκοπεῖν ἐπεβάλετο, κατακαλῶν εἰς τὴν Μακεδονίαν καὶ τοὺς τὰ χρέα φεύγοντας καὶ τοὺς πρὸς καταδίκας ἐκπεπτωκότας καὶ τοὺς ἐπὶ βασιλικοῖς ἐγκλήμασι παρακεχωρηκότας. καὶ τούτων ἐξετίθει προγραφὰς εἴς τε Δῆλον καὶ Δελφοὺς καὶ τὸ τῆς Ἰτωνίας Ἀθηνᾶς ἱερόν, διδοὺς οὐ μόνον τὴν ἀσφάλειαν τοῖς καταπορευομένοις, ἀλλὰ καὶ τῶν ὑπαρχόντων κομιδήν, ἀφ’ ὧν ἕκαστος ἔφυγε. παρέλυσε δὲ καὶ τοὺς ἐν αὐτῇ τῇ Μακεδονίᾳ τῶν βασιλικῶν ὀφειλημάτων, ἀφῆκε δὲ καὶ τοὺς ἐν ταῖς φυλακαῖς ἐγκεκλεισμένους ἐπὶ βασιλικαῖς αἰτίαις. ταῦτα δὲ ποιήσας πολλοὺς ἐμετεώρισε, δοκῶν καλὰς ἐλπίδας ὑποδεικνύναι πᾶσι τοῖς Ἕλλησιν ἐν αὑτῷ. ἐπέφαινε δὲ καὶ κατὰ τὴν ἐν τῷ λοιπῷ βίῳ προστασίαν τὸ τῆς βασιλείας ἀξίωμα. κατά τε γὰρ τὴν ἐπιφάνειαν ἦν ἱκανὸς καὶ πρὸς πᾶσαν σωματικὴν χρείαν τὴν διατείνουσαν εἰς τὸν πραγματικὸν τρόπον εὔθετος, κατά τε τὴν ἐπίφασιν εἶχεν ἐπισκύνιον καὶ τάξιν οὐκ ἀνοίκειον τῆς ἡλικίας. ἐπεφεύγει δὲ καὶ τὴν πατρικὴν ἀσέλγειαν τήν τε περὶ τὰς γυναῖκας καὶ τὴν περὶ τοὺς πότους, καὶ οὐ μόνον αὐτὸς μέτριον ἔπινε δειπνῶν, ἀλλὰ καὶ οἱ συνόντες αὐτῷ φίλοι. καὶ τὰ μὲν προοίμια τῆς Περσέως ἀρχῆς τοιαύτην εἶχε διάθεσιν. — ὅτι Φίλιππος ὁ βασιλεύς, ὅτε μὲν ηὐξήθη καὶ τὴν κατὰ τῶν Ἑλλήνων ἐξουσίαν ἔλαβε, πάντων ἦν ἀπιστότατος καὶ παρανομώτατος, ὅτε δὲ πάλιν τὰ τῆς τύχης ἀντέπνευσε, πάντων μετριώτατος. ἐπεὶ δὲ τοῖς ὅλοις πράγμασιν ἔπταισε, πρὸς πᾶν τὸ μέλλον ἁρμοζόμενος ἐπειρᾶτο κατὰ πάντα τρόπον σωματοποιεῖν τὴν αὑτοῦ βασιλείαν.", "st": "25.3"}, {"sp": "N", "t": "ὅτι μετὰ τὴν ἀποστολὴν τῶν ὑπάτων Τεβερίου καὶ Κλαυδίου τὴν πρὸς Ἴστρους καὶ Ἀγρίους ἡ σύγκλητος ἐχρημάτισε τοῖς παρὰ τῶν Λυκίων ἥκουσι πρεσβευταῖς, ἤδη τῆς θερείας ληγούσης, οἵτινες παρεγένοντο μὲν εἰς τὴν Ῥώμην ἤδη καταπεπολεμημένων τῶν Λυκίων, ἐξαπεστάλησαν δὲ χρόνοις ἱκανοῖς ἀνώτερον. οἱ γὰρ Ξάνθιοι, καθ’ ὃν καιρὸν ἔμελλον εἰς τὸν πόλεμον ἐμβαίνειν, ἐξέπεμψαν πρεσβευτὰς εἴς τε τὴν Ἀχαΐαν καὶ τὴν Ῥώμην τοὺς περὶ Νικόστρατον. οἳ τότε παραγενηθέντες εἰς τὴν Ῥώμην πολλοὺς εἰς ἔλεον ἐξεκαλέσαντο τῶν ἐν τῷ συνεδρίῳ, τιθέντες ὑπὸ τὴν ὄψιν τήν τε Ῥοδίων βαρύτητα καὶ τὴν αὑτῶν περίστασιν. καὶ τέλος εἰς τοῦτ’ ἤγαγον τὴν σύγκλητον, ὥστε πέμψαι πρεσβευτὰς εἰς τὴν Ῥόδον τοὺς διασαφήσοντας ὅτι, τῶν ὑπομνηματισμῶν ἀναληφθέντων ὧν οἱ δέκα πρέσβεις ἐποιήσαντο κατὰ τὴν Ἀσίαν, ὅτε τὰ πρὸς Ἀντίοχον ἐχείριζον, εὕρηνται Λύκιοι δεδομένοι Ῥοδίοις οὐκ ἐν δωρεᾷ, τὸ δὲ πλεῖον ὡς φίλοι καὶ σύμμαχοι. τοιαύτης δὲ γενομένης διαλύσεως, οὐδ’ ὅλως ἤρεσκε πολλοῖς τὸ γεγονός. ἐδόκουν γὰρ οἱ Ῥωμαῖοι τὰ κατὰ τοὺς Ῥοδίους καὶ Λυκίους διαγωνοθετεῖν, θέλοντες ἐκδαπανᾶσθαι τὰς παραθέσεις τῶν Ῥοδίων καὶ τοὺς θησαυρούς, ἀκηκοότες τήν τε νυμφαγωγίαν τὴν νεωστὶ τῷ Περσεῖ γεγενημένην ὑπ’ αὐτῶν καὶ τὴν ἀνάπειραν τῶν πλοίων. συνέβαινε γὰρ βραχεῖ χρόνῳ πρότερον ἐπιφανῶς καὶ μεγαλομερῶς ταῖς παρασκευαῖς ἀναπεπειρᾶσθαι τοὺς Ῥοδίους ἅπασι τοῖς σκάφεσι τοῖς ὑπάρχουσιν αὐτοῖς. καὶ γὰρ ξύλων πλῆθος εἰς ναυπηγίαν ἐδίδοτο παρὰ τοῦ Περσέως τοῖς Ῥοδίοις, καὶ στελγίδα χρυσῆν ἑκάστῳ τῶν ἀφρακτιτῶν ἐδεδώρητο τῶν νεωστὶ νενυμφαγωγηκότων αὐτῷ τὴν Λαοδίκην.", "st": "25.4"}, {"sp": "N", "t": "ὅτι εἰς τὴν Ῥόδον παραγενομένων τῶν ἐκ τῆς Ῥώμης πρεσβευτῶν καὶ διασαφούντων τὰ δεδογμένα τῇ συγκλήτῳ, θόρυβος ἦν ἐν τῇ Ῥόδῳ καὶ πολλὴ ταραχὴ περὶ τοὺς πολιτευομένους, ἀγανακτούντων ἐπὶ τῷ μὴ φάσκειν ἐν δωρεᾷ δεδόσθαι τοὺς Λυκίους αὐτοῖς, ἀλλὰ κατὰ συμμαχίαν. ἄρτι γὰρ δοκοῦντες καλῶς τεθεῖσθαι τὰ κατὰ Λυκίους, αὖθις ἄλλην ἀρχὴν ἑώρων φυομένην πραγμάτων· εὐθέως γὰρ οἱ Λύκιοι, τῶν Ῥωμαίων παραγενομένων καὶ διασαφούντων ταῦτα τοῖς Ῥοδίοις, πάλιν ἐστασίαζον καὶ πᾶν ὑπομένειν οἷοί τ’ ἦσαν ὑπὲρ τῆς αὐτονομίας καὶ τῆς ἐλευθερίας. οὐ μὴν ἀλλ’ οἵ γε Ῥόδιοι διακούσαντες τῶν πρεσβευτῶν καὶ νομίσαντες ἐξηπατῆσθαι τοὺς Ῥωμαίους ὑπὸ τῶν Λυκίων, παραχρῆμα κατέστησαν τοὺς περὶ Λυκόφρονα πρεσβευτάς, διδάξοντας τὴν σύγκλητον περὶ τῶν προειρημένων. καὶ ταῦτα μὲν ἐπὶ τούτων ἦν, ὅσον οὔπω δοκούντων πάλιν ἐπαναστήσεσθαι τῶν Λυκίων.", "st": "25.5"}, {"sp": "N", "t": "ὅτι ἡ σύγκλητος, παραγενομένων τῶν ἐκ τῆς Ῥόδου πρεσβευτῶν, διακούσασα τῶν λόγων ὑπερέθετο τὴν ἀπόκρισιν. ἡκόντων δὲ τῶν Δαρδανίων καὶ περὶ τοῦ πλήθους τῶν Βασταρνῶν καὶ περὶ τοῦ μεγέθους τῶν ἀνδρῶν καὶ τῆς ἐν τοῖς κινδύνοις τόλμης ἐξηγουμένων, καὶ διασαφούντων περὶ τῆς Περσέως κοινοπραγίας καὶ τῶν Γαλατῶν καὶ φασκόντων τοῦτον ἀγωνιᾶν μᾶλλον ἢ τοὺς Βαστάρνας καὶ διὰ ταῦτα δεομένων σφίσι βοηθεῖν, παρόντων δὲ καὶ Θετταλῶν καὶ συνεπιμαρτυρούντων τοῖς Δαρδανίοις καὶ παρακαλούντων καὶ τούτων ἐπὶ τὴν βοήθειαν, ἔδοξε τῇ συγκλήτῳ πέμψαι τινὰς τοὺς αὐτόπτας ἐσομένους τῶν προσαγγελλομένων. καὶ παραυτίκα καταστήσαντες Αὖλον Ποστόμιον ἐξαπέστειλαν καὶ σὺν τούτῳ τινὰς τῶν νέων.", "st": "25.6"}, {"sp": "HDR", "t": "Βιβλίον ΚϚʹ", "st": "26"}, {"sp": "N", "t": "Πολύβιος δ’ ἐν τῇ ἕκτῃ καὶ εἰκοστῇ τῶν Ἱστοριῶν καλεῖ αὐτὸν Ἐπιμανῆ καὶ οὐκ Ἐπιφανῆ διὰ τὰς πράξεις. οὐ μόνον γὰρ μετὰ δημοτῶν ἀνθρώπων κατέβαινεν εἰς ὁμιλίας, ἀλλὰ καὶ μετὰ τῶν παρεπιδημούντων ξένων καὶ τῶν εὐτελεστάτων συνέπινεν. εἰ δὲ καὶ τῶν νεωτέρων, φησίν, αἴσθοιτο τινας συνευωχουμένους ὁπουδήποτε, παρῆν μετὰ κερατίου καὶ συμφωνίας, ὥστε τοὺς πολλοὺς διὰ τὸ παράδοξον ἀνισταμένους φεύγειν. πολλάκις δὲ καὶ τὴν βασιλικὴν ἐσθῆτα ἀποβαλὼν τήβενναν ἀναλαβὼν περιῄει τὴν ἀγοράν. —", "st": "26.1a"}, {"sp": "N", "t": "Ἀντίοχος ὁ Ἐπιφανὴς μὲν κληθείς, Ἐπιμανὴς δ’ ἐκ τῶν πράξεων ὀνομασθείς … περὶ οὗ φησι Πολύβιος τάδε, ὡς ἀποδιδράσκων ἐκ τῆς αὐλῆς ἐνίοτε τοὺς θεραπεύοντας, οὗ τύχοι τῆς πόλεως, ἀλύων ἐφαίνετο δεύτερος καὶ τρίτος. μάλιστα δὲ πρὸς τοῖς ἀργυροκοπείοις εὑρίσκετο καὶ χρυσοχοείοις, εὑρησιλογῶν καὶ φιλοτεχνῶν πρὸς τοὺς τορευτὰς καὶ τοὺς ἄλλους τεχνίτας. ἔπειτα καὶ μετὰ δημοτῶν ἀνθρώπων συγκαταβαίνων ὡμίλει, ᾧ τύχοι, καὶ μετὰ τῶν παρεπιδημούντων συνέπινε τῶν εὐτελεστάτων. ὅτε δὲ τῶν νεωτέρων αἴσθοιτό τινας συνευωχουμένους, οὐδεμίαν ἔμφασιν ποιήσας παρῆν ἐπικωμάζων μετὰ κερατίου καὶ συμφωνίας, ὥστε τοὺς πολλοὺς διὰ τὸ παράδοξον ἀφισταμένους φεύγειν. πολλάκις δὲ καὶ τὴν βασιλικὴν ἀποθέμενος ἐσθῆτα τήβενναν ἀναλαβὼν περιῄει κατὰ τὴν ἀγορὰν ἀρχαιρεσιάζων καὶ τοὺς μὲν δεξιούμενος, τοὺς δὲ καὶ περιπτύσσων παρεκάλει φέρειν αὑτῷ τὴν ψῆφον, ποτὲ μὲν ὡς ἀγορανόμος γένηται, ποτὲ δὲ καὶ ὡς δήμαρχος. τυχὼν δὲ τῆς ἀρχῆς καὶ καθίσας ἐπὶ τὸν ἐλεφάντινον δίφρον κατὰ τὸ παρὰ Ῥωμαίοις ἔθος διήκουε τῶν κατὰ τὴν ἀγορὰν γινομένων συναλλαγμάτων καὶ διέκρινε μετὰ πολλῆς σπουδῆς καὶ προθυμίας. ἐξ ὧν εἰς ἀπορίαν ἦγε τῶν ἀνθρώπων τοὺς ἐπιεικεῖς· οἱ μὲν γὰρ ἀφελῆ τινα αὐτὸν εἶναι ὑπελάμβανον, οἱ δὲ μαινόμενον. καὶ γὰρ περὶ τὰς δωρεὰς ἦν παραπλήσιος· ἐδίδου γὰρ τοῖς μὲν ἀστραγάλους δορκαδείους, τοῖς δὲ φοινικοβαλάνους, ἄλλοις δὲ χρυσίον. καὶ ἐξ ἀπαντήσεως δέ τισιν ἐντυγχάνων, οὓς μὴ ἑωράκει ποτέ, ἐδίδου δωρεὰς ἀπροσδοκήτους. ἐν δὲ ταῖς πρὸς τὰς πόλεις θυσίαις καὶ ταῖς πρὸς τοὺς θεοὺς τιμαῖς πάντας ὑπερέβαλλε τοὺς βεβασιλευκότας. τοῦτο δ’ ἄν τις τεκμήραιτο ἔκ τε τοῦ παρ’ Ἀθηναίοις Ὀλυμπιείου καὶ τῶν περὶ τὸν ἐν Δήλῳ βωμὸν ἀνδριάντων. ἐλούετο δὲ κἀν τοῖς δημοσίοις βαλανείοις, ὅτε δημοτῶν ἦν τὰ βαλανεῖα πεπληρωμένα, κεραμίων εἰσφερομένων αὐτῷ μύρων τῶν πολυτελεστάτων. ὅτε καί τινος εἰπόντος \"Μακάριοί ἐστε ὑμεῖς οἱ βασιλεῖς οἱ καὶ τούτοις χρώμενοι καὶ ὀδωδότες ἡδύ\" [καὶ] μηδὲν τὸν ἄνθρωπον προσειπών, ὅπου ’κεῖνος τῇ ἑξῆς ἐλοῦτο, ἐπεισελθὼν ἐποίησεν αὐτοῦ καταχυθῆναι τῆς κεφαλῆς μέγιστον κεράμιον πολυτελεστάτου μύρου, τῆς στακτῆς καλουμένης, ὡς πάντας ἀναστάντας κυλίεσθαι τοὺς λουομένους τῷ μύρῳ καὶ διὰ τὴν γλισχρότητα καταπίπτοντας γέλωτα παρέχειν, καθάπερ καὶ αὐτὸν τὸν βασιλέα.", "st": "26.1"}, {"sp": "HDR", "t": "Βιβλίον ΚΖʹ", "st": "27"}, {"sp": "N", "t": "ὅτι ἐν τῷ καιρῷ τούτῳ παρεγένοντο πρέσβεις παρὰ μὲν Θεσπιέων οἱ περὶ Λασῆν καὶ Καλλέαν, παρὰ δὲ Νέωνος Ἰσμηνίας, οἱ μὲν περὶ Λασῆν ἐγχειρίζοντες τὴν ἑαυτῶν πατρίδα Ῥωμαίοις, ὁ δ’ Ἰσμηνίας κατὰ κοινὸν πάσας τὰς ἐν τῇ Βοιωτίᾳ πόλεις διδοὺς εἰς τὴν τῶν πρεσβευτῶν πίστιν. ἦν δὲ τοῦτο μὲν ἐναντιώτατον τοῖς περὶ τὸν Μάρκιον, τὸ δὲ κατὰ πόλιν διελεῖν τοὺς Βοιωτοὺς οἰκειότατον. διὸ τοὺς μὲν περὶ τὸν Λασῆν καὶ τοὺς Χαιρωνεῖς καὶ τοὺς Λεβαδεῖς καὶ τοὺς ἄλλους, ὅσοι παρῆσαν ἀπὸ τῶν πόλεων, ἀσμένως ἀπεδέχοντο καὶ κατέψων, τὸν δ’ Ἰσμηνίαν παρεδειγμάτιζον, ἀποτριβόμενοι καὶ παρορῶντες. ὅτε καὶ συνεπιθέμενοί τινες τῶν φυγάδων μικροῦ κατέλευσαν τὸν Ἰσμηνίαν, εἰ μὴ κατέφυγεν ὑπὸ τὰ δίθυρα τῶν Ῥωμαίων. κατὰ δὲ τὸν καιρὸν τοῦτον ἐν ταῖς Θήβαις συνέβαινε ταραχὰς εἶναι καὶ στάσεις. οἱ μὲν γὰρ ἔφασαν δεῖν διδόναι τὴν πόλιν εἰς τὴν Ῥωμαίων πίστιν, οἱ δὲ Κορωνεῖς καὶ Ἁλιάρτιοι συνδεδραμηκότες εἰς τὰς Θήβας ἀκμὴν ἀντεποιοῦντο τῶν πραγμάτων καὶ μένειν ἔφασαν δεῖν ἐν τῇ πρὸς τὸν Περσέα συμμαχίᾳ. καὶ μέχρι μέν τινος ἐφάμιλλος ἦν ἡ διάθεσις τῶν στασιαζόντων. Ὀλυμπίχου δὲ τοῦ Κορωνέως πρώτου μεταθεμένου καὶ φάσκοντος δεῖν ἀντέχεσθαι Ῥωμαίων, ἐγένετό τις ὁλοσχερὴς ῥοπὴ καὶ μετάπτωσις τοῦ πλήθους, καὶ πρῶτον μὲν τὸν Δικέταν ἠνάγκασαν πρεσβεύειν πρὸς τοὺς περὶ τὸν Μάρκιον, ἀπολογησόμενον ὑπὲρ τῆς πρὸς τὸν Περσέα συμμαχίας. μετὰ δὲ ταῦτα τοὺς περὶ τὸν Νέωνα καὶ τὸν Ἱππίαν ἐξέβαλον, συντρέχοντες ἐπὶ τὰς οἰκίας αὐτῶν καὶ κελεύοντες αὐτοὺς ὑπὲρ αὑτῶν ἀπολογεῖσθαι περὶ τῶν διῳκονομημένων· οὗτοι γὰρ ἦσαν οἱ τὰ περὶ τὴν συμμαχίαν οἰκονομήσαντες. τούτων δὲ παραχωρησάντων, ἐξ αὐτῆς ἁθροισθέντες εἰς ἐκκλησίαν πρῶτον μὲν τιμὰς ἐψηφίσαντο καὶ δωρεὰς τοῖς Ῥωμαίοις, εἶτ’ ἐνεργεῖν ἐπέταξαν τοῖς ἄρχουσι τὴν συμμαχίαν, ἐπὶ δὲ πᾶσιν πρεσβευτὰς κατέστησαν τοὺς ἐγχειριοῦντας τὴν πόλιν Ῥωμαίοις καὶ κατάξοντας τοὺς παρ’ αὑτῶν φυγάδας.", "st": "27.1"}, {"sp": "N", "t": "τούτων δὲ συντελουμένων ἐν ταῖς Θήβαις, οἱ φυγάδες ἐν τῇ Χαλκίδι προστησάμενοι Πομπίδην κατηγορίαν ἐποιοῦντο τῶν περὶ τὸν Ἰσμηνίαν καὶ Νέωνα καὶ Δικέταν. προδήλου δὲ τῆς ἀγνοίας οὔσης τῶν προειρημένων, καὶ τῶν Ῥωμαίων συνεπισχυόντων τοῖς φυγάσιν, εἰς τὴν ἐσχάτην διάθεσιν ἧκον οἱ περὶ τὸν Ἱππίαν, ὥστε καὶ τῷ βίῳ κινδυνεῦσαι παρ’ αὐτὸν τὸν καιρὸν ὑπὸ τῆς ὁρμῆς τοῦ πλήθους, ἕως οὗ βραχύ τι τῆς ἀσφαλείας αὐτῶν προυνοήθησαν οἱ Ῥωμαῖοι, παρακατασχόντες τὴν ἐπιφορὰν τῶν ὄχλων. τῶν δὲ Θηβαίων παραγενομένων καὶ κομιζόντων τὰ προειρημένα δόγματα καὶ τὰς τιμάς, ταχεῖαν ἕκαστα τῶν πραγμάτων ἐλάμβανε τὴν ἀνταπόδοσιν, ἅτε τῶν πόλεων παρακειμένων ἀλλήλαις ἐν πάνυ βραχεῖ διαστήματι. πλὴν ἀποδεξάμενοι τοὺς Θηβαίους οἱ περὶ τὸν Μάρκιον τήν τε πόλιν ἐπῄνεσαν καὶ τοὺς φυγάδας συνεβούλευσαν καταγαγεῖν εἰς τὴν οἰκείαν. εὐθύς τε παρήγγειλαν πρεσβεύειν πᾶσι τοῖς ἀπὸ τῶν πόλεων εἰς τὴν Ῥώμην, διδόντας αὑτοὺς εἰς τὴν πίστιν κατ’ ἰδίαν ἑκάστους. πάντων δὲ κατὰ τὴν πρόθεσιν αὐτοῖς χωρούντων — ταῦτα δ’ ἦν τὸ διαλῦσαι τῶν Βοιωτῶν τὸ ἔθνος καὶ λυμήνασθαι τὴν τῶν πολλῶν εὔνοιαν πρὸς τὴν Μακεδόνων οἰκίαν — οὗτοι μὲν μεταπεμψάμενοι Σέρουιον ἐξ Ἄργους καὶ καταλιπόντες ἐπὶ τῆς Χαλκίδος προῆγον ἐπὶ Πελοπόννησον, Νέων δὲ μετά τινας ἡμέρας ἀνεχώρησεν εἰς Μακεδονίαν. οἱ δὲ περὶ τὸν Ἰσμηνίαν καὶ Δικέταν τότε μὲν ἀπήχθησαν εἰς φυλακήν, μετὰ δέ τινα χρόνον ἀπήλλαξαν αὑτοὺς ἐκ τοῦ ζῆν. τὸ δὲ τῶν Βοιωτῶν ἔθνος ἐπὶ πολὺν χρόνον συντετηρηκὸς τὴν κοινὴν συμπολιτείαν καὶ πολλοὺς καὶ ποικίλους καιροὺς διαπεφευγὸς παραδόξως τότε προπετῶς καὶ ἀλογίστως ἑλόμενον τὰ παρὰ Περσέως, εἰκῇ καὶ παιδαριωδῶς πτοηθὲν κατελύθη καὶ διεσκορπίσθη κατὰ πόλεις. οἱ δὲ περὶ τὸν Αὖλον καὶ Μάρκιον παραγενηθέντες εἰς τὴν τῶν Ἀργείων πόλιν ἐχρημάτισαν ταῖς συναρχίαις ταῖς τῶν Ἀχαιῶν καὶ παρεκάλεσαν Ἄρχωνα τὸν στρατηγὸν χιλίους ἐκπέμψαι στρατιώτας εἰς Χαλκίδα, παραφυλάξοντας τὴν πόλιν μέχρι τῆς Ῥωμαίων διαβάσεως. τοῦ δ’ Ἄρχωνος ἑτοίμως συνυπακούσαντος, οὗτοι μὲν ταῦτα διαπράξαντες ἐν τοῖς Ἕλλησι κατὰ χειμῶνα καὶ τῷ Ποπλίῳ συμμίξαντες ἀπέπλεον εἰς τὴν Ῥώμην. —", "st": "27.2"}, {"sp": "N", "t": "ὅτι οἱ περὶ τὸν Τεβέριον καὶ Ποστόμιον καὶ Ἰούνιον κατὰ τοὺς αὐτοὺς καιροὺς ἐπιπορευόμενοι τὰς νήσους καὶ τὰς κατὰ τὴν Ἀσίαν πόλεις πλεῖστον δ’ ἐν τῇ Ῥόδῳ, καίπερ οὐ προσδεομένων τῶν Ῥοδίων κατὰ τοὺς τότε χρόνους. Ἁγησίλοχος γάρ, τότε πρυτανεύων, ἀνὴρ τῶν εὐδοκιμούντων, ὁ καὶ μετὰ ταῦτα πρεσβεύσας εἰς τὴν Ῥώμην, ἔτι πρότερον ἅμα τῷ φανερὸν γενέσθαι διότι μέλλουσι πολεμεῖν Ῥωμαῖοι τῷ Περσεῖ, τἄλλα τε παρακεκλήκει τοὺς πολλοὺς ὑπὲρ τοῦ κοινωνεῖν τῶν αὐτῶν ἐλπίδων καὶ τετταράκοντα ναῦς συμβουλεύσας τοῖς Ῥοδίοις ὑποζωννύειν, ἵν’, ἐάν τις ἐκ τῶν καιρῶν γένηται χρεία, μὴ τότε παρασκευάζωνται πρὸς τὸ παρακαλούμενον, ἀλλ’ ἑτοίμως διακείμενοι πράττωσι τὸ κριθὲν ἐξ αὐτῆς. ἃ τότε προφερόμενος τοῖς Ῥωμαίοις καὶ δεικνὺς ὑπὸ τὴν ὄψιν τὰς παρασκευάς, εὐδοκουμένους τῇ πόλει τοὺς πρεσβευτὰς ἐξαπέστειλεν. οἱ δὲ περὶ τὸν Τεβέριον ἀποδεδεγμένοι τὴν τῶν Ῥοδίων εὔνοιαν ἐκομίζοντο εἰς τὴν Ῥώμην. —", "st": "27.3"}, {"sp": "N", "t": "ὅτι Περσεὺς μετὰ τὸν σύλλογον τὸν πρὸς τοὺς Ῥωμαίους, τῶν Ἑλλήνων, πάντα τὰ δίκαια κατέταττεν εἰς τὴν ἐπιστολὴν καὶ τοὺς ὑφ’ ἑκατέρων ῥηθέντας λόγους, ἅμα μὲν ὑπολαμβάνων ὑπερδέξιος φανήσεσθαι τοῖς δικαίοις, ἅμα δὲ βουλόμενος ἀπόπειραν λαμβάνειν τῆς ἑκάστων προαιρέσεως. πρὸς μὲν οὖν τοὺς ἄλλους δι’ αὐτῶν τῶν γραμματοφόρων ἔπεμπε τὰς ἐπιστολάς, εἰς δὲ τὴν Ῥόδον καὶ πρεσβευτὰς συναπέστειλεν Ἀντήνορα καὶ Φίλιππον. οἳ καὶ παραγενηθέντες τὰ γεγραμμένα τοῖς ἄρχουσιν ἀπέδωκαν· καὶ μετά τινας ἡμέρας ἐπελθόντες ἐπὶ τὴν βουλὴν παρεκάλουν τοὺς Ῥοδίους κατὰ μὲν τὸ παρὸν ἡσυχίαν ἔχειν, ἀποθεωροῦντας τὸ γινόμενον· ἐὰν δὲ Ῥωμαῖοι παρὰ τὰς συνθήκας ἐγχειρῶσι τὰς χεῖρας ἐπιβάλλειν τῷ Περσεῖ καὶ Μακεδόσιν, πειρᾶσθαι διαλύειν. τοῦτο γὰρ πᾶσι μὲν συμφέρειν, πρέπειν δὲ μάλιστα Ῥοδίοις. ὅσῳ γὰρ πλεῖον ὀρέγονται τῆς ἰσηγορίας καὶ παρρησίας καὶ διατελοῦσι προστατοῦντες οὐ μόνον τῆς αὑτῶν ἀλλὰ καὶ τῆς τῶν ἄλλων Ἑλλήμων ἐλευθερίας, τοσούτῳ καὶ τὴν ἐναντίαν προαίρεσιν μάλιστα δεῖν αὐτοὺς προορᾶσθαι καὶ φυλάττεσθαι κατὰ δύναμιν. ταῦτα καὶ τούτοις παραπλήσια διαλεχθέντων τῶν πρέσβεων, ἤρεσκε μὲν ἅπασι τὰ λεγόμενα· προκατεχόμενοι δὲ τῇ πρὸς Ῥωμαίους εὐνοίᾳ, καὶ νικῶντος αὐτοῖς τοῦ βελτίονος, τἄλλα μὲν ἀπεδέξαντο φιλανθρώπως τοὺς πρεσβευτάς, ἠξίουν δὲ τὸν Περσέα διὰ τῆς ἀποκρίσεως εἰς μηδὲν αὑτοὺς παρακαλεῖν τοιοῦτον ἐξ οὗ φανήσονται πρὸς τὴν Ῥωμαίων ἀντιπράττοντες βούλησιν. οἱ δὲ περὶ τὸν Ἀντήνορα τὴν μὲν ἀπόκρισιν οὐκ ἔλαβον, τὴν δὲ λοιπὴν φιλανθρωπίαν ἀποδεξάμενοι τὴν Ῥοδίων ἀπέπλευσαν εἰς τὴν Μακεδονίαν. —", "st": "27.4"}, {"sp": "N", "t": "ὅτι Περσεὺς πυνθανόμενος ἔτι τινὰς τῶν ἐν τῇ Βοιωτίᾳ πόλεις ἀντέχεσθαι τῆς πρὸς αὐτὸν εὐνοίας, Ἀντίγονον ἐξαπέστειλε τὸν Ἀλεξάνδρου πρεσβευτήν. ὃς καὶ παραγενόμενος εἰς Βοιωτοὺς τὰς μὲν ἄλλας πόλεις παρῆκε διὰ τὸ μηδεμίαν ἀφορμὴν λαμβάνειν ἐπιπλοκῆς, εἰς δὲ Κορώνειαν καὶ Θίσβας, ἔτι δ’ Ἁλίαρτον εἰσελθὼν παρεκάλεσε τοὺς ἀνθρώπους ἀντέχεσθαι τῆς πρὸς Μακεδόνας εὐνοίας. τῶν δὲ προθύμως ἀποδεχομένων τὰ λεγόμενα καὶ πρεσβευτὰς ψηφισαμένων πέμπειν εἰς Μακεδονίαν, οὗτος μὲν ἀπέπλευσε καὶ συμμίξας τῷ βασιλεῖ διεσάφει τὰ κατὰ τὴν Βοιωτίαν. παραγενομένων δὲ καὶ τῶν πρεσβευτῶν μετ’ ὀλίγον καὶ παρακαλούντων βοήθειαν ἐκπέμψαι ταῖς πόλεσι ταῖς αἱρουμέναις τὰ Μακεδόνων· τοὺς γὰρ Θηβαίους βαρεῖς ὄντας ἐπικεῖσθαι καὶ παρενοχλεῖν αὐτοὺς διὰ τὸ μὴ βούλεσθαι συμφρονεῖν σφίσιν μηδ’ αἱρεῖσθαι τὰ Ῥωμαίων· ἅπερ ὁ Περσεὺς διακούσας βοήθειαν μὲν οὐδαμῶς ἔφη δύνασθαι πέμπειν οὐδενὶ διὰ τὰς ἀνοχάς, καθόλου δ’ αὐτοὺς παρεκάλει Θηβαίους μὲν ἀμύνασθαι κατὰ δύναμιν, Ῥωμαίοις δὲ μὴ πολεμεῖν, ἀλλὰ τὴν ἡσυχίαν ἔχειν. —", "st": "27.5"}, {"sp": "N", "t": "ὅτι οἱ Ῥωμαῖοι τῶν ἀπὸ τῆς Ἀσίας παραγεγονότων πρεσβευτῶν διακούσαντες τά τε κατὰ τὴν Ῥόδον καὶ τὰ κατὰ τὰς ἄλλας πόλεις προσεκαλέσαντο τοὺς παρὰ τοῦ Περσέως πρεσβευτάς. οἱ δὲ περὶ τὸν Σόλωνα καὶ τὸν Ἱππίαν ἐπειρῶντο μὲν καὶ περὶ τῶν ὅλων λέγειν τι καὶ παραιτεῖσθαι τὴν σύγκλητον· τὸ δὲ πλέον ἀπελογοῦντο περὶ τῆς ἐπιβουλῆς τῆς κατὰ τὸν Εὐμένη. ληξάντων δὲ τῆς δικαιολογίας αὐτῶν, πάλαι προδιειληφότες ὑπὲρ τοῦ πολεμεῖν προσέταξαν αὐτοῖς ἐκ μὲν τῆς Ῥώμης εὐθέως ἀπαλλάττεσθαι καὶ τοῖς ἄλλοις ἅπασιν Μακεδόσιν, ὅσοι παρεπιδημοῦντες ἔτυχον, ἐκ δὲ τῆς Ἰταλίας ἐν τριάκονθ’ ἡμέραις ἐκχωρεῖν. μετὰ δὲ ταῦτα τοὺς ὑπάτους ἀνακαλεσάμενοι παρώρμων ἔχεσθαι τοῦ καιροῦ καὶ μὴ καθυστερεῖν. —", "st": "27.6"}, {"sp": "N", "t": "ὅτι Γάιος ἔτι περὶ τὴν Κεφαλληνίαν ὁρμῶν ἐξέπεμψε τοῖς Ῥοδίοις γράμματα περὶ πλοίων ἐξαποστολῆς, συνθεὶς τὴν ἐπιστολὴν ἀλείπτῃ τινὶ Σωκράτει. παραγενομένων δὲ τῶν γραμμάτων εἰς τὴν Ῥόδον, Στρατοκλέους πρυτανεύοντος τὴν δευτέραν ἕκμηνον, καὶ τοῦ διαβουλίου προτεθέντος, τοῖς μὲν περὶ τὸν Ἀγαθάγητον καὶ Ῥοδοφῶντα καὶ Ἀστυμήδην καὶ ἑτέροις πλείοσιν ἐδόκει πέμπειν τὰς ναῦς καὶ συνάπτεσθαι τῆς ἀρχῆς εὐθέως τοῦ πολέμου, μηδεμίαν πρόφασιν ποιουμένους. οἱ δὲ περὶ τὸν Δείνωνα καὶ Πολυάρατον δυσαρεστοῦντες μὲν καὶ τοῖς ἤδη γεγονόσι φιλανθρώποις πρὸς Ῥωμαίους, τότε δὲ προθέμενοι τὸ τοῦ βασιλέως Εὐμένους πρόσωπον ἤρξαντο λυμαίνεσθαι τὴν τῶν πολλῶν προαίρεσιν. ὑπαρχούσης γὰρ τοῖς Ῥοδίοις ὑποψίας καὶ διαφορᾶς πρὸς τὸν Εὐμένη, πάλαι μὲν ἐκ τοῦ πολέμου τοῦ πρὸς Φαρνάκην, ὅτε, τοῦ βασιλέως Εὐμένους ἐφορμοῦντος ἐπὶ τοῦ κατὰ τὸν Ἑλλήσποντον στόματος χάριν τοῦ κωλύειν τοὺς πλέοντας εἰς τὸν Πόντον, ἐπελάβοντο τῆς ὁρμῆς αὐτοῦ καὶ διεκώλυσαν Ῥόδιοι, μικροῖς δ’ ἀνώτερον χρόνοις ἐκ τῶν Λυκιακῶν ἀναξαινομένης τῆς διαφορᾶς ἔκ τινων ἐρυμάτων καὶ χώρας, ἣν συνέβαινε κεῖσθαι μὲν ἐπὶ τῆς ἐσχατιᾶς τῆς τῶν Ῥοδίων Περαίας, κακοποιεῖσθαι δὲ συνεχῶς διὰ τῶν ὑπ’ Εὐμένει ταττομένων· ἐκ πάντων δὴ τούτων εὐηκόως διέκειντο πρὸς πᾶν τὸ λεγόμενον κατὰ τοῦ βασιλέως. διὸ ταύτης ἐπιλαβόμενοι τῆς ἀφορμῆς οἱ περὶ τὸν Δείνωνα διέσυρον τὴν ἐπιστολήν, φάσκοντες οὐ παρὰ Ῥωμαίων αὐτὴν ἥκειν, ἀλλὰ παρ’ Εὐμένους, θέλοντος αὐτοὺς ἐκείνου κατὰ πάντα τρόπον ἐμβιβάζειν εἰς τὸν πόλεμον καὶ προσάπτειν τῷ δήμῳ δαπάνας καὶ κακοπαθείας οὐκ ἀναγκαίας. καὶ μαρτύριον ἐποίουν τῆς ἑαυτῶν ἀποφάσεως τὸ παραγεγονέναι φέροντα τὴν ἐπιστολὴν [ἀλείπτην τινὰ καὶ] τοιοῦτον ἄνθρωπον, οὐκ εἰωθότων τοῦτο ποιεῖν Ῥωμαίων, ἀλλὰ καὶ λίαν μετὰ πολλῆς σπουδῆς καὶ προστασίας διαπεμπομένων ὑπὲρ τῶν τοιούτων. ἔλεγον δὲ ταῦτα, καλῶς μὲν εἰδότες ὅτι συμβαίνει γεγράφθαι τὴν ἐπιστολὴν ὑπὸ τοῦ Λοκρητίου, βουλόμενοι δὲ τοὺς πολλοὺς διδάσκειν μηδὲν ἐξ ἑτοίμου ποιεῖν Ῥωμαίοις, ἀλλ’ ἐν πᾶσι δυσχρηστεῖν καὶ διδόναι προσκοπῆς καὶ δυσαρεστήσεως ἀφορμάς. ἦν γὰρ τὸ προκείμενον αὐτοῖς ἀπὸ μὲν τῆς πρὸς Ῥωμαίους εὐνοίας ἀλλοτριοῦν τὸν δῆμον, εἰς δὲ τὴν τοῦ Περσέως φιλίαν ἐμπλέκειν, καθ’ ὅσον οἷοί τ’ ἦσαν. συνέβαινε δὲ τοὺς προειρημένους οἰκείους ὑπάρχειν διὰ τὸ τὸν μὲν Πολυάρατον, ἀλαζονικώτερον ὄντα καὶ κενόδοξον, ὑπόχρεων πεποιηκέναι τὴν οὐσίαν, τὸν δὲ Δείνωνα, φιλάργυρον ὄντα καὶ θρασύν, ἐξ ἀρχῆς οἰκεῖον εἶναι τῆς ἐκ τῶν δυναστῶν καὶ βασιλέων ἐπανορθώσεως. ἐφ’ οἷς Στρατοκλῆς ὁ πρύτανις ἐπαναστὰς καὶ πολλὰ μὲν κατὰ τοῦ Περσέως εἰπών, πολλὰ δὲ περὶ Ῥωμαίων ἐπ’ ἀγαθῷ, παρώρμησε τοὺς πολλοὺς εἰς τὸ κυρῶσαι τὸ ψήφισμα τὸ περὶ τῆς ἐξαποστολῆς τῶν πλοίων. καὶ παραυτίκα καταρτίσαντες τετρήρεις ἕξ, πέντε μὲν ἐξαπέστειλαν ἐπὶ Χαλκίδος, ἡγεμόνα συστήσαντες ἐπ’ αὐτῶν Τιμαγόραν, τὴν δὲ μίαν εἰς Τένεδον, ἐφ’ ἧς ἄρχων ἐπέπλει Τιμαγόρας. ὃς καὶ καταλαβὼν ἐν Τενέδῳ Διοφάνην, ἀπεσταλμένον ὑπὸ τοῦ Περσέως πρὸς Ἀντίοχον, αὐτοῦ μὲν οὐκ ἐγενήθη κύριος, τοῦ δὲ πληρώματος. ὁ δὲ Λοκρήτιος πάντας ἀποδεξάμενος φιλανθρώπως τοὺς κατὰ θάλατταν παραγεγονότας συμμάχους ἀπέλυσε τῆς χρείας, φήσας οὐ προσδεῖσθαι τὰ πράγματα τῆς κατὰ θάλατταν βοηθείας. —", "st": "27.7"}, {"sp": "N", "t": "ὅτι μετὰ τὴν νίκην τῶν Μακεδόνων, συνεδρίου παρὰ τῷ Περσεῖ συναχθέντος, ὑπέδειξάν τινες τῶν φίλων διότι δεῖ πρεσβείαν πέμψαι τὸν βασιλέα πρὸς τὸν στρατηγὸν τῶν Ῥωμαίων, ἐπιδεχόμενον ἔτι καὶ νῦν ὅτι φόρους δώσει Ῥωμαίοις, ὅσους πρότερον ὑπέσχετο [ὁ] πατὴρ καταπολεμηθείς, καὶ τόπων ἐκχωρήσει τῶν αὐτῶν. ἐάν τε γὰρ δέξωνται τὰς διαλύσεις, καλὴν ἔφασαν ἔσεσθαι τῷ βασιλεῖ τὴν ἐξαγωγὴν τοῦ πολέμου, πεπροτερηκότι διὰ τῶν ὑπαίθρων, καὶ καθόλου πρὸς τὸ μέλλον εὐλαβεστέρους ὑπάρξειν τοὺς Ῥωμαίους, πεῖραν εἰληφότας τῆς Μακεδόνων ἀνδρείας εἰς τὸ μηδὲν ἄδικον μηδὲ βαρὺ προστάττειν Μακεδόσιν. ἐάν τε μὴ δέξωνται θυμομαχοῦντες ἐπὶ τοῖς γεγονόσιν, ἐκείνοις μὲν δικαίως νεμεσήσειν τὸ δαιμόνιον, αὐτῷ δὲ διὰ τὴν μετριότητα συναγωνιστὰς ὑπάρξειν τοὺς θεοὺς καὶ τοὺς ἀνθρώπους. ταῦτα μὲν οὖν ἐδόκει τοῖς πλείοσι τῶν φίλων. συγκαταθεμένου δὲ τοῦ Περσέως ἐπέμποντο παραχρῆμα πρεσβευταὶ Πάνταυχος Βαλάκρου καὶ Μίδων Βεροιεύς. ὧν παραγενομένων πρὸς τὸν Λικίννιον εὐθέως ὁ στρατηγὸς συνῆγε συνέδριον. τῶν δὲ πρέσβεων διασαφησάντων τὰ κατὰ τὰς ἐντολάς, μεταστησάμενοι τοὺς περὶ τὸν Πάνταυχον ἐβουλεύοντο περὶ τῶν προσπεπτωκότων. ἔδοξεν οὖν αὐτοῖς ὁμοθυμαδὸν ὡς βαρυτάτην δοῦναι τὴν ἀπόκρισιν. ἴδιον γὰρ τοῦτο πάντῃ παρὰ Ῥωμαίοις ἔθος καὶ πάτριόν ἐστι τὸ κατὰ μὲν τὰς ἐλαττώσεις αὐθαδεστάτους καὶ βαρυτάτους φαίνεσθαι, κατὰ δὲ τὰς ἐπιτυχίας ὡς μετριωτάτους. τοῦτο δ’ ὅτι καλὸν πᾶς ἄν τις ὁμολογήσειεν· εἰ δὲ καὶ δυνατὸν ἐν ἐνίοις καιροῖς, εἰκότως ἄν τις ἐπαπορήσειεν. πλὴν τότε γε τοιαύτην ἔδωκαν τὴν ἀπόκρισιν· ἐκέλευον γὰρ ἐπιτρέπειν τὸν Περσέα τὰ καθ’ αὑτόν, καὶ καθόλου διδόναι τῇ συγκλήτῳ τὴν ἐξουσίαν, ὡς ἂν αὐτῇ δοκῇ, βουλεύεσθαι περὶ τῶν κατὰ τὴν Μακεδονίαν. οἱ δὲ περὶ τὸν Πάνταυχον ταῦτ’ ἀκούσαντες ἐπανῆλθον καὶ διεσάφουν τῷ Περσεῖ καὶ τοῖς φίλοις. ὧν τινες ἐκπληττόμενοι τὴν ὑπερηφανίαν παρωξύνοντο καὶ συνεβούλευον τῷ Περσεῖ μήτε διαπρεσβεύεσθαι μηκέτι μήτε διαπέμπεσθαι περὶ μηδενός. οὐ μὴν ὁ Περσεὺς τοιοῦτος ἦν, ἀλλὰ προστιθεὶς καὶ τὸ πλῆθος αὔξων τῶν χρημάτων διεπέμπετο πλεονάκις πρὸς τὸν Λικίννιον. προκόπτων δ’ οὐδέν, ἀλλὰ καὶ τῶν πλείστων φίλων ἐπιτιμώντων αὐτῷ καὶ φασκόντων ὅτι νικῶν ποιεῖ τὰ τοῦ λειπομένου καὶ τοῖς ὅλοις ἐπταικότος, οὕτως ἠναγκάσθη τὰς διαπρεσβείας ἀπογνοὺς μεταστρατοπεδεῦσαι πάλιν ἐπὶ τὸ Συκύριον. καὶ ταῦτα μὲν ἐπὶ τούτων ἦν. —", "st": "27.8"}, {"sp": "N", "t": "ὅτι τῆς κατὰ τὴν ἱππομαχίαν φήμης μετὰ τὴν νίκην τῶν Μακεδόνων εἰς τὴν Ἑλλάδα διαγγελθείσης ἐξέλαμψε καθαπερεὶ πῦρ ἡ τῶν πολλῶν πρὸς τὸν Περσέα διάθεσις, τὸν πρὸ τούτου χρόνον ἐπικρυπτομένων τῶν πλείστων. ἦν δὲ περὶ αὐτοὺς τοιαύτη τις, ἐμοὶ δοκεῖ, διάθεσις· παραπλήσιον ἦν τὸ γινόμενον τῷ συμβαίνοντι περὶ τοὺς γυμνικοὺς ἀγῶνας. καὶ γὰρ ἐν ἐκείνοις ὅταν πρὸς ἐπιφανῆ καὶ ἀήττητον ἀθλητὴν εἶναι δοκοῦντα συγκαταστῇ ταπεινὸς καὶ πολὺ καταδεέστερος ἀνταγωνιστής, εὐθέως ἀπομερίζει τὰ πλήθη τὴν εὔνοιαν τῷ καταδεεστέρῳ καὶ θαρρεῖν παρακαλεῖ καὶ συνεξανίσταται τούτῳ ταῖς ὁρμαῖς· ἐὰν δὲ καὶ ψαύσῃ τοῦ προσώπου καὶ ποιήσῃ τι σημεῖον τῆς πληγῆς, παραυτίκα πάλιν ἁπάντων ἀγὼν μικρὸς γίνεται· ποτὲ δὲ καὶ χλευάζειν ἐγχειροῦσι τὸν ἕτερον, οὐ μισοῦντες οὐδὲ καταγινώσκοντες, ἀλλὰ παραδόξως τε συμπαθεῖς γινόμενοι καὶ τῷ καταδεεστέρῳ φύσει προσμερίζοντες τὴν ἑαυτῶν εὔνοιαν· οὓς ἐὰν ἐπιστήσῃ τις ἐν καιρῷ, ταχέως μετατίθενται καὶ παρὰ πόδας ἐπιλαμβάνονται τῆς ἑαυτῶν ἀγνοίας. ὅ φασι ποιῆσαι Κλειτόμαχον· ἐκείνου γὰρ ἀνυποστάτου δοκοῦντος εἶναι κατὰ τὴν ἄθλησιν, καὶ τῆς αὐτοῦ δόξης ἐπιπολαζούσης κατὰ πᾶσαν τὴν οἰκουμένην, Πτολεμαῖόν φασι τὸν βασιλέα φιλοδοξήσαντα πρὸς τὸ καταλῦσαι τὴν δόξαν αὐτοῦ, παρασκευάσαντα μετὰ πολλῆς φιλοτιμίας Ἀριστόνικον τὸν πύκτην ἐξαποστεῖλαι, δοκοῦντα φύσιν ἔχειν ὑπερέχουσαν ἐπὶ ταύτην τὴν χρείαν· παραγενομένου δ’ εἰς τὴν Ἑλλάδα τοῦ προειρημένου καὶ συγκαταστάντος Ὀλυμπίασι πρὸς τὸν Κλειτόμαχον, ἐξ αὐτῆς, ὡς ἔοικεν, ἀπένευσαν οἱ πολλοὶ πρὸς τὸν Ἀριστόνικον καὶ παρεκάλουν, χαίροντες ἐπὶ τῷ βραχύ τι τετολμηκέναι τινὰ συγκαταστῆναι πρὸς τὸν Κλειτόμαχον· ὡς δέ γε προβαίνων ἐφάμιλλος ἐφαίνετο κατὰ τὸν ἀγῶνα καί που καὶ τραῦμα καίριον ἐποίησε, κρότος ἐγίνετο καὶ συνεξέπιπτον οἱ πολλοὶ ταῖς ὁρμαῖς, θαρρεῖν παρακαλοῦντες τὸν Ἀριστόνικον. ἐν ᾧ καιρῷ φασι τὸν Κλειτόμαχον ἀποστάντα καὶ διαπνεύσαντα βραχὺν χρόνον, ἐπιστρέψαντα πρὸς τὰ πλήθη πυνθάνεσθαι τί βουλόμενοι παρακαλοῦσι τὸν Ἀριστόνικον καὶ συναγωνίζονται ’κείνῳ καθ’ ὅσον εἰσὶ δυνατοί, πότερον οὐ συνοίδασιν αὐτῷ ποιοῦντι τὰ δίκαια κατὰ τὴν ἄθλησιν ἢ τοῦτ’ ἀγνοοῦσι διότι Κλειτόμαχος μὲν ἀγωνίζεται νῦν ὑπὲρ τῆς τῶν Ἑλλήνων δόξης, Ἀριστόνικος δὲ περὶ τῆς Πτολεμαίου τοῦ βασιλέως. πότερον ἂν οὖν βουληθεῖεν τὸν Ὀλυμπίασι στέφανον Αἰγύπτιον ἀποφέρειν ἄνθρωπον νικήσαντα τοὺς Ἕλληνας, ἢ Θηβαῖον καὶ Βοιώτιον κηρύττεσθαι νικῶντα τῇ πυγμῇ τοὺς ἄνδρας. ταῦτα δ’ εἰπόντος τοῦ Κλειτομάχου τηλικαύτην φασὶ γενέσθαι τὴν μετάπτωσιν τῶν πολλῶν ὥστε πάλιν ἐκ μεταβολῆς μᾶλλον ὑπὸ τοῦ πλήθους ἢ τοῦ Κλειτομάχου καταγωνισθῆναι τὸν Ἀριστόνικον.", "st": "27.9"}, {"sp": "N", "t": "τούτῳ δὲ παραπλήσιον ἦν καὶ τὸ κατὰ τὸν Περσέα συμβαῖνον περὶ τοὺς ὄχλους· εἰ γάρ τις ἐπιστήσας αὐτοὺς ἤρετο μετὰ παρρησίας εἰ βούλοιντ’ ἂν εἰς ἕνα πεσεῖν τὴν τηλικαύτην ὑπεροχὴν καὶ λαβεῖν μοναρχικῆς πεῖραν ἐξουσίας, ἀνυπευθύνου κατὰ πάντα τρόπον, ταχέως ἂν αὐτοὺς ὑπολαμβάνω συννοήσαντας παλινῳδίαν ποιῆσαι καὶ μεταπεσεῖν εἰς τοὐναντίον· εἰ δὲ καὶ βραχέα τις ὑπέμνησε τῶν γεγονότων ἐκ μὲν τῆς Μακεδόνων οἰκίας δυσκόλων τοῖς Ἕλλησιν, ἐκ δὲ τῆς Ῥωμαίων ἀρχῆς συμφερόντων, καὶ λίαν ἂν παρὰ πόδας αὐτοὺς ὑπολαμβάνω μεταμεληθῆναι. πλὴν τότε γε κατὰ τὴν ἀνεπίστατον καὶ πρώτην ὁρμὴν ἐκφανὴς ἦν ἡ τῶν πολλῶν εὐδόκησις τοῖς προσαγγελλομένοις, ἀσμενιζόντων διὰ τὸ παράδοξον, εἰ καθόλου πέφηνέ τις ἱκανὸς ἀνταγωνιστὴς Ῥωμαίοις. περὶ μὲν οὖν τούτων ἐπὶ τοσοῦτον προήχθην εἰπεῖν, ἵνα μή τις ἀκρίτως εἰς ἀχαριστίαν ὀνειδίζῃ τοῖς Ἕλλησι τὴν τότε διάθεσιν, ἀγνοῶν τὰ φύσει παρεπόμενα τοῖς ἀνθρώποις. —", "st": "27.10"}, {"sp": "N", "t": "Κέστρος. ξένον ἦν τοῦτο τὸ εὕρημα κατὰ τὸν Περσικὸν πόλεμον. τὸ δὲ βέλος τοιοῦτον· διπάλαιστον ἦν, ἴσον ἔχον τὸν αὐλίσκον τῇ προβολῇ. τούτῳ ξύλον ἐνήρμοστο τῷ μὲν μήκει σπιθαμιαῖον, τῷ δὲ πάχει δακτυλιαίαν ἔχον τὴν διάμετρον. εἰς δὲ τούτου τὸ μέσον ἐσφήνωτο πτερύγια τρία ξύλινα, βραχέα παντελῶς. τοῦτο, δυεῖν κώλων ἀνίσων ὑπαρχόντων τῆς σφενδόνης, εἰς τὸ μέσον ἐνηγκυλίζετο τῶν κώλων εὐλύτως. λοιπὸν ἐν μὲν τῇ περιαγωγῇ τεταμένων τούτων ἔμενεν· ὅτε δὲ παραλυθείη θάτερον τῶν κώλων κατὰ τὴν ἄφεσιν, ἐκπῖπτον ἐκ τῆς ἀγκύλης καθαπερεὶ μολυβδὶς ἐκ τῆς σφενδόνης ἐφέρετο καὶ προσπῖπτον μετὰ βιαίας πληγῆς κακῶς διετίθει τοὺς συγκυρήσαντας. —", "st": "27.11"}, {"sp": "N", "t": "ὅτι ὁ Κότυς ἦν ἀνὴρ καὶ κατὰ τὴν ἐπιφάνειαν ἀξιόλογος καὶ πρὸς τὰς πολεμικὰς χρείας διαφέρων, ἔτι δὲ κατὰ τὴν ψυχὴν πάντα μᾶλλον ἢ Θρᾷξ· καὶ γὰρ νήπτης ὑπῆρχε καὶ πρᾳότητα καὶ βάθος ὑπέφαινεν ἐλευθέριον.", "st": "27.12"}, {"sp": "N", "t": "ὅτι Πτολεμαῖος ὁ στρατηγὸς ὁ κατὰ Κύπρον οὐδαμῶς Αἰγυπτιακὸς γέγονεν, ἀλλὰ νουνεχὴς καὶ πρακτικός. παραλαβὼν γὰρ τὴν νῆσον ἔτι νηπίου τοῦ βασιλέως ὄντος ἐγίνετο μὲν ἐπιμελῶς περὶ συναγωγὴν χρημάτων, ἐδίδου δ’ ἁπλῶς οὐδὲν οὐδενί, καίπερ αἰτούμενος πολλάκις ὑπὸ τῶν βασιλικῶν διοικητῶν καὶ καταλαλούμενος πικρῶς ἐπὶ τῷ μηδὲν προΐεσθαι. τοῦ δὲ βασιλέως εἰς ἡλικίαν παραγεγονότος, συνθεὶς πλῆθος ἱκανὸν χρημάτων ἐξαπέστειλεν, ὥστε καὶ τὸν Πτολεμαῖον αὐτὸν καὶ τοὺς περὶ τὴν αὐλὴν εὐδοκῆσαι τῇ πρότερον αὐτοῦ συστολῇ καὶ τῷ μηδὲν προΐεσθαι.", "st": "27.13"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν ἡνίκα Περσεὺς ἐκ τοῦ πολέμου τοῦ πρὸς Ῥωμαίους ἀπελύθη, Ἀντήνορος παραγενομένου παρὰ τοῦ Περσέως περὶ τῆς τῶν αἰχμαλώτων διαλυτρώσεως τῶν μετὰ Διοφάνους πλεόντων, ἐνέπεσε μεγάλη τοῖς πολιτευομένοις ἀπορία περὶ τοῦ τί δέον εἴη ποιεῖν. τοῖς μὲν γὰρ περὶ τὸν Φιλόφρονα καὶ Θεαίδητον οὐδαμῶς ἤρεσκε προσδέχεσθαι τὴν τοιαύτην ἐπιπλοκήν, τοῖς δὲ περὶ τὸν Δείνωνα καὶ Πολυάρατον ἤρεσκε. καὶ τέλος ἐποιήσαντο διάταξιν πρὸς τὸν Περσέα περὶ τῆς τῶν αἰχμαλώτων διαλυτρώσεως. —", "st": "27.14"}, {"sp": "N", "t": "ὅτι Κέφαλος ἧκεν ἐξ Ἠπείρου, ἔχων μὲν καὶ πρότερον ἤδη σύστασιν πρὸς τὴν Μακεδόνων οἰκίαν, τότε δὲ διὰ τῶν πραγμάτων ἠναγκασμένος αἱρεῖσθαι τὰ τοῦ Περσέως. ἡ δ’ αἰτία τοῦ συμβαίνοντος ἐγένετο τοιαύτη. Χάροψ ἦν Ἠπειρώτης, ἀνὴρ τἄλλα μὲν καλὸς κἀγαθὸς καὶ φίλος Ῥωμαίων, ὃς Φιλίππου τὰ κατὰ τὴν Ἤπειρον στενὰ κατασχόντος αἴτιος ἐγένετο τοῦ Φίλιππον μὲν ἐκπεσεῖν ἐκ τῆς Ἠπείρου, Τίτον δὲ καὶ τῆς Ἠπείρου κρατῆσαι καὶ τῶν Μακεδόνων. οὗτος υἱὸν ἔσχε Μαχατᾶν, οὗ Χάροψ ἐγένετο. τοῦτον ἀντίπαιδα κατὰ τὴν ἡλικίαν ὄντα τοῦ πατρὸς μεταλλάξαντος ὁ Χάροψ μετὰ τῆς καθηκούσης προστασίας εἰς τὴν Ῥώμην ἀπέστειλε χάριν τοῦ καὶ τὴν διάλεκτον καὶ τὰ γράμματα τὰ Ῥωμαϊκὰ μαθεῖν. τοῦτο τὸ μειράκιον πολλοῖς σύνηθες γεγονὸς ἐπανῆλθε μετά τινα χρόνον εἰς τὴν οἰκείαν. ὁ μὲν οὖν πρεσβύτερος Χάροψ μετήλλαξε τὸν βίον. τὸ δὲ μειράκιον μετέωρον ὂν τῇ φύσει καὶ πάσης πονηρίας ἔμπλεων ἐκορωνία καὶ παρετρίβετο πρὸς τοὺς ἐπιφανεῖς ἄνδρας. τὰς μὲν οὖν ἀρχὰς οὐδεὶς ἦν αὐτοῦ λόγος, ἀλλ’ οἱ προκατέχοντες καὶ ταῖς ἡλικίαις καὶ ταῖς δόξαις, οἱ περὶ τὸν Ἀντίνουν, ἐχείριζον τὰ κοινὰ κατὰ τὰς αὑτῶν γνώμας. τοῦ δὲ πολέμου τοῦ Περσικοῦ συστάντος, εὐθέως διέβαλλε τὸ μειράκιον τοὺς προειρημένους ἄνδρας πρὸς Ῥωμαίους, ἀφορμῇ μὲν χρώμενον τῇ προγεγενημένῃ συστάσει τῶν ἀνδρῶν πρὸς τὴν Μακεδόνων οἰκίαν, κατὰ δὲ τὸ παρὸν πάντα παρατηροῦν καὶ πᾶν τὸ λεγόμενον ἢ πραττόμενον ὑπ’ αὐτῶν ἐπὶ τὸ χεῖρον ἐκδεχόμενον καὶ τὰ μὲν ἀφαιροῦν τὰ δὲ προστιθὲν ἐλάμβανε πιθανότητας κατὰ τῶν ἀνθρώπων. ὁ δὲ Κέφαλος, τἄλλα τε φρόνιμος καὶ στάσιμος ἄνθρωπος, καὶ κατὰ τοὺς καιροὺς τούτους ἐπὶ τῆς ἀρίστης ὑπῆρχε γνώμης. ἀρχόμενος γὰρ ηὔξατο τοῖς θεοῖς μὴ συστῆναι τὸν πόλεμον μηδὲ κριθῆναι τὰ πράγματα· πραττομένου δὲ τοῦ πολέμου τὰ κατὰ τὴν συμμαχίαν ἐβούλετο δίκαια ποιεῖν Ῥωμαίοις, πέρα δὲ τούτου μήτε προστρέχειν ἀγεννῶς μήθ’ ὑπηρετεῖν μηδὲν παρὰ τὸ δέον. τοῦ δὲ Χάροπος ἐνεργῶς χρωμένου ταῖς κατ’ αὐτοῦ διαβολαῖς καὶ πᾶν τὸ παρὰ τὴν Ῥωμαίων βούλησιν γινόμενον εἰς ἐθελοκάκησιν ἄγοντος, τὸ μὲν πρῶτον οἱ προειρημένοι κατεφρόνουν, οὐδὲν αὑτοῖς συνειδότες ἀλλότριον βουλευομένοις Ῥωμαίων. ὡς δὲ τοὺς περὶ τὸν Ἱππόλοχον καὶ Νίκανδρον καὶ Λόχαγον εἶδον τοὺς Αἰτωλοὺς ἀναγομένους εἰς τὴν Ῥώμην ἀπὸ τῆς ἱππομαχίας ἀλόγως, καὶ τὰς διαβολὰς τὰς ἐκ τῶν περὶ Λυκίσκον πεπιστευμένας κατ’ αὐτῶν, οἵτινες κατὰ τὴν Αἰτωλίαν τὴν αὐτὴν αἵρεσιν ἦγον τῷ Χάροπι, τὸ τηνικάδε προϊδόμενοι τὸ μέλλον ἐβουλεύοντο περὶ αὑτῶν. ἔδοξεν οὖν αὐτοῖς παντὸς πεῖραν λαμβάνειν ἐφ’ ᾧ μὴ προέσθαι σφᾶς αὐτοὺς ἀκρίτως εἰς τὴν Ῥώμην ἐπανάγεσθαι διὰ τὰς Χάροπος διαβολάς. οὕτω μὲν οὖν οἱ περὶ τὸν Κέφαλον ἠναγκάσθησαν παρὰ τὰς αὑτῶν προαιρέσεις ἑλέσθαι τὰ τοῦ Περσέως. —", "st": "27.15"}, {"sp": "N", "t": "ὅτι οἱ περὶ Θεόδοτον καὶ Φιλόστρατον ἐποίησαν ἀσεβὲς πρᾶγμα καὶ παράσπονδον ὁμολογουμένως. πυθόμενοι γὰρ τὸν ὕπατον τῶν Ῥωμαίων Αὖλον Ὁστίλιον παραγίνεσθαι κομιζόμενον εἰς Θετταλίαν ἐπὶ τὸ στρατόπεδον καὶ νομίζοντες, εἰ παραδοῖεν τὸν Αὖλον τῷ Περσεῖ, μεγίστην μὲν ἂν πίστιν προσενέγκασθαι, μέγιστα δ’ ἂν βλάψαι κατὰ τὸ παρὸν Ῥωμαίους, ἔγραφον τῷ Περσεῖ συνεχῶς ἐπισπεύδειν. ὁ δὲ βασιλεὺς ἐβούλετο μὲν ἐξ αὐτῆς προάγειν καὶ συνάπτειν, τῶν δὲ Μολοττῶν κατὰ τὸν Ἀῷον ποταμὸν τὴν γέφυραν κατειληφότων ἐκωλύετο τῆς ὁρμῆς καὶ πρῶτον ἠναγκάζετο διαμάχεσθαι πρὸς τούτους. συνέβη δὲ τὸν Αὖλον εἰς τοὺς Φανοτεῖς παραγενόμενον καταλῦσαι παρὰ Νέστορι τῷ Κρωπίῳ καὶ παραδοῦναι καθ’ αὑτοῦ τοῖς ἐχθροῖς καιρὸν ὁμολογούμενον· ὃν εἰ μὴ τύχη τις ἐβράβευσε πρὸς τὸ βέλτιον, οὐκ ἄν μοι δοκεῖ διαφυγεῖν. νῦν δὲ δαιμονίως πως ὁ Νέστωρ τὸ μέλλον ὀττευσάμενος ἐξ αὐτῆς ἠνάγκασε μετελθεῖν εἰς Γίτανα τῆς νυκτός. καὶ ἀπογνοὺς τὴν διὰ τῆς Ἠπείρου πορείαν ἀνήχθη καὶ πλεύσας εἰς Ἀντίκυραν ἐκεῖθεν ἐποιήσατο τὴν ὁρμὴν εἰς Θετταλίαν.", "st": "27.16"}, {"sp": "N", "t": "ὅτι Φαρνάκης πάντων τῶν πρὸ τοῦ βασιλέων ἐγένετο παρανομώτατος. —", "st": "27.17"}, {"sp": "N", "t": "ὅτι Ἄτταλος χειμάζων ἐν Ἐλατείᾳ καὶ σαφῶς εἰδὼς τὸν ἀδελφὸν Εὐμένη λυπούμενον ὡς ἔνι μάλιστα καὶ βαρυνόμενον ἐπὶ τῷ τὰς ἐπιφανεστάτας αὐτοῦ τιμὰς ἠθετῆσθαι παρὰ τῶν ἐν Πελοποννήσῳ διὰ κοινοῦ δόγματος, ἐπικρυπτόμενον δὲ πρὸς πάντας τὴν περὶ αὐτὸν ὑπάρχουσαν διάθεσιν, ἐπεβάλετο διαπέμπεσθαι πρός τινας τῶν ἐν Ἀχαΐᾳ, σπουδάζων ἀποκατασταθῆναι τἀδελφῷ δι’ αὑτοῦ μὴ μόνον τὰς ἀναθηματικάς, ἀλλὰ καὶ τὰς ἐγγράπτους τιμάς. τοῦτο δ’ ἐποίει πεπεισμένος μεγίστην μὲν ἂν ἐκείνῳ ταύτην τὴν χάριν προσενέγκασθαι, μάλιστα δ’ ἂν τὸ φιλάδελφον καὶ γενναῖον τῆς αὑτοῦ προαιρέσεως ἐναποδείξασθαι τοῖς Ἕλλησι διὰ ταύτης τῆς πράξεως. —", "st": "27.18"}, {"sp": "N", "t": "ὅτι Ἀντίοχος ὁρῶν ἐκφανῶς ἤδη τοὺς κατὰ τὴν Ἀλεξάνδρειαν παρασκευαζομένους εἰς τὸν περὶ Κοίλης Συρίας πόλεμον, εἰς μὲν τὴν Ῥώμην ἔπεμψε πρεσβευτὰς τοὺς περὶ Μελέαγρον, ἐντειλάμενος λέγειν τῇ συγκλήτῳ καὶ διαμαρτύρασθαι διότι παρὰ πάντα τὰ δίκαια Πτολεμαῖος αὐτῷ τὰς χεῖρας ἐπιβάλλει πρότερος —", "st": "27.19"}, {"sp": "N", "t": "ἴσως μὲν οὖν ἐν πᾶσι τοῖς ἀνθρωπείοις τῷ καιρῷ δεῖ μετρεῖν ἕκαστα τῶν ἐνεργουμένων· μεγίστην γὰρ οὗτος ἔχει δύναμιν· μάλιστα δ’ ἐν τοῖς πολεμικοῖς· ὀξύταται γὰρ περὶ τούτων εἰς ἑκάτερα τὰ μέρη γίνονται ῥοπαί· τὸ δ’ ἀστοχεῖν τούτων μέγιστόν ἐστι τῶν ἁμαρτημάτων. — ὅτι δοκοῦσι πολλοὶ μὲν τῶν ἀνθρώπων ἐπιθυμεῖν τῶν καλῶν, ὀλίγοι δὲ τολμᾶν ἐγχειρεῖν αὐτοῖς, σπάνιοι δὲ τῶν ἐγχειρησάντων ἐπὶ τέλος ἀγαγεῖν τὰ πρὸς τὸ καθῆκον ἐν ἑκάστοις ποιούμενα.", "st": "27.20"}], []);})();
